window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s34-69","number":69,"surah":34,"verses":[19],"references":[{"surah":34,"verses":[19]}],"verseLabel":"سبأ: 19","question":"ما الصورة التي يرسمها قوله: ﴿وَمَزَّقْنَاهُمْ كُلَّ مُمَزَّقٍ﴾؟","answer":"يشبه تفريقهم في البلاد بتمزيق الثوب قطعًا متناثرة؛ فبعد اجتماعهم وعمرانهم صاروا جماعات متباعدة يُضرب بتفرقها المثل.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص119، تحت عنوان «بلاغة التعبير بالاستعارة في ﴿ومزقناهم﴾»","url":""}]},{"id":"s34-28","number":28,"surah":34,"verses":[20],"references":[{"surah":34,"verses":[20]}],"verseLabel":"سبأ: 20","question":"كيف توسع القراءتان معنى قوله: ﴿وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُ﴾؟","answer":"قراءة التخفيف تفيد أن ظن إبليس فيهم وافق الواقع، وقراءة التشديد تفيد أنه حقق ظنه بإغوائهم؛ فتجمعان بين صدق توقعه ووقوع أثر وسوسته.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص131، تحت عنوان «أثر تنوع القراءات في ﴿صدق عليهم إبليس ظنه﴾»","url":""}]},{"id":"s34-70","number":70,"surah":34,"verses":[20],"references":[{"surah":34,"verses":[20]}],"verseLabel":"سبأ: 20","question":"لماذا سُمّي توقع إبليس عنهم ﴿ظَنَّهُ﴾؟","answer":"لأنه لا يعلم الغيب؛ إنما توقع استجابتهم بالوسوسة لما عرف من ضعف البشر، فلما اتبعوه صدق ظنه من غير علم سابق بما سيكون.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص134–135، تحت عنوان «دلالة التعبير بالظن في ﴿ظنه﴾»","url":""}]},{"id":"s34-29","number":29,"surah":34,"verses":[21],"references":[{"surah":34,"verses":[21]}],"verseLabel":"سبأ: 21","question":"ما الذي ينفيه قوله عن إبليس: ﴿وَمَا كَانَ لَهُ عَلَيْهِمْ مِنْ سُلْطَانٍ﴾؟","answer":"ينفي أن تكون له حجة أو قهر أو قدرة تجبرهم على الكفر؛ سلطانه لا يتجاوز الوسوسة، وهم اتبعوه باختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص144–145، تحت عنوان «دلالة التعبير بـ(السلطان)»","url":""}]},{"id":"s34-71","number":71,"surah":34,"verses":[21],"references":[{"surah":34,"verses":[21]}],"verseLabel":"سبأ: 21","question":"كيف يُفهم الاستثناء في قوله: ﴿إِلَّا لِنَعْلَمَ﴾ بعد نفي سلطان إبليس؟","answer":"ليس معناه أن إبليس مُنح سلطانًا قاهرًا، بل استُثنيت حكمة إمهاله ووسوسته: أن يقع الابتلاء الذي يتميز به المؤمن بالآخرة من الشاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص145، تحت عنوان «معنى ﴿إلا﴾ ودلالتها في جملة ﴿إلا لنعلم﴾»","url":""}]},{"id":"s34-30","number":30,"surah":34,"verses":[22],"references":[{"surah":34,"verses":[22]}],"verseLabel":"سبأ: 22","question":"لماذا نُفي عن المعبودات ملك ﴿مِثْقَالَ ذَرَّةٍ﴾؟","answer":"لأن مثقال الذرة يمثل أدق مقدار يتصوره السامع؛ فنفي ملكه يقطع أن يكون لها أدنى استقلال في السماوات أو الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص166، تحت عنوان «سر إضافة ﴿مثقال﴾ إلى ﴿ذرة﴾»","url":""}]},{"id":"s34-72","number":72,"surah":34,"verses":[22],"references":[{"surah":34,"verses":[22]}],"verseLabel":"سبأ: 22","question":"ماذا يضيف قوله: ﴿وَمَا لَهُمْ فِيهِمَا مِنْ شِرْكٍ﴾ بعد نفي ملك الذرة؟","answer":"ينفي احتمال أن يكون لهم نصيب مشترك في ملك الكون بعدما نُفي ملكهم المستقل، فتسقط شبهة الشراكة من أصلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص169، تحت عنوان «معنى (الواو) ودلالتها في قوله: ﴿وما لهم﴾»","url":""}]},{"id":"s34-73","number":73,"surah":34,"verses":[22],"references":[{"surah":34,"verses":[22]}],"verseLabel":"سبأ: 22","question":"ماذا يضيف قوله: ﴿وَمَا لَهُ مِنْهُمْ مِنْ ظَهِيرٍ﴾؟","answer":"ينفي أن يكون الله محتاجًا إلى واحد منهم معينًا أو معاونًا؛ فبعد نفي استقلالهم وشركتهم نُفي حتى أن يكون لهم دور في الإعانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص172، تحت عنوان «معنى (الواو) ودلالتها في ﴿وما له﴾»","url":""}]},{"id":"s34-31","number":31,"surah":34,"verses":[23],"references":[{"surah":34,"verses":[23]}],"verseLabel":"سبأ: 23","question":"لماذا قُيّد نفع الشفاعة بقوله: ﴿عِنْدَهُ إِلَّا لِمَنْ أَذِنَ لَهُ﴾؟","answer":"ليقرر أن الشفاعة لا تعمل بضغط شافع ولا باستحقاق أحد، وإنما تقع في حضرة ملكه وبإذنه وحده؛ فيبطل اعتماد المشركين على شفعاء مستقلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص181–182، تحت عنوان «نكتة تقييد نفي الشفاعة بالظرف»","url":""}]},{"id":"s34-32","number":32,"surah":34,"verses":[24],"references":[{"surah":34,"verses":[24]}],"verseLabel":"سبأ: 24","question":"ما غرض السؤال: ﴿مَنْ يَرْزُقُكُمْ مِنَ السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"هو تقرير وتبكيت؛ فالجواب معلوم لهم، والسؤال يستدعي اعترافهم بأن رازقهم الله ثم يلزمهم أن العبادة لا تكون إلا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص197، تحت عنوان «غرض الاستفهام وفائدته»","url":""}]},{"id":"s34-74","number":74,"surah":34,"verses":[24],"references":[{"surah":34,"verses":[24]}],"verseLabel":"سبأ: 24","question":"كيف يستدرجهم قوله: ﴿وَإِنَّا أَوْ إِيَّاكُمْ لَعَلَى هُدًى أَوْ فِي ضَلَالٍ مُبِينٍ﴾ إلى الإنصاف؟","answer":"يعرض الاحتمالين في ظاهر منصف من غير مصادرة، مع وضوح أن أحد الفريقين مهتد والآخر ضال؛ فيدعو الخصم إلى التفكر حتى يقر بالحقيقة بنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص201–202، تحت عنوان «فن الاستدراج في الخطاب»","url":""}]},{"id":"s34-33","number":33,"surah":34,"verses":[25],"references":[{"surah":34,"verses":[25]}],"verseLabel":"سبأ: 25","question":"لماذا نسب الرسول ﷺ الإجرام إلى نفسه فقال: ﴿عَمَّا أَجْرَمْنَا﴾؟","answer":"جاء على سبيل الإنصاف واللطف في المحاورة، فافترض الجرم في جانب المتكلم ليبعد عناد الخصم ويفتح له باب النظر الهادئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص213، تحت عنوان «نكتة إسناد فعل الإجرام إلى ضمير المتكلم»","url":""}]},{"id":"s34-75","number":75,"surah":34,"verses":[25],"references":[{"surah":34,"verses":[25]}],"verseLabel":"سبأ: 25","question":"لماذا قوبل ﴿عَمَّا أَجْرَمْنَا﴾ بقوله: ﴿عَمَّا تَعْمَلُونَ﴾؟","answer":"سمّى ما في جانبه جرمًا على سبيل التواضع الجدلي، وسمّى ما في جانبهم عملًا بلا تقبيح؛ فبلغ غاية الأدب والإنصاف مع تقرير استقلال كل نفس بتبعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص214، تحت عنوان «بلاغة المقابلة بين الجمل المتعاطفة»","url":""}]},{"id":"s34-34","number":34,"surah":34,"verses":[28],"references":[{"surah":34,"verses":[28]}],"verseLabel":"سبأ: 28","question":"ماذا يفيد القصر في قوله: ﴿وَمَا أَرْسَلْنَاكَ إِلَّا كَافَّةً لِلنَّاسِ﴾؟","answer":"يثبت أن رسالة محمد ﷺ عامة لجميع الناس، لا تختص بمكة أو العرب؛ فهو بشير ونذير للبشر كافة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص234–235، تحت عنوان «بلاغة القصر»","url":""}]},{"id":"s34-76","number":76,"surah":34,"verses":[28],"references":[{"surah":34,"verses":[28]}],"verseLabel":"سبأ: 28","question":"لماذا اختيرت كلمة ﴿كَافَّةً﴾ في وصف الرسالة؟","answer":"لأنها تجمع معنى الإحاطة بالناس ومعنى كفهم وردعهم عن الكفر؛ فتلخص شمول الرسالة ووظيفتها في لفظ واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص235، تحت عنوان «بلاغة استعمال مفردة ﴿كافة﴾ وأوجه إعرابها»","url":""}]},{"id":"s34-35","number":35,"surah":34,"verses":[31],"references":[{"surah":34,"verses":[31]}],"verseLabel":"سبأ: 31","question":"ماذا تكشف ﴿لَوْلَا﴾ في قول المستضعفين للمستكبرين: ﴿لَوْلَا أَنْتُمْ لَكُنَّا مُؤْمِنِينَ﴾؟","answer":"تكشف محاولتهم تعليق ضلالهم كله على قادتهم والتنصل من مسؤوليتهم؛ جعلوا وجود المستكبرين مانعًا من الإيمان مع أنهم اتبعوهم باختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص267، تحت عنوان «دلالة ﴿لولا﴾ في الجملة»","url":""}]},{"id":"s34-77","number":77,"surah":34,"verses":[31],"references":[{"surah":34,"verses":[31]}],"verseLabel":"سبأ: 31","question":"لماذا قالوا: ﴿لَكُنَّا مُؤْمِنِينَ﴾ بصيغة الماضي؟","answer":"ليصوروا الإيمان كأنه كان وصفًا ثابتًا متحققًا لهم لولا المستكبرون، وفي ذلك مبالغة في دعوى البراءة وكشف لكذب اعتذارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص268، تحت عنوان «دلالة التعبير بالكون الماضي»","url":""}]},{"id":"s34-36","number":36,"surah":34,"verses":[34],"references":[{"surah":34,"verses":[34]}],"verseLabel":"سبأ: 34","question":"لماذا أُسند تكذيب النذير إلى ﴿مُتْرَفُوهَا﴾؟","answer":"لأن المترفين غالبًا رؤساء القرى وأصحاب النفوذ، فيقودون التكذيب ثم يتبعهم غيرهم؛ فإسناد القول إليهم يكشف مصدر الصد والعداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص310، تحت عنوان «وجه إسناد فعل القول إلى المترفين»","url":""}]},{"id":"s34-37","number":37,"surah":34,"verses":[35],"references":[{"surah":34,"verses":[35]}],"verseLabel":"سبأ: 35","question":"لماذا حُكي قولهم عن الأموال والأولاد بصيغة الماضي: ﴿وَقَالُوا﴾؟","answer":"لتصوير اعتقادهم الباطل بأنه قول راسخ متكرر لا خاطر عابر؛ استقر عندهم أن كثرة المال والولد دليل رضا الله وأمان من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص315، تحت عنوان «دلالة التعبير بفعل القول ماضيًا»","url":""}]},{"id":"s34-78","number":78,"surah":34,"verses":[35],"references":[{"surah":34,"verses":[35]}],"verseLabel":"سبأ: 35","question":"ماذا يفيد قولهم: ﴿وَمَا نَحْنُ بِمُعَذَّبِينَ﴾؟","answer":"يفيد ثقتهم المغرورة بأنهم هم خاصة بمنأى عن العذاب، فكأن ما نالوه في الدنيا ضمان لمكانتهم في الآخرة، وهو استدلال قلبته الآيات عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص318، تحت عنوان «دلالة تقديم النفي على الضمير»","url":""}]},{"id":"s34-38","number":38,"surah":34,"verses":[37],"references":[{"surah":34,"verses":[37]}],"verseLabel":"سبأ: 37","question":"ما الصورة في قوله: ﴿مَا أَمْوَالُكُمْ وَلَا أَوْلَادُكُمْ بِالَّتِي تُقَرِّبُكُمْ عِنْدَنَا زُلْفَى﴾؟","answer":"تصور القرب من الله منزلة لا تحمل إليها الأموال والأولاد؛ فنفت أن تكون زينة الدنيا وسيلة تشريف، وجاء المضارع لنفي ذلك في كل وقت.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص338، تحت عنوان «بلاغة الكناية في ﴿تقربكم﴾ وصوغها مضارعًا»","url":""}]},{"id":"s34-79","number":79,"surah":34,"verses":[37],"references":[{"surah":34,"verses":[37]}],"verseLabel":"سبأ: 37","question":"ماذا يبين الاستثناء: ﴿إِلَّا مَنْ آمَنَ وَعَمِلَ صَالِحًا﴾؟","answer":"يبين أن المال والولد لا ينفعان بذاتهما، وإنما ينفع صاحبهما إيمانه وعمله الصالح بما يسخرهما فيه؛ فالعبرة باستعمال النعمة لا بمجرد امتلاكها.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص341، تحت عنوان «دلالة الاستثناء في قوله: ﴿إلا من آمن﴾»","url":""}]},{"id":"s34-80","number":80,"surah":34,"verses":[37],"references":[{"surah":34,"verses":[37]}],"verseLabel":"سبأ: 37","question":"لماذا قُدّم الإيمان على العمل الصالح؟","answer":"لأن الإيمان أصل قبول العمل وروحه؛ فلا يكون العمل صالحًا مثمرًا عند الله إلا إذا قام على إيمان صحيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص343، تحت عنوان «نكتة تقديم ذكر الإيمان على العمل»","url":""}]},{"id":"s34-39","number":39,"surah":34,"verses":[39],"references":[{"surah":34,"verses":[39]}],"verseLabel":"سبأ: 39","question":"ماذا يفيد تنكير ﴿شَيْءٍ﴾ في قوله: ﴿وَمَا أَنْفَقْتُمْ مِنْ شَيْءٍ﴾؟","answer":"يفيد العموم والتوكيد: أي نفقة مهما صغرت أو كبرت إذا كانت في سبيل الله داخلة في الوعد بالخلف، وفيه حث على البذل.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص369، تحت عنوان «غرض تنكير لفظ ﴿شيء﴾»","url":""}]},{"id":"s34-81","number":81,"surah":34,"verses":[39],"references":[{"surah":34,"verses":[39]}],"verseLabel":"سبأ: 39","question":"لماذا لم يذكر نوع الخلف في قوله: ﴿فَهُوَ يُخْلِفُهُ﴾؟","answer":"ليعم الوعد كل خلف يختاره الله: مالًا أو ثوابًا أو بركة ودفع سوء؛ فالحذف يوسع الرجاء ولا يقيده بصورة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص370–371، تحت عنوان «نكتة حذف متعلق فعل ﴿يخلفه﴾»","url":""}]},{"id":"s34-40","number":40,"surah":34,"verses":[40],"references":[{"surah":34,"verses":[40]}],"verseLabel":"سبأ: 40","question":"لماذا يسأل الله الملائكة: ﴿أَهَؤُلَاءِ إِيَّاكُمْ كَانُوا يَعْبُدُونَ﴾ وهو يعلم الحقيقة؟","answer":"لتبكيت المشركين وفضح دعواهم على رؤوس الأشهاد؛ يسمعون الملائكة أنفسهم يتبرؤون من عبادتهم فتقوم الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص384، تحت عنوان «غرض الاستفهام في الآية»","url":""}]},{"id":"s34-41","number":41,"surah":34,"verses":[46],"references":[{"surah":34,"verses":[46]}],"verseLabel":"سبأ: 46","question":"لماذا قُيّد القيام بقوله: ﴿أَنْ تَقُومُوا لِلَّهِ﴾؟","answer":"ليكون النظر خالصًا لطلب الحق، بعيدًا عن العصبية والهوى والمصلحة؛ فالإخلاص يحرر العقل من الموانع التي تصده عن الإنصاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص457، تحت عنوان «معنى (اللام) في ﴿لله﴾»","url":""}]},{"id":"s34-82","number":82,"surah":34,"verses":[46],"references":[{"surah":34,"verses":[46]}],"verseLabel":"سبأ: 46","question":"لماذا دُعوا إلى النظر ﴿مَثْنَى وَفُرَادَى﴾؟","answer":"لأن التشاور بين اثنين يكشف ما قد يغيب عن الواحد، والانفراد يبعد ضغط الجماعة؛ فتجتمع مراجعة الفكر وحرية الضمير للوصول إلى الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص458، تحت عنوان «دلالة التعبير بالفرد والاثنين»","url":""}]},{"id":"s34-83","number":83,"surah":34,"verses":[46],"references":[{"surah":34,"verses":[46]}],"verseLabel":"سبأ: 46","question":"لماذا جاء التفكر بعد القيام لله مثنى وفرادى؟","answer":"لأن التحرر من الهوى وضغط الجماعة يهيئ العقل للتفكر العميق؛ فرتبت الآية سلامة القصد أولًا ثم النظر الذي يكشف صدق الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص460–461، تحت عنوان «دلالة التعبير بالتفكر في: ﴿تتفكروا﴾»","url":""}]},{"id":"s34-42","number":42,"surah":34,"verses":[48],"references":[{"surah":34,"verses":[48]}],"verseLabel":"سبأ: 48","question":"ما الصورة في قوله: ﴿إِنَّ رَبِّي يَقْذِفُ بِالْحَقِّ﴾؟","answer":"يشبه الحق بسهم قوي يصيبه الله موضعه فيدمغ الباطل؛ فالقذف يصور سرعة إظهاره وقوته ودقته في إصابة الهدف.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص479، تحت عنوان «بلاغة الاستعارة في ﴿يقذف﴾»","url":""}]},{"id":"s34-84","number":84,"surah":34,"verses":[48],"references":[{"surah":34,"verses":[48]}],"verseLabel":"سبأ: 48","question":"لماذا حُذف الموضع الذي يُقذف فيه الحق؟","answer":"ليعم كل موضع يصلح له: يقذف الله الحق في قلوب المؤمنين وفي وجوه الباطل، فتبدو الجملة شاملة لا يحدها ميدان واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص481، تحت عنوان «نكتة حذف متعلق الفعل ﴿يقذف﴾»","url":""}]},{"id":"s34-43","number":43,"surah":34,"verses":[49],"references":[{"surah":34,"verses":[49]}],"verseLabel":"سبأ: 49","question":"لماذا صُوِّر الباطل بأنه لا يُبدئ ولا يُعيد؟","answer":"لأن الابتداء والإعادة من آثار القدرة والحياة؛ فنفيهما يصوّر الباطل هالكًا منزوع الفاعلية، لا يملك إنشاء أثر ولا إحياء ما زال منه بعد مجيء الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص490، تحت عنوان «بلاغة الكناية في ﴿وما يبدئ الباطل وما يعيد﴾»","url":""}]},{"id":"s34-85","number":85,"surah":34,"verses":[49],"references":[{"surah":34,"verses":[49]}],"verseLabel":"سبأ: 49","question":"لماذا تكررت ﴿مَا﴾ في قوله: ﴿وَمَا يُبْدِئُ الْبَاطِلُ وَمَا يُعِيدُ﴾؟","answer":"ليستقل كل فعل بنفي مؤكد؛ فلا يملك الباطل ابتداءً ولا إعادةً، وبذلك يعم النفي وجهي الفعل ويقرر زوال الباطل من جميع الوجوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص490، تحت عنوان «علة تكرار ﴿ما﴾ في: ﴿وما يعيد﴾»","url":""}]},{"id":"s34-44","number":44,"surah":34,"verses":[51],"references":[{"surah":34,"verses":[51]}],"verseLabel":"سبأ: 51","question":"لماذا قيل: ﴿فَلَا فَوْتَ﴾ ولم يقل: فلا سَبْق؟","answer":"لأن الفوت ينفي مجرد إمكان النجاة والانفكاك، أما السبق فقد يوهم مسافةً أو قدرةً على التقدم؛ فاختير الفوت لتصوير أنهم مقهورون لا يملكون مهربًا أصلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص504، تحت عنوان «دلالة التعبير بالفوت دون السّبق»","url":""}]},{"id":"s34-86","number":86,"surah":34,"verses":[51],"references":[{"surah":34,"verses":[51]}],"verseLabel":"سبأ: 51","question":"لماذا قيل إنهم أُخذوا ﴿مِنْ مَكَانٍ قَرِيبٍ﴾؟","answer":"كناية عن سرعة أخذهم وسهولته وتمام القدرة عليهم؛ فسلطان الله لا تعوقه مسافة، وهم في قبضته أينما كانوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص507، تحت عنوان «بلاغة الكناية في قرب المكان»","url":""}]},{"id":"s34-45","number":45,"surah":34,"verses":[52],"references":[{"surah":34,"verses":[52]}],"verseLabel":"سبأ: 52","question":"ما الصورة في قوله: ﴿وَأَنَّى لَهُمُ التَّنَاوُشُ مِنْ مَكَانٍ بَعِيدٍ﴾؟","answer":"مثّل طلبهم الإيمان النافع بعد فوات زمنه بمن يحاول تناول شيء من موضع بعيد لا تبلغه يده؛ فقد كان الإيمان قريبًا ميسورًا في الدنيا، ثم صار بعد المعاينة متعذرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص510، تحت عنوان «بلاغة الاستعارة التمثيلية في ﴿وأنى لهم التناوش﴾»","url":""}]},{"id":"s34-46","number":46,"surah":34,"verses":[54],"references":[{"surah":34,"verses":[54]}],"verseLabel":"سبأ: 54","question":"لماذا قيل: ﴿وَحِيلَ بَيْنَهُمْ وَبَيْنَ مَا يَشْتَهُونَ﴾؟","answer":"يصور فعل الحيلولة انفصالًا قهريًا تامًا بينهم وبين مطلوبهم بعد أن ظنوا إمكان بلوغه؛ فيورثهم عزلًا وحسرةً أشد من مجرد الإخبار بالحرمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص519، تحت عنوان «دلالة التعبير بفعل الحيلولة»","url":""}]},{"id":"s34-87","number":87,"surah":34,"verses":[54],"references":[{"surah":34,"verses":[54]}],"verseLabel":"سبأ: 54","question":"لماذا أُبهم المرغوب في قوله: ﴿مَا يَشْتَهُونَ﴾؟","answer":"ليعم كل ما تتعلق به رغباتهم: النجاة من النار، والإيمان النافع، والرجوع إلى الدنيا، وسائر ما يرجونه؛ فالإبهام يوسّع الوعيد ويصور حرمانًا شاملًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص520، تحت عنوان «دلالة ﴿ما﴾ في: ﴿ما يشتهون﴾»","url":""}]},{"id":"s34-88","number":88,"surah":34,"verses":[54],"references":[{"surah":34,"verses":[54]}],"verseLabel":"سبأ: 54","question":"لماذا قيل: ﴿كَمَا فُعِلَ بِأَشْيَاعِهِمْ مِنْ قَبْلُ﴾؟","answer":"لبيان أن عاقبتهم ليست حادثة منفردة؛ فقد جرت سنة الله في أمثالهم من المكذبين أن يُحال بينهم وبين ما يشتهون حين يفوت زمن الإيمان، فتتأكد حتمية المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص521، تحت عنوان «بلاغة التشبيه المرسل في الآية»","url":""}]},{"id":"s34-89","number":89,"surah":34,"verses":[2],"references":[{"surah":34,"verses":[2]}],"verseLabel":"سبأ: 2","question":"ما سر حذف ﴿وهو معكم أينما كنتم﴾ هنا، مع ورودها بعد التعبير نفسه في سورة الحديد؟","answer":"سياق الحديد سياق خلق وعمل ومراقبة، وتحيط بالآية عبارات العلم والبصر؛ فناسبه ذكر المعية والمراقبة. أما سياق سبأ فمبني على الآخرة وطيّ صفحة العمل والجزاء، وخُتم بالرحمة والمغفرة؛ فكان حذف عبارة المراقبة أوفق بجو السورة وبختام ﴿الرحيم الغفور﴾.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: سبأ 2 – اختلاف ختام آيتي سبأ والحديد، مبحث «عدم ذكر وهو معكم أينما كنتم في سبأ».","url":""}]},{"id":"s34-90","number":90,"surah":34,"verses":[3],"references":[{"surah":34,"verses":[3]}],"verseLabel":"سبأ: 3","question":"ما دلالة الضمير في ﴿لا يعزب عنه﴾ بدل الاسم الظاهر الوارد في يونس: ﴿عن ربك﴾؟","answer":"سبق الضميرَ في سبأ ذكرُ الرب وعالم الغيب: ﴿قل بلى وربي لتأتينكم عالم الغيب﴾، فصار مرجعه حاضرًا، وكان الإضمار أوفق وأبعد عن التكرار. أما في يونس فلم يسبق في السياق القريب اسم يعود عليه الضمير، فاقتضى البيان إظهار ﴿ربك﴾.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: سبأ 3 – الفروق بينها وبين يونس 61، مبحث «عنه وعن ربك».","url":""}]},{"id":"s34-91","number":91,"surah":34,"verses":[3],"references":[{"surah":34,"verses":[3]}],"verseLabel":"سبأ: 3","question":"ما دلالة جمع ﴿السماوات﴾ هنا، وإفراد ﴿السماء﴾ في آية يونس المشابهة؟","answer":"قد تدل ﴿السماء﴾ بالإفراد على كل ما علا، فتكون أوسع من السماوات المعدودة؛ لذلك ناسبت سياق يونس القائم على استغراق العلم وإحاطته. أما في سبأ فالمقام متعلق بالساعة لا بتفصيل الاستغراق، فجاءت ﴿السماوات﴾ بحسب ما يقتضيه ذلك السياق.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: سبأ 3 – الفروق بينها وبين يونس 61، مبحث «السماء والسماوات».","url":""}]},{"id":"s34-92","number":92,"surah":34,"verses":[3],"references":[{"surah":34,"verses":[3]}],"verseLabel":"سبأ: 3","question":"ما سر قوله: ﴿لا يعزب عنه﴾ في سبأ، وقوله: ﴿وما يعزب عن ربك﴾ في يونس؟","answer":"آية يونس تتحدث عن أحوال واقعة: ﴿وما تكون في شأن وما تتلو منه من قرآن﴾، فناسب نفي الحال بـ﴿ما﴾. أما آية سبأ فجواب عن إنكار الساعة الآتية في المستقبل، فناسبها ﴿لا﴾ التي يكثر استعمالها في نفي المستقبل، واتسق النفي مع قولهم: ﴿لا تأتينا الساعة﴾.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: سبأ 3 – الفروق بينها وبين يونس 61، مبحث «ما يعزب ولا يعزب».","url":""}]},{"id":"s34-93","number":93,"surah":34,"verses":[12],"references":[{"surah":34,"verses":[12]}],"verseLabel":"سبأ: 12","question":"ما سر إفراد الريح في قوله: ﴿ولسليمان الريح﴾ مع أن جمعها يرد غالبًا في مواطن الرحمة؟","answer":"الغالب أن تفرد الريح في سياق الشدة وتجمع في سياق الخير، لكن ريح سليمان لم تُخصّص بوجه واحد؛ فقد سُخرت له يتصرف بها حيث شاء، في الخير أو في غيره. لذلك جاء لفظ الجنس المفرد ﴿الريح﴾ عامًا غير مقيد بوظيفة واحدة.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: سبأ 12 – دلالة إفراد الريح، مبحث «الريح والرياح».","url":""}]},{"id":"s34-94","number":94,"surah":34,"verses":[14],"references":[{"surah":34,"verses":[14]}],"verseLabel":"سبأ: 14","question":"ما الدقة البيانية في اختيار ﴿منسأته﴾ بدل «عصاه» في قصة سليمان؟","answer":"المنسأة عصا عظيمة يُزجر بها البعير ليساق، ومادتها تدل أيضًا على التأخير. وقد جمعت في القصة المعنيين: ظلت تسوق الجن إلى العمل لظنهم أن سليمان حي، وأخرت انكشاف موته وامتد بها حكمه إلى أن سقطت؛ فكانت أدق من لفظ العصا العام.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص196–197، مبحث «المنسأة والعصا في قصتي سليمان وموسى»؛ النص المباشر.","url":""}]},{"id":"s34-95","number":95,"surah":34,"verses":[33],"references":[{"surah":34,"verses":[33]}],"verseLabel":"سبأ: 33","question":"ما دقة التعبير بـ﴿الندامة﴾ هنا، وبـ﴿الحسرة﴾ في مواضع أخرى؟","answer":"الندامة جنس التأسف على ما فات، أما الحسرة فهي أشد الندم حتى يبلغ بصاحبه الانقطاع والعجز عن التدارك. فاختيار كل لفظ يراعي درجة الشعور في سياقه؛ والحسرة أغلظ وأقسى من مجرد الندامة.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: سبأ 33 – الفرق بين الندامة والحسرة، مبحث «الحسرة أشد الندم».","url":""}]},{"id":"s34-96","number":96,"surah":34,"verses":[33],"references":[{"surah":34,"verses":[33]}],"verseLabel":"سبأ: 33","question":"ما سر اختصاص الوعيد بقوله: ﴿هل يجزون إلا ما كانوا يعملون﴾ وعدم وروده بهذا الأسلوب في خطاب المؤمنين؟","answer":"السيئة تجازى بمثلها، فيناسبها حصر الجزاء في العمل، أما الحسنة فتضاعف ويزاد صاحبها من الفضل؛ لذلك يقال في المؤمنين: ﴿أحسن ما عملوا﴾ و﴿ويزيدهم من فضله﴾. ولو خوطب المؤمن بهذا التركيب لأوهم أن جزاءه لا يتجاوز مقدار عمله.","sources":[{"label":"فاضل السامرائي، هل يجزون إلا ما كانوا يعملون – خصوصية الاستعمال القرآني، مبحث «عدم ورودها في خطاب المؤمنين».","url":""}]},{"id":"s34-97","number":97,"surah":34,"verses":[53],"references":[{"surah":34,"verses":[53]}],"verseLabel":"سبأ: 53","question":"ما الصورة البيانية المدهشة في قوله: ﴿ويقذفون بالغيب من مكان بعيد﴾؟","answer":"يصور أقوالهم في الله والرسالة والبعث برامٍ يقذف هدفًا لا يعرف موضعه، ومن مسافة لا تبلغها رميته؛ فهو لا يعلم ماذا يرمي ولا أين يرمي. هكذا كانت أحكامهم على الغيب ظنونًا جزافية: شاعر أو ساحر، ولا بعث ولا جنة ولا نار، بلا علم ولا دليل.","sources":[{"label":"فاضل السامرائي، سبأ 53: ويقذفون بالغيب من مكان بعيد، عنوان المادة الجزئي «ما معنى هذه الآية؟».","url":""}]},{"id":"s34-98","number":98,"surah":34,"verses":[3],"references":[{"surah":34,"verses":[3]}],"verseLabel":"سبأ: 3","question":"ما سر حذف ﴿مِن﴾ في ﴿لا يعزب عنه مثقال ذرة﴾، وذكرها في يونس: ﴿من مثقال ذرة﴾؟","answer":"﴿مِن﴾ زائدة للتوكيد والاستغراق، وقد جاءت في يونس لأن السياق كله في إحاطة العلم بكل شأن وتلاوة وعمل. أما سبأ فالسياق الأصلي فيها إثبات مجيء الساعة والرد على منكريها، لا تفصيل استغراق العلم؛ فجاء التعبير من غير ﴿مِن﴾ مع بقاء المعنى التام.","sources":[{"label":"فاضل السامرائي، اللمسات البيانية في الآية 3 من سبأ والآية 61 من يونس، مقطع مباشر، مبحث «من الاستغراقية».","url":""}]},{"id":"s34-99","number":99,"surah":34,"verses":[3],"references":[{"surah":34,"verses":[3]}],"verseLabel":"سبأ: 3","question":"ما سر تقديم السماوات على الأرض هنا، وتقديم الأرض في آية يونس؟","answer":"الحديث في يونس عن شأن الناس وتلاوتهم وأعمالهم، وهم أهل الأرض؛ فبدأ بمسكنهم. أما سبأ فالكلام عن الساعة، وأمرها يأتي من السماء ويبدأ بأهل السماوات عند النفخ في الصور؛ فناسب أن تتقدم السماوات على الأرض.","sources":[{"label":"فاضل السامرائي، تقديم الأرض على السماء والعكس، مقطع مباشر.","url":""}]},{"id":"s34-100","number":100,"surah":34,"verses":[11],"references":[{"surah":34,"verses":[11]}],"verseLabel":"سبأ: 11","question":"ما دلالة تقديم ﴿بما تعملون﴾ على ﴿بصير﴾ في قوله: ﴿إني بما تعملون بصير﴾؟","answer":"دار السياق كله على العمل: ﴿اعمل سابغات﴾ و﴿اعملوا صالحًا﴾، فتقدم المعمول به موضع العناية: ﴿بما تعملون﴾. وإذا كان السياق منصبًّا على صفة الله قدمت الصفة، نحو ﴿والله بصير بما تعملون﴾؛ فلكل تقديم مركزه في الكلام.","sources":[{"label":"فاضل السامرائي، آية سبأ 11: بما تعملون بصير وبصير بما تعملون، عنوان المادة الجزئي «تقديم العمل أو البصر بحسب السياق».","url":""}]},{"id":"s34-101","number":101,"surah":34,"verses":[31],"references":[{"surah":34,"verses":[31]}],"verseLabel":"سبأ: 31","question":"ما سر حذف جواب ﴿لو﴾ في قوله: ﴿ولو ترى إذ الظالمون موقوفون عند ربهم﴾؟","answer":"حُذف الجواب ليذهب ذهن السامع كل مذهب في تصور هول المشهد؛ فكل جواب محدد سيحصر المعنى في صورة واحدة، أما الحذف فيفتح أمام الخيال ما لا يحيط به وصف من الفزع والتلاوم والعقوبة. لذلك يكون الحذف هنا أبلغ في التعظيم والتهويل.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: سبأ 31 – حذف جواب لو، مبحث «حذف الجواب للتعظيم».","url":""}]},{"id":"s34-102","number":102,"surah":34,"verses":[38],"references":[{"surah":34,"verses":[38]}],"verseLabel":"سبأ: 38","question":"ما دلالة المضارع في قوله: ﴿والذين يسعون في آياتنا معاجزين﴾؟","answer":"يصور المضارع المزاولة والاستمرار في مقاومة الآيات، لا فعلًا وقع وانقضى. ولو قيل «سعوا» لاحتمل أن الساعي أقلع وتاب، أما ﴿يسعون﴾ فتصف من يداوم على هذا المسعى، وهو الذي استحق أن يكون في العذاب محضرًا.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: سبأ 38 – دلالة المضارع يسعون، مبحث «المضارع للمزاولة والاستمرار».","url":""}]},{"id":"s34-103","number":103,"surah":34,"verses":[39],"references":[{"surah":34,"verses":[39]}],"verseLabel":"سبأ: 39","question":"ما دلالة زيادة ﴿له﴾ في قوله: ﴿يبسط الرزق لمن يشاء من عباده ويقدر له﴾؟","answer":"تجعل ﴿له﴾ البسط والتضييق واقعين للشخص نفسه؛ فيوسع الله عليه حينًا ويضيق عليه حينًا آخر. وهذا يلائم قصة سبأ التي بُسط لها الرزق ثم ضُيق عليها بعد الإعراض، بخلاف حذف ﴿له﴾ حيث قد يكون البسط لقوم والتضييق لآخرين.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: سبأ 39 – يبسط الرزق ويقدر له، مبحث «دلالة له في تقدير الرزق».","url":""}]},{"id":"s34-104","number":104,"surah":34,"verses":[42],"references":[{"surah":34,"verses":[42]}],"verseLabel":"سبأ: 42","question":"ما سر تقديم النفع على الضر في قوله: ﴿لا يملك بعضكم لبعض نفعًا ولا ضرًا﴾؟","answer":"تقدم قبلها ما يدل على النفع ثم الضر: ﴿يبسط الرزق… ويقدر له﴾؛ فالبسط نفع والتقدير تضييق. لذلك جاء الترتيب هنا ﴿نفعًا ولا ضرًا﴾ موافقًا لترتيب المعاني في السياق، كما يقدم الضر في المواضع التي يسبقه فيها الحديث عن الضر والعذاب.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: سبأ 42 – تقديم النفع على الضر، مبحث «مناسبة ترتيب النفع والضر للسياق».","url":""}]},{"id":"s35-1","number":1,"surah":35,"verses":[1],"references":[{"surah":35,"verses":[1]}],"verseLabel":"فاطر: 1","question":"لماذا افتتحت سورة فاطر بالحمد؟","answer":"لأن السورة تعرض دلائل القدرة والنعم ومصير الخلق، فكان الحمد براعة استهلال تهيئ القلب للاعتراف بالمنعم قبل تفصيل آيات فضله وقدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص542، تحت عنوان «براعة الاستهلال في الافتتاح بالحمد»","url":""}]},{"id":"s35-2","number":2,"surah":35,"verses":[1],"references":[{"surah":35,"verses":[1]}],"verseLabel":"فاطر: 1","question":"ما دلالة قوله عن أجنحة الملائكة: ﴿مَثْنَى وَثُلَاثَ وَرُبَاعَ﴾؟","answer":"يدل على تفاوت الملائكة في عدد الأجنحة؛ فمنهم ذو جناحين أو ثلاثة أو أربعة، وليس المقصود حصر الخلق في هذه الأعداد، بدليل قوله بعده: ﴿يزيد في الخلق ما يشاء﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص547، تحت عنوان «توجيه الدلالة العددية في ﴿مثنى وثلاث ورباع﴾»","url":""}]},{"id":"s35-3","number":3,"surah":35,"verses":[2],"references":[{"surah":35,"verses":[2]}],"verseLabel":"فاطر: 2","question":"لماذا صُوّرت الرحمة في قوله: ﴿مَا يَفْتَحِ اللَّهُ لِلنَّاسِ مِنْ رَحْمَةٍ﴾ بشيء يُفتح؟","answer":"شُبه وصول الرحمة بفتح باب أو خزانة مغلقة؛ فإذا فتحها الله اندفعت إلى الناس ولم يقدر أحد على حبسها، فالصورة تجمع السعة واليسر وانفراد الله بالمنح.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص553، تحت عنوان «بلاغة المجاز والاستعارة في ﴿ما يفتح﴾»","url":""}]},{"id":"s35-43","number":43,"surah":35,"verses":[2],"references":[{"surah":35,"verses":[2]}],"verseLabel":"فاطر: 2","question":"ماذا يفيد تنكير ﴿رَحْمَةٍ﴾ في قوله: ﴿مِنْ رَحْمَةٍ﴾؟","answer":"يعمم كل لون من الرحمة مهما دق أو عظم؛ فأي رحمة يفتحها الله للناس لا يستطيع أحد إمساكها.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص554، تحت عنوان «دلالة التنكير في ﴿رحمة﴾»","url":""}]},{"id":"s35-44","number":44,"surah":35,"verses":[2],"references":[{"surah":35,"verses":[2]}],"verseLabel":"فاطر: 2","question":"ماذا يفيد قوله: ﴿فَلَا مُمْسِكَ لَهَا﴾ بعد فتح الرحمة؟","answer":"يفيد نفي القدرة على حبسها عن جميع الخلق نفيًا قاطعًا؛ فمتى أرسلها الله نفذت ولم يقف في طريقها مانع.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص555، تحت عنوان «دلالة النفي في الجواب: ﴿فلا ممسك لها﴾»","url":""}]},{"id":"s35-4","number":4,"surah":35,"verses":[2],"references":[{"surah":35,"verses":[2]}],"verseLabel":"فاطر: 2","question":"ما دلالة المقابلة بين فتح الرحمة وإمساكها في الآية؟","answer":"تُظهر أن خزائن النفع كلها بيد الله: ما يفتحه لا يقدر أحد على إمساكه، وما يمسكه لا يقدر أحد على إرساله؛ فتُحكم جهتا العطاء والمنع في صورة متقابلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص556، تحت عنوان «توجيه المقابلة المعنوية بين (الفتح) و(الإمساك)»","url":""}]},{"id":"s35-5","number":5,"surah":35,"verses":[3],"references":[{"surah":35,"verses":[3]}],"verseLabel":"فاطر: 3","question":"لماذا جُمع في الحجة بين الخلق والرزق: ﴿خَالِقٍ... يَرْزُقُكُمْ﴾؟","answer":"لأن الخالق هو الذي أوجدهم، والرازق هو الذي يمد حياتهم؛ فاجتماع بدء الوجود واستمراره يثبت كمال افتقارهم إلى الله ويبطل أن يستحق العبادة سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص572، تحت عنوان «نكتة اختصاص صفتي الخالقية والرازقية في إثبات الألوهية»","url":""}]},{"id":"s35-6","number":6,"surah":35,"verses":[5],"references":[{"surah":35,"verses":[5]}],"verseLabel":"فاطر: 5","question":"لماذا سُمّي الشيطان ﴿الْغَرُورُ﴾؟","answer":"لأنه بالغ في خداع الإنسان وتزيين الباطل حتى صار كأنه الخداع نفسه؛ فصيغة الوصف تحذر من كثرة تغريره، ولا سيما حين يمني العاصي بعفو الله ليجرئه على الذنب.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص599–600، تحت عنوان «علة التعبير بـ﴿الغرور﴾»","url":""}]},{"id":"s35-7","number":7,"surah":35,"verses":[6],"references":[{"surah":35,"verses":[6]}],"verseLabel":"فاطر: 6","question":"لماذا قيل: ﴿فَاتَّخِذُوهُ عَدُوًّا﴾ مع أن الشيطان عدو بالفعل؟","answer":"لأن المطلوب ألا تبقى عداوته معلومة في الذهن فحسب، بل أن يعامله الإنسان معاملة العدو فيحذره ويخالفه؛ فالتعبير بالاتخاذ ينقل العلم إلى موقف عملي دائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص609–610، تحت عنوان «علة التعبير بالأخذ»","url":""}]},{"id":"s35-8","number":8,"surah":35,"verses":[8],"references":[{"surah":35,"verses":[8]}],"verseLabel":"فاطر: 8","question":"لماذا قيل في صاحب العمل السيئ: ﴿فَرَآهُ حَسَنًا﴾ ولم يقل: فظنه حسنًا؟","answer":"لأن تزيين الباطل بلغ منه مبلغ اليقين الراسخ حتى صار يعتقد قبحه جمالًا كأنه يراه بعينه؛ فالرؤية هنا قلبية لكنها تصور شدة انخداعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص643–644، تحت عنوان «علة التعبير بالرؤية»","url":""}]},{"id":"s35-45","number":45,"surah":35,"verses":[8],"references":[{"surah":35,"verses":[8]}],"verseLabel":"فاطر: 8","question":"لماذا حُذف خبر ﴿أَفَمَنْ زُيِّنَ لَهُ سُوءُ عَمَلِهِ﴾؟","answer":"لأن المقابِل مفهوم من السياق: أفهذا كمن عرف الحق ورأى القبيح قبيحًا؟ وحذف الجواب يفتح الذهن لتقدير كل وجوه المفارقة، ويقرر أن الفريقين لا يستويان.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص645–646، تحت عنوان «سر حذف الخبر في الاستفهام»","url":""}]},{"id":"s35-9","number":9,"surah":35,"verses":[8],"references":[{"surah":35,"verses":[8]}],"verseLabel":"فاطر: 8","question":"ما سرّ جمع ﴿حَسَرَاتٍ﴾ في قوله ﴿فَلَا تَذْهَبْ نَفْسُكَ عَلَيْهِمْ حَسَرَاتٍ﴾؟","answer":"الجمع يدل على تضاعف الأسف على أحوالهم وأعمالهم الموجبة للعقوبة. وصيغة جمع القلة تصور أن أدنى تلك الحسرات يكفي لإذهاب النفس، تعظيمًا لرحمة الرسول ﷺ وحرصه على هداية قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص655–656، تحت عنوان «نكتة إيراد الجمع جمع قلة في ﴿حسرات﴾»","url":""}]},{"id":"s35-10","number":10,"surah":35,"verses":[9],"references":[{"surah":35,"verses":[9]}],"verseLabel":"فاطر: 9","question":"لماذا قيل بعد إحياء الأرض: ﴿كَذَلِكَ النُّشُورُ﴾؟","answer":"لأن إحياء الأرض بعد موتها مشهد محسوس يقاس عليه بعث الأجساد؛ فالذي أعاد الحياة إلى التراب بالنبات قادر على إخراج الموتى من قبورهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص677، تحت عنوان «دلالة الكاف في قوله ﴿كذلك﴾»","url":""}]},{"id":"s35-11","number":11,"surah":35,"verses":[10],"references":[{"surah":35,"verses":[10]}],"verseLabel":"فاطر: 10","question":"لماذا حُذف جواب قوله: ﴿مَنْ كَانَ يُرِيدُ الْعِزَّةَ﴾؟","answer":"لأن ما بعده يدل عليه: من أراد العزة فليطلبها من الله؛ وحذف الجواب يجعل السامع يستحضره بنفسه ويقطع الطريق على طلبها من غير مالكها.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص687، تحت عنوان «سر حذف جواب الشرط»","url":""}]},{"id":"s35-46","number":46,"surah":35,"verses":[10],"references":[{"surah":35,"verses":[10]}],"verseLabel":"فاطر: 10","question":"ماذا يفيد تقديم ﴿فَلِلَّهِ﴾ في قوله: ﴿فَلِلَّهِ الْعِزَّةُ﴾؟","answer":"يفيد اختصاص العزة الحقيقية بالله؛ فهو مالكها ومصدرها، ولا ينالها أحد إلا بطاعته والانتساب إلى جانبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص688، تحت عنوان «نكتة تقديم الجار والمجرور»","url":""}]},{"id":"s35-47","number":47,"surah":35,"verses":[10],"references":[{"surah":35,"verses":[10]}],"verseLabel":"فاطر: 10","question":"ماذا تضيف كلمة ﴿جَمِيعًا﴾ في قوله: ﴿فَلِلَّهِ الْعِزَّةُ جَمِيعًا﴾؟","answer":"تنفي أن يكون لغير الله جزء مستقل من العزة؛ فكل أنواعها ودرجاتها له، وما يظهر عند الخلق فمن عطائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص689، تحت عنوان «علة التعبير بـ﴿جميعًا﴾»","url":""}]},{"id":"s35-12","number":12,"surah":35,"verses":[10],"references":[{"surah":35,"verses":[10]}],"verseLabel":"فاطر: 10","question":"لماذا عبّر عن وصول الكلم الطيب إلى الله بالصعود: ﴿إِلَيْهِ يَصْعَدُ الْكَلِمُ الطَّيِّبُ﴾؟","answer":"لأن الصعود يناسب شرف الكلمة وقبولها وبلوغها محل الرضا؛ فصُور القول الطيب كشيء كريم يرتقي ولا يضيع.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص691، تحت عنوان «علة التعبير بالصعود»","url":""}]},{"id":"s35-48","number":48,"surah":35,"verses":[10],"references":[{"surah":35,"verses":[10]}],"verseLabel":"فاطر: 10","question":"لماذا عبّر عن أثر العمل الصالح بقوله: ﴿وَالْعَمَلُ الصَّالِحُ يَرْفَعُهُ﴾؟","answer":"لأن الرفع انتقال إلى الأعلى، فكُني به عن قبول العمل ورفعة صاحبه؛ فكما يصعد الكلم الطيب بصاحبه إلى مقام القبول، يرفعه العمل الصالح منزلةً وعزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص695، تحت عنوان «علة التعبير بالرفع»","url":""}]},{"id":"s35-13","number":13,"surah":35,"verses":[11],"references":[{"surah":35,"verses":[11]}],"verseLabel":"فاطر: 11","question":"ماذا يفيد الانتقال بـ﴿ثُمَّ﴾ من الخلق من تراب إلى الخلق من نطفة؟","answer":"يلفت إلى التفاوت البعيد بين أصل الإنسان الأول من تراب وبين تناسل ذريته من نطفة، ويصور الانتقال العجيب بين مرحلتين مختلفتين من الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص712–713، تحت عنوان «علة التعبير بـ﴿ثم﴾»","url":""}]},{"id":"s35-14","number":14,"surah":35,"verses":[12],"references":[{"surah":35,"verses":[12]}],"verseLabel":"فاطر: 12","question":"لماذا قال بعد نفي استواء البحرين: ﴿وَمِنْ كُلٍّ تَأْكُلُونَ لَحْمًا طَرِيًّا﴾؟","answer":"ليبين أن اختلاف العذب والملح لا يمنع اشتراكهما في منافع سخرها الله؛ فمن كل واحد يأتي الطعام والحلية، فتجتمع دقة التمييز وسعة الانتفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص740، تحت عنوان «دلالة التعبير بالواو في ﴿ومن كل﴾»","url":""}]},{"id":"s35-15","number":15,"surah":35,"verses":[12],"references":[{"surah":35,"verses":[12]}],"verseLabel":"فاطر: 12","question":"لماذا أُدخل قوله: ﴿لِتَبْتَغُوا مِنْ فَضْلِهِ﴾ في مشهد الفلك المواخر؟","answer":"لأن شق السفن للبحر ليس منظر قدرة فحسب، بل نعمة تمكّن الناس من السفر والتجارة وطلب الرزق؛ فأُدمج الامتنان بمصالحهم في أثناء عرض الآية الكونية.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص750، تحت عنوان «بلاغة الإدماج في الآية»","url":""}]},{"id":"s35-16","number":16,"surah":35,"verses":[13],"references":[{"surah":35,"verses":[13]}],"verseLabel":"فاطر: 13","question":"لماذا ضُرب القطمير مثلًا لما لا تملكه المعبودات من دون الله؟","answer":"لأن القطمير قشرة رقيقة جدًا على نواة التمر لا تكاد تُذكر؛ فنفي ملكه يصور عجز تلك المعبودات عن أدنى شيء، فضلًا عن جلب نفع أو دفع ضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص779–780، تحت عنوان «سر اختيار القطمير دون غيره»","url":""}]},{"id":"s35-17","number":17,"surah":35,"verses":[14],"references":[{"surah":35,"verses":[14]}],"verseLabel":"فاطر: 14","question":"لماذا سُمّي تبرؤ المعبودات يوم القيامة ﴿كفرًا﴾ بشرك عابديها؟","answer":"لأنها تنكر عبادتهم وتتبرأ منها وتبطل نسبتهم الشراكة إليها؛ فالتعبير بالكفر يصور الرفض التام لما كانوا يثبتونه لها في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص791، تحت عنوان «سر التعبير بالكفر في قوله: ﴿يكفرون بشرككم﴾»","url":""}]},{"id":"s35-18","number":18,"surah":35,"verses":[15],"references":[{"surah":35,"verses":[15]}],"verseLabel":"فاطر: 15","question":"لماذا أتبع وصف الله بـ﴿الْغَنِيُّ﴾ وصفه بـ﴿الْحَمِيدُ﴾؟","answer":"ليبين أن غناه ليس غنى منع وجفاء؛ فهو مع استغنائه عن الخلق محمود في عطائه وتدبيره، يمنحهم من فضله ويستحق حمدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص18، تحت عنوان «سر إتباع صفة ﴿الغني﴾ بـ ﴿الحميد﴾»","url":""}]},{"id":"s35-19","number":19,"surah":35,"verses":[18],"references":[{"surah":35,"verses":[18]}],"verseLabel":"فاطر: 18","question":"ماذا يضيف قوله: ﴿وَإِنْ تَدْعُ مُثْقَلَةٌ إِلَى حِمْلِهَا لَا يُحْمَلْ مِنْهُ شَيْءٌ﴾ بعد ﴿وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى﴾؟","answer":"ينقل القاعدة إلى مشهد حي: نفس أثقلتها الذنوب تستغيث بمن يحمل عنها فلا تجد من يأخذ شيئًا؛ فيتحول نفي انتقال الوزر إلى صورة محسوسة لشدة الحاجة والعجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص38–39، تحت عنوان «بلاغة ذكر ﴿وإن تدع مثقلة إلى حملها﴾ بعد الجملة السابقة»","url":""}]},{"id":"s35-49","number":49,"surah":35,"verses":[18],"references":[{"surah":35,"verses":[18]}],"verseLabel":"فاطر: 18","question":"لماذا قيل فيمن يُدعى لحمل الذنب: ﴿وَلَوْ كَانَ ذَا قُرْبَى﴾؟","answer":"لأن القريب أرجى الناس للنصرة في الدنيا؛ فإذا لم يحمل يوم القيامة شيئًا عن قريبه، كان غيره أولى بالعجز، وظهر أن كل نفس مرهونة بعملها.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص43–44، تحت عنوان «دلالة (لو) في قوله: ﴿ولو كان ذا قربى﴾»","url":""}]},{"id":"s35-20","number":20,"surah":35,"verses":[19,20,21,22],"references":[{"surah":35,"verses":[19,20,21,22]}],"verseLabel":"فاطر: 19-22","question":"لماذا رُتبت أمثال المؤمن والكافر من الأعمى والبصير حتى الأحياء والأموات بهذا التدرج؟","answer":"بدأت بآلة الإدراك: البصر والعمى، ثم بما لا تتم الرؤية إلا به: النور والظلمات، ثم بمآلهما: الظل المريح والحرور المتعب، وانتهت بما هو أبلغ: الحياة والموت؛ فتترقى المفارقة حتى تجعل الإيمان حياة والكفر موتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص74، تحت عنوان «بلاغة ترتيب التمثيلات»","url":""}]},{"id":"s35-21","number":21,"surah":35,"verses":[19,20,21,22],"references":[{"surah":35,"verses":[19,20,21,22]}],"verseLabel":"فاطر: 19-22","question":"لماذا تكررت ﴿لَا﴾ في المقابلات: ﴿وَلَا الظُّلُمَاتُ وَلَا النُّورُ وَلَا الظِّلُّ وَلَا الْحَرُورُ﴾؟","answer":"لتستقل كل مقابلة بنفيها ويتأكد امتناع التسوية في كل وجه؛ فلا يلتبس الهدى بالضلال ولا الراحة بالعذاب، كما لا يستوي البصير والأعمى.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص65، تحت عنوان «براعة تكرار حرف النفي (لا)»","url":""}]},{"id":"s35-50","number":50,"surah":35,"verses":[19,20,21,22],"references":[{"surah":35,"verses":[19,20,21,22]}],"verseLabel":"فاطر: 19-22","question":"لماذا أُعيدت عبارة ﴿وَمَا يَسْتَوِي﴾ قبل الأحياء والأموات؟","answer":"لأن المقابلة الأخيرة أبلغ من سابقاتها وتمثل خلاصة مستقلة: المؤمن حي القلب والكافر ميت القلب؛ فأعيد نفي الاستواء لتوكيدها وإبراز انتقال الكلام إلى ذروة التمثيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص70، تحت عنوان «نكتة تكرار نفي الاستواء»","url":""}]},{"id":"s35-22","number":22,"surah":35,"verses":[24],"references":[{"surah":35,"verses":[24]}],"verseLabel":"فاطر: 24","question":"ماذا يفيد القصر في قوله: ﴿وَإِنْ مِنْ أُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرٌ﴾؟","answer":"يفيد أن إرسال النذر سنة شملت الأمم كلها؛ فلم تُترك أمة بلا من يقيم عليها الحجة ويدعوها إلى الهدى، وفي ذلك تسلية للنبي ﷺ بأن رسالته امتداد لسنة الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص91، تحت عنوان «بلاغة القصر وغرضه»","url":""}]},{"id":"s35-51","number":51,"surah":35,"verses":[24],"references":[{"surah":35,"verses":[24]}],"verseLabel":"فاطر: 24","question":"ما الصورة في قوله عن النذير: ﴿خَلَا فِيهَا﴾؟","answer":"أصل الخلو فراغ المكان، فنُقل إلى مضي النذير في الأمة وانقضاء عهده؛ وفيه تصوير الرسالة السابقة بأمر تحقق واستقر في تاريخ الأمم، لا بخبر مستبعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص92، تحت عنوان «بلاغة المجاز في لفظ ﴿خلا﴾»","url":""}]},{"id":"s35-23","number":23,"surah":35,"verses":[27],"references":[{"surah":35,"verses":[27]}],"verseLabel":"فاطر: 27","question":"لماذا تكرر ذكر ﴿أَلْوَانُهَا﴾ في الثمرات والجبال والناس والدواب والأنعام؟","answer":"ليلفت إلى وحدة سنّة التنويع في عوالم متباعدة؛ فالماء واحد وتختلف به الثمرات، وتتنوع خطوط الجبال وألوان الأحياء، فيشهد اختلاف الألوان لوحدة القدرة وحسن التدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص119، تحت عنوان «بلاغة استعمال مفردة الألوان»","url":""}]},{"id":"s35-52","number":52,"surah":35,"verses":[27],"references":[{"surah":35,"verses":[27]}],"verseLabel":"فاطر: 27","question":"لماذا خُصت الجبال بالذكر في مشهد اختلاف الألوان؟","answer":"لأن ألوان الجبال ثابتة ظاهرة على امتدادها، وفي جددها البيض والحمر والغرابيب السود مشهد عظيم لا يخفى؛ فكانت أنسب ما يمثل تنوع ألوان الجماد وجماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص121، تحت عنوان «توجيه تخصيص الجبال بالذكر دون الأرض»","url":""}]},{"id":"s35-24","number":24,"surah":35,"verses":[28],"references":[{"surah":35,"verses":[28]}],"verseLabel":"فاطر: 28","question":"ماذا يفيد القصر في قوله: ﴿إِنَّمَا يَخْشَى اللَّهَ مِنْ عِبَادِهِ الْعُلَمَاءُ﴾؟","answer":"يفيد أن الخشية الكاملة ثمرة العلم بالله وآياته؛ فكلما ازداد العبد معرفة بعظمته وقدرته ازداد خوفًا منه وتعظيمًا له، ولذلك خُص العلماء بهذه المنزلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص133، تحت عنوان «بلاغة الاستئناف بجملة القصر»","url":""}]},{"id":"s35-53","number":53,"surah":35,"verses":[28],"references":[{"surah":35,"verses":[28]}],"verseLabel":"فاطر: 28","question":"لماذا قُدّم اسم الله في قوله: ﴿إِنَّمَا يَخْشَى اللَّهَ... الْعُلَمَاءُ﴾؟","answer":"للعناية بالمخشيّ وتعظيمه، ولإبقاء لفظ العلماء في ختام الجملة موضع البيان بعد عرض دلائل القدرة؛ فالمقصود أن العلم بهذه الآيات هو الذي يورث خشية الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص135، تحت عنوان «نكتة تقديم لفظ الجلالة»","url":""}]},{"id":"s35-25","number":25,"surah":35,"verses":[29],"references":[{"surah":35,"verses":[29]}],"verseLabel":"فاطر: 29","question":"لماذا صُوّرت أعمال أهل القرآن بأنها ﴿تِجَارَةً﴾؟","answer":"لأنهم يبذلون التلاوة والصلاة والإنفاق طلبًا لثواب الله، فشُبه عملهم بتجارة يرجو صاحبها الربح؛ غير أن هذه التجارة مضمونة العاقبة مع الله وليست عرضة للخسارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص150، تحت عنوان «بلاغة الاستعارة وفائدتها»","url":""}]},{"id":"s35-54","number":54,"surah":35,"verses":[29],"references":[{"surah":35,"verses":[29]}],"verseLabel":"فاطر: 29","question":"لماذا قيل: ﴿لَنْ تَبُورَ﴾ ولم يقل: لا تبور؟","answer":"لأن ﴿لن﴾ تؤكد نفي الخسران في المستقبل؛ فتطمئنهم إلى أن تجارتهم لا تكسد عند لقاء الله، بل يبقى ربحها ويضاعف جزاؤها.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص150–151، تحت عنوان «سر النفي بـ ﴿لن﴾ دون (لا)»","url":""}]},{"id":"s35-26","number":26,"surah":35,"verses":[30],"references":[{"surah":35,"verses":[30]}],"verseLabel":"فاطر: 30","question":"لماذا قُدّم ﴿غَفُورٌ﴾ على ﴿شَكُورٌ﴾؟","answer":"لأن سلامة العمل من تبعات التقصير تسبق نيل الزيادة في الثواب؛ فبدأ بالمغفرة التي تزيل المانع، ثم بالشكر الذي يضاعف الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص154، تحت عنوان «نكتة تقديم الغفور على الشكور»","url":""}]},{"id":"s35-27","number":27,"surah":35,"verses":[32],"references":[{"surah":35,"verses":[32]}],"verseLabel":"فاطر: 32","question":"إلى من يعود الضمير في قوله: ﴿فَمِنْهُمْ ظَالِمٌ لِنَفْسِهِ﴾ بعد ﴿الَّذِينَ اصْطَفَيْنَا﴾؟","answer":"يعود إلى الذين أورثهم الله الكتاب؛ فحتى الظالم لنفسه لم يخرج من جماعة الأمة المصطفاة، وفي ذلك تحذير من التفريط مع فتح باب الرجاء له بالمغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص173–174، تحت عنوان «نكتة عود الضمير في ﴿فمنهم﴾»","url":""}]},{"id":"s35-55","number":55,"surah":35,"verses":[32],"references":[{"surah":35,"verses":[32]}],"verseLabel":"فاطر: 32","question":"لماذا أُشير إلى السبق بالخيرات بقوله: ﴿ذَلِكَ هُوَ الْفَضْلُ الْكَبِيرُ﴾؟","answer":"أشير إليه باسم البعيد لتعظيم منزلته ورفع شأنه؛ فالسبق ليس ثمرة القدرة البشرية وحدها، بل فضل كبير من الله وإذن منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص179، تحت عنوان «غرض التعبير باسم الإشارة البعيد»","url":""}]},{"id":"s35-28","number":28,"surah":35,"verses":[33],"references":[{"surah":35,"verses":[33]}],"verseLabel":"فاطر: 33","question":"ماذا يوحي قوله عن أهل الجنة: ﴿يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ﴾؟","answer":"يوحي بأن التحلية تُجرى عليهم تكريمًا وخدمة، لا أنهم يتكلفونها بأنفسهم؛ فالمشهد مشهد إكرام متجدد في دار النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص188، تحت عنوان «دلالة التعبير بقوله ﴿يحلون﴾»","url":""}]},{"id":"s35-29","number":29,"surah":35,"verses":[33],"references":[{"surah":35,"verses":[33]}],"verseLabel":"فاطر: 33","question":"لماذا قُدمت حلي الأساور على لباس الحرير في وصف نعيم الجنة؟","answer":"لأن الحلي زيادة تجمل فوق أصل اللباس، فبدء الوصف بها أسرع في إظهار الترف والتكريم، ثم ذُكر الحرير لباسًا دائمًا يحيط بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص193، تحت عنوان «بلاغة تقديم تحلية الأساور على اللباس»","url":""}]},{"id":"s35-30","number":30,"surah":35,"verses":[34],"references":[{"surah":35,"verses":[34]}],"verseLabel":"فاطر: 34","question":"ما سرّ التعبير في قول أهل الجنة ﴿الَّذِي أَذْهَبَ عَنَّا الْحَزَنَ﴾ معرفًا؟","answer":"التعريف للاستغراق، فيشمل كل فرد من أفراد الحزن؛ فلا يصيبهم منه شيء بعد دخول الجنة. ومن أعظم ما زال حزن الخوف من سوء العاقبة، كما تزول هموم الدنيا ومتاعبها كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص200، تحت عنوان «معنى (أل) في لفظ ﴿الحزن﴾»","url":""}]},{"id":"s35-31","number":31,"surah":35,"verses":[35],"references":[{"surah":35,"verses":[35]}],"verseLabel":"فاطر: 35","question":"لماذا أعيدت عبارة ﴿وَلَا يَمَسُّنَا﴾ مع ﴿لُغُوبٌ﴾؟","answer":"ليستقل نفي كل نوع من التعب ويتأكد: فلا يلحقهم نصب أثناء العمل، ولا لغوب أو إعياء بعده؛ وإعادة الفعل تصور انتفاءهما التام والدائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص207–208، تحت عنوان «نكتة إعادة ذكر ﴿ولا يمسنا﴾»","url":""}]},{"id":"s35-32","number":32,"surah":35,"verses":[36],"references":[{"surah":35,"verses":[36]}],"verseLabel":"فاطر: 36","question":"لماذا قيل عن أهل النار: ﴿لَا يُقْضَى عَلَيْهِمْ فَيَمُوتُوا وَلَا يُخَفَّفُ عَنْهُمْ مِنْ عَذَابِهَا﴾؟","answer":"لأن انقطاع الحياة راحة من الألم، وتخفيف العذاب راحة مع البقاء؛ فنفت الآية الطريقين معًا، فلا موت ينهي عذابهم ولا تخفيف يهون استمراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص221، تحت عنوان «فائدة ذكر جملة نفي التخفيف بعد نفي الموت»","url":""}]},{"id":"s35-33","number":33,"surah":35,"verses":[37],"references":[{"surah":35,"verses":[37]}],"verseLabel":"فاطر: 37","question":"ما غرض السؤال: ﴿أَوَلَمْ نُعَمِّرْكُمْ مَا يَتَذَكَّرُ فِيهِ مَنْ تَذَكَّرَ﴾؟","answer":"هو توبيخ يقطع عذرهم؛ فقد مُنحوا عمرًا كافيًا للتفكر والرجوع، فلم تكن خسارتهم من ضيق الفرصة بل من إضاعة ما أمهلوا فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص228، تحت عنوان «بلاغة الاستفهام ونوعه وغرضه»","url":""}]},{"id":"s35-56","number":56,"surah":35,"verses":[37],"references":[{"surah":35,"verses":[37]}],"verseLabel":"فاطر: 37","question":"لماذا عبّر عن إمهالهم بقوله: ﴿نُعَمِّرْكُمْ﴾؟","answer":"لأن التعمير منح مدة ممتدة تتكرر فيها فرص التذكر؛ فكلما طال العمر قويت الحجة على من بقي معرضًا حتى جاءه النذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص229، تحت عنوان «دلالة التعبير بـجملة ﴿نعمركم﴾»","url":""}]},{"id":"s35-34","number":34,"surah":35,"verses":[39],"references":[{"surah":35,"verses":[39]}],"verseLabel":"فاطر: 39","question":"لماذا قيل للناس: ﴿جَعَلَكُمْ خَلَائِفَ فِي الْأَرْضِ﴾؟","answer":"لأن الأجيال يخلف بعضها بعضًا في عمارة الأرض والتصرف فيها؛ فاللفظ يجمع نعمة التمكين ومسؤولية الاختبار، وينبه كل جيل إلى أنه راحل وسيأتي بعده غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص251، تحت عنوان «غرض استعمال مفردة ﴿خلائف﴾»","url":""}]},{"id":"s35-35","number":35,"surah":35,"verses":[40],"references":[{"surah":35,"verses":[40]}],"verseLabel":"فاطر: 40","question":"لماذا تتابعت الأسئلة في إبطال الشرك من خلق الأرض إلى الشركة في السماء ثم الدليل من كتاب؟","answer":"لإحاطة كل دعاوى الشرك بالإبطال: سأل أولًا عن أثر محسوس خلقته الآلهة في الأرض، ثم عن نصيب لها في السماوات، ثم عن كتاب من الله يجيز عبادتها؛ فلما عجزوا عن الخلق والملك والحجة انكشف بطلانها كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص282، تحت عنوان «دلالات الاستفهام المتوالي»","url":""}]},{"id":"s35-36","number":36,"surah":35,"verses":[41],"references":[{"surah":35,"verses":[41]}],"verseLabel":"فاطر: 41","question":"ما الصورة في قوله: ﴿إِنَّ اللَّهَ يُمْسِكُ السَّمَاوَاتِ وَالْأَرْضَ أَنْ تَزُولَا﴾؟","answer":"صُورت السماوات والأرض كجسمين عظيمين يوشكان أن ينفصلا أو يسقطا، والله يمسكهما بقدرته؛ فتقرب الصورة حفظ النظام الكوني المستمر من غير دعامة يراها الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص293، تحت عنوان «بلاغة الاستعارة»","url":""}]},{"id":"s35-57","number":57,"surah":35,"verses":[41],"references":[{"surah":35,"verses":[41]}],"verseLabel":"فاطر: 41","question":"لماذا جاء إمساك السماوات والأرض بصيغة المضارع ﴿يُمْسِكُ﴾؟","answer":"ليصور الحفظ فعلًا متجددًا مستمرًا في كل لحظة؛ فبقاء الكون منوط دائمًا بقدرة الله، لا بفعل وقع ثم انقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص293–294، تحت عنوان «نكتة التعبير بالمضارع»","url":""}]},{"id":"s35-37","number":37,"surah":35,"verses":[43],"references":[{"surah":35,"verses":[43]}],"verseLabel":"فاطر: 43","question":"ما الصورة التي ترسمها كلمة ﴿يَحِيقُ﴾ في قوله: ﴿وَلَا يَحِيقُ الْمَكْرُ السَّيِّئُ إِلَّا بِأَهْلِهِ﴾؟","answer":"ترسم المكر كشيء يحيط بصاحبه وينزل به من كل جانب؛ فمن دبر السوء لغيره ارتد تدبيره عليه حتى صار هو المحاصر بنتيجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص326، تحت عنوان «بلاغة استعمال مفردة ﴿يحيق﴾ مادة وصيغة»","url":""}]},{"id":"s35-58","number":58,"surah":35,"verses":[43],"references":[{"surah":35,"verses":[43]}],"verseLabel":"فاطر: 43","question":"ماذا يفيد القصر في قوله: ﴿وَلَا يَحِيقُ الْمَكْرُ السَّيِّئُ إِلَّا بِأَهْلِهِ﴾؟","answer":"يفيد أن العاقبة الملازمة للمكر السيئ راجعة إلى أصحابه؛ فقد يصيب أذاهم غيرهم مؤقتًا، لكن وباله المستقر لا يفلت منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص328، تحت عنوان «بلاغة القصر ودلالته»","url":""}]},{"id":"s35-38","number":38,"surah":35,"verses":[43],"references":[{"surah":35,"verses":[43]}],"verseLabel":"فاطر: 43","question":"ماذا يفيد نفي ﴿التَّبْدِيلِ﴾ عن سنة الله؟","answer":"يفيد أن سنة الله لا تستبدل بسنة أخرى تخالفها؛ فلا تتحول عاقبة المكذبين إلى نجاة مع بقاء أسبابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص335، تحت عنوان «نكتة استعمال (التبديل) وتنكيرها»","url":""}]},{"id":"s35-59","number":59,"surah":35,"verses":[43],"references":[{"surah":35,"verses":[43]}],"verseLabel":"فاطر: 43","question":"ماذا يضيف نفي ﴿التَّحْوِيلِ﴾ بعد نفي التبديل؟","answer":"ينفي أن تُصرف السنة نفسها عن مستحقها أو تُحوّل إلى غير موضعها؛ فليس هناك قانون بديل، ولا مهرب بتحويل مجراه عن المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص336، تحت عنوان «نكتة استعمال (التحويل) وتنكيرها»","url":""}]},{"id":"s35-39","number":39,"surah":35,"verses":[44],"references":[{"surah":35,"verses":[44]}],"verseLabel":"فاطر: 44","question":"ما أثر الجمع بين قوله عن السابقين: ﴿كَانُوا أَشَدَّ مِنْهُمْ قُوَّةً﴾ وختم الآية: ﴿وَمَا كَانَ اللَّهُ لِيُعْجِزَهُ مِنْ شَيْءٍ﴾؟","answer":"يبدأ المشهد بقوة الأمم التي توهم المنعة، ثم ينتهي بنفي أن يعجز الله شيء؛ فتلتقي بدايته ونهايته لتبين أن أشد قوة بشرية لا تخرج عن قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص354–355، تحت عنوان «بلاغة تشابه الأطراف»","url":""}]},{"id":"s35-40","number":40,"surah":35,"verses":[45],"references":[{"surah":35,"verses":[45]}],"verseLabel":"فاطر: 45","question":"لماذا قيل: ﴿وَلَوْ يُؤَاخِذُ اللَّهُ النَّاسَ بِمَا كَسَبُوا﴾ ولم يقل: المشركين؟","answer":"لأن التقصير والكسب السيئ لا يختصان بالمشركين؛ فلفظ الناس يعمهم ويذكر الجميع بأن بقاءهم قائم على حلم الله، لا على استحقاق السلامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص362، تحت عنوان «نكتة استعمال لفظ ﴿الناس﴾ دون (المشركين)»","url":""}]},{"id":"s35-60","number":60,"surah":35,"verses":[45],"references":[{"surah":35,"verses":[45]}],"verseLabel":"فاطر: 45","question":"ماذا يفيد قوله: ﴿مِنْ دَابَّةٍ﴾ في ﴿مَا تَرَكَ عَلَى ظَهْرِهَا مِنْ دَابَّةٍ﴾؟","answer":"يفيد العموم المؤكد: لو جرت المؤاخذة العاجلة لاستأصل أثرها كل دابة على الأرض، لا الإنسان وحده؛ فيظهر اتساع أثر الذنوب وعظم الحلم الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص365، تحت عنوان «دلالة العموم في قيد ﴿من دابة﴾»","url":""}]},{"id":"s35-41","number":41,"surah":35,"verses":[45],"references":[{"surah":35,"verses":[45]}],"verseLabel":"فاطر: 45","question":"لماذا حُذف جواب الشرط في ختام السورة: ﴿فَإِذَا جَاءَ أَجَلُهُمْ فَإِنَّ اللَّهَ كَانَ بِعِبَادِهِ بَصِيرًا﴾؟","answer":"لأن الجملة الأخيرة تدل عليه: إذا جاء الأجل جازاهم الله بما عملوا؛ فحذف الجزاء يجعله مهيبًا مفتوحًا على ما يقتضيه علم الله التام من ثواب وعقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص370، تحت عنوان «بلاغة حذف جواب الشرط»","url":""}]},{"id":"s35-61","number":61,"surah":35,"verses":[45],"references":[{"surah":35,"verses":[45]}],"verseLabel":"فاطر: 45","question":"لماذا قيل: ﴿كَانَ بِعِبَادِهِ بَصِيرًا﴾ بصيغة الماضي؟","answer":"للدلالة على أن إحاطته بأعمال عباده صفة قديمة ثابتة لم تبدأ عند مجيء أجلهم؛ فهو كان ولا يزال بصيرًا بهم، ولذلك لا يضيع عند الجزاء شيء من أعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص371، تحت عنوان «سر ذكر فعل الكون الماضي»","url":""}]},{"id":"s35-42","number":42,"surah":35,"verses":[45],"references":[{"surah":35,"verses":[45]}],"verseLabel":"فاطر: 45","question":"لماذا قيل في فاطر: ﴿عَلَى ظَهْرِهَا مِنْ دَابَّةٍ﴾، وفي النحل: ﴿عَلَيْهَا مِنْ دَابَّةٍ﴾؟","answer":"في فاطر سبق مشهد ظاهر الأرض من ألوان الجبال، فناسب ذكر ﴿ظهرها﴾ وخصّ الظاهر مع سياق المعاصي؛ أما النحل فالسياق في الظلم والشرك الأعم، فجيء بالضمير ﴿عليها﴾ ليشمل الأرض كلها من غير تخصيص ظاهرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص364–365، تحت عنوان «توجيه المتشابه اللفظي في (الإظهار والإضمار)»","url":""}]},{"id":"s35-62","number":62,"surah":35,"verses":[2,45],"references":[{"surah":35,"verses":[2,45]}],"verseLabel":"فاطر: 2، 45","question":"ما السر في أن تُفتتح السورة برحمة لا يستطيع أحد إمساكها، ثم تُختتم بتأخير العقوبة عن الناس؟","answer":"يكشف ختام السورة صورة عملية للرحمة المذكورة في أولها؛ فلو عوجل الناس بجميع ما كسبوا لم تبق دابة، لكن العقوبة أُخّرت. ودخول لو يفيد امتناع المؤاخذة العامة لوجود رحمة الله، فكأن خاتمة السورة برهان على قوله: ﴿مَا يَفْتَحِ اللَّهُ لِلنَّاسِ مِنْ رَحْمَةٍ فَلَا مُمْسِكَ لَهَا﴾.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «تناسب فواتح سورة فاطر مع خواتيمها»، الفقرة الخاصة بالآيتين 2 و45.","url":""}]},{"id":"s35-63","number":63,"surah":35,"verses":[4,44],"references":[{"surah":35,"verses":[4,44]}],"verseLabel":"فاطر: 4، 44","question":"كيف يحوّل ختام السورة تسلية الرسول في قوله ﴿فَقَدْ كُذِّبَتْ رُسُلٌ مِنْ قَبْلِكَ﴾ إلى حجة مخيفة للمكذبين؟","answer":"أجمل مطلع السورة سنّة التكذيب التي لقيها الرسل، ثم جاء قرب الختام ما يكشف عاقبة المكذبين: ﴿فَيَنْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِنْ قَبْلِهِمْ﴾. فالعلاقة إكمال وبيان: من سار في طريق الأمم المكذبة فليتأمل نهايتها، مهما بلغت قوته.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «تناسب فواتح سورة فاطر مع خواتيمها»، الفقرة الخاصة بالآيتين 4 و44.","url":""}]},{"id":"s35-64","number":64,"surah":35,"verses":[9],"references":[{"surah":35,"verses":[9]}],"verseLabel":"فاطر: 9","question":"ما سر الانتقال من الماضي ﴿أَرْسَلَ﴾ إلى المضارع ﴿فَتُثِيرُ﴾، ثم العودة إلى الماضي ﴿فَسُقْنَاهُ﴾؟","answer":"الأحداث كلها واقعة في نسق واحد، لكن إثارة الرياح للسحاب هي موطن الحركة والمشهد الحي؛ فجيء لها بالمضارع ليستحضر السامع السحاب وهو يتكوّن ويتحرك أمامه. ثم عاد التعبير إلى الماضي في ﴿فَسُقْنَاهُ﴾ بعد اكتمال الصورة المتحركة، وهذا من حكاية الحال.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: سورة فاطر، «دلالة اختلاف صيغة الأفعال بين الماضي والمضارع»، مبحث الآية 9.","url":""}]},{"id":"s35-65","number":65,"surah":35,"verses":[10],"references":[{"surah":35,"verses":[10]}],"verseLabel":"فاطر: 10","question":"كيف جمع رفعُ ﴿الْعَمَلُ الصَّالِحُ﴾ بين معنيين لا يؤديهما النصب؟","answer":"رفعُ ﴿العملُ الصالحُ﴾ يفتح احتمالين صحيحين: أن العمل الصالح يرفع الكلم الطيب، وأن الله يرفع العمل الصالح؛ لأن ضمير ﴿يرفعه﴾ يحتمل عوده على الكلم، ويحتمل أن يكون الفاعل المستتر عائدًا إلى الله. أما نصب «العملَ الصالحَ» فيحصر المعنى في أن الله يرفعه، فضاعت سعة الدلالة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص57، مبحث «التوسع في المعنى في قوله: ﴿والعمل الصالح يرفعه﴾»؛ وانظر المقطع المباشر: باحث: «إليه يصعد الكلم الطيب والعمل الصالح يرفعه».","url":""}]},{"id":"s35-66","number":66,"surah":35,"verses":[12],"references":[{"surah":35,"verses":[12]}],"verseLabel":"فاطر: 12","question":"ما دلالة تقديم ﴿فِيهِ﴾ في فاطر: ﴿وَتَرَى الْفُلْكَ فِيهِ مَوَاخِرَ﴾، وتأخيرها في النحل: ﴿وَتَرَى الْفُلْكَ مَوَاخِرَ فِيهِ﴾؟","answer":"سياق فاطر منصبّ على البحرين وخصائصهما، فقدم ضمير البحر ﴿فيه﴾ ليبقى محور الكلام متصلًا بما قبله. أما سياق النحل فسبق فيه تعداد وسائل النقل من الأنعام والخيل والبغال والحمير، فقدم وصف السفن ﴿مواخر﴾ وألصقه بها؛ لأن موطن العناية هناك وسيلة النقل.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: سورة فاطر، «دلالة التقديم والتأخير في وترى الفلك»، مبحث الآية 12.","url":""}]},{"id":"s35-67","number":67,"surah":35,"verses":[25],"references":[{"surah":35,"verses":[25]}],"verseLabel":"فاطر: 25","question":"ما دلالة مجيء التكذيب مضارعًا في ﴿وَإِنْ يُكَذِّبُوكَ﴾، مع وروده ماضيًا في آل عمران: ﴿فَإِنْ كَذَّبُوكَ﴾؟","answer":"المضارع في فعل الشرط يصور التكذيب أمرًا متجددًا مستمرًا، وهو الملائم لمقام فاطر الذي يعرض سنّة المكذبين عبر الزمن. أما الماضي في آل عمران فمتصل بحادثة تاريخية معينة سبق ذكرها، فناسبه الدلالة على وقوع الحدث، لا على استمراره وتجدد صورته.","sources":[{"label":"فاضل السامرائي، لمسات بيانية، ج1، ص536، مبحث «مقام التوكيد في سورة فاطر»؛ النص المباشر في المكتبة القرآنية.","url":""}]},{"id":"s35-68","number":68,"surah":35,"verses":[28],"references":[{"surah":35,"verses":[28]}],"verseLabel":"فاطر: 28","question":"كيف يمنع ضبطُ كلمتي ﴿اللَّهَ﴾ و﴿الْعُلَمَاءُ﴾ انقلابَ المعنى، وما سر القصر بـ﴿إِنَّمَا﴾؟","answer":"لفظ الجلالة منصوب مفعول به، و﴿العلماءُ﴾ فاعل مؤخر مرفوع؛ فالعلماء هم الذين يخشون الله. و﴿إنما﴾ تقصر الخشية الحقة عليهم؛ لأن معرفتهم بقدرة الله وعظمته تجعل خشيتهم أتم من خشية الجاهل، فكلما رسخ العلم بالله عظمت الخشية منه.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: سورة فاطر، «المعنى الإعرابي لقوله إنما يخشى الله من عباده العلماء»، مبحث الآية 28.","url":""}]},{"id":"s35-69","number":69,"surah":35,"verses":[29],"references":[{"surah":35,"verses":[29]}],"verseLabel":"فاطر: 29","question":"ما دلالة ترتيب الأفعال: ﴿يَتْلُونَ﴾ ثم ﴿أَقَامُوا﴾ ثم ﴿أَنْفَقُوا﴾، والعدول من المضارع إلى الماضي؟","answer":"رُتبت الأعمال بحسب الكثرة والاستمرار: تلاوة الكتاب أوسع؛ فهي في الصلاة وخارجها، ثم الصلاة في أوقاتها، ثم الإنفاق وهو أقل تكرارًا. لذلك بدأ بالمضارع الدال على التجدد في ﴿يتلون﴾، وجاء بالماضي في العملين ذوي الأوقات المحددة، مع بقاء الماضي بعد الموصول صالحًا للدلالة على التحقق والاستقبال.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: سورة فاطر، «دلالة استخدام الفعل الماضي والمضارع»، مبحث الآية 29.","url":""}]},{"id":"s35-70","number":70,"surah":35,"verses":[35],"references":[{"surah":35,"verses":[35]}],"verseLabel":"فاطر: 35","question":"ما دقة الجمع بين نفي ﴿نَصَبٌ﴾ ونفي ﴿لُغُوبٌ﴾، ولماذا تقدم النصب؟","answer":"النَّصَب هو التعب والإعياء، واللُّغوب هو الفتور الذي يعقب التعب؛ فرتبهما التعبير من السبب إلى أثره. وقيل أيضًا: النصب تعب البدن واللغوب تعب النفس، فيكون الجمع نفيًا لكل تعب ظاهر وباطن، لا مجرد نفي نوع واحد من المشقة.","sources":[{"label":"فاضل السامرائي، باحث: «معنى النصب واللغوب»، مقطع مباشر من سلسلة سورة فاطر.","url":""}]},{"id":"s35-71","number":71,"surah":35,"verses":[43],"references":[{"surah":35,"verses":[43]}],"verseLabel":"فاطر: 43","question":"ما سر تكرار الجملة مع تغيير كلمة واحدة: ﴿فَلَنْ تَجِدَ لِسُنَّتِ اللَّهِ تَبْدِيلًا وَلَنْ تَجِدَ لِسُنَّتِ اللَّهِ تَحْوِيلًا﴾؟","answer":"ليس التكرار توكيدًا لفظيًا محضًا؛ فـالتبديل نفي أن تُغيّر العقوبة المستحقة إلى شيء آخر أو إلى إكرام، والتحويل نفي أن تُصرف العقوبة عن أهلها إلى قوم آخرين. فسنّة الجزاء لا تتغير في ماهيتها، ولا تنتقل عن مستحقها.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: سورة فاطر، «الحكمة من تكرار التركيب: تبديلًا وتحويلًا»، مبحث الآية 43.","url":""}]},{"id":"s35-72","number":72,"surah":35,"verses":[44],"references":[{"surah":35,"verses":[44]}],"verseLabel":"فاطر: 44","question":"ما الدلالة الخفية للواو في ﴿وَكَانُوا أَشَدَّ مِنْهُمْ قُوَّةً﴾؟","answer":"الواو واو الحال، فالمعنى: لينظروا كيف كانت عاقبة السابقين مع أنهم كانوا أشد منهم قوة. وبذلك لا تضيف الآية خبرًا تاريخيًا فحسب، بل تجعل شدة قوتهم حالًا يزيد العبرة رهبة: القوة التي اغتروا بها لم تمنع عنهم العاقبة.","sources":[{"label":"فاضل السامرائي، باحث: «الواو في الآية: وكانوا أشد منهم قوة»، مقطع مباشر من سلسلة سورة فاطر.","url":""}]},{"id":"s35-73","number":73,"surah":35,"verses":[45],"references":[{"surah":35,"verses":[45]}],"verseLabel":"فاطر: 45","question":"ما سر التعبير بـ﴿بِمَا كَسَبُوا﴾ في فاطر، وبـ﴿بِظُلْمِهِمْ﴾ في آية النحل المشابهة؟","answer":"سياق النحل سبقه وأد البنات، وهو ظلم صريح لا يكون إلا شرًا، فناسبه ﴿بظلمهم﴾. أما فاطر فسياقها في أعمال الأمم، فجاءت بلفظ الكسب الذي يقع في الخير والشر، وإن كان المراد هنا كسب السوء. ثم إن الظلم مصدر مطلق عن الزمن، أما ﴿كسبوا﴾ ففعل ماضٍ مقيد، ولكل منهما ما يلائم سياقه.","sources":[{"label":"فاضل السامرائي، باحث: مقارنة خاتمتي النحل وفاطر، من الدقيقة 1:38 إلى 7:31.","url":""}]},{"id":"s35-74","number":74,"surah":35,"verses":[45],"references":[{"surah":35,"verses":[45]}],"verseLabel":"فاطر: 45","question":"ما سر ختم آية فاطر بـ﴿فَإِنَّ اللَّهَ كَانَ بِعِبَادِهِ بَصِيرًا﴾، وختم نظيرتها في النحل بضبط الأجل: ﴿لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ﴾؟","answer":"سياق فاطر قبل الآية يدور على علم الله وقدرته وصفاته: علم الغيب، والإحاطة بالصدور، وإمساك السماوات والأرض، وعدم إعجاز شيء له؛ فناسبه الختام بصفة البصر المحيط بالعباد. أما سياق النحل فمحوره الناس وأفعالهم وصفاتهم، فناسبه أن يختم بما يقع عليهم عند مجيء أجلهم.","sources":[{"label":"فاضل السامرائي، باحث: مقارنة خاتمتي النحل وفاطر، من الدقيقة 9:42 إلى 13:23.","url":""}]},{"id":"s35-75","number":75,"surah":35,"verses":[10],"references":[{"surah":35,"verses":[10]}],"verseLabel":"فاطر: 10","question":"ما سر التعبير بـ﴿الْكَلِمُ الطَّيِّبُ﴾ بدل «الكلام الطيب»؟","answer":"الكلام هو اللفظ المفيد الذي يتم به المعنى، أما الكَلِم فهو اسم جنس جمعي يدل على ثلاث كلمات فأكثر، سواء تم بها معنى مستقل أم لم يتم. واختيار ﴿الكلم الطيب﴾ أوسع؛ فيشمل أصناف الأقوال الطيبة والذكر والدعاء، ولا يقصر الصعود على جملة تامة بعينها.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «ما الفرق بين الكلم والكلام والقول والقيل؟»، الفقرة الخاصة بفاطر: 10.","url":""}]},{"id":"s35-76","number":76,"surah":35,"verses":[12,19,22],"references":[{"surah":35,"verses":[12,19,22]}],"verseLabel":"فاطر: 12، 19، 22","question":"ما دلالة نفي الاستواء بـ﴿مَا﴾ في البحريْن والأعمى والبصير والأحياء والأموات، مع مجيء ﴿لَا يَسْتَوِي﴾ في مواضع أخرى؟","answer":"الأصل في ما مع المضارع نفي الحال، ولذلك جاءت هنا مع فروق مشاهدة في الدنيا: اختلاف البحرين، والأعمى والبصير، والأحياء والأموات. أما لا فأصلها نفي الاستقبال، وتناسب غالبًا الفروق التي يظهر تمامها في الآخرة، مثل عدم استواء أصحاب النار وأصحاب الجنة.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: سورة فاطر، «دلالة استعمال أداة النفي ما ولا»، مبحث الآية 12 المحيل إلى الآيتين 19 و22.","url":""}]},{"id":"s35-77","number":77,"surah":35,"verses":[12],"references":[{"surah":35,"verses":[12]}],"verseLabel":"فاطر: 12","question":"ما سر حذف الواو من ﴿لِتَبْتَغُوا مِنْ فَضْلِهِ﴾ في فاطر، وإثباتها في آية النحل: ﴿وَلِتَبْتَغُوا﴾؟","answer":"سورة النحل في مقام تعداد النعم؛ فالواو تعطف ابتغاء الفضل على منافع مذكورة وأخرى مقدرة، وكأنها تشير إلى أبواب أخرى من النفع لم تُفصّل. أما فاطر فليس سياقها تعداد النعم على هذا النحو، فجاءت اللام بلا واو متصلة مباشرة بالغرض من جريان الفلك.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: سورة فاطر، «استخدام الواو وعدمه في ولتبتغوا»، مبحث الآية 12.","url":""}]},{"id":"s35-78","number":78,"surah":35,"verses":[18],"references":[{"surah":35,"verses":[18]}],"verseLabel":"فاطر: 18","question":"ما دلالة الجمع بين المضارع ﴿يَخْشَوْنَ رَبَّهُمْ﴾ والماضي ﴿وَأَقَامُوا الصَّلَاةَ﴾ في وصف فريق واحد؟","answer":"الخشية عمل مستمر لا يختص بوقت، فناسبها المضارع الدال على التجدد. أما الصلاة فلها أوقات محددة، فجاءت بصيغة الماضي في صلة الموصول للدلالة على تحقق إقامتها عند وقتها؛ ولذلك يتكرر هذا النسق في التعبير القرآني: مضارع للصفة المستمرة، وماضٍ للعمل المؤقت المحقق.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: سورة فاطر، «اللمسة البيانية في استعمال الأفعال المضارعة والماضية»، مبحث الآية 18.","url":""}]},{"id":"s35-79","number":79,"surah":35,"verses":[31],"references":[{"surah":35,"verses":[31]}],"verseLabel":"فاطر: 31","question":"ما سر الجمع بين ﴿لَخَبِيرٌ﴾ و﴿بَصِيرٌ﴾ في وصف علم الله بعباده؟","answer":"الخبير هو العليم ببواطن الأمور ودقائقها، والبصير يدل على الإحاطة بظواهرها، مع دلالة البصيرة على المعرفة النافذة. فالجمع بينهما يستوعب سرائر العباد وأعمالهم الظاهرة، ويؤكد أن التصديق والاصطفاء المذكورين في السياق واقعان بعلم شامل لا يخفى عليه باطن ولا ظاهر.","sources":[{"label":"فاضل السامرائي، الموسوعة القرآنية، نقلًا عن تدارس: «ما الفرق بين خبير وبصير؟»، الفقرة الخاصة بفاطر: 31.","url":""}]},{"id":"s35-80","number":80,"surah":35,"verses":[37],"references":[{"surah":35,"verses":[37]}],"verseLabel":"فاطر: 37","question":"ما سر اختيار الصيغة الأطول ﴿يَتَذَكَّرُ﴾ في قوله ﴿مَا يَتَذَكَّرُ فِيهِ مَنْ تَذَكَّرَ﴾؟","answer":"صيغة يتذكّر أطول مقاطع من يذّكّر، ويستعملها القرآن حين يكون التذكر ممتدًا محتاجًا إلى زمن. والآية تتحدث عن عمر كامل مُنح للإنسان كي يراجع ويعتبر، فناسب امتداد العمر امتداد الصيغة؛ أما ﴿يذّكّر﴾ فتأتي فيما يحتاج إلى هزة قوية وإيقاظ للقلب.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: سورة فاطر، «الفرق بين يذّكرون ويتذكرون»، مبحث الآية 37.","url":""}]},{"id":"s35-81","number":81,"surah":35,"verses":[39],"references":[{"surah":35,"verses":[39]}],"verseLabel":"فاطر: 39","question":"ما دلالة إثبات ﴿فِي﴾ في ﴿خَلَائِفَ فِي الْأَرْضِ﴾، وحذفها من ﴿خَلَائِفَ الْأَرْضِ﴾ في الأنعام؟","answer":"﴿خلائف الأرض﴾ بلا واسطة أوسع وأشمل، أما ﴿خلائف في الأرض﴾ فتفيد الظرفية والتحديد. وسياق فاطر في الكافرين ومآل كفرهم، فجاء التعبير الأضيق؛ بينما سياق الأنعام في خطاب المؤمنين وامتداد خلافتهم، فناسبه التركيب الأعم بحذف ﴿في﴾.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: سورة فاطر، «اللمسة البيانية في ذكر وحذف في»، مبحث الآية 39.","url":""}]},{"id":"s36-1","number":1,"surah":36,"verses":[1],"references":[{"surah":36,"verses":[1]}],"verseLabel":"يس: 1","question":"ما دلالة افتتاح السورة بـ﴿يس﴾ على توجيهها من الحروف المقطعة؟","answer":"توجه الموسوعة ﴿يس﴾ على أنها من الحروف المقطعة التي افتتحت بها بعض السور للإشارة إلى إعجاز القرآن، ثم يتبعها القسم بالقرآن الحكيم على صدق الرسالة. وبهذا يرتبط الافتتاح بالكتاب الذي تقوم به حجة الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص387، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s36-2","number":2,"surah":36,"verses":[2],"references":[{"surah":36,"verses":[2]}],"verseLabel":"يس: 2","question":"لماذا أقسم الله بـ﴿الْقُرْآنِ الْحَكِيمِ﴾ على صدق الرسالة؟","answer":"لأن القرآن نفسه أعظم معجزة للرسول ﷺ ودليل رسالته؛ فجاء القسم به في صورة استشهاد بالدليل، مع تعظيم المقسَم به والمقسَم عليه ودعوة المنكر إلى تدبر القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص389، تحت عنوان «سر تخصيص القسم بالقرآن المقيد بصفة الحكيم»","url":""}]},{"id":"s36-3","number":3,"surah":36,"verses":[3,4],"references":[{"surah":36,"verses":[3,4]}],"verseLabel":"يس: 3-4","question":"لماذا توالت المؤكدات في قوله: ﴿إِنَّكَ لَمِنَ الْمُرْسَلِينَ﴾؟","answer":"جاء القسم ثم ﴿إن﴾ واللام والجملة الاسمية لتثبيت الرسالة في وجه إنكار شديد؛ فكل مؤكد يبدد شبهة ويقرر الخبر حتى يستقر في النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص392، تحت عنوان «بلاغة تتابع التأكيد في السياق المجيد»","url":""}]},{"id":"s36-4","number":4,"surah":36,"verses":[5],"references":[{"surah":36,"verses":[5]}],"verseLabel":"يس: 5","question":"ما سرّ الجمع بين وصفي ﴿الْعَزِيزِ الرَّحِيمِ﴾ في إنزال القرآن؟","answer":"إضافة التنزيل إلى العزيز الرحيم تجمع الترهيب والترغيب: فهو صادر عن غالب قادر على عقاب المعرضين، ورحيم بعباده أنزل إليهم ما يهديهم. فالعزة تؤكد سلطان الوحي، والرحمة تظهر النعمة في إنزاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص403–404، تحت عنوان «براعة إضافة التنزيل إلى العزة والرحمة»","url":""}]},{"id":"s36-5","number":5,"surah":36,"verses":[6],"references":[{"surah":36,"verses":[6]}],"verseLabel":"يس: 6","question":"كيف تُفهم ﴿مَا﴾ في قوله: ﴿مَا أُنْذِرَ آبَاؤُهُمْ﴾؟","answer":"أشهر وجوهها النفي: أي لم يأت آباءهم الأقربين نذير فطالت الغفلة واشتدت الحاجة إلى الإنذار. وتحتمل الوصل أو المصدرية، أي لتنذرهم الذي أُنذر به آباؤهم أو إنذارًا مثل إنذارهم، فتصل الرسالة بخط الرسل السابقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص409–410، تحت عنوان «دلالة ﴿ما﴾ في قوله: ﴿ما أنذر آباؤهم﴾»","url":""}]},{"id":"s36-6","number":6,"surah":36,"verses":[8],"references":[{"surah":36,"verses":[8]}],"verseLabel":"يس: 8","question":"ما الذي تصوره الأغلال البالغة إلى الأذقان في قوله: ﴿فَهُمْ مُقْمَحُونَ﴾؟","answer":"تصوّر عنادهم قيدًا يغل أعناقهم ويرفع رؤوسهم ويمنعهم من الإطراق والنظر؛ فكأن استكبارهم وإصرارهم على الكفر هيئة حسية من العجز والانحباس عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص431–432، تحت عنوان «بلاغة الاستعارة في الآية»","url":""}]},{"id":"s36-7","number":7,"surah":36,"verses":[9],"references":[{"surah":36,"verses":[9]}],"verseLabel":"يس: 9","question":"ما الصورة في جعل سدٍّ من أمام الكافرين وسدٍّ من خلفهم ثم إغشائهم؟","answer":"هي صورة تمثيلية لانغلاق جهات الاعتبار عليهم: لا ينظرون فيما أمامهم من الآيات والعواقب، ولا فيما خلفهم من أخبار الأمم، وقد غطى العناد بصائرهم؛ فبدوا محاصرين لا يبصرون سبيل الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص446، تحت عنوان «بلاغة الاستعارة في الآية»","url":""}]},{"id":"s36-8","number":8,"surah":36,"verses":[11],"references":[{"surah":36,"verses":[11]}],"verseLabel":"يس: 11","question":"لماذا قُصر الإنذار النافع على من اتبع الذكر في قوله: ﴿إِنَّمَا تُنْذِرُ﴾؟","answer":"ليس المراد أن الإنذار لا يوجَّه إلى غيرهم، بل أن الانتفاع التام به لا يكون إلا لمن اتبع القرآن وخشي الله؛ فالقصر يميز المستجيب من المعاند بعد عموم البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص464–465، تحت عنوان «دلالة القصر بـ ﴿إنما﴾»","url":""}]},{"id":"s36-9","number":9,"surah":36,"verses":[12],"references":[{"surah":36,"verses":[12]}],"verseLabel":"يس: 12","question":"لماذا عطف الله ﴿وَآثَارَهُمْ﴾ على ما قدَّم الناس من أعمال؟","answer":"ليدخل في الكتابة ما يبقى بعد صاحبه من نتائج عمله، خيرًا أو شرًّا؛ فليس المحفوظ فعله المباشر وحده، بل ما سنَّه وخلّفه وامتد أثره في الآخرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص486–487، تحت عنوان «سبب إيثار التعبير بـ﴿وآثارهم﴾»","url":""}]},{"id":"s36-10","number":10,"surah":36,"verses":[12],"references":[{"surah":36,"verses":[12]}],"verseLabel":"يس: 12","question":"لماذا سُمّي الكتاب الذي أحصى الله فيه كل شيء ﴿إِمَامًا﴾؟","answer":"لأنه أصل جامع يُرجع إليه ويتبع ما أثبته، فكأنه إمام تتبعه أحوال الخلق عند الحساب؛ واللفظ يوحي بالمرجعية والإحاطة لا بمجرد كونه سجلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص489–490، تحت عنوان «دلالة لفظ ﴿إمام﴾»","url":""}]},{"id":"s36-52","number":52,"surah":36,"verses":[12],"references":[{"surah":36,"verses":[12]}],"verseLabel":"يس: 12","question":"ما دلالة وصف الإمام بأنه ﴿مُبِينٍ﴾؟","answer":"يدل على أنه بيّن في نفسه ومبيّن لما أودع فيه، فلا خفاء في سجله ولا التباس في دلالته عند الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص490، تحت عنوان «نكتة التقييد بالصفة ﴿مبين﴾»","url":""}]},{"id":"s36-11","number":11,"surah":36,"verses":[13],"references":[{"surah":36,"verses":[13]}],"verseLabel":"يس: 13","question":"ما سرّ عدم تسمية القرية في قوله ﴿أَصْحَابَ الْقَرْيَةِ﴾؟","answer":"لم تسم القرية لأن المقصود ضرب المثل بحال أصحابها مع الرسل، وما جرى من التكذيب وعاقبته، لا معرفة مكانها. فإبهام الاسم يوجه النظر إلى العبرة التي من أجلها سيقت القصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص498–499، تحت عنوان «نكتة عدم تعيين القرية»","url":""}]},{"id":"s36-12","number":12,"surah":36,"verses":[14],"references":[{"surah":36,"verses":[14]}],"verseLabel":"يس: 14","question":"لماذا عُبّر عن إرسال الرسول الثالث بقوله: ﴿فَعَزَّزْنَا بِثَالِثٍ﴾؟","answer":"لأن الثالث قوّى الرسولين وشد أزرهما وزاد الحجة ظهورًا؛ فلفظ التعزيز يصور الرسالة قوة متساندة، لا مجرد زيادة عددية.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص508–509، تحت عنوان «نكتة التعبير بلفظ (عزز)»","url":""}]},{"id":"s36-13","number":13,"surah":36,"verses":[15],"references":[{"surah":36,"verses":[15]}],"verseLabel":"يس: 15","question":"ماذا أراد المكذبون بقولهم للرسل: ﴿مَا أَنْتُمْ إِلَّا بَشَرٌ مِثْلُنَا﴾؟","answer":"حصروا الرسل في وصف البشرية توهمًا أن الرسول يجب أن يكون ملكًا، وجعلوا مماثلتهم لهم حجة على نفي الرسالة؛ فتكشف العبارة أصل شبهتهم وفسادها.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص515، تحت عنوان «بلاغة القصر بالنفي والاستثناء»","url":""}]},{"id":"s36-14","number":14,"surah":36,"verses":[18],"references":[{"surah":36,"verses":[18]}],"verseLabel":"يس: 18","question":"لماذا قال أهل القرية للرسل: ﴿إِنَّا تَطَيَّرْنَا بِكُمْ﴾؟","answer":"استعاروا التطير للتشاؤم، كأن قدوم الرسل هو الطائر الذي جلب الشؤم؛ وبذلك قلبوا نعمة النصح سببًا للمصيبة تهربًا من الحجة وتبريرًا للتهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص537–538، تحت عنوان «بلاغة التعبير بـ﴿تطيرنا﴾»","url":""}]},{"id":"s36-15","number":15,"surah":36,"verses":[19],"references":[{"surah":36,"verses":[19]}],"verseLabel":"يس: 19","question":"ماذا يعني جواب الرسل: ﴿طَائِرُكُمْ مَعَكُمْ﴾؟","answer":"يعني أن سبب ما ينالهم ملازم لهم ناشئ من كفرهم وأعمالهم، لا من الرسل؛ فالتعبير يعيد الشؤم المزعوم إلى مصدره الحقيقي ويحمّلهم مسؤولية اختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص548–549، تحت عنوان «بلاغة التعبير بـ﴿طائركم﴾»","url":""}]},{"id":"s36-16","number":16,"surah":36,"verses":[20],"references":[{"surah":36,"verses":[20]}],"verseLabel":"يس: 20","question":"ماذا يوحي مجيء الرجل ﴿مِنْ أَقْصَى الْمَدِينَةِ﴾؟","answer":"يوحي بأن دعوة الرسل بلغت أطراف المدينة، وأن الرجل قطع المسافة لنصرتهم؛ فيبرز صدق إيمانه وحرصه، ويدفع توهم تواطئه القريب معهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص560، تحت عنوان «دلالة التعبير بقوله تعالى ﴿من أقصى المدينة﴾»","url":""}]},{"id":"s36-17","number":17,"surah":36,"verses":[21],"references":[{"surah":36,"verses":[21]}],"verseLabel":"يس: 21","question":"ما الذي يضيفه قوله عن الرسل: ﴿وَهُمْ مُهْتَدُونَ﴾؟","answer":"يضم إلى إخلاصهم سلامة الطريق؛ فهم لا يطلبون منفعة لأنفسهم، وهم كذلك على هدى في علمهم وسلوكهم، فاجتمع للدعوة صدق القصد وصحة المنهج.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص571، تحت عنوان «فائدة الإخبار بقوله ﴿وهم مهتدون﴾»","url":""}]},{"id":"s36-18","number":18,"surah":36,"verses":[22],"references":[{"surah":36,"verses":[22]}],"verseLabel":"يس: 22","question":"لماذا قال المؤمن: ﴿وَمَا لِيَ لَا أَعْبُدُ الَّذِي فَطَرَنِي﴾ بدل أن يقول لقومه: ما لكم لا تعبدون؟","answer":"عدل إلى الحديث عن نفسه تعريضًا لطيفًا؛ قدّم لهم النصيحة في صورة محاسبة ذاتية حتى لا يثير عنادهم، مع أن المقصود دعوتهم إلى عبادة فاطرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص574–575، تحت عنوان «بلاغة التعريض»","url":""}]},{"id":"s36-19","number":19,"surah":36,"verses":[22],"references":[{"surah":36,"verses":[22]}],"verseLabel":"يس: 22","question":"لماذا انتقل الرجل من قوله: ﴿فَطَرَنِي﴾ إلى خطاب قومه: ﴿وَإِلَيْهِ تُرْجَعُونَ﴾؟","answer":"بدأ بنفسه تلطفًا وتعريضًا، ثم واجههم بحقيقة الرجوع لأنها تشملهم ولا تحتمل الإعراض؛ فجمع رفق الدعوة مع صراحة الإنذار والمساءلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص575، تحت عنوان «بلاغة التعريض»","url":""}]},{"id":"s36-20","number":20,"surah":36,"verses":[26],"references":[{"surah":36,"verses":[26]}],"verseLabel":"يس: 26","question":"ما سرّ الانتقال إلى قوله ﴿قِيلَ ادْخُلِ الْجَنَّةَ﴾ بعد موقف الرجل المؤمن؟","answer":"طوى النظم ما وقع للرجل بين إعلان إيمانه والأمر بدخول الجنة، وفيه كناية عن قتله وانتقاله إلى كرامة الله. فالإيجاز يوجه الاهتمام إلى فوزه، ويجعل جزاء إيمانه هو المشهد البارز في القصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص600–601، تحت عنوان «بلاغة الإيجاز بالحذف»","url":""}]},{"id":"s36-21","number":21,"surah":36,"verses":[26,27],"references":[{"surah":36,"verses":[26,27]}],"verseLabel":"يس: 26-27","question":"لماذا تمنى المؤمن بعد دخوله الجنة أن يعلم قومه بما أكرمه الله؟","answer":"بقي ناصحًا لقومه حتى بعد أذاهم له؛ تمنى أن يعرفوا أن الإيمان الذي دعاهم إليه أورث المغفرة والكرامة، لعل علمهم بذلك يحملهم على التصديق والتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص604–605، تحت عنوان «سبب إيراد التمني»","url":""}]},{"id":"s36-22","number":22,"surah":36,"verses":[29],"references":[{"surah":36,"verses":[29]}],"verseLabel":"يس: 29","question":"لماذا وُصفت الصيحة التي أهلكتهم بأنها ﴿وَاحِدَةً﴾؟","answer":"لتأكيد أنها لم تحتج إلى تكرار ولا معالجة؛ صيحة واحدة أنهت قوتهم، وفي ذلك تصوير لسرعة الهلاك وسهولة إنفاذ القدرة فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص621، تحت عنوان «فائدة توكيد الموصوف بـ﴿واحدة﴾»","url":""}]},{"id":"s36-53","number":53,"surah":36,"verses":[29],"references":[{"surah":36,"verses":[29]}],"verseLabel":"يس: 29","question":"ما الصورة في قوله عن أصحاب القرية: ﴿فَإِذَا هُمْ خَامِدُونَ﴾؟","answer":"شبّههم بنار كانت متقدة ثم انطفأت فجأة؛ فبعد الحركة والصخب صاروا ساكنين لا أثر للحياة فيهم، وتختصر كلمة ﴿خامدون﴾ انقلابهم الكامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص623، تحت عنوان «بلاغة الاستعارة ﴿فإذا هم خامدون﴾»","url":""}]},{"id":"s36-23","number":23,"surah":36,"verses":[30],"references":[{"surah":36,"verses":[30]}],"verseLabel":"يس: 30","question":"ما سر النداء في قوله: ﴿يَا حَسْرَةً عَلَى الْعِبَادِ﴾؟","answer":"يصوّر الحسرة كأنها شيء حاضر يُنادى ليقبل، لأن الحال بلغت غاية الأسف: يتكرر مجيء الرسل ويتكرر الاستهزاء بهم، فكأن هذا موطن الحسرة الكبرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص627–628، تحت عنوان «فائدة النداء ﴿يا حسرة﴾ وغرضه»","url":""}]},{"id":"s36-24","number":24,"surah":36,"verses":[33],"references":[{"surah":36,"verses":[33]}],"verseLabel":"يس: 33","question":"لماذا رتبت الآية إحياء الأرض ثم إخراج الحب ثم أكل الناس منه؟","answer":"لأنها تنتقل من أصل الدليل إلى ثمرته المشاهدة: تحيا الأرض الميتة، فيخرج منها القوت، ثم يصل إلى الإنسان؛ فيجتمع برهان البعث مع تذكيرهم بالنعمة التي يعيشون بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص652، تحت عنوان «بلاغة الترتيب بين الجمل المتعاطفة»","url":""}]},{"id":"s36-54","number":54,"surah":36,"verses":[33],"references":[{"surah":36,"verses":[33]}],"verseLabel":"يس: 33","question":"لماذا خُصَّ ﴿الْحَبَّ﴾ بالذكر بعد إحياء الأرض؟","answer":"لأنه أبرز ما تقوم به حياة الإنسان وأقرب ثمرات الأرض إلى حاجته؛ فذِكره يدمج في دليل الإحياء تذكيرًا بنعمة الرزق والقوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص654، تحت عنوان «بديع الإدماج ﴿وأخرجنا منها حبًّا﴾»","url":""}]},{"id":"s36-55","number":55,"surah":36,"verses":[33],"references":[{"surah":36,"verses":[33]}],"verseLabel":"يس: 33","question":"ما الذي يضيفه قوله بعد إخراج الحب: ﴿فَمِنْهُ يَأْكُلُونَ﴾؟","answer":"يلفتهم من مشهد النبات إلى صلته المباشرة بحياتهم؛ فما يخرج من الأرض ليس منظرًا فحسب بل قوتهم، فتقوى الحجة بالنعمة المحسوسة التي يباشرونها كل يوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص655، تحت عنوان «براعة الإيماء بمفردة الأكل»","url":""}]},{"id":"s36-25","number":25,"surah":36,"verses":[35],"references":[{"surah":36,"verses":[35]}],"verseLabel":"يس: 35","question":"كيف تتسع ﴿وَمَا عَمِلَتْهُ أَيْدِيهِمْ﴾ لمعنيين مع قراءتي إثبات الهاء وحذفها؟","answer":"بإثبات الهاء تكون ﴿ما﴾ موصولة: يأكلون من ثمرٍ لم تصنعه أيديهم. وبحذفها تحتمل المصدرية، أي ومن عمل أيديهم، فتجمع القراءتان بين كون الثمر خلقًا لله وكون بعض الطعام مما يعالجه الإنسان ويصنعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص668–669، تحت عنوان «توجيه القراءات القرآنية في الآية»","url":""}]},{"id":"s36-26","number":26,"surah":36,"verses":[36],"references":[{"surah":36,"verses":[36]}],"verseLabel":"يس: 36","question":"لماذا افتتح الحديث عن خلق الأزواج بالتسبيح لا بالحمد: ﴿سُبْحَانَ الَّذِي خَلَقَ﴾؟","answer":"لأن تنوع الأزواج ودقة نظامها يكشفان كمال الخالق وتنزهه عن الشريك والعجز؛ فناسب المقام تنزيهه عما لا يليق به قبل تعداد دلائل قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص674، تحت عنوان «مناسبة إيثار التسبيح على الحمد»","url":""}]},{"id":"s36-56","number":56,"surah":36,"verses":[36],"references":[{"surah":36,"verses":[36]}],"verseLabel":"يس: 36","question":"ما سر اختيار كلمة ﴿الْأَزْوَاجَ﴾ في قوله: ﴿خَلَقَ الْأَزْوَاجَ كُلَّهَا﴾؟","answer":"تشمل الأصناف والأنواع المتقابلة والمتآلفة، لا الذكر والأنثى وحدهما؛ فتفتح اللفظة معنى التنوع الشامل في النبات والأنفس وما يجهله البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص675، تحت عنوان «نكتة استعمال لفظ ﴿الأزواج﴾»","url":""}]},{"id":"s36-57","number":57,"surah":36,"verses":[36],"references":[{"surah":36,"verses":[36]}],"verseLabel":"يس: 36","question":"لماذا عطف ﴿وَمِمَّا لَا يَعْلَمُونَ﴾ على الأزواج التي يعرفها الناس؟","answer":"ليدل على أن ما عرفوه جزء يسير من نظام الخلق، وأن وراءه أنواعًا لا يحيطون بها؛ فيتسع الدليل ويتجدد مع كل ما يكشفه العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص677–678، تحت عنوان «سر عطف المجهول على المعلوم ﴿ومما لا يعلمون﴾»","url":""}]},{"id":"s36-27","number":27,"surah":36,"verses":[37],"references":[{"surah":36,"verses":[37]}],"verseLabel":"يس: 37","question":"ما سرّ التعبير بـ﴿وَآيَةٌ لَهُمُ اللَّيْلُ نَسْلَخُ مِنْهُ النَّهَارَ﴾؟","answer":"استعير السلخ لإزالة ضوء النهار عن موضع الليل، كما ينزع الجلد عما يستره فينكشف ما تحته. فالصورة تجعل ذهاب النور وظهور الظلمة مشهدًا محسوسًا، وتبرز دقة الانتقال بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص685–686، تحت عنوان «بلاغة الاستعارة في ﴿نسلخ﴾»","url":""}]},{"id":"s36-28","number":28,"surah":36,"verses":[38],"references":[{"surah":36,"verses":[38]}],"verseLabel":"يس: 38","question":"لماذا قيل عن الشمس: ﴿تَجْرِي﴾؟","answer":"ليصور حركتها المستمرة السريعة في نظام لا يفتر؛ فاللفظ ينقلها من جرم يبدو ساكنًا للناظر إلى آية متحركة منضبطة بأمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص693، تحت عنوان «نكتة استعمال مفردة الجري»","url":""}]},{"id":"s36-29","number":29,"surah":36,"verses":[39],"references":[{"surah":36,"verses":[39]}],"verseLabel":"يس: 39","question":"لماذا شُبّه القمر في آخر منازله بـ﴿الْعُرْجُونِ﴾؟","answer":"لأنه يعود دقيقًا مقوسًا مصفرًا كعود عذق النخل بعد أن يجف؛ فالتشبيه يرسم الهيئة واللون والدقة والانحناء في صورة مألوفة دقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص704–705، تحت عنوان «بلاغة التشبيه التمثيلي ﴿كالعرجون القديم﴾»","url":""}]},{"id":"s36-58","number":58,"surah":36,"verses":[39],"references":[{"surah":36,"verses":[39]}],"verseLabel":"يس: 39","question":"ما الذي يضيفه وصف العرجون بـ﴿الْقَدِيمِ﴾؟","answer":"فالعرجون لا يدق ويقوس ويصفر تمامًا إلا بعد أن ييبس ويقدم؛ لذلك أكمل الوصف أوجه الشبه وجعل الصورة أشد دقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص705، تحت عنوان «نكتة التقييد بالصفة ﴿القديم﴾»","url":""}]},{"id":"s36-30","number":30,"surah":36,"verses":[40],"references":[{"surah":36,"verses":[40]}],"verseLabel":"يس: 40","question":"لماذا قيل: ﴿لَا الشَّمْسُ يَنْبَغِي لَهَا أَنْ تُدْرِكَ الْقَمَرَ﴾؟","answer":"لأن ﴿ينبغي﴾ تنفي الإمكان والملاءمة معًا؛ فليس من شأن الشمس في النظام الذي قدره الله أن تلحق القمر فتفسد حسابه، لا أنها تحاول ثم تعجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص709–710، تحت عنوان «نكتة استعمال فعل ﴿ينبغي﴾»","url":""}]},{"id":"s36-59","number":59,"surah":36,"verses":[40],"references":[{"surah":36,"verses":[40]}],"verseLabel":"يس: 40","question":"ما الصورة في قوله: ﴿وَلَا اللَّيْلُ سَابِقُ النَّهَارِ﴾؟","answer":"صوّر الليل والنهار كمتسابقين، لكل منهما حد لا يتجاوزه؛ فلا يطغى أحدهما على الآخر، ويظل تعاقبهما جاريًا وفق التقدير.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص713، تحت عنوان «بلاغة الكناية ﴿ولا الليل سابق النهار﴾»","url":""}]},{"id":"s36-31","number":31,"surah":36,"verses":[41],"references":[{"surah":36,"verses":[41]}],"verseLabel":"يس: 41","question":"ما دلالة وصف الفلك بأنه ﴿الْمَشْحُونِ﴾؟","answer":"يدل على امتلائه بالناس وما يحتاجون إليه، ومع ذلك حملهم الله سالمين؛ فيبرز عظم القدرة والعناية في سفينة مثقلة وسط الطوفان.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص730، تحت عنوان «نكتة التعبير بقوله: ﴿المشحون﴾»","url":""}]},{"id":"s36-32","number":32,"surah":36,"verses":[45],"references":[{"surah":36,"verses":[45]}],"verseLabel":"يس: 45","question":"ما سرّ حذف جواب الشرط بعد قوله ﴿وَإِذَا قِيلَ لَهُمُ اتَّقُوا مَا بَيْنَ أَيْدِيكُمْ وَمَا خَلْفَكُمْ﴾؟","answer":"حذف الجواب، وتقديره أنهم أعرضوا، لدلالة السياق التالي عليه. وفي الحذف تصوير لعدم مبالاتهم بالنصح؛ فكأن الأمر بالتقوى لم يلق منهم ما يستحق أن يذكر سوى ما يكشفه السياق من إعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص755، تحت عنوان «بلاغة حذف جواب الشرط»","url":""}]},{"id":"s36-33","number":33,"surah":36,"verses":[47],"references":[{"surah":36,"verses":[47]}],"verseLabel":"يس: 47","question":"ماذا يكشف سؤال الكافرين: ﴿أَنُطْعِمُ مَنْ لَوْ يَشَاءُ اللَّهُ أَطْعَمَهُ﴾؟","answer":"هو استفهام إنكاري اتخذوه ذريعة للبخل: احتجوا بأن فقر المحتاج واقع بمشيئة الله، وغفلوا أن أمره بالإنفاق من مشيئته وأن المال الذي بأيديهم رزقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص771، تحت عنوان «بلاغة الاستفهام المجازي»","url":""}]},{"id":"s36-60","number":60,"surah":36,"verses":[47],"references":[{"surah":36,"verses":[47]}],"verseLabel":"يس: 47","question":"كيف قلب الكافرون الاحتجاج بمشيئة الله في قولهم: ﴿لَوْ يَشَاءُ اللَّهُ أَطْعَمَهُ﴾؟","answer":"علّقوا إطعام الفقير على المشيئة ليوهموا أنهم يوافقون إرادة الله بتركه، مع أن الله ابتلاهم بالمال وأمرهم بالإنفاق؛ فستروا البخل بكلمة حق أريد بها إسقاط التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص772، تحت عنوان «بلاغة الكناية في تعليق الجزاء بالمشيئة»","url":""}]},{"id":"s36-34","number":34,"surah":36,"verses":[49],"references":[{"surah":36,"verses":[49]}],"verseLabel":"يس: 49","question":"ما دلالة أخذهم بالصيحة ﴿وَهُمْ يَخِصِّمُونَ﴾؟","answer":"يفاجئهم العذاب وهم غارقون في خصومات الأسواق والمعاملات، لا ينتظرون نهاية العالم؛ فالكلمة ترسم انشغالهم وصخبهم لحظة الانقطاع المفاجئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص790، تحت عنوان «دلالة لفظ ﴿يخصمون﴾ في السياق»","url":""}]},{"id":"s36-35","number":35,"surah":36,"verses":[51],"references":[{"surah":36,"verses":[51]}],"verseLabel":"يس: 51","question":"ما الذي تصوره كلمة ﴿يَنْسِلُونَ﴾ في خروجهم من الأجداث؟","answer":"تصور خروجًا سريعًا متتابعًا، كأنهم يندفعون من القبور إلى المحشر لا يملكون التوقف؛ فتجعل حركة البعث مشهدًا حيًا عاجلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص15، تحت عنوان «سر التعبير بلفظ: ﴿ينسلون﴾»","url":""}]},{"id":"s36-36","number":36,"surah":36,"verses":[52],"references":[{"surah":36,"verses":[52]}],"verseLabel":"يس: 52","question":"لماذا سمّى المبعوثون قبورهم ﴿مَرْقَدَنَا﴾؟","answer":"لأن ما كانوا فيه يشبه الرقاد بالنسبة إلى هول البعث، أو لأنهم ناموا حقيقة بين النفختين؛ فاللفظ يصور دهشتهم من الانتقال المفاجئ من السكون إلى المشهد العظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص21–22، تحت عنوان «توجيه التعبير بلفظ: ﴿مرقدنا﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s36-61","number":61,"surah":36,"verses":[52],"references":[{"surah":36,"verses":[52]}],"verseLabel":"يس: 52","question":"كيف جاء جواب ﴿هَذَا مَا وَعَدَ الرَّحْمَنُ﴾ على سؤالهم: ﴿مَنْ بَعَثَنَا﴾؟","answer":"عدل عن تعيين الباعث إلى ما هو أهم: هذا هو البعث الذي كذبوا به، وقد صدق المرسلون؛ فواجه دهشتهم بالحقيقة التي تنفعهم وتبكت إنكارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص24–25، تحت عنوان «بلاغة العدول بطريق الأسلوب الحكيم»","url":""}]},{"id":"s36-37","number":37,"surah":36,"verses":[55],"references":[{"surah":36,"verses":[55]}],"verseLabel":"يس: 55","question":"ما دلالة كون أهل الجنة ﴿فِي شُغُلٍ﴾؟","answer":"يدل على استغراقهم في نعيم متجدد يملك عليهم نفوسهم، فلا يلتفتون إلى أهل النار ولا إلى ما يكدر سرورهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص47، تحت عنوان «دلالة لفظ ﴿شغل﴾»","url":""}]},{"id":"s36-62","number":62,"surah":36,"verses":[55],"references":[{"surah":36,"verses":[55]}],"verseLabel":"يس: 55","question":"لماذا وُصف أصحاب الجنة بأنهم ﴿فَاكِهُونَ﴾؟","answer":"لأن اللفظ يجمع التلذذ والسرور والمرح الطيب؛ فهو أوسع من مجرد الضحك ويصور نعيم النفس مع نعيم الجسد.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص49، تحت عنوان «نكتة التعبير بـ﴿فاكهون﴾»","url":""}]},{"id":"s36-38","number":38,"surah":36,"verses":[58],"references":[{"surah":36,"verses":[58]}],"verseLabel":"يس: 58","question":"ما الذي يضيفه قوله في سلام أهل الجنة: ﴿مِنْ رَبٍّ﴾؟","answer":"يجعل السلام صادرًا من الله نفسه لا بواسطة، وذلك غاية التكريم والأمان؛ فشرف التحية من شرف قائلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص68–69، تحت عنوان «نكتة تقييد القول بكونه من الله»","url":""}]},{"id":"s36-63","number":63,"surah":36,"verses":[58],"references":[{"surah":36,"verses":[58]}],"verseLabel":"يس: 58","question":"لماذا خُتم سلام أهل الجنة بوصف ﴿رَحِيمٍ﴾؟","answer":"ليدل على أن هذا السلام والنعيم أثر من رحمته، ويطمئنهم إلى دوام الإكرام والأمان؛ فمقام الجنة مقام الرحمة الكاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص69، تحت عنوان «مناسبة إيثار التعبير بوصف الربوبية»","url":""}]},{"id":"s36-39","number":39,"surah":36,"verses":[59],"references":[{"surah":36,"verses":[59]}],"verseLabel":"يس: 59","question":"ما دلالة الأمر للمجرمين: ﴿وَامْتَازُوا الْيَوْمَ﴾؟","answer":"هو أمر إهانة وفصل: انفردوا عن المؤمنين وعن شفعائكم المزعومين، واذهبوا إلى مصيركم؛ فيجسد انقطاع الروابط وظهور العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص73–74، تحت عنوان «غرض التعبير بلفظ ﴿وامتازوا﴾»","url":""}]},{"id":"s36-40","number":40,"surah":36,"verses":[60],"references":[{"surah":36,"verses":[60]}],"verseLabel":"يس: 60","question":"لماذا سمّى القرآن طاعة الشيطان ﴿عِبَادَةً﴾ له؟","answer":"لأن من أطاعه في الكفر والمعصية واتبع أمره فقد خضع له خضوع العابد، وإن لم يسجد له؛ فتكشف التسمية خطورة الطاعة التي تصرف حق الله إلى عدوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص82–83، تحت عنوان «نكتة نسبة العبادة إلى ﴿الشيطان﴾»","url":""}]},{"id":"s36-41","number":41,"surah":36,"verses":[65],"references":[{"surah":36,"verses":[65]}],"verseLabel":"يس: 65","question":"لماذا يُختم على أفواه المجرمين يوم القيامة؟","answer":"لأنهم اعتادوا الإنكار والكذب، فيمنع اللسان وتنتقل الشهادة إلى الجوارح التي لا تستطيع المكابرة؛ فتقوم الحجة من أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص112، تحت عنوان «نكتة التعبير بالختم على الأفواه»","url":""}]},{"id":"s36-64","number":64,"surah":36,"verses":[65],"references":[{"surah":36,"verses":[65]}],"verseLabel":"يس: 65","question":"لماذا جُعل الكلام للأيدي والشهادة للأرجل؟","answer":"لأن اليد تباشر معظم الأعمال فنسب إليها الكلام، والرجل تحضر مواقعها فناسبها أن تشهد؛ فتتوزع الجوارح وصف الواقعة وإثبات مكانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص115، تحت عنوان «سبب إيثار جعل الكلام للأيدي والشهادة للأرجل»","url":""}]},{"id":"s36-42","number":42,"surah":36,"verses":[66],"references":[{"surah":36,"verses":[66]}],"verseLabel":"يس: 66","question":"ما دلالة التهديد بقوله: ﴿لَطَمَسْنَا عَلَى أَعْيُنِهِمْ﴾؟","answer":"يصور إمكان محو أعينهم وملامحها حتى لا يبقى منفذ للبصر، أو طمس بصائرهم؛ وفي الحالين تهديد بسلب وسيلة الاهتداء التي عطلوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص126، تحت عنوان «دلالة التعبير بـ﴿لطمسنا﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s36-65","number":65,"surah":36,"verses":[66],"references":[{"surah":36,"verses":[66]}],"verseLabel":"يس: 66","question":"ما الذي تصوره كلمة ﴿فَاسْتَبَقُوا الصِّرَاطَ﴾ بعد طمس الأعين؟","answer":"تصورهم يحاولون الوصول مسرعين إلى الطريق، لكن الطمس يجعل السباق عبثًا؛ فتجتمع شدة الحرص مع استحالة الاهتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص127، تحت عنوان «دلالة لفظ ﴿فاستبقوا﴾»","url":""}]},{"id":"s36-43","number":43,"surah":36,"verses":[68],"references":[{"surah":36,"verses":[68]}],"verseLabel":"يس: 68","question":"ما الصورة في قوله: ﴿وَمَنْ نُعَمِّرْهُ نُنَكِّسْهُ فِي الْخَلْقِ﴾؟","answer":"يصوّر الشيخوخة تنكيسًا بعد اكتمال البنية والقوة: يعود الإنسان من الصعود إلى الضعف ونقص الحواس، كأن خلقه قُلب على مراحله الأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص146، تحت عنوان «بلاغة الاستعارة في التنكيس»","url":""}]},{"id":"s36-44","number":44,"surah":36,"verses":[69],"references":[{"surah":36,"verses":[69]}],"verseLabel":"يس: 69","question":"لماذا نفى الله أنه علّم النبي ﷺ الشعر؟","answer":"ليقطع شبهة أن القرآن كلام شاعر؛ فطبيعة الوحي والذكر تختلف عن صنعة الشعر وتخييله، والرسول لم يُعرف به أصلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص154، تحت عنوان «فائدة النفي في قوله: ﴿وما علمناه الشعر وما ينبغي له﴾»","url":""}]},{"id":"s36-66","number":66,"surah":36,"verses":[69],"references":[{"surah":36,"verses":[69]}],"verseLabel":"يس: 69","question":"ماذا يضيف قوله عن الشعر: ﴿وَمَا يَنْبَغِي لَهُ﴾ بعد نفي تعليمه؟","answer":"ينفي مجرد ملاءمة الشعر لطبيعة رسالته، لا وقوعه فقط؛ فليس الشعر من شأنه ولا مما ينسجم مع مقام الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص155، تحت عنوان «فائدة عطف نفي الانبغاء»","url":""}]},{"id":"s36-45","number":45,"surah":36,"verses":[71],"references":[{"surah":36,"verses":[71]}],"verseLabel":"يس: 71","question":"ما دلالة قوله عن الأنعام: ﴿مِمَّا عَمِلَتْ أَيْدِينَا﴾؟","answer":"هو تمثيل لقدرة الله المباشرة في الإيجاد والإتقان بما يقرّب المعنى، مع إضافة الأيدي إلى ضمير العظمة لتفخيم الصنع والعناية، من غير تشبيه للخالق بالمخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص173، تحت عنوان «بلاغة إضافة الأيدي إلى ضمير العظمة»","url":""}]},{"id":"s36-67","number":67,"surah":36,"verses":[71],"references":[{"surah":36,"verses":[71]}],"verseLabel":"يس: 71","question":"لماذا خُصت ﴿أَنْعَامًا﴾ بالذكر من بين مخلوقات الله؟","answer":"لشدة اتصالها بمعاشهم ومنافعهم من ركوب وغذاء ولباس؛ فهي نعمة حاضرة يرونها ويملكونها، ومع ذلك لم يصنعوا أصلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص173، تحت عنوان «فائدة إيثار ذكر الأنعام»","url":""}]},{"id":"s36-46","number":46,"surah":36,"verses":[74],"references":[{"surah":36,"verses":[74]}],"verseLabel":"يس: 74","question":"كيف يكون المشركون ﴿لَهُمْ جُنْدٌ مُحْضَرُونَ﴾ مع أنهم يرجون نصر آلهتهم؟","answer":"انقلبت العلاقة: بدل أن تكون الآلهة جندًا ينصرونهم، صار العابدون هم الجند الذين يحضرون لخدمتها والدفاع عنها، ثم يُحشر الجميع للعذاب؛ وفي ذلك تهكم بعجز المعبود والعابد.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص200–201، تحت عنوان «دلالة الواو في ﴿وهم لهم جند﴾»","url":""}]},{"id":"s36-47","number":47,"surah":36,"verses":[77],"references":[{"surah":36,"verses":[77]}],"verseLabel":"يس: 77","question":"كيف يحتج خلق الإنسان من نطفة على بطلان إنكاره للبعث؟","answer":"ينقله الدليل من أصل ضئيل لا حياة ظاهرة فيه إلى إنسان كامل يجادل خالقه؛ فمن قدر على الإنشاء الأول من نطفة قادر على الإعادة، والمفارقة تفضح نسيانه لأصل خلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص217، تحت عنوان «بلاغة الحجاج في الآية»","url":""}]},{"id":"s36-48","number":48,"surah":36,"verses":[78],"references":[{"surah":36,"verses":[78]}],"verseLabel":"يس: 78","question":"لماذا قيل عن منكر البعث: ﴿وَضَرَبَ لَنَا مَثَلًا﴾؟","answer":"جعل العظم البالي مثالًا يقيس عليه استحالة الإحياء، لكنه أقام المثال في غير موضعه؛ قاس قدرة الخالق على قدرة المخلوق وغفل عن الإنشاء الأول.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص231، تحت عنوان «بلاغة الاستعارة في لفظ ﴿مثلًا﴾»","url":""}]},{"id":"s36-68","number":68,"surah":36,"verses":[78],"references":[{"surah":36,"verses":[78]}],"verseLabel":"يس: 78","question":"ما دلالة قوله عن منكر البعث: ﴿وَنَسِيَ خَلْقَهُ﴾؟","answer":"يكشف أصل شبهته: نظر إلى العظم بعد فنائه ونسي أنه نفسه خُلق من عدم؛ فلو استحضر بدايته لزالت دعوى استحالة الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص233، تحت عنوان «نكتة التعبير بلفظ ﴿ونسي﴾»","url":""}]},{"id":"s36-49","number":49,"surah":36,"verses":[80],"references":[{"surah":36,"verses":[80]}],"verseLabel":"يس: 80","question":"ما سر الجمع بين ﴿الشَّجَرِ الْأَخْضَرِ﴾ وإيقاد النار منه؟","answer":"جمع بين الخضرة الرطبة والنار الحارة في مشهد واحد؛ فالذي أودع النار في ضدها وأخرجها منه قادر على إعادة الحياة إلى العظام، وفي التضاد حجة محسوسة قوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص249، تحت عنوان «براعة الطباق الخفي»","url":""}]},{"id":"s36-50","number":50,"surah":36,"verses":[82],"references":[{"surah":36,"verses":[82]}],"verseLabel":"يس: 82","question":"ما دلالة القصر في قوله: ﴿إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا﴾؟","answer":"يقصر شأن الإيجاد على إرادة نافذة لا تحتاج معالجة ولا زمنًا ولا معينًا؛ فإذا أراد الله شيئًا وقع بلا مانع.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص262–263، تحت عنوان «بلاغة القصر بـ﴿إنما﴾»","url":""}]},{"id":"s36-51","number":51,"surah":36,"verses":[83],"references":[{"surah":36,"verses":[83]}],"verseLabel":"يس: 83","question":"ما الصورة في قوله: ﴿بِيَدِهِ مَلَكُوتُ كُلِّ شَيْءٍ﴾؟","answer":"هي كناية عن انفراده بالملك والتدبير والقدرة التامة، كأن زمام كل موجود في قبضته؛ ولذلك كان الرجوع إليه وحده خاتمة لازمة للسورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص273، تحت عنوان «بلاغة الكناية»","url":""}]},{"id":"s36-69","number":69,"surah":36,"verses":[2],"references":[{"surah":36,"verses":[2]}],"verseLabel":"يس: 2","question":"ما الأسرار التي جمعها وصف القرآن بأنه ﴿الْحَكِيمِ﴾ في كلمة واحدة؟","answer":"جمع الوصف إحكام القرآن وخلوه من التناقض والباطل، واتصافه بالحكمة ونطقه بها، وكونه حاكمًا مهيمنًا على الأحكام والكتب. فالكلمة لا تؤدي معنى واحدًا، بل تجمع المحكم، وذا الحكمة، والحاكم المهيمن في بناء موجز بالغ.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص6-8، مبحث: «والقرآن الحكيم».","url":""}]},{"id":"s36-70","number":70,"surah":36,"verses":[8],"references":[{"surah":36,"verses":[8]}],"verseLabel":"يس: 8","question":"ما دلالة تقديم ﴿فِي أَعْنَاقِهِمْ﴾ على ﴿أَغْلَالًا﴾ في هذا المشهد المهيب؟","answer":"مدار السياق على هؤلاء المعاندين لا على وصف الأغلال، فَقُدِّم ما يتصل بهم. وترسم الآية هيئة من بلغ الغل ذقنه فارتفع رأسه وتعذر عليه أن يطأطئه أو يبصر طريقه؛ وهي صورة حسية لعجزه عن رؤية صراط الهدى والانقياد له.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص31-33، مبحث: «إنا جعلنا في أعناقهم أغلالًا».","url":""}]},{"id":"s36-71","number":71,"surah":36,"verses":[12],"references":[{"surah":36,"verses":[12]}],"verseLabel":"يس: 12","question":"ما الفرق البياني بين ﴿مَا قَدَّمُوا﴾ و﴿آثَارَهُمْ﴾؟","answer":"﴿ما قدموا﴾ هو ما باشره الإنسان من خير أو شر في حياته، أما ﴿آثارهم﴾ فهي النتائج الممتدة بعده: علم نافع أو سنة حسنة، أو بدعة وضلالة وضرر باقٍ. فالإحصاء لا يقف عند الفعل، بل يتبعه إلى ما ولّده في الناس والزمن.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص55-58، مبحث: «ونكتب ما قدموا وآثارهم».","url":""}]},{"id":"s36-72","number":72,"surah":36,"verses":[12],"references":[{"surah":36,"verses":[12]}],"verseLabel":"يس: 12","question":"ما دلالة تقديم إحياء الموتى على كتابة الأعمال؟","answer":"البعث هو الغاية التي من أجلها تظهر قيمة كتابة الأعمال ويقع الحساب، فناسب أن يتقدم. وهو أيضًا فعل لا يقدر عليه إلا الله، بخلاف الكتابة التي قد توكل إلى الملائكة؛ فتقدم الفعل الأعظم والأخص بالله، ووافق ذلك المحور العام للسورة.","sources":[{"label":"فاضل السامرائي، «تقديم إحياء الموتى على الكتابة» – مقطع مباشر، عنوان المبحث الجزئي: «تقديم إحياء الموتى على الكتاب».","url":""}]},{"id":"s36-73","number":73,"surah":36,"verses":[12],"references":[{"surah":36,"verses":[12]}],"verseLabel":"يس: 12","question":"ما دلالة توكيد إحياء الموتى بقوله: ﴿إِنَّا نَحْنُ نُحْيِي الْمَوْتَى﴾؟","answer":"جاءت ﴿إنَّ﴾ للتوكيد، وجاء ضمير الفصل ﴿نحن﴾ لزيادة التوكيد والقصر؛ فإحياء الموتى لا يملكه إلا الله. وهذا هو المحور الذي يشيع في السورة من أولها إلى آخرها، لذلك جاء تقريره حاسمًا لا يحتمل شركة ولا ترددًا.","sources":[{"label":"فاضل السامرائي، «إنا نحن نحيي الموتى» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة إنا نحن».","url":""}]},{"id":"s36-74","number":74,"surah":36,"verses":[13],"references":[{"surah":36,"verses":[13]}],"verseLabel":"يس: 13","question":"ما سر التعبير بـ﴿إِذْ جَاءَهَا الْمُرْسَلُونَ﴾ بدل الإخبار عن مجيئهم إلى أهلها؟","answer":"﴿جاءها﴾ يدل على أنهم قصدوا القوم في مقرهم وبلغوا الدعوة إلى ديارهم، وفيه تصوير لجدهم في البلاغ وما تحملوه من مشقة. والمجيء أقوى من مطلق الإتيان في هذا السياق، لأنه يلائم ما صاحبه من أذى وتهديد.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص67-70، مبحث: «إذ جاءها المرسلون».","url":""}]},{"id":"s36-75","number":75,"surah":36,"verses":[14],"references":[{"surah":36,"verses":[14]}],"verseLabel":"يس: 14","question":"ما دلالة التوكيد في قول الرسل: ﴿إِنَّا إِلَيْكُمْ مُرْسَلُونَ﴾؟","answer":"جاء التوكيد بعد تكذيب القوم للرسولين، فالمقام انتقل من مجرد البلاغ إلى مقابلة الإنكار. كما قُدِّم ﴿إليكم﴾ لإبراز أن الرسالة موجهة إليهم خاصة وأن الحجة قد قامت عليهم.","sources":[{"label":"فاضل السامرائي، «التوكيد في إنا إليكم لمرسلون» – مقطع مباشر، عنوان المبحث الجزئي: «التوكيد في إن إليكم لمرسلون».","url":""}]},{"id":"s36-76","number":76,"surah":36,"verses":[16],"references":[{"surah":36,"verses":[16]}],"verseLabel":"يس: 16","question":"ما دلالة قولهم: ﴿رَبُّنَا يَعْلَمُ إِنَّا إِلَيْكُمْ لَمُرْسَلُونَ﴾؟","answer":"﴿ربنا يعلم﴾ تجري مجرى القسم؛ لذلك جاء جوابها مؤكدًا بإن واللام. واختيار ﴿ربنا﴾ يلائم مقام الرسالة، لأن الرب هو المربي والهادي، فكأنهم يستشهدون بمن تولى تربيتهم وإرسالهم لهداية الخلق.","sources":[{"label":"فاضل السامرائي، «ربنا يعلم إنا إليكم لمرسلون» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة ربنا يعلم».","url":""}]},{"id":"s36-77","number":77,"surah":36,"verses":[18],"references":[{"surah":36,"verses":[18]}],"verseLabel":"يس: 18","question":"ما أثر تكرار لام القسم ونون التوكيد في ﴿لَنَرْجُمَنَّكُمْ وَلَيَمَسَّنَّكُمْ﴾؟","answer":"تكرار اللام والنون مع الفعلين يدل على أنهم عازمون على إنفاذ التهديدين معًا، لا على أحدهما فحسب. وزيادة ﴿مِنَّا﴾ تعيّن مصدر العذاب، أي إنهم سيتولونه بأنفسهم، فتشتد نبرة الوعيد والعدوان.","sources":[{"label":"فاضل السامرائي، «لنرجمنكم وليمسنكم منا عذاب أليم» – مقطع مباشر، عنوان المبحث الجزئي: «توكيد التهديد».","url":""}]},{"id":"s36-78","number":78,"surah":36,"verses":[23],"references":[{"surah":36,"verses":[23]}],"verseLabel":"يس: 23","question":"ما سر الجمع بين اسم ﴿الرَّحْمَنُ﴾ وذكر الضر في قوله: ﴿إِنْ يُرِدْنِ الرَّحْمَنُ بِضُرٍّ﴾؟","answer":"المقام مقام طلب الرحمة والنجاة من الضر الذي هدده به قومه، فناسب ذكر الرحمن. وفيه معنى أبلغ: إذا أراد الرحمن نفسه ضرًّا لحكمة، عجزت الآلهة كلها عن دفعه؛ فكيف يُرجى منها نفع أو شفاعة؟","sources":[{"label":"فاضل السامرائي، «إن يردن الرحمن بضر» – مقطع مباشر، عنوان المبحث الجزئي: «اقتران الرحمن بالضر».","url":""}]},{"id":"s36-79","number":79,"surah":36,"verses":[27],"references":[{"surah":36,"verses":[27]}],"verseLabel":"يس: 27","question":"ما دلالة قوله: ﴿مِنَ الْمُكْرَمِينَ﴾ بدل الاكتفاء بوصفه مكرمًا؟","answer":"التعبير يدخله في زمرة المكرمين من الأنبياء والصالحين، فلا يثبت له الإكرام منفردًا فحسب، بل يثبت له الصحبة والانضمام إلى أهل الكرامة. وفي ذلك أنس له ورفع لمقامه بعد ما لقيه من قومه.","sources":[{"label":"فاضل السامرائي، «وجعلني من المكرمين» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة من المكرمين».","url":""}]},{"id":"s36-80","number":80,"surah":36,"verses":[27],"references":[{"surah":36,"verses":[27]}],"verseLabel":"يس: 27","question":"ما سعة المعنى في قوله: ﴿بِمَا غَفَرَ لِي رَبِّي﴾؟","answer":"تحتمل ﴿ما﴾ المصدرية، فيكون المعنى: بمغفرة ربي لي، وتحتمل الموصولية، أي بالسبب أو العمل الذي غفر لي به. وتركها من غير تعيين يجمع المغفرة نفسها وسببها، فيتسع المعنى ولا ينحصر في وجه واحد.","sources":[{"label":"فاضل السامرائي، «بما غفر لي ربي» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة ما في بما غفر لي».","url":""}]},{"id":"s36-81","number":81,"surah":36,"verses":[28],"references":[{"surah":36,"verses":[28]}],"verseLabel":"يس: 28","question":"ما دلالة تكرار ﴿مِنْ﴾ في قوله: ﴿مِنْ بَعْدِهِ مِنْ جُنْدٍ مِنَ السَّمَاءِ﴾؟","answer":"لكل واحدة وظيفة: الأولى تقرر سرعة العقوبة بعده، والثانية تستغرق جنس الجند فتنفي أن يكون قد نزل جندي واحد أو أكثر، والثالثة تبين جهة الجند. وفي هذا تحقير لشأن القوم؛ فما احتاج إهلاكهم إلى جيش سماوي، بل كفتهم صيحة واحدة.","sources":[{"label":"فاضل السامرائي، «وما أنزلنا على قومه من بعده من جند» – مقطع مباشر، عنوان المبحث الجزئي: «دلالات من المتكررة».","url":""}]},{"id":"s36-82","number":82,"surah":36,"verses":[33],"references":[{"surah":36,"verses":[33]}],"verseLabel":"يس: 33","question":"ما سر تقديم ﴿آيَةٌ﴾ في قوله: ﴿وَآيَةٌ لَهُمُ الْأَرْضُ الْمَيْتَةُ﴾؟","answer":"السياق في تعداد الآيات، فكان تقديم الآية أنسب من تقديم المخاطبين. كما أن قول ﴿لهم آية﴾ قد يوهم اختصاص الآية بهم، بينما إحياء الأرض آية عامة للخلق، وإن سيقت هنا حجة لهؤلاء خاصة.","sources":[{"label":"فاضل السامرائي، «وآية لهم الأرض الميتة» – مقطع مباشر، عنوان المبحث الجزئي: «تقديم آية».","url":""}]},{"id":"s36-83","number":83,"surah":36,"verses":[35],"references":[{"surah":36,"verses":[35]}],"verseLabel":"يس: 35","question":"ما سر اختلاف الترتيب بين ﴿فَمِنْهُ يَأْكُلُونَ﴾ و﴿لِيَأْكُلُوا مِنْ ثَمَرِهِ﴾؟","answer":"الحب قوت مستمر يعتمد عليه، فَقُدِّم ﴿منه﴾ للاهتمام بهذا الأصل الغذائي. أما الثمر فموسمي وليس كل الطعام، فلم يقدم الجار والمجرور كيلا يوهم الحصر أو المبالغة في الاعتماد عليه، فجاء كل ترتيب ملائمًا لطبيعة المذكور.","sources":[{"label":"فاضل السامرائي، «الآيتان 34 و35 من سورة يس» – مقطع مباشر، عنوان المبحث الجزئي: «منه يأكلون ومن ثمره».","url":""}]},{"id":"s36-84","number":84,"surah":36,"verses":[37],"references":[{"surah":36,"verses":[37]}],"verseLabel":"يس: 37","question":"ما دلالة قوله: ﴿فَإِذَا هُمْ مُظْلِمُونَ﴾ بدل وصف الأرض بالظلام؟","answer":"نقل التعبير أثر الظاهرة إلى الإنسان؛ فهم الذين يدخلون في الظلام وتتبدل حياتهم به، فتظهر النعمة في تعاقب الضياء والإظلام عليهم. و﴿إذا﴾ ترسم مفاجأة التحول وسرعته، فلا يملكون رد الليل إذا أقبل.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص176-181، مبحث: «فإذا هم مظلمون».","url":""}]},{"id":"s36-85","number":85,"surah":36,"verses":[40],"references":[{"surah":36,"verses":[40]}],"verseLabel":"يس: 40","question":"ما دلالة جمع الفعل في قوله: ﴿وَكُلٌّ فِي فَلَكٍ يَسْبَحُونَ﴾؟","answer":"الجمع يصور الأجرام كلها وهي تتحرك في وقت واحد، كلٌّ في فلكه، في نظام متناسق. واستعمال جمع العقلاء يشخصها كأنها سابحون منضبطون يعرف كل منهم مساره، فيبعث المشهد معنى الحركة الحية والأمان الكوني.","sources":[{"label":"فاضل السامرائي، «لا الشمس ينبغي لها أن تدرك القمر» – مقطع مباشر، عنوان المبحث الجزئي: «كل في فلك يسبحون».","url":""}]},{"id":"s36-86","number":86,"surah":36,"verses":[43],"references":[{"surah":36,"verses":[43]}],"verseLabel":"يس: 43","question":"ما سعة المعنى في قوله: ﴿فَلَا صَرِيخَ لَهُمْ وَلَا هُمْ يُنْقَذُونَ﴾؟","answer":"﴿صريخ﴾ تحتمل المغيث، والمستغيث، والصراخ نفسه؛ فينتفي من ينقذهم، ومن يستغيث لهم، بل حتى قدرتهم على الصراخ. ثم جاء ﴿ولا هم ينقذون﴾ لينفي كل وسيلة نجاة أخرى، ولو لم تكن بواسطة مغيث.","sources":[{"label":"فاضل السامرائي، «معنى الصريخ» – مقطع مباشر، عنوان المبحث الجزئي: «معنى الصريخ».","url":""}]},{"id":"s36-87","number":87,"surah":36,"verses":[50],"references":[{"surah":36,"verses":[50]}],"verseLabel":"يس: 50","question":"ما سر اختلاف ترتيب الكلمات بين ﴿فَلَا يَسْتَطِيعُونَ تَوْصِيَةً﴾ و﴿وَلَا إِلَى أَهْلِهِمْ يَرْجِعُونَ﴾؟","answer":"تقديم الفعل في الأولى ينفي القدرة على أية توصية أصلًا؛ ولو قدمت التوصية لأمكن أن يفهم أنهم يعجزون عنها ويقدرون على غيرها. أما تقديم ﴿إلى أهلهم﴾ في الثانية فيخص نفي الرجوع إلى الأهل، مع الإيحاء برجوع محتوم إلى جهة أخرى هي موقف الحساب.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص238-241، مبحث: «فلا يستطيعون توصية ولا إلى أهلهم يرجعون».","url":""}]},{"id":"s36-88","number":88,"surah":36,"verses":[53],"references":[{"surah":36,"verses":[53]}],"verseLabel":"يس: 53","question":"ما دلالة ﴿جَمِيعٌ لَدَيْنَا مُحْضَرُونَ﴾ بدل التعبير بأنهم مجموعون عند الله؟","answer":"﴿جميع﴾ على وزن فعيل بمعنى مجموع، وهي تلائم مشهدًا وقع وصار حاضرًا، لا خبرًا مستقبليًا فحسب. و﴿لدينا﴾ أخص من «عندنا» في الحضور والقرب، وتقديمها يفيد أنهم محضرون لدى الله وحده لا لدى غيره.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص260-262، مبحث: «فإذا هم جميع لدينا محضرون».","url":""}]},{"id":"s36-89","number":89,"surah":36,"verses":[54],"references":[{"surah":36,"verses":[54]}],"verseLabel":"يس: 54","question":"ما سعة نفي الظلم في قوله: ﴿لَا تُظْلَمُ نَفْسٌ شَيْئًا﴾؟","answer":"تنكير ﴿نفس﴾ يعم كل نفس، و﴿شيئًا﴾ تحتمل المفعول المطلق، أي لا تظلم شيئًا من الظلم ولو قليلًا، وتحتمل المفعول به، أي لا تنقص شيئًا من حقوقها. فجمع التعبير نفي جنس الظلم ونفيه في أي حق أو جزاء.","sources":[{"label":"فاضل السامرائي، «فاليوم لا تظلم نفس شيئًا» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة نفس وشيئًا».","url":""}]},{"id":"s36-90","number":90,"surah":36,"verses":[60],"references":[{"surah":36,"verses":[60]}],"verseLabel":"يس: 60","question":"ما دلالة ندائهم بـ﴿يَا بَنِي آدَمَ﴾ عند التحذير من عبادة الشيطان؟","answer":"هذا النداء يوقظ فيهم قصة أبيهم آدم مع إبليس، فيجعل عصيانهم امتدادًا لعداوة قديمة معلومة. ويستعمل التعبير في القرآن في مقام التذكير بقصة آدم والشيطان أو في مقام التكريم، وهنا جاء ليقيم الحجة عليهم من تاريخ أبيهم.","sources":[{"label":"فاضل السامرائي، «ألم أعهد إليكم يا بني آدم» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة يا بني آدم».","url":""}]},{"id":"s36-91","number":91,"surah":36,"verses":[62],"references":[{"surah":36,"verses":[62]}],"verseLabel":"يس: 62","question":"ما أثر قوله: ﴿جِبِلًّا كَثِيرًا﴾ في تصوير كثرة من أضلهم الشيطان؟","answer":"﴿جبلًّا﴾ تدل في ذاتها على الخلق الكثير، ثم جاء وصفها بـ﴿كثيرًا﴾ فصار المعنى كثرة فوق كثرة، أو كثرة كاثرة متراكمة. فليس المراد جمعًا كبيرًا فحسب، بل أجيال وجموع هائلة استجابوا للشيطان.","sources":[{"label":"فاضل السامرائي، «ولقد أضل منكم جبلًّا كثيرًا» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة جبلًّا كثيرًا».","url":""}]},{"id":"s36-92","number":92,"surah":36,"verses":[63],"references":[{"surah":36,"verses":[63]}],"verseLabel":"يس: 63","question":"ما أثر اسم الإشارة القريب في قوله: ﴿هَذِهِ جَهَنَّمُ الَّتِي كُنْتُمْ تُوعَدُونَ﴾؟","answer":"ينقل التعبير المكذبين إلى مشهد الآخرة كأنهم واقفون على شفير جهنم يرونها رأي العين؛ لذلك قيل ﴿هذه﴾ لا «تلك». ثم جاء ﴿توعدون﴾ جوابًا ساخرًا مرعبًا عن سؤالهم المتكرر: متى هذا الوعد؟ فها هو حاضر أمامهم.","sources":[{"label":"فاضل السامرائي، «هذه جهنم التي كنتم توعدون» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة هذه وتوعدون».","url":""}]},{"id":"s36-93","number":93,"surah":36,"verses":[64],"references":[{"surah":36,"verses":[64]}],"verseLabel":"يس: 64","question":"ما سر التعبير بـ﴿كُنْتُمْ تَكْفُرُونَ﴾ بدل صيغة ماضية موجزة؟","answer":"التركيب يدل على الاستمرار في الكفر في الزمن الماضي، لا على وقوعه مرة عابرة. وهو يقابل ﴿كنتم توعدون﴾: كان الوعد يتكرر وكانوا يقابلونه بالكفر المتكرر؛ كما أن إطلاق الكفر يتسع لكفر العقيدة وكفران النعمة.","sources":[{"label":"فاضل السامرائي، «اصلوها اليوم بما كنتم تكفرون» – مقطع مباشر، عنوان المبحث الجزئي: «كنتم تكفرون».","url":""}]},{"id":"s36-94","number":94,"surah":36,"verses":[67],"references":[{"surah":36,"verses":[67]}],"verseLabel":"يس: 67","question":"ما دلالة تقديم المضي على الرجوع في قوله: ﴿فَمَا اسْتَطَاعُوا مُضِيًّا وَلَا يَرْجِعُونَ﴾؟","answer":"المضي إلى الأمام أصعب لأنه ذهاب إلى طريق أو غاية قد لا يعرفها المرء، أما الرجوع فعادة إلى طريق مألوف ومحل إقامة. فبدأ بالأصعب ثم نفى عنهم الأيسر أيضًا، ليبلغ تصوير العجز غايته: لا تقدم ولا عودة ولا حركة.","sources":[{"label":"فاضل السامرائي، «ولو نشاء لمسخناهم على مكانتهم» – مقطع مباشر، عنوان المبحث الجزئي: «تقديم المضي على الرجوع».","url":""}]},{"id":"s36-95","number":95,"surah":36,"verses":[69],"references":[{"surah":36,"verses":[69]}],"verseLabel":"يس: 69","question":"ما سر مجيء نفي الشعر بعد مشهد كلام الأيدي وشهادة الأرجل؟","answer":"قد يتوهم المكذب أن مشاهد الختم على الأفواه ونطق الجوارح من خيال الشعراء وتصويرهم، فجاء النفي ليقرر أنها حقائق لا خيالات شعرية. فالآية ترد تهمة الشعر، وتثبت في الوقت نفسه صدق المشاهد العجيبة التي سبقتها.","sources":[{"label":"فاضل السامرائي، «وما علمناه الشعر وما ينبغي له» – مقطع مباشر، عنوان المبحث الجزئي: «ارتباط نفي الشعر بما قبله».","url":""}]},{"id":"s36-96","number":96,"surah":36,"verses":[71],"references":[{"surah":36,"verses":[71]}],"verseLabel":"يس: 71","question":"ما دلالة اختيار ﴿خَلَقْنَا لَهُمْ﴾ في الحديث عن الأنعام؟","answer":"«خلقنا لهم» أقوى في الامتنان من مجرد جعل الأنعام لهم، لأنه يرجع بالنعمة إلى أصل إيجادها مخصوصة لمنافعهم. وقد فصّل السياق تمام النعمة بالخلق والتمليك والتذليل والمنافع والمشارب، فناسبه اللفظ الأدعى إلى الشكر.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص336-342، مبحث: «خلقنا لهم مما عملت أيدينا أنعامًا».","url":""}]},{"id":"s36-97","number":97,"surah":36,"verses":[71,72],"references":[{"surah":36,"verses":[71,72]}],"verseLabel":"يس: 71، 72","question":"ما سر تدرج النعمة من خلق الأنعام إلى تمليكها ثم تذليلها؟","answer":"لا تتم منفعة الأنعام بمجرد وجودها؛ فذكر أولًا خلقها لهم، ثم كونهم مالكين لها، ثم انقيادها للصغير والكبير. ولو كانت نافرة متوحشة لتعذر ركوبها وحلبها والانتفاع بها، فجمع التدرج أصل النعمة وتمامها.","sources":[{"label":"فاضل السامرائي، «وذللناها لهم» – مقطع مباشر، عنوان المبحث الجزئي: «الخلق والتمليك والتذليل».","url":""}]},{"id":"s36-98","number":98,"surah":36,"verses":[73],"references":[{"surah":36,"verses":[73]}],"verseLabel":"يس: 73","question":"ما سعة التعبير بكلمة ﴿مَشَارِبُ﴾ بدل الاكتفاء بذكر الشراب؟","answer":"المشارب تشمل ما يُشرب من الأنعام كاللبن، وتشمل ما يُتخذ من جلودها أو أجزائها أوعيةً وآلات للشرب. ولو قيل «شراب» لانحصر المعنى في السائل المشروب، فجاء الجمع ليوسع دائرة المنافع.","sources":[{"label":"فاضل السامرائي، «ولهم فيها منافع ومشارب» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة مشارب».","url":""}]},{"id":"s36-99","number":99,"surah":36,"verses":[76],"references":[{"surah":36,"verses":[76]}],"verseLabel":"يس: 76","question":"ما اللطف البياني في قوله: ﴿فَلَا يَحْزُنْكَ قَوْلُهُمْ﴾؟","answer":"لم يأت النهي بصيغة مباشرة للرسول عن الحزن، بل جُعل قولهم هو الفاعل المنهي عن إحزانه؛ فكأن العناية الإلهية تخاطب أقوالهم: لا تحزنوا رسولي. وفي ذلك تكريم بالغ وتسلية ورعاية للنبي ﷺ.","sources":[{"label":"فاضل السامرائي، «فلا يحزنك قولهم» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة فلا يحزنك قولهم».","url":""}]},{"id":"s36-100","number":100,"surah":36,"verses":[77],"references":[{"surah":36,"verses":[77]}],"verseLabel":"يس: 77","question":"ما المفارقة المدهشة بين ﴿مِنْ نُطْفَةٍ﴾ و﴿خَصِيمٌ مُبِينٌ﴾؟","answer":"تنقل الآية الإنسان فجأة من أصله الضعيف المهين إلى حالته قادرًا على البيان والخصام، فتقيم دليل القدرة من جهة، وتفضح جحوده من جهة أخرى. فالذي أنعم عليه بالعقل واللسان جعل هذه النعمة أداة لمخاصمة خالقه وإنكار البعث.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص365-370، مبحث: «فإذا هو خصيم مبين».","url":""}]},{"id":"s36-101","number":101,"surah":36,"verses":[79],"references":[{"surah":36,"verses":[79]}],"verseLabel":"يس: 79","question":"ما سر ختم جواب البعث بقوله: ﴿وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ﴾؟","answer":"إعادة الأجساد تقتضي علمًا شاملًا بكل ذرة تفرقت من كل مخلوق وأين استقرت، فجاء ﴿عليم﴾ مطلق الدلالة مناسبًا لهذا الشمول. أما ﴿علّام﴾ فاختص في الاستعمال القرآني بالغيوب، بينما المقام هنا علم الخلق كله وتفاصيله.","sources":[{"label":"فاضل السامرائي، «وهو بكل خلق عليم» – مقطع مباشر، عنوان المبحث الجزئي: «عليم وعلام».","url":""}]},{"id":"s36-102","number":102,"surah":36,"verses":[83],"references":[{"surah":36,"verses":[83]}],"verseLabel":"يس: 83","question":"ما جمال الارتباط بين مطلع السورة وخاتمتها في ﴿وَإِلَيْهِ تُرْجَعُونَ﴾؟","answer":"بدأت السورة بإرسال الرسول: ﴿إِنَّكَ لَمِنَ الْمُرْسَلِينَ﴾، وانتهت برجوع الخلق إلى من أرسله. فجمع البناء رحلة التكليف كلها: إرسال من الله، وبلاغ في الدنيا، ثم رجوع إليه للحساب؛ ولذلك قُدِّم ﴿إليه﴾ لقصر الرجوع عليه وحده.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص377-381، مبحث: «ارتباط خاتمة يس بمطلعها».","url":""}]},{"id":"s36-103","number":103,"surah":36,"verses":[4],"references":[{"surah":36,"verses":[4]}],"verseLabel":"يس: 4","question":"ما سر مجيء ﴿عَلَى صِرَاطٍ مُسْتَقِيمٍ﴾ بعد إثبات الرسالة؟","answer":"يحتمل التركيب أن يكون خبرًا ثانيًا، فيكون المعنى: إنك مرسل وإنك ثابت على صراط مستقيم، ويحتمل تعلقه بالمرسلين، أي أُرسلت على طريق مستقيم. وهكذا يجمع النظم بين شرف الرسالة واستقامة الطريق الذي يحمل الرسول الناس إليه.","sources":[{"label":"فاضل السامرائي، «على صراط مستقيم» – مقطع مباشر، عنوان المبحث الجزئي: «على صراط مستقيم».","url":""}]},{"id":"s36-104","number":104,"surah":36,"verses":[12],"references":[{"surah":36,"verses":[12]}],"verseLabel":"يس: 12","question":"ما أثر نصب ﴿كُلَّ شَيْءٍ﴾ في قوله: ﴿وَكُلَّ شَيْءٍ أَحْصَيْنَاهُ﴾؟","answer":"النصب على الاشتغال يقدر معه: «أحصينا كل شيء»، فيفيد الإحاطة بكل شيء من غير استثناء. أما الرفع فقد يحتمل أن تكون جملة ﴿أحصيناه﴾ وصفًا لقسم مخصوص من الأشياء، فيبقى احتمال قسم آخر؛ فجاء النصب لإغلاق هذا الاحتمال وتقرير الشمول.","sources":[{"label":"فاضل السامرائي، «وكل شيء أحصيناه» – مقطع مباشر، عنوان المبحث الجزئي: «الاشتغال في وكل شيء أحصيناه».","url":""}]},{"id":"s36-105","number":105,"surah":36,"verses":[13],"references":[{"surah":36,"verses":[13]}],"verseLabel":"يس: 13","question":"ما دلالة الأمر بضرب قصة أصحاب القرية مثلًا للمكذبين؟","answer":"المثل يعرض لقوم النبي ﷺ صورة قوم جاءتهم الرسل فكذبوهم، ليعتبروا بمآلهم. وفي الوقت نفسه يحمل للنبي ﷺ تسلية وتثبيتًا؛ فالمعارضة التي يلقاها ليست بدعًا، وقد لقي المرسلون قبله مثلها وصبروا.","sources":[{"label":"فاضل السامرائي، «واضرب لهم مثلًا أصحاب القرية» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة واضرب لهم مثلًا».","url":""}]},{"id":"s36-106","number":106,"surah":36,"verses":[14],"references":[{"surah":36,"verses":[14]}],"verseLabel":"يس: 14","question":"ما سر حذف المفعول في قوله: ﴿فَعَزَّزْنَا بِثَالِثٍ﴾؟","answer":"لم يقل: «فعززناهما»؛ لأن الحذف يوسع المعنى، فيشمل تقوية الرسولين، وتقوية الرسالة والحجة والحق الذي جاءوا به. ولو ذُكر المفعول لانحصر التعزيز في الشخصين، أما الحذف فجمع وجوه القوة كلها.","sources":[{"label":"فاضل السامرائي، «إذ أرسلنا إليهم اثنين فعززنا بثالث» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة فعززنا بثالث».","url":""}]},{"id":"s36-107","number":107,"surah":36,"verses":[15],"references":[{"surah":36,"verses":[15]}],"verseLabel":"يس: 15","question":"ما سر اختيار اسم ﴿الرَّحْمَنُ﴾ في إنكارهم: ﴿وَمَا أَنْزَلَ الرَّحْمَنُ مِنْ شَيْءٍ﴾؟","answer":"إرسال الرسل وإنزال الوحي من أعظم مظاهر الرحمة؛ لأنهما إنقاذ للناس من الضلال والعذاب. فجاء اسم الرحمن مناسبًا لطبيعة الرسالة ولجو السورة، وكان إنكارهم أشد قبحًا لأنهم جحدوا الرحمة التي سيقت إليهم لهدايتهم.","sources":[{"label":"فاضل السامرائي، «وما أنزل الرحمن من شيء» – مقطع مباشر، عنوان المبحث الجزئي: «اختيار الرحمن في مقام الرسالة».","url":""}]},{"id":"s36-108","number":108,"surah":36,"verses":[22],"references":[{"surah":36,"verses":[22]}],"verseLabel":"يس: 22","question":"ما دلالة تقديم ﴿إِلَيْهِ﴾ في قوله: ﴿وَإِلَيْهِ تُرْجَعُونَ﴾؟","answer":"تقديم الجار والمجرور يفيد القصر: إليه وحده يكون الرجوع، لا إلى غيره. وهو يربط بين مبدأ الخلق ومنتهاه؛ فالذي فطرهم أول مرة هو وحده الذي يرجعون إليه للحساب.","sources":[{"label":"فاضل السامرائي، «إليه ترجعون» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة تقديم إليه».","url":""}]},{"id":"s36-109","number":109,"surah":36,"verses":[29],"references":[{"surah":36,"verses":[29]}],"verseLabel":"يس: 29","question":"ما أثر اجتماع ﴿وَاحِدَةً﴾ و﴿فَإِذَا﴾ في قوله: ﴿إِلَّا صَيْحَةً وَاحِدَةً فَإِذَا هُمْ خَامِدُونَ﴾؟","answer":"﴿واحدة﴾ تؤكد أن صيحة واحدة كفت لإهلاكهم، فتظهر ضعفهم وعظمة القدرة. والفاء تفيد التعقيب بلا مهلة، و﴿إذا﴾ تفيد المفاجأة؛ فتحول المشهد في لحظة من الصخب والتهديد إلى خمود تام.","sources":[{"label":"فاضل السامرائي، «إن كانت إلا صيحة واحدة فإذا هم خامدون» – مقطع مباشر، عنوان المبحث الجزئي: «صيحة واحدة وفجاءة الخمود».","url":""}]},{"id":"s36-110","number":110,"surah":36,"verses":[31],"references":[{"surah":36,"verses":[31]}],"verseLabel":"يس: 31","question":"ما دلالة قوله: ﴿كَمْ أَهْلَكْنَا قَبْلَهُمْ﴾ من غير ﴿مِنْ﴾؟","answer":"﴿قبلهم﴾ تشمل القرون القريبة والبعيدة على السواء، أما ﴿من قبلهم﴾ فتبرز ابتداء الغاية وتقرّب الأمم السابقة منهم، فيشتد بها التهديد. وجاء التعبير هنا أعم زمنًا وأقل تخصيصًا بالقرب، ملائمًا لنسق الآية.","sources":[{"label":"فاضل السامرائي، «ألم يروا كم أهلكنا قبلهم» – مقطع مباشر، عنوان المبحث الجزئي: «قبلهم ومن قبلهم».","url":""}]},{"id":"s36-111","number":111,"surah":36,"verses":[34],"references":[{"surah":36,"verses":[34]}],"verseLabel":"يس: 34","question":"ما دلالة تقديم النخيل على الأعناب في قوله: ﴿جَنَّاتٍ مِنْ نَخِيلٍ وَأَعْنَابٍ﴾؟","answer":"السياق في الشجر والجنات ومجموع المنافع، والنخلة أنفع من شجرة العنب لكثرة ما ينتفع به من أجزائها وثمرها. لذلك تقدمت هنا، بينما قد يتقدم العنب حين يكون السياق في الفاكهة والطعام وكثرتهما.","sources":[{"label":"فاضل السامرائي، «تقديم النخيل على الأعناب» – مقطع مباشر، عنوان المبحث الجزئي: «تقديم النخيل على الأعناب».","url":""}]},{"id":"s36-112","number":112,"surah":36,"verses":[36],"references":[{"surah":36,"verses":[36]}],"verseLabel":"يس: 36","question":"ما دلالة ترتيب الأزواج: ﴿مِمَّا تُنْبِتُ الْأَرْضُ وَمِنْ أَنْفُسِهِمْ وَمِمَّا لَا يَعْلَمُونَ﴾؟","answer":"بدأ بما تنبت الأرض لأن الكلام قبلها كان على إحياء الأرض وحبها وثمرها. ثم ذكر أنفسهم لأنهم المنتفعون بها وسكانها، ثم ختم بما لا يعلمون، فانتقل من المشاهد القريب إلى عالم مجهول واسع يفتح باب التفكر.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص176، مبحث: «سبحان الذي خلق الأزواج كلها».","url":""}]},{"id":"s36-113","number":113,"surah":36,"verses":[41],"references":[{"surah":36,"verses":[41]}],"verseLabel":"يس: 41","question":"ما سر الانتقال من فلك الأجرام إلى ﴿الْفُلْكِ الْمَشْحُونِ﴾؟","answer":"ربط النظم بين مشهد الأجرام السابحة في أفلاكها والسفينة السابحة في الماء، فانتقل من فلك إلى فلك بلفظ واحد ذي دلالتين. ووصف السفينة بالمشحون يبرز تمام النعمة؛ فهي محملة بالناس والمتاع، ومع ذلك تجري وتحملهم بأمان.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص189-195، مبحث: «وآية لهم أنا حملنا ذريتهم في الفلك المشحون».","url":""}]},{"id":"s36-114","number":114,"surah":36,"verses":[51],"references":[{"surah":36,"verses":[51]}],"verseLabel":"يس: 51","question":"ما دلالة تقديم مبدأ الرحلة ومنتهاها في قوله: ﴿مِنَ الْأَجْدَاثِ إِلَى رَبِّهِمْ يَنْسِلُونَ﴾؟","answer":"قُدِّم الخروج من القبور لأنه موطن العجب والبعث، ثم قُدِّمت جهة الانطلاق إلى الرب لإفادة أنه لا مقصد لهم سواه. واختيار ﴿ربهم﴾ يجمع رجوع المؤمن إلى ربه المنعم، ورجوع الجاحد إلى من رباه بالنعم فعصاه.","sources":[{"label":"فاضل السامرائي، «من الأجداث إلى ربهم ينسلون» – مقطع مباشر، عنوان المبحث الجزئي: «تقديم من الأجداث وإلى ربهم».","url":""}]},{"id":"s36-115","number":115,"surah":36,"verses":[55],"references":[{"surah":36,"verses":[55]}],"verseLabel":"يس: 55","question":"ما سر تنكير ﴿شُغُلٍ﴾ ثم وصف أصحابه بأنهم ﴿فَاكِهُونَ﴾؟","answer":"التنكير يدل على شغل عجيب غير معهود في الدنيا ولا تدرك حقيقته، ثم جاءت ﴿فاكهون﴾ لتمنع توهم التعب أو الهم؛ فهم في شغل يملؤهم تنعمًا ولذة. وذكر حالهم عقب خطاب أهل العذاب يزيد حسرة أولئك ويحفز السامعين إلى طريق الجنة.","sources":[{"label":"فاضل السامرائي، «إن أصحاب الجنة اليوم في شغل فاكهون» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة شغل فاكهون».","url":""}]},{"id":"s36-116","number":116,"surah":36,"verses":[66],"references":[{"surah":36,"verses":[66]}],"verseLabel":"يس: 66","question":"ما دلالة تعدية الطمس بـ﴿عَلَى﴾ في قوله: ﴿لَطَمَسْنَا عَلَى أَعْيُنِهِمْ﴾؟","answer":"الطمس محو أثر العين، أما الطمس عليها فيضيف معنى التغطية والاستيثاق حتى لا يبقى منفذ ولا أثر، فهو أشد من مجرد العمى. وجاء هذا الأشد مناسبًا للمسخ المذكور بعده وللعقوبات الخارجة عن المألوف في السياق.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص307-312، مبحث: «لطمسنا على أعينهم».","url":""}]},{"id":"s36-117","number":117,"surah":36,"verses":[68],"references":[{"surah":36,"verses":[68]}],"verseLabel":"يس: 68","question":"ما دلالة الأفعال المضارعة في قوله: ﴿وَمَنْ نُعَمِّرْهُ نُنَكِّسْهُ فِي الْخَلْقِ أَفَلَا يَعْقِلُونَ﴾؟","answer":"المضارع يصور سنة مستمرة متجددة في الخلق: يمتد العمر ثم تنعكس مسيرة القوة إلى الضعف. ولو جاء بالماضي لاحتمل حكاية واقعة انتهت، أما المضارع فيجعل السامع يرى القانون يعمل في كل جيل وأمام كل إنسان.","sources":[{"label":"فاضل السامرائي، «ومن نعمره ننكسه في الخلق» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة المضارع في نعمره وننكسه».","url":""}]},{"id":"s36-118","number":118,"surah":36,"verses":[76],"references":[{"surah":36,"verses":[76]}],"verseLabel":"يس: 76","question":"ما دلالة تقديم السر في قوله: ﴿نَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ﴾؟","answer":"السر أسبق نشوءًا؛ فالإنسان يضمر الأمر في نفسه ثم يظهره قولًا أو فعلًا. والسياق في المكذبين، وخطرهم يبدأ مما يخفونه من الكيد قبل ما يعلنونه، فناسب تقديم الأصل الخفي الذي تنبثق منه العلانية.","sources":[{"label":"فاضل السامرائي، «فلا يحزنك قولهم» – مقطع مباشر، عنوان المبحث الجزئي: «تقديم السر على العلن».","url":""}]},{"id":"s36-119","number":119,"surah":36,"verses":[78,79],"references":[{"surah":36,"verses":[78,79]}],"verseLabel":"يس: 78–79","question":"ما قوة الحجة في الجمع بين ﴿وَنَسِيَ خَلْقَهُ﴾ و﴿أَنْشَأَهَا أَوَّلَ مَرَّةٍ﴾؟","answer":"لو تذكر المنكر خلقه الأول من نطفة لما استبعد إعادة العظام؛ لذلك كشف التعبير أصل شبهته وهو النسيان. ثم ألزمته الآية بما لا يدفع: من أنشأها أول مرة من غير مثال قادر على إحيائها بعد أن صارت رميمًا، والإعادة أيسر في ميزان العقل من الابتداء.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص370-372، مبحث: «وضرب لنا مثلًا ونسي خلقه».","url":""}]},{"id":"s36-120","number":120,"surah":36,"verses":[81],"references":[{"surah":36,"verses":[81]}],"verseLabel":"يس: 81","question":"ما سر التدرج من خلق الإنسان إلى الشجر الأخضر ثم خلق السماوات والأرض؟","answer":"بدأ بدليل في ذات الإنسان، ثم انتقل إلى أمر عجيب مشاهد حوله، ثم ارتقى إلى أعظم المخلوقات وأوسعها. وخلق السماوات والأرض من غير مادة سابقة أعجب من جمع أجزاء الإنسان وإعادته، فبلغت الحجة ذروتها.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص373-376، مبحث: «أوليس الذي خلق السماوات والأرض بقادر».","url":""}]},{"id":"s36-121","number":121,"surah":36,"verses":[81],"references":[{"surah":36,"verses":[81]}],"verseLabel":"يس: 81","question":"ما دلالة التعريف والمبالغة في قوله: ﴿وَهُوَ الْخَلَّاقُ الْعَلِيمُ﴾؟","answer":"صيغة ﴿الخلاق﴾ تدل على كثرة الخلق واستمراره، وجاءت أل في الصفتين للقصر والكمال، فلا يشاركه أحد في الخلق والعلم على هذا الوجه. واجتماعهما دقيق؛ فالخلق لا يكون كاملًا إلا عن علم محيط، والعلم هنا متعلق بكل ما يخلقه ويعيده.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص373-376، مبحث: «وهو الخلاق العليم».","url":""}]},{"id":"s36-122","number":122,"surah":36,"verses":[82],"references":[{"surah":36,"verses":[82]}],"verseLabel":"يس: 82","question":"ما دلالة الفاء في قوله: ﴿كُنْ فَيَكُونُ﴾؟","answer":"الفاء تدل على التعقيب المباشر بلا تراخ ولا مهلة؛ فما يريده الله يقع فور تعلق أمره به. وجاءت الآية بعد ذكر مخلوقات وقعت في الماضي لتقرر أن القدرة ليست حدثًا مضى، بل سلطان نافذ في الماضي والحال والاستقبال.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص376-377، مبحث: «إنما أمره إذا أراد شيئًا».","url":""}]},{"id":"s36-123","number":123,"surah":36,"verses":[83],"references":[{"surah":36,"verses":[83]}],"verseLabel":"يس: 83","question":"ما سر اختيار ﴿مَلَكُوتُ كُلِّ شَيْءٍ﴾ في ختام السورة؟","answer":"زيادة المبنى في ﴿ملكوت﴾ تفيد سعة المعنى، فهي أوسع من الملك وتدل على السلطان والملك الشامل الخاص بالله الذي لم يرد أنه يمنح لأحد. فختمت السورة بإحاطة سلطانه بكل شيء بعد عرض دلائل الخلق والإحياء والإهلاك.","sources":[{"label":"فاضل السامرائي، «الملك والملكوت» – مقطع مباشر، عنوان المبحث الجزئي: «الملك والملكوت».","url":""}]},{"id":"s37-1","number":1,"surah":37,"verses":[1,2,3],"references":[{"surah":37,"verses":[1,2,3]}],"verseLabel":"الصافات: 1-3","question":"لماذا افتتحت سورة الصافات بالقسم؟","answer":"لتوكيد التوحيد الذي سيأتي جوابًا للقسم؛ فالمشركون بالغوا في إنكاره، فجاء القسم في المطلع تعظيمًا للخبر وزيادةً في تثبيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص286، تحت عنوان «سر الافتتاح بالقسم»","url":""}]},{"id":"s37-51","number":51,"surah":37,"verses":[1,2,3],"references":[{"surah":37,"verses":[1,2,3]}],"verseLabel":"الصافات: 1-3","question":"لماذا أقسم الله بالصافات والزاجرات والتاليات؟","answer":"لأن هذه الصفات ـ وهي للملائكة على الأظهر ـ تكشف انتظامها في العبادة وتنفيذ أمر الله وتلاوة ذكره؛ فالقسم بها تعظيم لشأنها ودلالة على عظمة خالقها ووحدانيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص286، تحت عنوان «سر القسم بالمذكورات»","url":""}]},{"id":"s37-52","number":52,"surah":37,"verses":[1,2,3],"references":[{"surah":37,"verses":[1,2,3]}],"verseLabel":"الصافات: 1-3","question":"ما الصورة التي يرسمها وصف الملائكة بـ﴿الصافات صفًّا﴾؟","answer":"يصورها منتظمة في مراتب العبادة والطاعة، بعضها فوق بعض أو مصطفة في خط مستقيم؛ وفي هذا النظام المحكم إشارة إلى دقة تدبير الخالق ووحدانيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص287، تحت عنوان «نكتة التعبير بالصف»","url":""}]},{"id":"s37-2","number":2,"surah":37,"verses":[4],"references":[{"surah":37,"verses":[4]}],"verseLabel":"الصافات: 4","question":"لماذا جاء قوله ﴿إِنَّ إِلَهَكُمْ لَوَاحِدٌ﴾ جوابًا للقسم؟","answer":"لأنه الحقيقة المقصودة التي مهد لها القسم: تقرير وحدانية الله. فجاءت الجملة جوابًا مباشرًا لما أقسم به، وأبرزت أهم الحقائق التي أنكرها المشركون.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص292، تحت عنوان «موقع جملة ﴿إن إلهكم لواحد﴾»","url":""}]},{"id":"s37-53","number":53,"surah":37,"verses":[4],"references":[{"surah":37,"verses":[4]}],"verseLabel":"الصافات: 4","question":"لماذا توالت المؤكدات في قوله ﴿إِنَّ إِلَهَكُمْ لَوَاحِدٌ﴾؟","answer":"لأن المخاطبين شديدو الإنكار للوحدانية، فقوبل إنكارهم بالقسم و﴿إن﴾ واللام والجملة الاسمية حتى يثبت الخبر من وجوه متعددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص294، تحت عنوان «بلاغة توالي المؤكدات»","url":""}]},{"id":"s37-54","number":54,"surah":37,"verses":[4],"references":[{"surah":37,"verses":[4]}],"verseLabel":"الصافات: 4","question":"لماذا قيل ﴿لَوَاحِدٌ﴾ في وصف الإله؟","answer":"لنفي تعدد الآلهة نفيًا صريحًا؛ فالواحد هو المنفرد الذي لا شريك له، وهو وصف يواجه أصل اعتقاد المشركين مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص294، تحت عنوان «سر التعبير بـ﴿لواحد﴾»","url":""}]},{"id":"s37-3","number":3,"surah":37,"verses":[6],"references":[{"surah":37,"verses":[6]}],"verseLabel":"الصافات: 6","question":"ماذا تفيد إضافة الزينة إلى الكواكب في قوله ﴿بِزِينَةٍ الْكَوَاكِبِ﴾؟","answer":"تفيد أن الكواكب نفسها هي زينة السماء بما فيها من تعدد الأشكال وحسن الانتظام والضوء؛ فليست الزينة أمرًا منفصلًا عنها، بل هي المظهر الذي تتجلى به الزينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص308، تحت عنوان «دلالة إضافة الزينة إلى ﴿الكواكب﴾»","url":""}]},{"id":"s37-4","number":4,"surah":37,"verses":[7,8,9,10],"references":[{"surah":37,"verses":[7,8,9,10]}],"verseLabel":"الصافات: 7-10","question":"لماذا عبّر عن استراق الشيطان للسمع بـ﴿خَطْفَةَ﴾؟","answer":"لأن الخطف أخذ سريع خفي؛ فيصور أن ما يناله الشيطان قليل عاجل، يختلسه على خوف قبل أن يدركه الشهاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص320، تحت عنوان «سر التعبير بالخطف»","url":""}]},{"id":"s37-55","number":55,"surah":37,"verses":[7,8,9,10],"references":[{"surah":37,"verses":[7,8,9,10]}],"verseLabel":"الصافات: 7-10","question":"لماذا قيل عن الشهاب ﴿فَأَتْبَعَهُ﴾؟","answer":"ليصور الشهاب لاحقًا بالشيطان فور خطفته، كأنه يتعقبه ولا يفارقه حتى يصيبه؛ فالتعبير يشعر بسرعة المطاردة واتصالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص321، تحت عنوان «سر التعبير بالإتباع»","url":""}]},{"id":"s37-56","number":56,"surah":37,"verses":[7,8,9,10],"references":[{"surah":37,"verses":[7,8,9,10]}],"verseLabel":"الصافات: 7-10","question":"لماذا وُصف الشهاب بأنه ﴿ثَاقِبٌ﴾؟","answer":"لأنه نافذ شديد الإضاءة والإصابة؛ يخترق الظلمة ويبلغ الشيطان، فيجمع الوصف قوة الضوء وقوة الأثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص322، تحت عنوان «بلاغة الوصف بـ﴿ثاقب﴾»","url":""}]},{"id":"s37-5","number":5,"surah":37,"verses":[11],"references":[{"surah":37,"verses":[11]}],"verseLabel":"الصافات: 11","question":"ما دلالة الاستفهام في قوله ﴿أَهُمْ أَشَدُّ خَلْقًا أَمْ مَنْ خَلَقْنَا﴾؟","answer":"هو استفهام تقريري يفضح ضعف إنكارهم للبعث؛ فخلق السماوات والملائكة والكواكب أعظم من خلق البشر، ومن قدر على الأعظم قدر على إعادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص329، تحت عنوان «بلاغة الاستفهام»","url":""}]},{"id":"s37-57","number":57,"surah":37,"verses":[11],"references":[{"surah":37,"verses":[11]}],"verseLabel":"الصافات: 11","question":"لماذا قيل ﴿مَنْ خَلَقْنَا﴾ مع أن المقصود يشمل السماوات والأرض وغيرها؟","answer":"غُلِّب العاقل لأن المذكورات تشمل الملائكة والعقلاء وغيرهم، وفي هذا التغليب إشارة إلى أشرف ما خلق الله مع بقاء العموم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص331، تحت عنوان «نكتة تغليب العاقل»","url":""}]},{"id":"s37-6","number":6,"surah":37,"verses":[11],"references":[{"surah":37,"verses":[11]}],"verseLabel":"الصافات: 11","question":"لماذا نُكّر ﴿طِينٍ﴾ في قوله ﴿مِنْ طِينٍ لَازِبٍ﴾؟","answer":"للدلالة على نوع مخصوص من الطين أصلحُه الله لبدء خلق الإنسان، مع التحقير المناسب للاحتجاج على من يستبعد البعث وهو مخلوق من مادة ضعيفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص333، تحت عنوان «نكتة تنكير ﴿طين﴾»","url":""}]},{"id":"s37-58","number":58,"surah":37,"verses":[11],"references":[{"surah":37,"verses":[11]}],"verseLabel":"الصافات: 11","question":"لماذا وُصف الطين الذي خُلق منه الإنسان بأنه ﴿لَازِبٍ﴾؟","answer":"لأنه طين متماسك يلتصق بعضه ببعض؛ والوصف يبرز ضعف أصل الإنسان ولين مادته، فيسقط استبعاده أن يعيده الله بعد موته.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص333، تحت عنوان «نكتة الوصف بـ﴿لازب﴾»","url":""}]},{"id":"s37-7","number":7,"surah":37,"verses":[12],"references":[{"surah":37,"verses":[12]}],"verseLabel":"الصافات: 12","question":"كيف يُفهم قوله ﴿بَلْ عَجِبْتَ وَيَسْخَرُونَ﴾ على قراءة ضم التاء؟","answer":"المقصود عجب يليق بالله لا عجبُ جهلٍ أو خفاء؛ أي تعظيمُ أمرهم أو إنكارُ فعلهم وإظهارُ شناعته، بينما هم يقابلون دلائل القدرة بالسخرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص334–335، تحت عنوان «توجيه القراءات في ﴿عجبت﴾ وبالغتها»","url":""}]},{"id":"s37-8","number":8,"surah":37,"verses":[19],"references":[{"surah":37,"verses":[19]}],"verseLabel":"الصافات: 19","question":"لماذا وُصفت الزجرة يوم البعث بأنها ﴿وَاحِدَةٌ﴾؟","answer":"لتأكيد أن بعث الخلق جميعًا لا يحتاج إلا صيحة واحدة؛ وفي ذلك تحقير لاستبعادهم البعث وإظهار كمال قدرة الله وسرعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص357، تحت عنوان «نكتة الوصف بـ﴿واحدة﴾»","url":""}]},{"id":"s37-59","number":59,"surah":37,"verses":[19],"references":[{"surah":37,"verses":[19]}],"verseLabel":"الصافات: 19","question":"ماذا تصور ﴿إِذَا﴾ في قوله ﴿فَإِذَا هُمْ يَنْظُرُونَ﴾؟","answer":"تصور المفاجأة وسرعة الانتقال: تقع الزجرة، فإذا هم قيام ينظرون من غير مهلة؛ فكأن البعث حاضر مباغت.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص358، تحت عنوان «دلالة (إذا)»","url":""}]},{"id":"s37-9","number":9,"surah":37,"verses":[22,23],"references":[{"surah":37,"verses":[22,23]}],"verseLabel":"الصافات: 22-23","question":"ما البلاغة في الأمر ﴿فَاهْدُوهُمْ﴾ وهم مساقون إلى النار؟","answer":"هو تهكم مرير؛ استُعيرت الهداية ـ التي تكون إلى الخير ـ للدلالة إلى طريق الجحيم، فصار اللفظ نفسه يزيدهم إذلالًا وحسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص370، تحت عنوان «بلاغة الاستعارة في الهداية»","url":""}]},{"id":"s37-60","number":60,"surah":37,"verses":[22,23],"references":[{"surah":37,"verses":[22,23]}],"verseLabel":"الصافات: 22-23","question":"لماذا سُمّي طريق النار ﴿صِرَاطَ الْجَحِيمِ﴾؟","answer":"استُعير الصراط للطريق الذي يسيرون فيه إلى الهلاك، وفي إضافته إلى الجحيم تصوير لطريق محدد لا يفضي إلا إلى النار مع شدة التهكم بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص371، تحت عنوان «بلاغة الاستعارة في الصراط»","url":""}]},{"id":"s37-10","number":10,"surah":37,"verses":[24],"references":[{"surah":37,"verses":[24]}],"verseLabel":"الصافات: 24","question":"ماذا يفيد الأمر ﴿وَقِفُوهُمْ﴾ يوم القيامة؟","answer":"يفيد إلزام الملائكة بحبسهم ومنعهم من تجاوز الموقف؛ فبعد سوقهم إلى الجحيم يوقفون للسؤال والتوبيخ، ولا يملكون فرارًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص372، تحت عنوان «دلالة صيغة الأمر»","url":""}]},{"id":"s37-61","number":61,"surah":37,"verses":[24],"references":[{"surah":37,"verses":[24]}],"verseLabel":"الصافات: 24","question":"لماذا لم يُذكر في قوله ﴿إِنَّهُمْ مَسْئُولُونَ﴾ عمّا يُسألون؟","answer":"لأن المقام يدل عليه، ولأن حذف المسؤول عنه يعمم السؤال فيشمل عقائدهم وأعمالهم وتقصيرهم كله، فيكون أشد تهويلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص373، تحت عنوان «نكتة حذف المسؤول عنه»","url":""}]},{"id":"s37-11","number":11,"surah":37,"verses":[25],"references":[{"surah":37,"verses":[25]}],"verseLabel":"الصافات: 25","question":"ما غرض السؤال التوبيخي ﴿مَا لَكُمْ لَا تَنَاصَرُونَ﴾؟","answer":"يسخر من عجزهم بعد أن كانوا يتناصرون في الدنيا ويزعمون أن آلهتهم تنصرهم؛ فيكشف الفرق بين دعاواهم القديمة وذلهم التام يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص377، تحت عنوان «دلالة الاستفهام بـ﴿ما﴾ وغرضه البلاغي»","url":""}]},{"id":"s37-12","number":12,"surah":37,"verses":[27],"references":[{"surah":37,"verses":[27]}],"verseLabel":"الصافات: 27","question":"ما الصورة في قوله ﴿وَأَقْبَلَ بَعْضُهُمْ عَلَى بَعْضٍ﴾ يوم القيامة؟","answer":"يصوّر شدة توجههم بعضهم إلى بعض للوم والمحاكمة، كأن كل فريق يواجه الآخر مواجهة مباشرة؛ فتتحول صحبتهم القديمة إلى خصومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص386، تحت عنوان «بلاغة الاستعارة في (أقبل)»","url":""}]},{"id":"s37-62","number":62,"surah":37,"verses":[27],"references":[{"surah":37,"verses":[27]}],"verseLabel":"الصافات: 27","question":"لماذا قيل ﴿يَتَسَاءَلُونَ﴾ لا «يسألون»؟","answer":"لأن صيغة التفاعل تصور سؤالًا متبادلًا متكررًا بين الأطراف، يحمل اللوم والجدال ومحاولة كل فريق إلقاء التبعة على غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص388، تحت عنوان «سر اختيار ﴿يتساءلون﴾ مادة وصيغة»","url":""}]},{"id":"s37-13","number":13,"surah":37,"verses":[28],"references":[{"surah":37,"verses":[28]}],"verseLabel":"الصافات: 28","question":"ما الصورة في قول الأتباع للمتبوعين ﴿كُنْتُمْ تَأْتُونَنَا عَنِ الْيَمِينِ﴾؟","answer":"استُعيرت اليمين لطريق الخير والقوة والثقة؛ فهم يتهمون قادتهم بأنهم جاؤوهم من الجهة التي اطمأنوا إليها، فلبّسوا الباطل بصورة النصح والحق حتى أضلوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص396–397، تحت عنوان «بلاغة الاستعارة والكناية في لفظ ﴿اليمين﴾»","url":""}]},{"id":"s37-14","number":14,"surah":37,"verses":[35],"references":[{"surah":37,"verses":[35]}],"verseLabel":"الصافات: 35","question":"لماذا عُبّر عن موقفهم من ﴿لَا إِلَهَ إِلَّا اللَّهُ﴾ بالمضارع ﴿يَسْتَكْبِرُونَ﴾؟","answer":"ليصور استكبارهم عادةً متجددة لا موقفًا عابرًا؛ فكلما دُعوا إلى التوحيد تجدد منهم الإباء والتعالي.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص429، تحت عنوان «نكتة إيثار المضارع ﴿يستكبرون﴾»","url":""}]},{"id":"s37-15","number":15,"surah":37,"verses":[37],"references":[{"surah":37,"verses":[37]}],"verseLabel":"الصافات: 37","question":"لماذا قيل عن الرسول ﷺ ﴿بَلْ جَاءَ بِالْحَقِّ﴾ بصيغة الماضي؟","answer":"للدلالة على أن مجيئه بالحق أمر متحقق ثابت، لا دعوى منتظرة؛ فهو قد جاء برسالة واضحة من عند الله وانتهى وقوعها إلى اليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص438، تحت عنوان «نكتة إيثار فعل (المجيء) ماضيًا»","url":""}]},{"id":"s37-63","number":63,"surah":37,"verses":[37],"references":[{"surah":37,"verses":[37]}],"verseLabel":"الصافات: 37","question":"لماذا عُرّف ﴿الْحَقِّ﴾ في قوله ﴿بَلْ جَاءَ بِالْحَقِّ﴾؟","answer":"للدلالة على الحق الكامل المعروف في بابه: الوحي والتوحيد الذي لا يلابسه باطل؛ وفي التعريف رد جامع على وصفي الشعر والجنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص439، تحت عنوان «إيثار التعبير بلفظ (الحق) معرفًا»","url":""}]},{"id":"s37-64","number":64,"surah":37,"verses":[37],"references":[{"surah":37,"verses":[37]}],"verseLabel":"الصافات: 37","question":"لماذا قيل ﴿وَصَدَّقَ الْمُرْسَلِينَ﴾؟","answer":"لأن ما جاء به موافق لما جاءت به الرسل قبله في أصل التوحيد والهدى، فكان مجيئه تصديقًا لرسالاتهم وزيادة حجة على صدقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص440، تحت عنوان «سر إيثار لفظ (صدق) مادة وصيغة»","url":""}]},{"id":"s37-16","number":16,"surah":37,"verses":[40,41],"references":[{"surah":37,"verses":[40,41]}],"verseLabel":"الصافات: 40-41","question":"لماذا تكرر استثناء ﴿عِبَادَ اللَّهِ الْمُخْلَصِينَ﴾؟","answer":"لأن الاستثناء الثاني ليس تكرارًا محضًا، بل استدراك يفصل مصيرهم عن مصير المكذبين: أولئك للعذاب، وهؤلاء لجزاء معلوم كريم؛ فيرسخ الفرق بين الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص457، تحت عنوان «توجيه تكرار الاستثناء»","url":""}]},{"id":"s37-65","number":65,"surah":37,"verses":[40,41],"references":[{"surah":37,"verses":[40,41]}],"verseLabel":"الصافات: 40-41","question":"لماذا وُصف رزقهم في الجنة بأنه ﴿مَعْلُومٌ﴾؟","answer":"لأنه رزق حاضر مضمون يعرفون وقته وصفته، لا ينقطع ولا يتخلف؛ فالإشارة إليه كالمشاهد تزيد شعورهم بالأمن والاختصاص والتكريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص460، تحت عنوان «نكتة وصف الرزق بـ﴿معلوم﴾»","url":""}]},{"id":"s37-17","number":17,"surah":37,"verses":[45,46,47],"references":[{"surah":37,"verses":[45,46,47]}],"verseLabel":"الصافات: 45-47","question":"لماذا وُصفت خمر الجنة بأنها ﴿بَيْضَاءَ﴾؟","answer":"لأن البياض يجمع صفاء اللون وبهاءه ونقاء الشراب، فيوحي بلذة خالصة لا كدر فيها ولا قبح كخمر الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص469، تحت عنوان «سر الوصف بلفظ ﴿بيضاء﴾»","url":""}]},{"id":"s37-66","number":66,"surah":37,"verses":[45,46,47],"references":[{"surah":37,"verses":[45,46,47]}],"verseLabel":"الصافات: 45-47","question":"لماذا قيل عن خمر الجنة ﴿لَذَّةٍ لِلشَّارِبِينَ﴾ بالمصدر؟","answer":"جاء المصدر للمبالغة، فكأنها اللذة نفسها لا مجرد شراب لذيذ؛ فيدل على خلو متعتها من كل منغص.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص469–470، تحت عنوان «دلالة الوصف بالمصدر في ﴿لذة﴾»","url":""}]},{"id":"s37-67","number":67,"surah":37,"verses":[45,46,47],"references":[{"surah":37,"verses":[45,46,47]}],"verseLabel":"الصافات: 45-47","question":"لماذا نُكّر ﴿غَوْلٌ﴾ في قوله ﴿لَا فِيهَا غَوْلٌ﴾؟","answer":"لنفي أي نوع من الأذى والفساد الذي يغتال العقل أو البدن؛ فالتنكير في سياق النفي يعم كل عيب تعرفه خمور الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص472، تحت عنوان «بلاغة استعمال لفظ ﴿غول﴾ نكرة»","url":""}]},{"id":"s37-18","number":18,"surah":37,"verses":[48],"references":[{"surah":37,"verses":[48]}],"verseLabel":"الصافات: 48","question":"ما دلالة وصف الحور بـ﴿قَاصِرَاتُ الطَّرْفِ﴾؟","answer":"يدل على العفة وكمال المحبة؛ فقد قصرن أبصارهن على أزواجهن فلا ينظرن إلى غيرهم، وفي الصيغة مبالغة في ثبات هذا الوصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص476، تحت عنوان «وجه تعريف ﴿قاصرات﴾ بالإضافة»","url":""}]},{"id":"s37-68","number":68,"surah":37,"verses":[48],"references":[{"surah":37,"verses":[48]}],"verseLabel":"الصافات: 48","question":"ماذا يضيف وصف الحور بأنهن ﴿عِينٌ﴾؟","answer":"يضيف جمال العيون واتساعها وحسن النظر، فيكتمل وصف العفة في ﴿قاصرات الطرف﴾ بوصف الجمال في ﴿عين﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص477، تحت عنوان «توجيه الوصف بـ(العين)»","url":""}]},{"id":"s37-19","number":19,"surah":37,"verses":[49],"references":[{"surah":37,"verses":[49]}],"verseLabel":"الصافات: 49","question":"لماذا شُبّه الحور بـ﴿بَيْضٌ﴾؟","answer":"شُبّه بياضهن وصفاؤهن ببيض النعام الذي يجمع لونًا نقيًا رقيقًا مشوبًا بصفرة محببة، وهو من ألوان الحسن عند العرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص478، تحت عنوان «وجه التعبير بلفظ ﴿بيض﴾»","url":""}]},{"id":"s37-69","number":69,"surah":37,"verses":[49],"references":[{"surah":37,"verses":[49]}],"verseLabel":"الصافات: 49","question":"لماذا وُصف البيض في التشبيه بأنه ﴿مَكْنُونٌ﴾؟","answer":"لأن المصون المستور لا تمسه الأيدي ولا الغبار، فالوصف يزيد التشبيه معنى الصفاء والحفظ والعفة مع جمال اللون.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص478، تحت عنوان «سر وصف البيض بـ﴿مكنون﴾»","url":""}]},{"id":"s37-20","number":20,"surah":37,"verses":[51],"references":[{"surah":37,"verses":[51]}],"verseLabel":"الصافات: 51","question":"لماذا اختير لفظ ﴿قَرِينٌ﴾ في حديث أهل الجنة عن صاحبهم القديم؟","answer":"لأن القرين ملازم لصاحبه، فيصور قرب ذلك المشكك وشدة صحبته في الدنيا؛ ولذلك كان خلاص المؤمن من تأثيره نعمة تستحق الاستذكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص486، تحت عنوان «سر اختيار لفظ ﴿قرين﴾ مادة وصيغة»","url":""}]},{"id":"s37-70","number":70,"surah":37,"verses":[51],"references":[{"surah":37,"verses":[51]}],"verseLabel":"الصافات: 51","question":"لماذا قال المؤمن في الجنة ﴿كَانَ لِي قَرِينٌ﴾ بالماضي؟","answer":"ليستحضر نعمة نجاته بمقارنة حاله الحاضر في الجنة بصحبته الماضية لذلك المشكك؛ فالماضي يباعد بين حالين متقابلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص486، تحت عنوان «دلالة فعل الكون الماضي»","url":""}]},{"id":"s37-71","number":71,"surah":37,"verses":[51],"references":[{"surah":37,"verses":[51]}],"verseLabel":"الصافات: 51","question":"ما غرض استفهام القرين ﴿أَإِنَّكَ لَمِنَ الْمُصَدِّقِينَ﴾؟","answer":"ليس طلبًا للجواب، بل إنكار وسخرية وتعجب من الإيمان بالبعث؛ فهو يضغط على صاحبه ليشككه ويصوره ساذجًا بسبب تصديقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص491، تحت عنوان «الغرض من الاستفهام بـ (الهمزة) في الآية»","url":""}]},{"id":"s37-21","number":21,"surah":37,"verses":[55],"references":[{"surah":37,"verses":[55]}],"verseLabel":"الصافات: 55","question":"لماذا قيل عن القرين في النار إنه ﴿فِي سَوَاءِ الْجَحِيمِ﴾؟","answer":"لأن ﴿سواء﴾ تصور وقوعه في وسط الجحيم وأشد مواضعه، محاطًا بالعذاب من كل جهة؛ فتبرز هول ما نجا منه المؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص509، تحت عنوان «دلالة التعبير بـ﴿سواء﴾»","url":""}]},{"id":"s37-72","number":72,"surah":37,"verses":[55],"references":[{"surah":37,"verses":[55]}],"verseLabel":"الصافات: 55","question":"ماذا تضيف إضافة ﴿سَوَاء﴾ إلى ﴿الْجَحِيمِ﴾؟","answer":"تعيّن أن التوسط ليس في نار عارضة بل في الجحيم المعروف بعذابه المتفاقم، فتزيد المشهد رهبة وتذكّر المؤمن بفضل الله في نجاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص510، تحت عنوان «الغرض من إضافة ﴿سواء﴾ إلى ﴿الجحيم﴾»","url":""}]},{"id":"s37-22","number":22,"surah":37,"verses":[62],"references":[{"surah":37,"verses":[62]}],"verseLabel":"الصافات: 62","question":"ما غرض الاستفهام في قوله ﴿أَذَلِكَ خَيْرٌ نُزُلًا أَمْ شَجَرَةُ الزَّقُّومِ﴾؟","answer":"هو تهكم وتقريع؛ فلا خير في الزقوم، وإنما وُضعت ضيافة الجنة والعذاب في مقابلة تكشف سوء اختيار المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص541، تحت عنوان «غرض الاستفهام بـ (الهمزة) في الآية»","url":""}]},{"id":"s37-73","number":73,"surah":37,"verses":[62],"references":[{"surah":37,"verses":[62]}],"verseLabel":"الصافات: 62","question":"لماذا استُعمل التفضيل ﴿خَيْرٌ﴾ بين نعيم الجنة وشجرة الزقوم؟","answer":"لزيادة التهكم بهم؛ إذ لا اشتراك حقيقي بين النعيم والعذاب في الخير، فكأن من يختار الكفر يفضّل الزقوم على الرزق الكريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص542–543، تحت عنوان «دلالة التعبير بالتفضيل في الآية»","url":""}]},{"id":"s37-23","number":23,"surah":37,"verses":[65],"references":[{"surah":37,"verses":[65]}],"verseLabel":"الصافات: 65","question":"ما سرّ تشبيه طلع الزقوم برؤوس الشياطين مع أنهم لم يروها؟","answer":"اعتمد التشبيه على ما استقر في النفوس من تمثل الشيطان في غاية القبح، وإن لم تشاهد صورته. فإحالته إلى هذه الصورة المتخيلة تزيد النفرة والتهويل، وتجعل طلع الزقوم بالغًا أقصى ما يتصور من البشاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص553–554، تحت عنوان «بلاغة التشبيه في جملة: ﴿كأنه رؤوس الشياطين﴾»","url":""}]},{"id":"s37-24","number":24,"surah":37,"verses":[69,70],"references":[{"surah":37,"verses":[69,70]}],"verseLabel":"الصافات: 69-70","question":"لماذا قيل ﴿أَلْفَوْا آبَاءَهُمْ ضَالِّينَ﴾ بدل «وجدوا»؟","answer":"لأن الإلفاء يشعر بمصادفة حال ثابتة أمامهم؛ وجدوا آباءهم على الضلال فتلقوه بلا نظر ولا برهان، وكأن مجرد وجودهم عليه صار حجتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص568، تحت عنوان «سر إيثار التعبير بـ (الإلفاء) دون غيره»","url":""}]},{"id":"s37-74","number":74,"surah":37,"verses":[69,70],"references":[{"surah":37,"verses":[69,70]}],"verseLabel":"الصافات: 69-70","question":"ما الصورة في قوله ﴿فَهُمْ عَلَى آثَارِهِمْ يُهْرَعُونَ﴾؟","answer":"تصورهم يندفعون مسرعين خلف آثار آبائهم بلا تفكير، كأن قوة تدفعهم؛ فتفضح شدة التقليد وغياب العقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص571–572، تحت عنوان «دلالة التعبير بالهرع في الفعل ﴿يهرعون﴾»","url":""}]},{"id":"s37-25","number":25,"surah":37,"verses":[75],"references":[{"surah":37,"verses":[75]}],"verseLabel":"الصافات: 75","question":"لماذا عبّر عن دعاء نوح بقوله ﴿نَادَانَا﴾؟","answer":"النداء دعاء بصوت واستغاثة بعد طول المعاناة، فيصور شدة اضطراره وتوجهه إلى الله وحده طلبًا للنجاة والنصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص592، تحت عنوان «دلالة التعبير بالفعل الماضي (نادى)»","url":""}]},{"id":"s37-75","number":75,"surah":37,"verses":[75],"references":[{"surah":37,"verses":[75]}],"verseLabel":"الصافات: 75","question":"لماذا قيل ﴿فَلَنِعْمَ الْمُجِيبُونَ﴾؟","answer":"﴿نعم﴾ صيغة مدح تبلغ بالإجابة غايتها؛ فاستجابة الله كاملة عاجلة، وجمع المجيبون للتعظيم وتطمين كل داع صادق.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص594، تحت عنوان «دلالة التعبير بـ (نعم)»","url":""}]},{"id":"s37-26","number":26,"surah":37,"verses":[77],"references":[{"surah":37,"verses":[77]}],"verseLabel":"الصافات: 77","question":"ماذا يفيد قوله ﴿وَجَعَلْنَا ذُرِّيَّتَهُ هُمُ الْبَاقِينَ﴾؟","answer":"يفيد الحصر: ذرية نوح هي التي امتد منها نسل البشر بعد الطوفان، فجيء بضمير الفصل لتأكيد اختصاصهم بالبقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص603–604، تحت عنوان «نوع الحصر ودلالته»","url":""}]},{"id":"s37-76","number":76,"surah":37,"verses":[77],"references":[{"surah":37,"verses":[77]}],"verseLabel":"الصافات: 77","question":"ما البلاغة في التعبير عن امتداد نسل نوح بـ﴿الْبَاقِينَ﴾؟","answer":"كنّى بالبقاء عن استمرار الذرية وامتدادها بعد هلاك المكذبين؛ فالكلمة تجمع النجاة واستمرار النسل في إيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص605، تحت عنوان «بلاغة الكناية في استعمال مفردة البقاء»","url":""}]},{"id":"s37-27","number":27,"surah":37,"verses":[79],"references":[{"surah":37,"verses":[79]}],"verseLabel":"الصافات: 79","question":"لماذا بدأ قوله ﴿سَلَامٌ عَلَى نُوحٍ﴾ بكلمة ﴿سَلَامٌ﴾ نكرة؟","answer":"للدلالة على سلام عظيم متجدد يفوق الوصف، باقٍ لنوح في الأمم بعده جزاءً لإيمانه وصبره.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص609، تحت عنوان «علة الابتداء بالنكرة»","url":""}]},{"id":"s37-77","number":77,"surah":37,"verses":[79],"references":[{"surah":37,"verses":[79]}],"verseLabel":"الصافات: 79","question":"ماذا يفيد حرف ﴿عَلَى﴾ في قوله ﴿سَلَامٌ عَلَى نُوحٍ﴾؟","answer":"يفيد شمول السلام له وتمكنه منه، كأنه غطاء يحيط به، مع دلالة على دوام تكريمه وعلو منزلته.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص609–610، تحت عنوان «دلالة حرف الاستعلاء»","url":""}]},{"id":"s37-28","number":28,"surah":37,"verses":[83],"references":[{"surah":37,"verses":[83]}],"verseLabel":"الصافات: 83","question":"ما معنى كون إبراهيم ﴿مِنْ شِيعَةِ﴾ نوح؟","answer":"أي أنه على طريقته في التوحيد والدعوة والثبات، لا أنه من زمنه أو أتباعه المباشرين؛ فالشيعة هنا جماعة المنهج الواحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص619–620، تحت عنوان «تعيين مرجع الضمير»","url":""}]},{"id":"s37-78","number":78,"surah":37,"verses":[83],"references":[{"surah":37,"verses":[83]}],"verseLabel":"الصافات: 83","question":"لماذا أكّد قوله ﴿وَإِنَّ مِنْ شِيعَتِهِ لَإِبْرَاهِيمَ﴾ بإن واللام؟","answer":"لتثبيت قوة الصلة المنهجية بين إبراهيم ونوح مع تباعد الزمن، وإبراز أن دعوة التوحيد سلسلة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص620، تحت عنوان «بلاغة التوكيد ودلالته البيانية»","url":""}]},{"id":"s37-29","number":29,"surah":37,"verses":[84],"references":[{"surah":37,"verses":[84]}],"verseLabel":"الصافات: 84","question":"لماذا نُسبت السلامة إلى ﴿قَلْبٍ﴾ إبراهيم؟","answer":"لأن القلب موضع الاعتقاد والقصد، فإذا سلم من الشرك والغل والفساد تبعه العمل؛ فسلامته أصل سلامة الإنسان كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص623، تحت عنوان «بلاغة استعمال مفردة القلب»","url":""}]},{"id":"s37-79","number":79,"surah":37,"verses":[84],"references":[{"surah":37,"verses":[84]}],"verseLabel":"الصافات: 84","question":"لماذا نُكّر ﴿قَلْبٍ﴾ في قوله ﴿بِقَلْبٍ سَلِيمٍ﴾؟","answer":"للتعظيم؛ أي بقلب عظيم الشأن بلغ درجة متميزة من الصفاء والإخلاص لا يحيط بمدحه وصف موجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص624، تحت عنوان «نكتة تنكير لفظ (قلب)»","url":""}]},{"id":"s37-30","number":30,"surah":37,"verses":[88,89],"references":[{"surah":37,"verses":[88,89]}],"verseLabel":"الصافات: 88-89","question":"لماذا قيل ﴿فَنَظَرَ نَظْرَةً فِي النُّجُومِ﴾ لا «إلى النجوم»؟","answer":"لأن المراد إعمال الفكر فيما يتعلق بالنجوم لا مجرد إبصارها؛ اتخذ النظر فيها وسيلةً للتورية والخلاص من الخروج معهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص635، تحت عنوان «فائدة استعمال حرف الظرفية دون (إلى)»","url":""}]},{"id":"s37-80","number":80,"surah":37,"verses":[88,89],"references":[{"surah":37,"verses":[88,89]}],"verseLabel":"الصافات: 88-89","question":"أين التورية في قول إبراهيم ﴿إِنِّي سَقِيمٌ﴾؟","answer":"أوهم قومه مرض الجسد، وأراد معنى صحيحًا يحتمله اللفظ؛ كسقمه من شركهم أو أنه صائر إلى السقم والموت، فنجا من الخروج دون تصريح بالكذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص639، تحت عنوان «بديع فن التورية»","url":""}]},{"id":"s37-31","number":31,"surah":37,"verses":[91],"references":[{"surah":37,"verses":[91]}],"verseLabel":"الصافات: 91","question":"ما غرض سؤال إبراهيم الأصنام ﴿أَلَا تَأْكُلُونَ﴾؟","answer":"هو استهزاء وتعريض بعجزها؛ قدّم لها الطعام ثم سألها ليقيم على قومه حجة محسوسة: من لا يأكل ولا يجيب لا يستحق العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص645–646، تحت عنوان «معنى الاستفهام وغرضه المجازي»","url":""}]},{"id":"s37-81","number":81,"surah":37,"verses":[91],"references":[{"surah":37,"verses":[91]}],"verseLabel":"الصافات: 91","question":"ما غرض قوله للأصنام ﴿مَا لَكُمْ لَا تَنْطِقُونَ﴾؟","answer":"زيادة في التحقير وإلزام لقومه؛ فصمتها بعد السؤال يكشف عجزها التام عن النفع والجواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص648، تحت عنوان «غرض الاستفهام وبلاغته»","url":""}]},{"id":"s37-82","number":82,"surah":37,"verses":[91],"references":[{"surah":37,"verses":[91]}],"verseLabel":"الصافات: 91","question":"لماذا خاطب إبراهيم الأصنام خطاب العقلاء؟","answer":"ليجاري تصور عابديها ثم يهدمه عمليًا؛ عاملها لحظةً كمن يسمع ويجيب، فظهر للحاضرين أنها جماد أعجز من أن تُعبد.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص648، تحت عنوان «نكتة مخاطبة الجماد مخاطبة العقلاء»","url":""}]},{"id":"s37-32","number":32,"surah":37,"verses":[93],"references":[{"surah":37,"verses":[93]}],"verseLabel":"الصافات: 93","question":"ما المعنيان اللذان يجتمعان في قوله ﴿ضَرْبًا بِالْيَمِينِ﴾؟","answer":"يحتمل اليمين الجارحة التي باشر بها الضرب، ويحتمل القوة أو القسم الذي سبق منه بكسر الأصنام؛ فيجمع التعبير قوة التنفيذ وصدق العزم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص651–652، تحت عنوان «براعة استعمال مفردة (اليمين) بمعنيين مرادين»","url":""}]},{"id":"s37-33","number":33,"surah":37,"verses":[99],"references":[{"surah":37,"verses":[99]}],"verseLabel":"الصافات: 99","question":"لماذا عبّر إبراهيم عن هجرته بقوله ﴿إِنِّي ذَاهِبٌ إِلَى رَبِّي﴾؟","answer":"لأن ذهابه لم يكن انتقال مكان فحسب، بل مفارقةً للشرك وتوجهًا إلى الله بالطاعة؛ فربط الهجرة بقصدها الأعلى.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص667، تحت عنوان «دلالة التعبير بلفظ ﴿ذاهب﴾»","url":""}]},{"id":"s37-83","number":83,"surah":37,"verses":[99],"references":[{"surah":37,"verses":[99]}],"verseLabel":"الصافات: 99","question":"لماذا قال ﴿إِلَى رَبِّي﴾ ولم يقل «إلى الله»؟","answer":"عنوان الربوبية يناسب طلب الرعاية والهداية في الغربة، ويظهر ثقته بمن تولى تربيته وإحسانه وتدبير أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص668، تحت عنوان «بلاغة إيثار عنوان الربوبية على الألوهية»","url":""}]},{"id":"s37-34","number":34,"surah":37,"verses":[100],"references":[{"surah":37,"verses":[100]}],"verseLabel":"الصافات: 100","question":"لماذا قال إبراهيم ﴿رَبِّ هَبْ لِي مِنَ الصَّالِحِينَ﴾ ولم يصرح بالولد؟","answer":"حذف المفعول اعتمادًا على وضوح المراد، وفيه أدب ورقة في الطلب؛ لم يتكلف التفصيل بل فوّض إلى ربه أن يهبه غلامًا صالحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص670، تحت عنوان «علة حذف مفعول فعل الهبة»","url":""}]},{"id":"s37-84","number":84,"surah":37,"verses":[100],"references":[{"surah":37,"verses":[100]}],"verseLabel":"الصافات: 100","question":"لماذا عبّر عن طلب الولد بلفظ ﴿هَبْ﴾؟","answer":"لأن الولد هبة محضة من الله لا تنالها القدرة البشرية وحدها؛ فاللفظ يعلن افتقاره ورجاءه في فضل ربه بلا استحقاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص671، تحت عنوان «بلاغة استعمال مفردة الهبة»","url":""}]},{"id":"s37-35","number":35,"surah":37,"verses":[102],"references":[{"surah":37,"verses":[102]}],"verseLabel":"الصافات: 102","question":"لماذا قال الابن ﴿افْعَلْ مَا تُؤْمَرُ﴾ ولم يقل «اذبحني»؟","answer":"لإظهار امتثاله الكامل للوحي وتثبيت أبيه؛ أحال الفعل إلى أمر الله دون تصوير ألم الذبح، فجمع الأدب والشجاعة والتسليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص683–684، تحت عنوان «بلاغة استعمال مفردة الفعل دون الذبح»","url":""}]},{"id":"s37-36","number":36,"surah":37,"verses":[102],"references":[{"surah":37,"verses":[102]}],"verseLabel":"الصافات: 102","question":"ماذا تفيد السين في قول الابن ﴿سَتَجِدُنِي﴾؟","answer":"تفيد وعدًا قريبًا واثقًا بأنه سيثبت عند التنفيذ، مع أدبٍ لا يزكي النفس لأنه علق ذلك بمشيئة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص684–685، تحت عنوان «معنى السين في: ﴿ستجدني﴾»","url":""}]},{"id":"s37-85","number":85,"surah":37,"verses":[102],"references":[{"surah":37,"verses":[102]}],"verseLabel":"الصافات: 102","question":"لماذا قدّم قوله ﴿إِنْ شَاءَ اللَّهُ﴾ قبل ﴿مِنَ الصَّابِرِينَ﴾؟","answer":"ليعلن أن الصبر لا يكون بقوة النفس وحدها، بل بتوفيق الله؛ فسبق الاستعانةُ دعوى القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص685، تحت عنوان «نكتة تقديم المشيئة»","url":""}]},{"id":"s37-86","number":86,"surah":37,"verses":[102],"references":[{"surah":37,"verses":[102]}],"verseLabel":"الصافات: 102","question":"لماذا قال ﴿مِنَ الصَّابِرِينَ﴾ بالجمع؟","answer":"تواضع فلم يدع أنه الصابر الكامل منفردًا، بل سأل أن ينتظم في جماعة أهل الصبر؛ والجماعة أعون على الثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص685، تحت عنوان «نكتة الجمع دون الإفراد»","url":""}]},{"id":"s37-37","number":37,"surah":37,"verses":[103],"references":[{"surah":37,"verses":[103]}],"verseLabel":"الصافات: 103","question":"لماذا قال ﴿فَلَمَّا أَسْلَمَا﴾ بضمير التثنية؟","answer":"لأن الامتحان قام على تسليم الأب والابن معًا: إبراهيم نفذ أمر ربه، والابن رضي وانقاد؛ فنجاح البلاء ثمرة موقفهما المشترك.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص691، تحت عنوان «نكتة ذكر ضمير التثنية في ﴿أسلما﴾»","url":""}]},{"id":"s37-87","number":87,"surah":37,"verses":[103],"references":[{"surah":37,"verses":[103]}],"verseLabel":"الصافات: 103","question":"ما الصورة في قوله ﴿وَتَلَّهُ لِلْجَبِينِ﴾؟","answer":"﴿تله﴾ تصور إضجاعه بقوة وثبات، ووضع الجبين على الأرض يبرز كمال الخضوع ويبعد النظر إلى وجهه رحمةً به واستعدادًا للتنفيذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص692، تحت عنوان «نكتة التعبير في قوله: ﴿وتله للجبين﴾»","url":""}]},{"id":"s37-38","number":38,"surah":37,"verses":[104,105],"references":[{"surah":37,"verses":[104,105]}],"verseLabel":"الصافات: 104-105","question":"كيف قيل لإبراهيم ﴿قَدْ صَدَّقْتَ الرُّؤْيَا﴾ مع أن الذبح لم يقع؟","answer":"لأنه حقق المقصود من الابتلاء: صدق العزم وباشر أسباب التنفيذ حتى لم يبق إلا إمرار السكين، فعدّ امتثاله تصديقًا تامًا للرؤيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص694–695، تحت عنوان «نكتة استعمال فعل التصديق وتأكيده بحرف التحقيق»","url":""}]},{"id":"s37-39","number":39,"surah":37,"verses":[107],"references":[{"surah":37,"verses":[107]}],"verseLabel":"الصافات: 107","question":"ماذا يفيد قوله ﴿وَفَدَيْنَاهُ﴾ وإسناد الفداء إلى ضمير العظمة؟","answer":"يبرز أن الله تولى الفداء بفضله، وأن الواقعة عظيمة متصلة بعنايته؛ فصار الفداء تشريفًا لإبراهيم وابنه وإبقاءً لذكرهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص700، تحت عنوان «نكتة التعبير بجملة: ﴿وفديناه﴾ وإسناد الفعل لضمير العظمة»","url":""}]},{"id":"s37-88","number":88,"surah":37,"verses":[107],"references":[{"surah":37,"verses":[107]}],"verseLabel":"الصافات: 107","question":"لماذا نُكّر ﴿ذِبْحٍ﴾ في قوله ﴿بِذِبْحٍ عَظِيمٍ﴾؟","answer":"للتعظيم؛ أي بفداء جليل الشأن غير مألوف، قُدّم بدلًا من الابن في هذا الامتحان العظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص701، تحت عنوان «نكتة تنكير لفظ (ذبح)»","url":""}]},{"id":"s37-89","number":89,"surah":37,"verses":[107],"references":[{"surah":37,"verses":[107]}],"verseLabel":"الصافات: 107","question":"لماذا وُصف الذبح بأنه ﴿عَظِيمٍ﴾؟","answer":"لعظمة الفداء والمفديّ به ومَن شرعه؛ فهو آية على رحمة الله وطاعة خليله، وبقي أثره سنةً في الأضاحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص701، تحت عنوان «نكتة وصف الذبح بـ﴿عظيم﴾»","url":""}]},{"id":"s37-40","number":40,"surah":37,"verses":[112],"references":[{"surah":37,"verses":[112]}],"verseLabel":"الصافات: 112","question":"لماذا جاءت البشارة بإسحاق موصوفًا بأنه ﴿نَبِيًّا﴾؟","answer":"لأنها ليست بشارة بولادته فقط، بل بمستقبله وعلو منزلته؛ سيكون نبيًا، فاجتمع لإبراهيم سرور الولد وشرف النبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص715، تحت عنوان «دلالة موقع لفظ ﴿نبيًّا﴾»","url":""}]},{"id":"s37-90","number":90,"surah":37,"verses":[112],"references":[{"surah":37,"verses":[112]}],"verseLabel":"الصافات: 112","question":"ماذا تضيف عبارة ﴿مِنَ الصَّالِحِينَ﴾ بعد وصف إسحاق بالنبوة؟","answer":"تثبت أن النبوة اقترنت بصلاح السيرة والعمل، وهو مدح مستقل لا يغني عنه ذكر المنصب؛ فالصلاح كمال أخلاقي وعبادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص716، تحت عنوان «دلالة موقع: ﴿من الصالحين﴾»","url":""}]},{"id":"s37-41","number":41,"surah":37,"verses":[125],"references":[{"surah":37,"verses":[125]}],"verseLabel":"الصافات: 125","question":"ما غرض استفهام إلياس ﴿أَتَدْعُونَ بَعْلًا﴾؟","answer":"إنكار وتوبيخ على عبادة صنم عاجز وترك عبادة الله؛ فالاستفهام يوقظهم إلى قبح المفاضلة التي صنعوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص749، تحت عنوان «بلاغة الاستفهام ونوعه وغرضه»","url":""}]},{"id":"s37-91","number":91,"surah":37,"verses":[125],"references":[{"surah":37,"verses":[125]}],"verseLabel":"الصافات: 125","question":"ما أثر الطباق بين ﴿تَدْعُونَ﴾ و﴿تَذَرُونَ﴾؟","answer":"يكشف المفارقة بحدة: أقبلوا على الباطل وتركوا الحق، فجمع الفعلان المتضادان انحرافهم في صورة موجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص751، تحت عنوان «بلاغة الطباق بين (تدعون) و(تذرون)»","url":""}]},{"id":"s37-92","number":92,"surah":37,"verses":[125],"references":[{"surah":37,"verses":[125]}],"verseLabel":"الصافات: 125","question":"لماذا وُصف الله بأنه ﴿أَحْسَنَ الْخَالِقِينَ﴾ في هذا المقام؟","answer":"لمقابلة الصنم المصنوع بالخالق الحق المتصف بأكمل الصفات؛ ففي الوصف تسفيه لمن ترك الأحسن وعبد ما صنعته الأيدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص751، تحت عنوان «غرض وصف الله تعالى بـ﴿أحسن الخالقين﴾»","url":""}]},{"id":"s37-42","number":42,"surah":37,"verses":[139],"references":[{"surah":37,"verses":[139]}],"verseLabel":"الصافات: 139","question":"لماذا أكدت الآية رسالة يونس قبل ذكر إباقه؟","answer":"دفعًا لتوهم أن خطأه يبطل رسالته؛ أكدت أنه من المرسلين، فالنبوة ثابتة لا تفارقه، وما وقع كان اجتهادًا عوتب عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص793، تحت عنوان «نكتة تتابع المؤكدات في الآية»","url":""}]},{"id":"s37-93","number":93,"surah":37,"verses":[139],"references":[{"surah":37,"verses":[139]}],"verseLabel":"الصافات: 139","question":"لماذا عبّر عن ذهاب يونس إلى السفينة بقوله ﴿أَبَقَ﴾؟","answer":"شبّه خروجه قبل الإذن بإباق العبد من سيده، لا انتقاصًا من نبوته بل لتصوير شدة العتاب ووحشته حين فارق قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص794–795، تحت عنوان «دلالة التعبير بـ﴿أبق﴾ مادة وصيغة»","url":""}]},{"id":"s37-43","number":43,"surah":37,"verses":[141],"references":[{"surah":37,"verses":[141]}],"verseLabel":"الصافات: 141","question":"لماذا قيل ﴿فَسَاهَمَ﴾ في وصف القرعة؟","answer":"لأن ركاب السفينة اشتركوا فيها كل بسهم، فصيغة المشاركة تصور عدل الاقتراع وتكافؤهم فيه حتى خرج السهم على يونس.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص797، تحت عنوان «دلالة التعبير بـ﴿ساهم﴾ مادة وصيغة»","url":""}]},{"id":"s37-94","number":94,"surah":37,"verses":[141],"references":[{"surah":37,"verses":[141]}],"verseLabel":"الصافات: 141","question":"ما الصورة في وصف يونس بأنه ﴿مِنَ الْمُدْحَضِينَ﴾؟","answer":"تصوره مزلقًا مزاحًا من مكانه إلى البحر بعد غلبة سهمه؛ واستعير الإدحاض للخسران في القرعة وما ترتب عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص799، تحت عنوان «بلاغة التعبير بالاستعارة في ﴿المدحضين﴾»","url":""}]},{"id":"s37-44","number":44,"surah":37,"verses":[143,144],"references":[{"surah":37,"verses":[143,144]}],"verseLabel":"الصافات: 143-144","question":"ماذا تفيد الشرطية ﴿فَلَوْلَا أَنَّهُ كَانَ مِنَ الْمُسَبِّحِينَ لَلَبِثَ فِي بَطْنِهِ﴾؟","answer":"تقرر أن تسبيحه كان سبب النجاة؛ فلولا ذكره وصلاته لبقي في بطن الحوت إلى البعث، فتظهر قيمة العبادة في زمن الرخاء والشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص802، تحت عنوان «بلاغة التعبير بالشرطية»","url":""}]},{"id":"s37-95","number":95,"surah":37,"verses":[143,144],"references":[{"surah":37,"verses":[143,144]}],"verseLabel":"الصافات: 143-144","question":"لماذا قيل ﴿مِنَ الْمُسَبِّحِينَ﴾ لا «مسبحًا»؟","answer":"ليدل على رسوخ التسبيح واستمراره وأنه واحد من جماعة عُرفوا به، لا أنه ذكر طارئ عند المحنة فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص804، تحت عنوان «دلالة التعبير بـ﴿المسبحين﴾ مادة وصيغة»","url":""}]},{"id":"s37-45","number":45,"surah":37,"verses":[145],"references":[{"surah":37,"verses":[145]}],"verseLabel":"الصافات: 145","question":"لماذا قيل إن يونس نُبذ ﴿بِالْعَرَاءِ﴾؟","answer":"العراء أرض مكشوفة خالية من النبات والظل؛ فيصور انتقاله من ظلمات البحر إلى فضاء خالٍ وهو شديد الضعف، لتظهر عناية الله اللاحقة به.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص14–15، تحت عنوان «دلالة التعبير بلفظ العراء مادة وصيغة»","url":""}]},{"id":"s37-96","number":96,"surah":37,"verses":[145],"references":[{"surah":37,"verses":[145]}],"verseLabel":"الصافات: 145","question":"ما دلالة قوله ﴿وَأَنْبَتْنَا عَلَيْهِ شَجَرَةً مِنْ يَقْطِينٍ﴾ بعد نبذه سقيمًا؟","answer":"يعطف حال الرعاية على حال الضعف: أنبت الله عليه ما يظله ويلائمه سريعًا، فبرز التحول من الكرب والعراء إلى الرحمة والشفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص16، تحت عنوان «معنى الواو ودلالتها في قوله: ﴿وأنبتنا﴾»","url":""}]},{"id":"s37-46","number":46,"surah":37,"verses":[147],"references":[{"surah":37,"verses":[147]}],"verseLabel":"الصافات: 147","question":"ما أوجه دلالة ﴿أَوْ يَزِيدُونَ﴾ في قوله ﴿مِائَةِ أَلْفٍ أَوْ يَزِيدُونَ﴾؟","answer":"تذكر الموسوعة أن ﴿أو﴾ قد تكون بمعنى الواو، أو للإضراب بمعنى بل، فتثبت الزيادة على المائة ألف. وقد تأتي على تقدير الرائي الذي يشاهد كثرتهم فيقول: مائة ألف أو يزيدون؛ فالتردد في هذا الوجه وصف لتقدير الناظر، لا لعلم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص21–22، تحت عنوان «معنى ﴿أو﴾ ودلالتها»","url":""}]},{"id":"s37-47","number":47,"surah":37,"verses":[149],"references":[{"surah":37,"verses":[149]}],"verseLabel":"الصافات: 149","question":"لماذا قيل ﴿لِرَبِّكَ﴾ في هذا الإنكار؟","answer":"إضافة الرب إلى النبي ﷺ تستحضر كمال الربوبية والعناية والخلق، فتجعل نسبة النقص إلى الرب الكامل أشد قبحًا وتناقضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص32، تحت عنوان «نكتة التعبير بلفظ الربوبية وإضافتها في ﴿ألربك﴾»","url":""}]},{"id":"s37-48","number":48,"surah":37,"verses":[164,165,166],"references":[{"surah":37,"verses":[164,165,166]}],"verseLabel":"الصافات: 164-166","question":"ماذا يفيد قول الملائكة ﴿إِلَّا لَهُ مَقَامٌ مَعْلُومٌ﴾؟","answer":"يفيد أن لكل ملك منزلة ووظيفة محددة لا يتجاوزها، فعبوديتهم منظمة خاضعة وليست لهم ألوهية كما زعم المشركون.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص81–82، تحت عنوان «بلاغة التعبير بالمقام»","url":""}]},{"id":"s37-97","number":97,"surah":37,"verses":[164,165,166],"references":[{"surah":37,"verses":[164,165,166]}],"verseLabel":"الصافات: 164-166","question":"لماذا وصف الملائكة أنفسهم بأنهم ﴿الصَّافُّونَ﴾؟","answer":"لأن الاصطفاف يصور اجتماعهم المنظم في العبادة والطاعة، ثابتين في مقاماتهم خاضعين لربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص84، تحت عنوان «بلاغة التعبير بمادة الاصطفاف»","url":""}]},{"id":"s37-98","number":98,"surah":37,"verses":[164,165,166],"references":[{"surah":37,"verses":[164,165,166]}],"verseLabel":"الصافات: 164-166","question":"لماذا قالوا ﴿وَإِنَّا لَنَحْنُ الْمُسَبِّحُونَ﴾؟","answer":"ليقرروا أنهم منزهون لله عابدون له، فيبطلوا قول من نسب إليهم البنوة أو جعلهم شركاء؛ فالتسبيح صفتهم لا الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص86، تحت عنوان «نكتة استعمال مادة التسبيح»","url":""}]},{"id":"s37-49","number":49,"surah":37,"verses":[171,172,173],"references":[{"surah":37,"verses":[171,172,173]}],"verseLabel":"الصافات: 171-173","question":"كيف يكون الرسل ﴿لَهُمُ الْمَنْصُورُونَ﴾ مع ما يصيبهم من أذى؟","answer":"النصر أوسع من السلامة العاجلة؛ هو ظهور الحجة وثبات الرسالة وحسن العاقبة، وقد يتأخر أو يأتي معنويًا، لكن كلمة الله لا تُغلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص106–107، تحت عنوان «دلالة استعمال مادة النصر»","url":""}]},{"id":"s37-99","number":99,"surah":37,"verses":[171,172,173],"references":[{"surah":37,"verses":[171,172,173]}],"verseLabel":"الصافات: 171-173","question":"لماذا قال ﴿وَإِنَّ جُنْدَنَا لَهُمُ الْغَالِبُونَ﴾؟","answer":"الغلبة تشمل قهر الباطل وعلو الحجة وانتصار المؤمنين في المآل؛ وإضافتهم إلى الله تشريف وضمان بأن العاقبة لجنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص109، تحت عنوان «بلاغة استعمال مادة الغلبة»","url":""}]},{"id":"s37-50","number":50,"surah":37,"verses":[180,181,182],"references":[{"surah":37,"verses":[180,181,182]}],"verseLabel":"الصافات: 180-182","question":"ما سر ترتيب ختام السورة: تسبيح ثم سلام على المرسلين ثم حمد؟","answer":"بدأ بتنزيه الله عما نسبه المشركون إليه، ثم نزّه رسله وسلّم عليهم، ثم ختم بالحمد الجامع لكل كمال؛ فانتظم الختام من دفع النقص إلى الثناء التام.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص131، تحت عنوان «براعة الترتيب بالعطف»","url":""}]},{"id":"s37-100","number":100,"surah":37,"verses":[180,181,182],"references":[{"surah":37,"verses":[180,181,182]}],"verseLabel":"الصافات: 180-182","question":"لماذا ختمت سورة الصافات بالحمد؟","answer":"لأن الحمد يجمع الثناء على الله بعد تنزيهه ونصر رسله، ويؤذن بأن العاقبة المحمودة للحق وأهله؛ فوافق مطلع التوحيد خاتمة التعظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص136، تحت عنوان «براعة اختتام السورة بالحمد»","url":""}]},{"id":"s37-101","number":101,"surah":37,"verses":[4,5,180,182],"references":[{"surah":37,"verses":[4,5,180,182]}],"verseLabel":"الصافات: 4، 5، 180، 182","question":"كيف عادت خاتمة السورة إلى مطلعها في تناسق بياني محكم؟","answer":"افتتحت السورة بتوحيد الربوبية: ﴿إِنَّ إِلَهَكُمْ لَوَاحِدٌ رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا﴾، وختمت بتنزيه هذا الرب وحمده بوصفه ﴿رَبِّ الْعَالَمِينَ﴾. فالمطلع ذكر مُلكه للسموات والأرض، والخاتمة جمعت عوالمها كلها تحت ربوبيته وحمده، فالتقى أول السورة بآخرها.","sources":[{"label":"فاضل السامرائي، «تناسب فاتحة سورة الصافات مع خاتمتها»، مادة إلكترونية مباشرة من بحث «تناسب فواتح سور القرآن الكريم مع خواتيمها».","url":""}]},{"id":"s37-102","number":102,"surah":37,"verses":[8],"references":[{"surah":37,"verses":[8]}],"verseLabel":"الصافات: 8","question":"ما سر التعبير المشدد ﴿لَا يَسَّمَّعُونَ﴾ بدل صيغة «لا يتسمعون»؟","answer":"أصل الصيغة «يتسمعون»، ثم أُبدلت التاء وأُدغمت، فاجتمع في اللفظ تشديدان يدلان على قوة الحدث ومبالغتهم في طلب السماع. وهم يريدون بلوغ أقصى التسمع في أقصر وقت قبل أن تدركهم الشهب، فجاء اللفظ المكثف مصورًا شدة المحاولة وسرعتها.","sources":[{"label":"فاضل السامرائي، «ما اللمسة البيانية في يسَّمَّعون؟»، تدارس القرآن الكريم.","url":""}]},{"id":"s37-103","number":103,"surah":37,"verses":[22],"references":[{"surah":37,"verses":[22]}],"verseLabel":"الصافات: 22","question":"ما سر التعبير بـ﴿أَزْوَاجَهُمْ﴾؟ وهل المراد زوجاتهم؟","answer":"المراد أشباه الظالمين ونظراؤهم في العمل، فيُحشر أصحاب الذنب الواحد بعضهم مع بعض. فالزوج في أصل الاستعمال هو القرين المماثل أو المقابل، ولذلك اتسع اللفظ هنا ليصوّر جمع كل طائفة مع من يشاكلها، لا جمع الرجال مع زوجاتهم فحسب.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص131، مبحث «الفرق بين الزوج والبعل».","url":""}]},{"id":"s37-104","number":104,"surah":37,"verses":[31],"references":[{"surah":37,"verses":[31]}],"verseLabel":"الصافات: 31","question":"ما الدلالة المخيفة في قولهم: ﴿فَحَقَّ عَلَيْنَا قَوْلُ رَبِّنَا﴾؟","answer":"«حق القول» و«حقت الكلمة» يردان في الاستعمال القرآني عند ثبوت العذاب ووجوبه على من استحقه. فالعبارة ليست مجرد تحقق خبر، بل إقرار بأن الوعيد السابق قد صار نافذًا فيهم، وأن كلمة ملء جهنم قد استقرت عليهم فلا مهرب منها.","sources":[{"label":"فاضل السامرائي، «ما معنى حق القول؟»، تدارس القرآن الكريم.","url":""}]},{"id":"s37-105","number":105,"surah":37,"verses":[42],"references":[{"surah":37,"verses":[42]}],"verseLabel":"الصافات: 42","question":"ما دلالة اختيار جمع ﴿فَوَاكِهُ﴾ هنا، واختيار اسم الجنس ﴿فَاكِهَةٍ﴾ للسابقين في سورة الواقعة؟","answer":"«فاكهة» اسم جنس يشمل الواحد والمثنى والجمع، والنوع الواحد والأنواع المتعددة، ولذلك هو أعم من «فواكه». ولما كان نعيم السابقين أعلى قيل في الواقعة: ﴿وَفَاكِهَةٍ مِمَّا يَتَخَيَّرُونَ﴾، أما هنا فجاء الجمع «فواكه» بما يلائم الدرجة المذكورة في السياق.","sources":[{"label":"فاضل السامرائي، «ما الفرق بين فاكهة وفواكه؟»، منصة باحث.","url":""}]},{"id":"s37-106","number":106,"surah":37,"verses":[45,47],"references":[{"surah":37,"verses":[45,47]}],"verseLabel":"الصافات: 45، 47","question":"ما سر بناء ﴿يُطَافُ عَلَيْهِمْ﴾ للمفعول، ومناسبته لقوله: ﴿يُنزَفُونَ﴾؟","answer":"جاء الطواف هنا مبنيًا لما لم يسم فاعله، وكذلك جاء «يُنزفون» على البناء نفسه، فانسجم بناء الفعلين في هذا المشهد. أما في سورة الواقعة فقيل: ﴿يَطُوفُ عَلَيْهِمْ وِلْدَانٌ﴾ مع قراءة «يَنزِفون» بالبناء للمعلوم؛ فانتظم كل سياق على نسقه التعبيري الخاص.","sources":[{"label":"فاضل السامرائي، «الفرق بين نعيم الصافات ونعيم السابقين في الواقعة»، تدارس القرآن الكريم.","url":""}]},{"id":"s37-107","number":107,"surah":37,"verses":[47],"references":[{"surah":37,"verses":[47]}],"verseLabel":"الصافات: 47","question":"كيف جمع التعبير ﴿لَا فِيهَا غَوْلٌ وَلَا هُمْ عَنْهَا يُنزَفُونَ﴾ بين سلامة الشراب وسلامة شاربه؟","answer":"نفى أولًا «الغول» عن الخمر نفسها، فلا تغتال العقل ولا تفسد البدن، ثم نفى «الإنزاف» عن الشارب، فلا يسكر ولا ينفد شرابه. فالأول وصف لسلامة المشروب، والثاني وصف لسلامة من يشربه ودوام متعته، فتم نفي آفات خمر الدنيا من الجانبين.","sources":[{"label":"فاضل السامرائي، «الفرق بين: لا يصدعون عنها ولا ينزفون، ولا فيها غول ولا هم عنها ينزفون»، تدارس القرآن الكريم.","url":""}]},{"id":"s37-108","number":108,"surah":37,"verses":[65],"references":[{"surah":37,"verses":[65]}],"verseLabel":"الصافات: 65","question":"كيف يصنع تشبيه ﴿طَلْعُهَا كَأَنَّهُ رُءُوسُ الشَّيَاطِينِ﴾ صورة مرعبة مع أن الطرفين غائبان عن الحس؟","answer":"هذا تشبيه تخييلي يطلق الذهن في أقبح صورة يستطيع تصورها؛ فالناس لم يروا طلع الزقوم ولا رؤوس الشياطين، لكن صورة الشيطان مستقرة في الخيال رمزًا لأقصى القبح. وبدل أن يحد التشبيه هيئة واحدة، يترك لكل نفس أن تستحضر أفظع ما تتخيله من منظر.","sources":[{"label":"فاضل السامرائي، «ما الحكمة من تشبيه طلع الزقوم برؤوس الشياطين؟»، تدارس القرآن الكريم.","url":""}]},{"id":"s37-109","number":109,"surah":37,"verses":[75,76],"references":[{"surah":37,"verses":[75,76]}],"verseLabel":"الصافات: 75، 76","question":"ما سر الواو في ﴿وَنَجَّيْنَاهُ وَأَهْلَهُ﴾، والفاء في نظيرها بسورة الأنبياء: ﴿فَنَجَّيْنَاهُ﴾؟","answer":"مقام الأنبياء أشد؛ فقد ذُكر تكذيب القوم ووصفهم بالسوء، ونصرة نوح عليهم ثم إغراقهم أجمعين، فناسبت الفاء سرعة الإجابة والنجاة في ذلك الكرب. أما الصافات فلم يذكر فيها القوم ولا شدة المواجهة بتلك التفاصيل، فجاءت الواو لمطلق الجمع من غير دلالة التعقيب السريع.","sources":[{"label":"فاضل السامرائي، «المقارنة بين: فاستجبنا له فنجيناه وأهله، ونجيناه وأهله»، منصة باحث.","url":""}]},{"id":"s37-110","number":110,"surah":37,"verses":[79],"references":[{"surah":37,"verses":[79]}],"verseLabel":"الصافات: 79","question":"ما سر تنكير ﴿سَلَامٌ﴾ في تحية نوح وسائر المرسلين؟","answer":"الأصل في النكرة العموم والشمول، فـ«سلام» أوسع من «السلام» المعرّف الذي قد يدل على سلام معين. ولهذا جاءت تحية الله في القرآن بالتنكير لتشمل كل جنس السلام ولا تدع منه شيئًا، سواء في سلامه على رسله أو في تحية أهل الجنة.","sources":[{"label":"فاضل السامرائي، «ما الفرق بين سلام والسلام؟»، تدارس القرآن الكريم.","url":""}]},{"id":"s37-111","number":111,"surah":37,"verses":[86],"references":[{"surah":37,"verses":[86]}],"verseLabel":"الصافات: 86","question":"كيف وسّع نصب ﴿إِفْكًا﴾ دائرة التوبيخ في قوله: ﴿أَئِفْكًا آلِهَةً دُونَ اللَّهِ تُرِيدُونَ﴾؟","answer":"يحتمل «إفكًا» أن يكون مفعولًا به، أي: أتريدون إفكًا، وتكون «آلهة» بدلًا منه؛ ويحتمل الحالية، أي: أتريدون آلهة حال كونكم آفكين؛ ويحتمل المفعول لأجله. هذا الاتساع النحوي يجمع توبيخهم على إرادة الباطل، وعلى اتخاذ الآلهة، وعلى حالهم في الافتراء.","sources":[{"label":"فاضل السامرائي، «أئفكًا آلهة دون الله تريدون: إعراب أئفكًا»، منصة باحث.","url":""}]},{"id":"s37-112","number":112,"surah":37,"verses":[98],"references":[{"surah":37,"verses":[98]}],"verseLabel":"الصافات: 98","question":"ما دلالة الفاء في ﴿فَأَرَادُوا بِهِ كَيْدًا﴾، والواو في نظيرها بسورة الأنبياء: ﴿وَأَرَادُوا بِهِ كَيْدًا﴾؟","answer":"في الصافات سبقت الآيةَ دعوتُهم المباشرة: ﴿ابْنُوا لَهُ بُنْيَانًا فَأَلْقُوهُ فِي الْجَحِيمِ﴾، فجاءت الفاء لتفيد ترتب إرادة الكيد وتعقيبها على هذا القرار قبل التنفيذ. أما في الأنبياء فذُكرت إرادة الكيد بعد وقوع الإلقاء وجعل النار بردًا وسلامًا، فلم يناسبها التعقيب بالفاء.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج4، ص157-161، مبحث «قصة إبراهيم بين الأنبياء والصافات».","url":""}]},{"id":"s37-113","number":113,"surah":37,"verses":[101],"references":[{"surah":37,"verses":[101]}],"verseLabel":"الصافات: 101","question":"ما سر وصف إسماعيل بـ﴿حَلِيمٍ﴾، ووصف إسحاق في مواضع أخرى بـ﴿عَلِيمٍ﴾؟","answer":"الحلم يظهر في مخالطة الناس وضبط النفس، وقد أبرز السياق علاقة إسماعيل بأبيه وقبوله أمر الذبح وصبره، كما عُرف بصدق الوعد ومشاركة أبيه في بناء البيت. أما سياق إسحاق فأبرز العلم والنبوة من غير عرض لمخالطة مماثلة؛ فالصفة المختارة هي الأبرز في المقام، ولا تنفي سائر الكمالات.","sources":[{"label":"فاضل السامرائي، «الغلامان الحليم والعليم»، منصة باحث.","url":""}]},{"id":"s37-114","number":114,"surah":37,"verses":[102],"references":[{"surah":37,"verses":[102]}],"verseLabel":"الصافات: 102","question":"ما سر المضارع في ﴿إِنِّي أَرَى فِي الْمَنَامِ أَنِّي أَذْبَحُكَ﴾ مع أن الرؤيا وقعت؟","answer":"المضارع يستحضر الرؤيا الماضية ويجعل صورتها حاضرة أمام السامع لشدة أهميتها، وهو ما يسمى حكاية الحال. ويُذكر كذلك أن الرؤيا تكررت، فناسبها ما يفيد التجدد؛ فصار المشهد حيًّا مستمرًا لا خبرًا ماضيًا بعيدًا.","sources":[{"label":"فاضل السامرائي، «دلالة صيغة المضارع في: إني أرى في المنام»، تدارس القرآن الكريم.","url":""}]},{"id":"s37-115","number":115,"surah":37,"verses":[116],"references":[{"surah":37,"verses":[116]}],"verseLabel":"الصافات: 116","question":"ما سر قوله: ﴿فَكَانُوا هُمُ الْغَالِبِينَ﴾ بعد قوله: ﴿وَنَصَرْنَاهُمْ﴾، مع أن مواضع أخرى عبرت بـ«جعلناهم»؟","answer":"سبق الفعلَ هنا التصريحُ بأن الله نجاهم ونصرهم، فدل السياق على أن غلبتهم ثمرة لذلك النصر: نصرهم فكانوا هم الغالبين. أما في قصة إبراهيم فقيل: ﴿فَجَعَلْنَاهُمُ الْأَسْفَلِينَ﴾ لأن قلب حال الكائدين وإسقاطهم هو جعل إلهي مباشر أبرزته الآية.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج4، ص157-161، مبحث «جعلناهم الأسفلين وفكانوا هم الغالبين».","url":""}]},{"id":"s37-116","number":116,"surah":37,"verses":[130],"references":[{"surah":37,"verses":[130]}],"verseLabel":"الصافات: 130","question":"ما سر التعبير بـ﴿إِلْ يَاسِينَ﴾ بدل «إلياس»؟","answer":"الأسماء الأعجمية تتصرف فيها العرب بصور متعددة، مثل «سيناء» و«سينين»، وقد يكون للنبي أكثر من اسم مستعمل في قومه، فيقال إلياس وإل ياسين. وتوجد قراءة «آل ياسين» التي تجعل السلام على أهله وأتباعه؛ فتعدد القراءة والاستعمال يفتح المعنى ولا يخل به.","sources":[{"label":"فاضل السامرائي، «لم قيل: سلام على إل ياسين؟»، تدارس القرآن الكريم.","url":""}]},{"id":"s37-117","number":117,"surah":37,"verses":[133,148],"references":[{"surah":37,"verses":[133,148]}],"verseLabel":"الصافات: 133، 148","question":"ما سر تأخير السلام على لوط ويونس وعدم إفرادهما بقول: «سلام على...» عقب قصتيهما؟","answer":"ذُكرت في قصة يونس مؤاخذة ترك الأولى بألفاظ ﴿أَبَقَ﴾ و﴿مُلِيمٌ﴾، فلا يناسب أن يعقب ذلك مباشرة بالسلام الخاص. وفي قصة لوط انتقل الكلام سريعًا إلى أهله وقومه وآثارهم، ولم تُعرض دعوته كما عُرضت دعوة غيره؛ ثم شملهما السلام العام في خاتمة السورة: ﴿وَسَلَامٌ عَلَى الْمُرْسَلِينَ﴾.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص126، مبحث «السلام على الرسل في سورة الصافات».","url":""}]},{"id":"s37-118","number":118,"surah":37,"verses":[139,148],"references":[{"surah":37,"verses":[139,148]}],"verseLabel":"الصافات: 139، 148","question":"ما سر تفصيل قصة يونس في الصافات أكثر من سائر مواضعها؟","answer":"اختص هذا الموضع بسلسلة المشاهد كاملة: إباقه إلى الفلك، والمساهمة، والتقام الحوت، والنبذ بالعراء، وإنبات اليقطين، ثم إرساله إلى قومه وذكر عددهم وإيمانهم. أما المواضع الأخرى فتنتقي جانب الدعاء أو العتاب بحسب مقصد السياق؛ فالتفصيل هنا مقصود لإبراز الرحلة من الشدة إلى النجاة ثم الرسالة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج4، ص197-198، مبحث «قصة يونس في الصافات».","url":""}]},{"id":"s37-119","number":119,"surah":37,"verses":[159,180],"references":[{"surah":37,"verses":[159,180]}],"verseLabel":"الصافات: 159، 180","question":"ما سر قوله أولًا: ﴿سُبْحَانَ اللَّهِ عَمَّا يَصِفُونَ﴾، ثم قوله في الخاتمة: ﴿سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ﴾؟","answer":"جاء التنزيه الأول بعد دعوى واحدة هي اتخاذ الولد، فكفى فيها ﴿سُبْحَانَ اللَّهِ﴾. أما الخاتمة فجاءت بعد الوعد القطعي بنصر المرسلين وغلبة جند الله وتهديد المكذبين بالعذاب؛ فناسب مقام القوة والنصر إضافة ﴿رَبِّ الْعِزَّةِ﴾، إذ العزة هي الصفة المحورية في السياق.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج4، ص58-61، مبحث «تنوع صيغ التسبيح عما يصفون».","url":""}]},{"id":"s37-120","number":120,"surah":37,"verses":[171],"references":[{"surah":37,"verses":[171]}],"verseLabel":"الصافات: 171","question":"ما دلالة اللام في ﴿سَبَقَتْ كَلِمَتُنَا لِعِبَادِنَا الْمُرْسَلِينَ﴾، ومقابلتها بـ«سبق عليه القول»؟","answer":"إذا عُدي السبق باللام كان فيما ينفع ويُبشّر، كما هنا في كلمة النصر للمرسلين؛ وإذا عُدي بـ«على» جاء في الوعيد والعقوبة، نحو «سبق عليه القول». فاختيار الحرف يرسم اتجاه الكلمة: اللام إيصال خير إلى أصحابها، و«على» استعلاء حكم العذاب عليهم.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج3، ص155-156، مبحث «سبق له وسبق عليه».","url":""}]},{"id":"s37-121","number":121,"surah":37,"verses":[175,179],"references":[{"surah":37,"verses":[175,179]}],"verseLabel":"الصافات: 175، 179","question":"ما سر ذكر المفعول في ﴿وَأَبْصِرْهُمْ﴾ أولًا، ثم حذفه في ﴿وَأَبْصِرْ﴾؟","answer":"الرؤية الأولى متجهة إلى قوم معينين وما نزل بهم يوم بدر من قتل وأسر وهزيمة، فذُكر الضمير لتعيينهم: ﴿أَبْصِرْهُمْ﴾. أما الثانية فاتصلت بفتح مكة وما امتد من أثره هداية ورحمة وفتحًا عامًا لجزيرة العرب، فأُطلق الفعل بحذف المفعول ليتسع مجال الإبصار ولا ينحصر في جماعة بعينها.","sources":[{"label":"فاضل السامرائي، أسرار البيان في التعبير القرآني، مبحث «الذكر والحذف: وأبصرهم وأبصر»، نص الكتاب الإلكتروني المباشر.","url":""}]},{"id":"s37-122","number":122,"surah":37,"verses":[180],"references":[{"surah":37,"verses":[180]}],"verseLabel":"الصافات: 180","question":"ما أثر وصف الله في الخاتمة بأنه ﴿رَبِّ الْعِزَّةِ﴾؟","answer":"سبقت الخاتمةَ كلمات النصر والغلبة: ﴿إِنَّهُمْ لَهُمُ الْمَنْصُورُونَ﴾ و﴿إِنَّ جُنْدَنَا لَهُمُ الْغَالِبُونَ﴾، ثم جاء الوعيد بنزول العذاب. فاختير «رب العزة» ليقرر أن العزة كلها ملكه وتحت ربوبيته، وأن النصر والغلبة أثران من آثارها، وتنزه صاحبها عما يصفه به المشركون.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج4، ص58-61، مبحث «سبحان ربك رب العزة عما يصفون».","url":""}]},{"id":"s37-123","number":123,"surah":37,"verses":[5],"references":[{"surah":37,"verses":[5]}],"verseLabel":"الصافات: 5","question":"ما سر ذكر ﴿رَبُّ الْمَشَارِقِ﴾ وحذف «المغارب» في مطلع السورة؟","answer":"خُصّت المشارق بالذكر لمناسبتها ما بعدها من تزيين السماء بالكواكب؛ فالزينة تبدو عند طلوع الكواكب وإشراقها. كما أن قذف الشياطين بالشهب يتصل بمشارق الكواكب لا بمغاربها، فكان الاقتصار على المشارق منسجمًا مع مشهد الزينة والحفظ الذي أعقب الآية.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص110، مبحث «ذكر المشارق وحذف المغارب».","url":""}]},{"id":"s37-124","number":124,"surah":37,"verses":[6],"references":[{"surah":37,"verses":[6]}],"verseLabel":"الصافات: 6","question":"ما الأثر البياني في مجيء ﴿الْكَوَاكِبِ﴾ بدلًا بعد قوله: ﴿بِزِينَةٍ﴾؟","answer":"«الزينة» لفظ عام، ثم جاء البدل ﴿الْكَوَاكِبِ﴾ ليعيّن هذه الزينة ويخصصها بعد إجمالها. وبذلك ينتقل التصوير من معنى الزينة المطلق إلى صورتها المشاهدة في السماء، فيجتمع في التركيب التشويق بالإجمال ثم البيان بالتخصيص.","sources":[{"label":"فاضل السامرائي، «ما إعراب كلمة الكواكب في قوله: بزينة الكواكب؟»، مادة إلكترونية في تدارس القرآن الكريم.","url":""}]},{"id":"s37-125","number":125,"surah":37,"verses":[7,10],"references":[{"surah":37,"verses":[7,10]}],"verseLabel":"الصافات: 7، 10","question":"ما سر وصف الشهاب هنا بأنه ﴿ثَاقِبٌ﴾، ووصفه في سورة الحجر بأنه ﴿مُبِينٌ﴾؟","answer":"سياق الصافات أشد: جاء فيه المصدر ﴿حِفْظًا﴾ الدال على الثبوت، ووُصف الشيطان بالمارد، وذُكر القذف من كل جانب والدحور والعذاب الواصب، كما عبّر عن أخذ السمع بالخطف السريع. فناسب هذه الشدة شهاب نافذ محرق «ثاقب»، أما سياق الحجر فناسبه وصف «مبين».","sources":[{"label":"فاضل السامرائي، «شهاب ثاقب وشهاب مبين»، تدارس القرآن الكريم.","url":""}]},{"id":"s37-126","number":126,"surah":37,"verses":[60],"references":[{"surah":37,"verses":[60]}],"verseLabel":"الصافات: 60","question":"ما سر اجتماع «إنَّ» ولام التوكيد وضمير الفصل في ﴿إِنَّ هَذَا لَهُوَ الْفَوْزُ الْعَظِيمُ﴾؟","answer":"جاء هذا التوكيد المتراكم بعد أن عاين المؤمن نعيمه ورأى قرينه في سواء الجحيم، فأدرك مقدار النجاة التي نالها. لذلك لم يكن المقام مجرد إخبار عن الفوز، بل مقام دهشة وفرح ويقين بعد مشاهدة الفرق الهائل، فناسبه أقوى صيغ التثبيت والحصر.","sources":[{"label":"فاضل السامرائي، «الفروق الدلالية في تعبيرات الفوز العظيم»، تدارس القرآن الكريم.","url":""}]},{"id":"s37-127","number":127,"surah":37,"verses":[85],"references":[{"surah":37,"verses":[85]}],"verseLabel":"الصافات: 85","question":"ما سر قوة الاستفهام في ﴿مَاذَا تَعْبُدُونَ﴾ مقارنة بقوله في الشعراء: ﴿مَا تَعْبُدُونَ﴾؟","answer":"«ماذا» أطول مبنى وأقوى في الاستفهام. وسياق الشعراء حوار ومحاجة ينتظر فيه إبراهيم جواب قومه، أما هنا فالموقف هجوم وإنكار شديد؛ فلم يمهلهم للجواب بل أتبع السؤال مباشرة بقوله: ﴿أَئِفْكًا آلِهَةً دُونَ اللَّهِ تُرِيدُونَ﴾، فناسبته الصيغة الأقوى.","sources":[{"label":"فاضل السامرائي، «ماذا تعبدون وما تعبدون في خطاب إبراهيم»، منصة باحث.","url":""}]},{"id":"s37-128","number":128,"surah":37,"verses":[107],"references":[{"surah":37,"verses":[107]}],"verseLabel":"الصافات: 107","question":"ما الدقة في كسر الذال في ﴿بِذِبْحٍ عَظِيمٍ﴾؟","answer":"«الذَّبح» بفتح الذال مصدر يدل على عملية الذبح، أما «الذِّبح» بكسرها فهو ما يُذبح، أي المذبوح الذي جُعل فداء. فجاءت الكسرة لتحدد أن الفداء كان بذبيحة عظيمة، لا بمجرد فعل الذبح بوصفه حدثًا.","sources":[{"label":"فاضل السامرائي، «الفرق بين الذَّبح والذِّبح»، تدارس القرآن الكريم.","url":""}]},{"id":"s37-129","number":129,"surah":37,"verses":[143,166],"references":[{"surah":37,"verses":[143,166]}],"verseLabel":"الصافات: 143، 166","question":"ما دلالة الصيغة الاسمية في ﴿مِنَ الْمُسَبِّحِينَ﴾ و﴿لَنَحْنُ الْمُسَبِّحُونَ﴾؟","answer":"الاسم يدل على ثبوت الصفة ورسوخها، بخلاف الفعل الذي يبرز حدوثها وتجددها. فوصف يونس بـ«المسبحين» يدل على أن التسبيح كان شأنًا ثابتًا له قبل الكرب فكان سبب نجاته، ووصف الملائكة بـ«المسبحون» يدل على أن التسبيح صفتهم الدائمة الملازمة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص31، مبحث «دلالة الجملة الاسمية والفعلية في التسبيح».","url":""}]},{"id":"s38-1","number":1,"surah":38,"verses":[1],"references":[{"surah":38,"verses":[1]}],"verseLabel":"ص: 1","question":"ما دلالة افتتاح السورة بحرف ﴿ص﴾؟","answer":"توجه الموسوعة هذا الافتتاح على أنه من الحروف المقطعة الدالة على إعجاز القرآن؛ فهو مركب من الحروف التي يعرفونها ويؤلفون منها كلامهم، ثم يعجزون عن الإتيان بمثله. فيهيئ الحرف للقسم بالقرآن ويستدعي الإصغاء إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص146–147، تحت عنوان «سر الافتتاح بالحرف: ﴿ص﴾»","url":""}]},{"id":"s38-2","number":2,"surah":38,"verses":[1],"references":[{"surah":38,"verses":[1]}],"verseLabel":"ص: 1","question":"ما الذي يضيفه وصف القرآن بأنه ﴿ذِي الذِّكْرِ﴾؟","answer":"يصفه بأنه صاحب الشرف والبيان والتذكير والموعظة؛ فهو كتاب يوقظ القلوب ويبين لها ما ينفعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص148، تحت عنوان «دلالة وصف المقسم به بوصف: ﴿ذِي الذِّكْرِ﴾»","url":""}]},{"id":"s38-3","number":3,"surah":38,"verses":[2],"references":[{"surah":38,"verses":[2]}],"verseLabel":"ص: 2","question":"ماذا تفيد ﴿بَلْ﴾ في قوله: ﴿بَلِ الَّذِينَ كَفَرُوا فِي عِزَّةٍ وَشِقَاقٍ﴾؟","answer":"تنقل الكلام من إثبات شأن القرآن إلى كشف سبب الإعراض عنه: ليس في القرآن ما يوجب الشك، وإنما منعهم الكبر ومشاقة الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص151–152، تحت عنوان «الغرض من التعبير باسم الموصول»","url":""}]},{"id":"s38-60","number":60,"surah":38,"verses":[2],"references":[{"surah":38,"verses":[2]}],"verseLabel":"ص: 2","question":"لماذا جُمعت ﴿عِزَّةٍ﴾ و﴿شِقَاقٍ﴾؟","answer":"لأن استكبارهم الباطن أورثهم المخالفة الظاهرة؛ فالعزة بالإثم سبب، والشقاق أثرها في معاداة الرسول والحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص153، تحت عنوان «دلالة عطف: (شقاق) على: ﴿عِزَّةٍ﴾»","url":""}]},{"id":"s38-4","number":4,"surah":38,"verses":[3],"references":[{"surah":38,"verses":[3]}],"verseLabel":"ص: 3","question":"ماذا يصور قوله عن الهالكين: ﴿فَنَادَوْا﴾؟","answer":"تصور الفاء مبادرتهم إلى الصراخ والاستغاثة فور نزول العذاب، لكن النداء جاء بعدما فات زمن النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص159، تحت عنوان «معنى الفاء ودلالتها في ﴿فَنَادَوْا﴾»","url":""}]},{"id":"s38-61","number":61,"surah":38,"verses":[3],"references":[{"surah":38,"verses":[3]}],"verseLabel":"ص: 3","question":"لماذا لم يذكر القرآن مَن ناداه الهالكون ولا ما طلبوه؟","answer":"ليعم كل ما يمكن أن يصدر عن المذعور من استغاثة وطلب نجاة؛ فالحذف يترك صرختهم مفتوحة على شدة الفزع.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص160، تحت عنوان «بلاغة حذف معمول فعل النداء»","url":""}]},{"id":"s38-62","number":62,"surah":38,"verses":[3],"references":[{"surah":38,"verses":[3]}],"verseLabel":"ص: 3","question":"ما دلالة التعبير بـ﴿وَلَاتَ حِينَ مَنَاصٍ﴾؟","answer":"ينفي إمكان الفرار أو النجاة في ذلك الوقت خاصة؛ فقد جاء الندم والاستغاثة بعد انقضاء المهلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص161، تحت عنوان «دلالة النفي بـ: (لات)»","url":""}]},{"id":"s38-5","number":5,"surah":38,"verses":[4],"references":[{"surah":38,"verses":[4]}],"verseLabel":"ص: 4","question":"لماذا عبّر عن موقف المشركين بقوله: ﴿وَعَجِبُوا﴾؟","answer":"ليكشف أنهم جعلوا أمرًا لا موجب للعجب منه موضع استغراب: أن يختار الله رسولًا من البشر؛ فالتعبير يفضح فساد معيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص163–164، تحت عنوان «دلالة التعبير بالفعل: (عجبوا)»","url":""}]},{"id":"s38-6","number":6,"surah":38,"verses":[5],"references":[{"surah":38,"verses":[5]}],"verseLabel":"ص: 5","question":"ما غرض الاستفهام في قولهم: ﴿أَجَعَلَ الْآلِهَةَ إِلَهًا وَاحِدًا﴾؟","answer":"هو الإنكار المشوب بالتعجب؛ استبعدوا التوحيد لأنهم ألفوا كثرة المعبودات، لا لأن حجته خفية.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص171، تحت عنوان «الغرض من الاستفهام في قوله: ﴿أَجَعَلَ﴾»","url":""}]},{"id":"s38-63","number":63,"surah":38,"verses":[5],"references":[{"surah":38,"verses":[5]}],"verseLabel":"ص: 5","question":"لماذا عبّروا عن التوحيد بفعل ﴿جَعَلَ﴾؟","answer":"صوروه كأنه تحويل للآلهة الكثيرة إلى إله واحد، مع أن الدعوة تكشف بطلان ألوهيتها ولا تحول ذواتها؛ وفي ذلك أثر تصورهم الفاسد.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص171–172، تحت عنوان «دلالة التعبير بالفعل: (جعل)»","url":""}]},{"id":"s38-64","number":64,"surah":38,"verses":[5],"references":[{"surah":38,"verses":[5]}],"verseLabel":"ص: 5","question":"لماذا نسبوا هذا «الجعل» إلى الرسول ﷺ؟","answer":"ليوهموا أن التوحيد شيء ابتدعه الرسول من عنده، مع أنه مبلغ عن الله؛ فالإسناد يكشف تعمدهم صرف الناس عن أصل الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص172، تحت عنوان «دلالة إسناد فعل الجعل إلى ضمير الرسول»","url":""}]},{"id":"s38-7","number":7,"surah":38,"verses":[6],"references":[{"surah":38,"verses":[6]}],"verseLabel":"ص: 6","question":"ماذا أراد الملأ بقولهم: ﴿امْشُوا﴾؟","answer":"أرادوا حث قومهم على المضي في عبادتهم أو الانصراف عن مجلس الدعوة، فجاء الأمر تحريضًا على الثبات في الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص178، تحت عنوان «الغرض من التعبير بالأمر: ﴿امْشُوا﴾»","url":""}]},{"id":"s38-65","number":65,"surah":38,"verses":[6],"references":[{"surah":38,"verses":[6]}],"verseLabel":"ص: 6","question":"لماذا قالوا: ﴿وَاصْبِرُوا عَلَى آلِهَتِكُمْ﴾؟","answer":"جعلوا التمسك بالأصنام صبرًا يحتاج إلى احتمال، ليشدوا أتباعهم أمام تأثير دعوة التوحيد؛ فقلبوا الصبر من نصرة الحق إلى حماية الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص178–179، تحت عنوان «دلالة عطف الأمر بالصبر»","url":""}]},{"id":"s38-8","number":8,"surah":38,"verses":[7],"references":[{"surah":38,"verses":[7]}],"verseLabel":"ص: 7","question":"لماذا احتجوا بقولهم: ﴿مَا سَمِعْنَا بِهَذَا﴾؟","answer":"جعلوا حدود ما ألفوه وسمعوه معيارًا للحق، فكأن عدم سماعهم بالتوحيد من قبل دليل على بطلانه؛ وهو احتجاج بالتقليد لا بالحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص183–184، تحت عنوان «دلالة نفي فعل السمع دون غيره»","url":""}]},{"id":"s38-66","number":66,"surah":38,"verses":[7],"references":[{"surah":38,"verses":[7]}],"verseLabel":"ص: 7","question":"ما دلالة تقييد نفي السماع بقولهم: ﴿فِي الْمِلَّةِ الْآخِرَةِ﴾؟","answer":"قيدوا معرفتهم بدين متأخر أدركوه أو بدين آبائهم الأقربين، ليصوروا دعوة التوحيد خروجًا عما استقر في محيطهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص185، تحت عنوان «سر تقييد نفي السماع بالجار والمجرور»","url":""}]},{"id":"s38-9","number":9,"surah":38,"verses":[8],"references":[{"surah":38,"verses":[8]}],"verseLabel":"ص: 8","question":"ما غرض الاستفهام في قولهم: ﴿أَأُنْزِلَ عَلَيْهِ الذِّكْرُ مِنْ بَيْنِنَا﴾؟","answer":"هو إنكار حسدٍ لا طلب جواب؛ استبعدوا أن يختص الرسول ﷺ بالوحي لأنهم قاسوا الاصطفاء بمكانتهم الدنيوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص190–191، تحت عنوان «الغرض من الاستفهام في قوله: ﴿أَأُنْزِلَ﴾»","url":""}]},{"id":"s38-67","number":67,"surah":38,"verses":[8],"references":[{"surah":38,"verses":[8]}],"verseLabel":"ص: 8","question":"لماذا قُدّم ﴿عَلَيْهِ﴾ في قولهم: ﴿أَأُنْزِلَ عَلَيْهِ الذِّكْرُ﴾؟","answer":"لإبراز الشخص الذي اعترضوا على اختصاصه بالوحي؛ فموضع إنكارهم لم يكن الذكر نفسه بقدر ما كان نزوله عليه دونهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص191–192، تحت عنوان «دلالة تقديم الجار والمجرور على نائب الفاعل»","url":""}]},{"id":"s38-10","number":10,"surah":38,"verses":[8],"references":[{"surah":38,"verses":[8]}],"verseLabel":"ص: 8","question":"لماذا تتابعت ﴿بَلْ﴾ في الرد على منكري الوحي؟","answer":"لأن كل واحدة تنقل إلى سبب أعمق من سابقه: من حسدهم للرسول إلى شكهم في الوحي، ثم إلى أنهم لم يذوقوا العذاب الذي سيزيل شكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص195، تحت عنوان «سر تتابع الإضراب في قوله: ﴿بَلْ لَمَّا﴾»","url":""}]},{"id":"s38-11","number":11,"surah":38,"verses":[9],"references":[{"surah":38,"verses":[9]}],"verseLabel":"ص: 9","question":"ما غرض السؤال: ﴿أَمْ عِنْدَهُمْ خَزَائِنُ رَحْمَةِ رَبِّكَ﴾؟","answer":"إنكار أن تكون خزائن الرحمة في ملكهم حتى يمنحوا النبوة من شاءوا ويمنعوها عمن شاءوا؛ فالاختيار لله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص199، تحت عنوان «معنى ﴿أَمْ﴾ ودلالتها في أول الآية»","url":""}]},{"id":"s38-12","number":12,"surah":38,"verses":[10],"references":[{"surah":38,"verses":[10]}],"verseLabel":"ص: 10","question":"ما غرض الأمر في قوله: ﴿فَلْيَرْتَقُوا فِي الْأَسْبَابِ﴾؟","answer":"هو التعجيز والتهكم: إن زعموا أنهم يملكون تدبير الوحي فليصعدوا في طرق السماوات ويتولوا قسمته؛ وعجزهم يفضح دعواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص203–204، تحت عنوان «الغرض من التعبير بالمضارع المقترن بلام الأمر»","url":""}]},{"id":"s38-13","number":13,"surah":38,"verses":[11],"references":[{"surah":38,"verses":[11]}],"verseLabel":"ص: 11","question":"ماذا تفيد ﴿مَا﴾ في قوله: ﴿جُنْدٌ مَا هُنَالِكَ مَهْزُومٌ﴾؟","answer":"تحتمل تحقير جمعهم أو إبهامه، وحتى على معنى التعظيم فالمحصلة أن أي جند يجمعونه حقير المصير أمام أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص208، تحت عنوان «معنى ﴿مَا﴾ ودلالتها»","url":""}]},{"id":"s38-68","number":68,"surah":38,"verses":[11],"references":[{"surah":38,"verses":[11]}],"verseLabel":"ص: 11","question":"لماذا وصف جند المشركين بـ﴿مَهْزُومٌ﴾ قبل وقوع الهزيمة؟","answer":"استعمل اسم المفعول للمستقبل المحقق كأنه واقع حاضر، تثبيتًا للرسول ﷺ ووعدًا بأن هذا الجمع سيُكسر لا محالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص210، تحت عنوان «دلالة المجاز في التعبير باسم المفعول»","url":""}]},{"id":"s38-14","number":14,"surah":38,"verses":[12],"references":[{"surah":38,"verses":[12]},{"surah":89,"verses":[10]}],"verseLabel":"ص: 12؛ الفجر: 10","question":"لماذا وُصف فرعون بأنه ﴿ذُو الْأَوْتَادِ﴾؟","answer":"لأن الأوتاد توحي بسلطان ثابت كثير الجند والخيام، وقيل هي أدوات تعذيبه؛ وعلى الوجهين ترسم قوة دنيوية لم تمنع عنه الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص216–217، تحت عنوان «دلالة وصف (فرعون) بـ﴿ذُو الْأَوْتَادِ﴾، وسر إضافته»","url":""}]},{"id":"s38-15","number":15,"surah":38,"verses":[13],"references":[{"surah":38,"verses":[13]}],"verseLabel":"ص: 13","question":"لماذا قيل عن الأمم المكذبة: ﴿أُولَئِكَ الْأَحْزَابُ﴾؟","answer":"قصر حقيقة التحزب فيهم؛ فهم الذين تجمعوا على مخالفة الرسل، فصار مشركو مكة حزبًا صغيرًا ملحقًا بأحزاب انتهت إلى الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص219–220، تحت عنوان «الغرض من التعبير بأسلوب القصر»","url":""}]},{"id":"s38-16","number":16,"surah":38,"verses":[15],"references":[{"surah":38,"verses":[15]}],"verseLabel":"ص: 15","question":"لماذا وُصفت الصيحة بأنها ﴿وَاحِدَةً﴾؟","answer":"لتأكيد أن إهلاكهم لا يحتاج تكرارًا ولا معالجة؛ صيحة واحدة تكفي لإنهاء جمعهم مهما بلغت قوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص229، تحت عنوان «سر تقييد المفعول بـ: ﴿وَاحِدَةً﴾»","url":""}]},{"id":"s38-69","number":69,"surah":38,"verses":[15],"references":[{"surah":38,"verses":[15]}],"verseLabel":"ص: 15","question":"ماذا تفيد الجملة الاسمية: ﴿مَا لَهَا مِنْ فَوَاقٍ﴾؟","answer":"تفيد ثبات انتفاء الإفاقة أو الرجوع أو المهلة عنها؛ فإذا جاءت الصيحة لم تتوقف ولم تترك فرصة للنجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص229–230، تحت عنوان «دلالة وصف الصيحة بالجملة الاسمية»","url":""}]},{"id":"s38-17","number":17,"surah":38,"verses":[16],"references":[{"surah":38,"verses":[16]}],"verseLabel":"ص: 16","question":"ما غرض قولهم: ﴿رَبَّنَا عَجِّلْ لَنَا﴾؟","answer":"قالوه استهزاءً وتكذيبًا، فطلبوا تقديم نصيبهم من العذاب بدل أن يخافوه؛ وفي الأمر كشف لجهلهم وجرأتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص234، تحت عنوان «الغرض من التعبير بفعل الأمر: ﴿عَجِّلْ﴾»","url":""}]},{"id":"s38-70","number":70,"surah":38,"verses":[16],"references":[{"surah":38,"verses":[16]}],"verseLabel":"ص: 16","question":"لماذا سموا نصيبهم من العذاب ﴿قِطَّنَا﴾؟","answer":"القط هو النصيب أو الصك المكتوب، فاستعاروه ساخرين لما وُعدوا به كأنهم يطلبون وثيقة نصيبهم عاجلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص235، تحت عنوان «دلالة التعبير بالـ(قط)، والغرض من إضافته»","url":""}]},{"id":"s38-71","number":71,"surah":38,"verses":[16],"references":[{"surah":38,"verses":[16]}],"verseLabel":"ص: 16","question":"لماذا قالوا: ﴿قَبْلَ يَوْمِ الْحِسَابِ﴾؟","answer":"زادوا في الاستهزاء بطلب العذاب قبل وقته، وسمّوا الآخرة يوم الحساب مع أن الحساب نفسه مما كانوا ينكرونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص235، تحت عنوان «الغرض من التعبير عن الآخرة بـ﴿يَوْمِ الْحِسَابِ﴾»","url":""}]},{"id":"s38-18","number":18,"surah":38,"verses":[17],"references":[{"surah":38,"verses":[17]}],"verseLabel":"ص: 17","question":"لماذا وُصف داود عليه السلام بأنه ﴿ذَا الْأَيْدِ﴾؟","answer":"هي كناية عن القوة في الطاعة والعبادة وتدبير الملك، لا مجرد قوة البدن؛ فاستحضار ثباته يعين الرسول ﷺ على الصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص243، تحت عنوان «بيان المراد بالكناية ﴿ذَا الْأَيْدِ﴾»","url":""}]},{"id":"s38-19","number":19,"surah":38,"verses":[18,19],"references":[{"surah":38,"verses":[18,19]}],"verseLabel":"ص: 18-19","question":"ماذا يصور المضارع في قوله عن الجبال: ﴿يُسَبِّحْنَ﴾؟","answer":"يستحضر تسبيح الجبال مع داود كأنه مشهد يتجدد أمام السامع، فيبرز دوام العبادة وتكرارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص249، تحت عنوان «دلالة الجملة الفعلية المضارعية»","url":""}]},{"id":"s38-72","number":72,"surah":38,"verses":[18,19],"references":[{"surah":38,"verses":[18,19]}],"verseLabel":"ص: 18-19","question":"ما دلالة الجمع بين ﴿بِالْعَشِيِّ وَالْإِشْرَاقِ﴾؟","answer":"يجمع طرفي النهار ليدل على استمرار التسبيح وتجدد العبادة من أوله إلى آخره، لا على لحظتين معزولتين فحسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص251، تحت عنوان «بلاغة الطباق بين أول النهار وآخره»","url":""}]},{"id":"s38-73","number":73,"surah":38,"verses":[18,19],"references":[{"surah":38,"verses":[18,19]}],"verseLabel":"ص: 18-19","question":"لماذا قيل: ﴿وَالطَّيْرَ مَحْشُورَةً﴾ بدل أن يقال: والطير تحشر؟","answer":"لإبراز هيئة الطير مجتمعة مسخرة حول داود، وكأن حشرها حال ثابتة مشاهدة تشارك فيها الجبال تسبيحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص253، تحت عنوان «سر العدول عن الجملة الحالية»","url":""}]},{"id":"s38-20","number":20,"surah":38,"verses":[20],"references":[{"surah":38,"verses":[20]}],"verseLabel":"ص: 20","question":"ما الصورة في قوله عن داود: ﴿وَشَدَدْنَا مُلْكَهُ﴾؟","answer":"شُبه الملك ببناء يُشد ويوثق حتى لا يتزعزع؛ فالتعبير يصور ما أمده الله به من قوة وهيبة وثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص260، تحت عنوان «دلالة الاستعارة في ﴿وَشَدَدْنَا مُلْكَهُ﴾»","url":""}]},{"id":"s38-74","number":74,"surah":38,"verses":[20],"references":[{"surah":38,"verses":[20]}],"verseLabel":"ص: 20","question":"ماذا يفيد تعريف ﴿الْحِكْمَةَ﴾ في قوله: ﴿وَآتَيْنَاهُ الْحِكْمَةَ﴾؟","answer":"يفيد كمال الحكمة المعروفة الجامعة للنبوة والعلم وإتقان القول والعمل، لا قدرًا مبهمًا منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص261، تحت عنوان «دلالة التعريف لـ﴿الْحِكْمَةَ﴾»","url":""}]},{"id":"s38-75","number":75,"surah":38,"verses":[20],"references":[{"surah":38,"verses":[20]}],"verseLabel":"ص: 20","question":"ما دلالة التعبير بـ﴿فَصْلَ الْخِطَابِ﴾؟","answer":"يدل على القدرة على تمييز الحق من الباطل وإنهاء الخصومة بكلام واضح حاسم؛ فالإضافة تجمع حسن البيان وصواب الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص262، تحت عنوان «دلالة إضافة المصدر ﴿وَفَصْلَ﴾»","url":""}]},{"id":"s38-21","number":21,"surah":38,"verses":[21],"references":[{"surah":38,"verses":[21]}],"verseLabel":"ص: 21","question":"لماذا قيل عن الخصمين: ﴿تَسَوَّرُوا الْمِحْرَابَ﴾؟","answer":"هي كناية عن دخولهم من أعلى السور على غير الطريق المعتاد؛ فتوجز هيئة مفاجئة تفسر فزع داود منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص271، تحت عنوان «بلاغة الكناية في ﴿تَسَوَّرُوا الْمِحْرَابَ﴾»","url":""}]},{"id":"s38-22","number":22,"surah":38,"verses":[22],"references":[{"surah":38,"verses":[22]}],"verseLabel":"ص: 22","question":"لماذا بادر الخصمان داود بقولهم: ﴿لَا تَخَفْ﴾؟","answer":"لأن دخولهما المفاجئ من غير الباب أفزعه، فبدآ بإزالة الخوف قبل عرض القضية حتى يطمئن ويسمع حجتهما؛ وفي النهي إيناس وتهيئة للمقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص277، تحت عنوان «دلالة النهي في ﴿لا تخف﴾»","url":""}]},{"id":"s38-23","number":23,"surah":38,"verses":[23],"references":[{"surah":38,"verses":[23]}],"verseLabel":"ص: 23","question":"ما الصورة في قول صاحب النعجة: ﴿وَعَزَّنِي فِي الْخِطَابِ﴾؟","answer":"جعل الخطاب ميدانًا تقع فيه الغلبة، كأن المتخاصمين يتباريان فيه فيقوى أحدهما بالحجة أو الفصاحة أو الجاه؛ وتوجز العبارة شدة ضغط خصمه عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص290، تحت عنوان «سر جعل الخطاب ظرفًا للعزة والغلبة»","url":""}]},{"id":"s38-24","number":24,"surah":38,"verses":[24],"references":[{"surah":38,"verses":[24]}],"verseLabel":"ص: 24","question":"ماذا يكشف تتابع ﴿فَاسْتَغْفَرَ رَبَّهُ وَخَرَّ رَاكِعًا وَأَنَابَ﴾؟","answer":"يكشف سرعة داود إلى تصحيح الموقف: استغفار بالقلب واللسان، وخضوع بالجسد، ثم رجوع كامل إلى الله؛ فترتيب الأفعال يصور توبة شاملة عاجلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص305، تحت عنوان «دلالة العطف في قوله: ﴿فاستغفر ربه وخر راكعًا وأناب﴾»","url":""}]},{"id":"s38-25","number":25,"surah":38,"verses":[25],"references":[{"surah":38,"verses":[25]}],"verseLabel":"ص: 25","question":"لماذا أعقب الله مغفرة داود بقوله: ﴿وَإِنَّ لَهُ عِنْدَنَا لَزُلْفَى وَحُسْنَ مَآبٍ﴾؟","answer":"ليبين أن المغفرة لم تكن مجرد ستر للذنب، بل أعقبها قرب وكرامة وحسن مرجع؛ فالتوبة رفعت مقامه ولم تنقصه، وجاءت المؤكدات لرد كل توهم بخلاف ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص311، تحت عنوان «دلالة وصل ﴿وإن له عندنا لزلفى﴾»","url":""}]},{"id":"s38-26","number":26,"surah":38,"verses":[26],"references":[{"surah":38,"verses":[26]}],"verseLabel":"ص: 26","question":"لماذا قابلت الآية بين الحكم بالحق واتباع الهوى؟","answer":"لأن الحق ميزان ثابت يوصل إلى حكم الله، أما الهوى فميل شخصي يصد عن سبيله؛ فالمقابلة تقرر أن القاضي لا يجمع بينهما، وأن أول واجب للاستخلاف مقاومة الميل.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص323، تحت عنوان «دلالة التقابل بين الحق والهوى»","url":""}]},{"id":"s38-27","number":27,"surah":38,"verses":[27],"references":[{"surah":38,"verses":[27]}],"verseLabel":"ص: 27","question":"ما الذي ينفيه قوله: ﴿وَمَا خَلَقْنَا السَّمَاءَ وَالْأَرْضَ وَمَا بَيْنَهُمَا بَاطِلًا﴾؟","answer":"ينفي أن يكون الخلق عبثًا بلا حكمة ولا حساب؛ فهذا النظام المقصود يقتضي تمييز المحسن من المسيء وبعث الخلق للجزاء، وإلا استوى الحق والباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص335، تحت عنوان «دلالة لفظ ﴿باطلًا﴾»","url":""}]},{"id":"s38-28","number":28,"surah":38,"verses":[28],"references":[{"surah":38,"verses":[28]}],"verseLabel":"ص: 28","question":"ما غرض السؤال: ﴿أَمْ نَجْعَلُ الَّذِينَ آمَنُوا... كَالْمُفْسِدِينَ فِي الْأَرْضِ﴾؟","answer":"هو إنكار شديد لاستواء الفريقين؛ فعدل الله وحكمة الخلق يأبيان أن تكون عاقبة المؤمن المصلح كعاقبة المفسد، وبذلك يقيم السؤال دليلًا على الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص343، تحت عنوان «توجيه العطف بـ﴿أم﴾»","url":""}]},{"id":"s38-29","number":29,"surah":38,"verses":[29],"references":[{"surah":38,"verses":[29]}],"verseLabel":"ص: 29","question":"لماذا وُصف القرآن بأنه ﴿كِتَابٌ أَنْزَلْنَاهُ إِلَيْكَ مُبَارَكٌ﴾؟","answer":"لأن خيره كثير دائم متجدد: يهدي ويصلح القلوب والأعمال، وتتولد من تدبر آياته معانٍ وهدايات لا تنفد؛ فبركته في أثره وفي عطائه المتواصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص358، تحت عنوان «وجه وصف القرآن بـ﴿مبارك﴾»","url":""}]},{"id":"s38-30","number":30,"surah":38,"verses":[30],"references":[{"surah":38,"verses":[30]}],"verseLabel":"ص: 30","question":"لماذا خُص سليمان بالثناء: ﴿إِنَّهُ أَوَّابٌ﴾؟","answer":"لأن ﴿أواب﴾ صيغة مبالغة تدل على كثرة رجوعه إلى الله في كل شأن؛ فليست الإنابة موقفًا عابرًا بل صفة راسخة تفسر استحقاقه المدح.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص370، تحت عنوان «سر التعبير بصيغة المبالغة ﴿أواب﴾»","url":""}]},{"id":"s38-31","number":31,"surah":38,"verses":[31],"references":[{"surah":38,"verses":[31]}],"verseLabel":"ص: 31","question":"ما دلالة الجمع بين وصف الخيل بـ﴿الصَّافِنَاتُ الْجِيَادُ﴾؟","answer":"جمع لها جمال الوقوف وقوة العدو: تصفن في سكونها هيئةً وأصالة، وتجود بالسرعة عند جريها؛ فاستوعب الوصفان محاسن الخيل في حالتي السكون والحركة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص378، تحت عنوان «دلالة الجمع بين الوصفين»","url":""}]},{"id":"s38-32","number":32,"surah":38,"verses":[32],"references":[{"surah":38,"verses":[32]}],"verseLabel":"ص: 32","question":"لماذا عبّر سليمان عن الصلاة بـ﴿ذِكْرِ رَبِّي﴾؟","answer":"لأن الصلاة أعظم صور الذكر، ولأن اللفظ يعم ما يتصل بذكر الله من عبادة ووحي؛ فالتعبير يكشف أن القضية ليست حركةً فاتته بل صلةً بربه يحرص عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص386، تحت عنوان «وجه التعبير بلفظ ﴿ذكر﴾»","url":""}]},{"id":"s38-33","number":33,"surah":38,"verses":[34],"references":[{"surah":38,"verses":[34]}],"verseLabel":"ص: 34","question":"ماذا يفيد قوله بعد فتنة سليمان: ﴿ثُمَّ أَنَابَ﴾؟","answer":"يفيد أن الفتنة انتهت برجوعه الكامل إلى الله، وأن الإنابة جاءت بعد إدراك ما في الابتلاء؛ و﴿ثم﴾ تصور انتقالًا من المحنة إلى حال جديدة من التوبة والقرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص403–404، تحت عنوان «دلالة العطف بـ﴿ثم﴾»","url":""}]},{"id":"s38-34","number":34,"surah":38,"verses":[35],"references":[{"surah":38,"verses":[35]}],"verseLabel":"ص: 35","question":"لماذا قدّم سليمان طلب المغفرة على سؤال الملك العظيم؟","answer":"لأن تطهير النفس وإصلاح الصلة بالله مقدمان على طلب حظوظ الدنيا، ولأن المغفرة تهيئ الدعاء للقبول؛ فبدأ بحاجة الدين قبل عطية الملك.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص409، تحت عنوان «علة تقديم الاستغفار على استيهاب الملك»","url":""}]},{"id":"s38-35","number":35,"surah":38,"verses":[36],"references":[{"surah":38,"verses":[36]}],"verseLabel":"ص: 36","question":"لماذا وُصفت الريح المسخرة لسليمان بأنها ﴿رُخَاءً﴾؟","answer":"لأن تسخيرها جمع القوة واللين: تجري بأمره حيث يريد، لكنها رخية طيبة لا تؤذيه ولا تعصف به؛ فكانت طائعة نافعة لا مجرد ريح شديدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص422–423، تحت عنوان «سر وصف الريح بكونها ﴿رخاء﴾»","url":""}]},{"id":"s38-36","number":36,"surah":38,"verses":[38],"references":[{"surah":38,"verses":[38]}],"verseLabel":"ص: 38","question":"ما الصورة في قوله عن الشياطين: ﴿مُقَرَّنِينَ فِي الْأَصْفَادِ﴾؟","answer":"تصور المردة وقد شُد بعضهم إلى بعض في القيود، أو جُمعت أيديهم إلى أعناقهم؛ فالتضعيف في ﴿مقرنين﴾ والأصفاد يصوران إحكام أسر قوتهم وإذلالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص428–429، تحت عنوان «سر إيثار صيغة ﴿مقرنين﴾ بالتضعيف»","url":""}]},{"id":"s38-37","number":37,"surah":38,"verses":[39],"references":[{"surah":38,"verses":[39]}],"verseLabel":"ص: 39","question":"ما دلالة قوله لسليمان: ﴿فَامْنُنْ أَوْ أَمْسِكْ بِغَيْرِ حِسَابٍ﴾؟","answer":"هو كناية عن سعة التفويض وتمام الثقة: أعط من تشاء أو امنع من تشاء، فلا تضييق عليك في هذا العطاء ولا مؤاخذة على وجوه تدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص437، تحت عنوان «الكناية في نفي الحساب»","url":""}]},{"id":"s38-38","number":38,"surah":38,"verses":[41],"references":[{"surah":38,"verses":[41]}],"verseLabel":"ص: 41","question":"لماذا نسب أيوب ما مسه إلى الشيطان؟","answer":"تأدبًا مع الله فلم ينسب إليه النصب والعذاب، وذكر الشيطان بوصفه سببًا للوسوسة والشماتة أو لما أذن الله أن يقع؛ مع يقينه أن الشفاء والضر بيد الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص450–451، تحت عنوان «سر نسبة المس إلى ﴿الشيطان﴾»","url":""}]},{"id":"s38-39","number":39,"surah":38,"verses":[42],"references":[{"surah":38,"verses":[42]}],"verseLabel":"ص: 42","question":"ما دلالة أمر أيوب: ﴿ارْكُضْ بِرِجْلِكَ﴾ مع أن الله قادر على شفائه بلا حركة؟","answer":"ليباشر سبب الشفاء بنفسه ويظهر صدق امتثاله، مع أن الركضة وحدها لا تخرج ماءً؛ فاجتمع الأخذ بالسبب وإظهار أن أثره من قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص455، تحت عنوان «دلالة الأمر ﴿اركض﴾»","url":""}]},{"id":"s38-40","number":40,"surah":38,"verses":[43],"references":[{"surah":38,"verses":[43]}],"verseLabel":"ص: 43","question":"ما دلالة قوله في نعمة أيوب: ﴿رَحْمَةً مِنَّا﴾؟","answer":"يدل على أن رد أهله ومثلهم معهم فضل صادر من الله وحده، لا استحقاقًا ولا مقابلًا؛ والإضافة إلى ضمير العظمة تفخم الرحمة وتبرز قرب العناية بأيوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص469–470، تحت عنوان «نكتة ذكر ﴿منا﴾»","url":""}]},{"id":"s38-41","number":41,"surah":38,"verses":[44],"references":[{"surah":38,"verses":[44]}],"verseLabel":"ص: 44","question":"لماذا أُمر أيوب أن يضرب بالضغث وفاءً بيمينه؟","answer":"لأن الضغث حزمة من عيدان دقيقة تجمع العدد في ضربة رفيقة؛ فحقق ظاهر يمينه من غير إيذاء زوجته الصابرة، وجمع الحكم بين الوفاء والرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص475–476، تحت عنوان «بلاغة اختيار مفردة الضغث»","url":""}]},{"id":"s38-42","number":42,"surah":38,"verses":[45],"references":[{"surah":38,"verses":[45]}],"verseLabel":"ص: 45","question":"ما دلالة وصف إبراهيم وإسحاق ويعقوب بـ﴿أولي الأيدي والأبصار﴾؟","answer":"تستعار الأيدي للقوة في الطاعة والعمل، والأبصار للبصيرة في الدين والعلم. فيجمع الوصف كمال القدرة وكمال الإدراك، ويشير إلى أن جوارحهم وقواهم متجهة إلى المقاصد التي خلقوا لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص486، تحت عنوان «بلاغة التعبير المجازي»","url":""}]},{"id":"s38-43","number":43,"surah":38,"verses":[46],"references":[{"surah":38,"verses":[46]}],"verseLabel":"ص: 46","question":"لماذا قال الله عن إبراهيم وإسحاق ويعقوب: ﴿إِنَّا أَخْلَصْنَاهُمْ﴾؟","answer":"لأن الله اصطفاهم ونقّاهم من الشوائب والعيوب، فجعل إخلاصهم وصفًا راسخًا وهيأهم للنبوة والاقتداء بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص488، تحت عنوان «بلاغة اختيار مفردة ﴿أخلصناهم﴾»","url":""}]},{"id":"s38-76","number":76,"surah":38,"verses":[46],"references":[{"surah":38,"verses":[46]}],"verseLabel":"ص: 46","question":"ما دلالة إضافة ﴿ذِكْرَى﴾ إلى ﴿الدَّارِ﴾؟","answer":"تجعل تذكّر الآخرة وتذكير الناس بها خصلةً راسخة فيهم؛ فاستحقوا المنزلة الرفيعة لأنهم وجّهوا القلوب إلى الدار الباقية.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص490–491، تحت عنوان «دلالة إضافة ﴿ذكرى﴾ للفظ ﴿الدار﴾»","url":""}]},{"id":"s38-44","number":44,"surah":38,"verses":[49],"references":[{"surah":38,"verses":[49]}],"verseLabel":"ص: 49","question":"لماذا جاء بعد قصص الأنبياء قوله: ﴿هَذَا ذِكْرٌ﴾؟","answer":"ليطوي ما سبق في جملة تذكير وعبرة، ثم ينقل السامع إلى جزاء المتقين؛ فكانت العبارة فاصلة تحفظ صلة الغرضين من غير إطالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص506–507، تحت عنوان «بلاغة فصل الخطاب أو الانتقال الاقتضابي»","url":""}]},{"id":"s38-77","number":77,"surah":38,"verses":[49],"references":[{"surah":38,"verses":[49]}],"verseLabel":"ص: 49","question":"لماذا اختيرت كلمة ﴿ذِكْرٌ﴾ في قوله: ﴿هَذَا ذِكْرٌ﴾؟","answer":"لأنها تجمع التذكير والاعتبار، وشرف الأنبياء المذكورين، والقرآن الذي حفظ خبرهم؛ فلفظ واحد يستوعب هذه المعاني المتآزرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص508، تحت عنوان «بلاغة استعمال مفردة ﴿ذكر﴾ دون رديفاتها»","url":""}]},{"id":"s38-45","number":45,"surah":38,"verses":[50],"references":[{"surah":38,"verses":[50]}],"verseLabel":"ص: 50","question":"ماذا تصوّر صيغة ﴿مُفَتَّحَةً﴾ في أبواب الجنة؟","answer":"تصوّر كثرة الأبواب ويسر فتحها، وأنها مهيأة على الدوام لاستقبال أهل الجنة بالإكرام والترحيب من غير عناء ولا انتظار.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص514، تحت عنوان «فائدة صيغة المبالغة ﴿مفتحة﴾»","url":""}]},{"id":"s38-78","number":78,"surah":38,"verses":[50],"references":[{"surah":38,"verses":[50]}],"verseLabel":"ص: 50","question":"لماذا قُدّم ﴿لَهُمُ﴾ في قوله: ﴿مُفَتَّحَةً لَهُمُ الْأَبْوَابُ﴾؟","answer":"لإبراز أن هذا الفتح خاص بالمتقين تكريمًا واحتفاءً بهم، وكأن أبواب الجنة فُتحت لهم قبل وصولهم انتظارًا لقدومهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص515، تحت عنوان «فائدة تقديم الجار والمجرور»","url":""}]},{"id":"s38-79","number":79,"surah":38,"verses":[50],"references":[{"surah":38,"verses":[50]}],"verseLabel":"ص: 50","question":"لماذا لم يُذكر دخول المتقين الجنة بعد قوله: ﴿مُفَتَّحَةً لَهُمُ الْأَبْوَابُ﴾؟","answer":"لأن فتح الأبواب لهم كناية تكفي عن الإذن بالدخول والتمكين من النعيم؛ وطيّ الحدث يسرّع المشهد ويترك النفس تتشوق لما وراء الأبواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص516، تحت عنوان «بلاغة الكناية في طيّ حديث دخول الجنات»","url":""}]},{"id":"s38-46","number":46,"surah":38,"verses":[55],"references":[{"surah":38,"verses":[55]}],"verseLabel":"ص: 55","question":"ما سر الانتقال بقوله: ﴿هَذَا وَإِنَّ لِلطَّاغِينَ لَشَرَّ مَآبٍ﴾؟","answer":"يفصل اسم الإشارة بين مشهد نعيم المتقين ومشهد عذاب الطاغين، مع إبقاء المقابلة حاضرة؛ فيتهيأ السامع للانتقال من الترغيب إلى الترهيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص539–540، تحت عنوان «براعة استعمال اسم الإشارة في الانتقال بين الأغراض»","url":""}]},{"id":"s38-80","number":80,"surah":38,"verses":[55],"references":[{"surah":38,"verses":[55]}],"verseLabel":"ص: 55","question":"لماذا قوبل ﴿حُسْنَ مَآبٍ﴾ للمتقين بـ﴿شَرَّ مَآبٍ﴾ للطاغين؟","answer":"لأن اختيار الشر يلمّح بضده إلى الخير الذي سبق للمتقين، فتوجز المقابلة تفاوت المصيرين وتبرز أن نهاية الطغيان شر محض.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص543، تحت عنوان «بلاغة اختلاف المقابلة في اختيار مفردة (شر)»","url":""}]},{"id":"s38-47","number":47,"surah":38,"verses":[57],"references":[{"surah":38,"verses":[57]}],"verseLabel":"ص: 57","question":"لماذا أشير إلى عذاب أهل النار بلفظ القريب: ﴿هَذَا﴾؟","answer":"ليُستحضر العذاب كأنه حاضر قريب تراه العين، فيشتد التحذير والتهويل من عاقبة الطاغين.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص548، تحت عنوان «وظيفة اسم الإشارة للقريب»","url":""}]},{"id":"s38-81","number":81,"surah":38,"verses":[57],"references":[{"surah":38,"verses":[57]}],"verseLabel":"ص: 57","question":"لماذا قيل لأهل النار: ﴿فَلْيَذُوقُوهُ﴾؟","answer":"استُعمل الذوق تهكمًا وتوبيخًا؛ فبدل أن يذوقوا طعامًا أو شرابًا لذيذًا يُجبرون على مباشرة الحميم والغساق، فيظهر هوانهم وشدة عقابهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص549، تحت عنوان «بلاغة الاستعارة التهكمية»","url":""}]},{"id":"s38-48","number":48,"surah":38,"verses":[59],"references":[{"surah":38,"verses":[59]}],"verseLabel":"ص: 59","question":"لماذا استقبل أهل النار الفوج الداخل بقولهم: ﴿لَا مَرْحَبًا بِهِمْ﴾؟","answer":"لأن نفي الترحيب أبلغ في إظهار البغض والتحقير من مجرد وصفهم بالذم؛ فهو دعاء بضيق المكان عليهم وكراهية شديدة لقدومهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص560–561، تحت عنوان «نكتة إيثار نفي الترحيب على إثبات الذم»","url":""}]},{"id":"s38-82","number":82,"surah":38,"verses":[59],"references":[{"surah":38,"verses":[59]}],"verseLabel":"ص: 59","question":"لماذا ردّ الأتباع على رؤسائهم بالكلمة نفسها: ﴿بَلْ أَنْتُمْ لَا مَرْحَبًا بِكُمْ﴾؟","answer":"ليردوا اللعنة على من أضلهم؛ فالكلمة المطابقة تكشف انقلاب الاتباع في الدنيا إلى خصومة، وتحمل الرؤساء مسؤولية ما انتهوا إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص565، تحت عنوان «دلالة استعمال ﴿لا مرحبًا بكم﴾ النظيرة لكلمة الأسياد»","url":""}]},{"id":"s38-49","number":49,"surah":38,"verses":[62],"references":[{"surah":38,"verses":[62]}],"verseLabel":"ص: 62","question":"ماذا يكشف سؤال أهل النار: ﴿مَا لَنَا لَا نَرَى رِجَالًا﴾؟","answer":"يكشف تعجبهم وحسرتهم حين لم يجدوا المؤمنين الذين كانوا يحتقرونهم؛ فقد انقلب معيارهم، وبان لهم أنهم هم الذين ضلوا المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص581، تحت عنوان «غرض الاستفهام بـ﴿ما﴾»","url":""}]},{"id":"s38-83","number":83,"surah":38,"verses":[62],"references":[{"surah":38,"verses":[62]}],"verseLabel":"ص: 62","question":"ماذا يفيد المضارع في قولهم: ﴿كُنَّا نَعُدُّهُمْ مِنَ الْأَشْرَارِ﴾؟","answer":"يفيد أن احتقارهم للمؤمنين كان عادة متجددة لا حكمًا عابرًا؛ ظلوا يكررونه في الدنيا حتى رسخ في نفوسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص583، تحت عنوان «دلالة التعبير بالمضارع ﴿نعدهم﴾»","url":""}]},{"id":"s38-84","number":84,"surah":38,"verses":[62],"references":[{"surah":38,"verses":[62]}],"verseLabel":"ص: 62","question":"ماذا تكشف عبارة ﴿مِنَ الْأَشْرَارِ﴾ عن نظرة الكافرين للمؤمنين؟","answer":"تكشف أنهم لم يكتفوا بوصفهم بالشر، بل زعموهم مندمجين في زمرة الأشرار؛ ثم قلبت الآخرة حكمهم حين ظهر فساد مقياسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص584، تحت عنوان «دلالة ﴿من﴾»","url":""}]},{"id":"s38-50","number":50,"surah":38,"verses":[67],"references":[{"surah":38,"verses":[67]}],"verseLabel":"ص: 67","question":"ماذا يفيد تنكير ﴿نَبَأٌ﴾ في قوله: ﴿هُوَ نَبَأٌ عَظِيمٌ﴾؟","answer":"يفيد التفخيم؛ فكأنه نبأ لا يحيط الوصف بقدره، ويحتمل من وجوه العظمة ما يوجب الإصغاء إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص620، تحت عنوان «نكتة تنكير النبأ»","url":""}]},{"id":"s38-85","number":85,"surah":38,"verses":[67],"references":[{"surah":38,"verses":[67]}],"verseLabel":"ص: 67","question":"لماذا وُصف النبأ بأنه ﴿عَظِيمٌ﴾؟","answer":"لتأكيد جلال شأنه وخطر عاقبته؛ فهو وحي من الله، في التصديق به نجاة وفي تكذيبه هلاك، فلا يصح الاستخفاف به.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص620، تحت عنوان «نكتة وصف النبأ بالعظيم»","url":""}]},{"id":"s38-86","number":86,"surah":38,"verses":[67],"references":[{"surah":38,"verses":[67]}],"verseLabel":"ص: 67","question":"ما الذي يضيفه قوله: ﴿أَنْتُمْ عَنْهُ مُعْرِضُونَ﴾ بعد وصفه بالنبأ العظيم؟","answer":"يفضح المفارقة بين عظمة النبأ وثبات إعراضهم عنه، فيتحول الوصف إلى توبيخ مباشر لمن يهمل خبرًا يمس مصيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص620–621، تحت عنوان «علة فصل ﴿أنتم عنه معرضون﴾»","url":""}]},{"id":"s38-51","number":51,"surah":38,"verses":[69],"references":[{"surah":38,"verses":[69]}],"verseLabel":"ص: 69","question":"كيف صار قول الرسول: ﴿مَا كَانَ لِي مِنْ عِلْمٍ بِالْمَلَإِ الْأَعْلَى﴾ دليلًا على الوحي؟","answer":"لأنه لم يشهد اختصام الملأ الأعلى ولم يكن يعلمه قبل الوحي، فإخباره به بعد ذلك يدل على أن العلم جاءه من الله لا من نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص625، تحت عنوان «علة فصل الآية»","url":""}]},{"id":"s38-52","number":52,"surah":38,"verses":[72],"references":[{"surah":38,"verses":[72]}],"verseLabel":"ص: 72","question":"ماذا تفيد ﴿سَوَّيْتُهُ﴾ في وصف خلق آدم؟","answer":"تفيد أن الله أتم خلقه في صورة متناسقة، وجعل أعضاءه سليمة تؤدي وظائفها على أكمل وجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص643، تحت عنوان «دلالة التعبير بالتسوية»","url":""}]},{"id":"s38-87","number":87,"surah":38,"verses":[72],"references":[{"surah":38,"verses":[72]}],"verseLabel":"ص: 72","question":"لماذا عُبّر عن إحياء آدم بالنفخ؟","answer":"هو تصوير لطيف لإفاضة الحياة في الجسد وسريان الروح في أجزائه، من غير أن يكون النفخ على حقيقته البشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص644، تحت عنوان «بلاغة التعبير بالنفخ»","url":""}]},{"id":"s38-53","number":53,"surah":38,"verses":[74],"references":[{"surah":38,"verses":[74]}],"verseLabel":"ص: 74","question":"لماذا عبّر عن موقف إبليس بقوله: ﴿اسْتَكْبَرَ﴾؟","answer":"لأن الصيغة تصوّر أنه طلب الكِبَر وتعاظم على أمر الله، فكان امتناعه ثمرة استعلاء شديد لا مجرد ترك عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص654، تحت عنوان «سر التعبير بالاستكبار»","url":""}]},{"id":"s38-88","number":88,"surah":38,"verses":[74],"references":[{"surah":38,"verses":[74]}],"verseLabel":"ص: 74","question":"ماذا تفيد ﴿كَانَ﴾ في قوله: ﴿وَكَانَ مِنَ الْكَافِرِينَ﴾؟","answer":"تحتمل أن كفره كان كامنًا فظهر عند الامتحان، أو أنه صار من الكافرين بسبب امتناعه؛ وعلى الوجهين تكشف رسوخ صلة الكبر بالكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص654، تحت عنوان «دلالة التعبير بـ(كان)»","url":""}]},{"id":"s38-54","number":54,"surah":38,"verses":[75],"references":[{"surah":38,"verses":[75]}],"verseLabel":"ص: 75","question":"ما غرض السؤال الإلهي لإبليس: ﴿مَا مَنَعَكَ أَنْ تَسْجُدَ﴾؟","answer":"ليس لطلب العلم، بل للتوبيخ والإنكار وإلزام إبليس أن يقر بسبب عصيانه، فتظهر قبح سريرته أمام الملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص659–660، تحت عنوان «بلاغة الاستفهام»","url":""}]},{"id":"s38-89","number":89,"surah":38,"verses":[75],"references":[{"surah":38,"verses":[75]}],"verseLabel":"ص: 75","question":"لماذا أضاف الله خلق آدم إلى نفسه في قوله: ﴿لِمَا خَلَقْتُ﴾؟","answer":"لتشريف آدم وبيان اختصاصه بعناية الله الذي تولى خلقه في أحسن صورة؛ فيزداد قبح رفض إبليس السجود له.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص662، تحت عنوان «سر إضافة الله الخلق إلى نفسه»","url":""}]},{"id":"s38-90","number":90,"surah":38,"verses":[75],"references":[{"surah":38,"verses":[75]}],"verseLabel":"ص: 75","question":"ما دلالة قوله تعالى عن آدم: ﴿خَلَقْتُ بِيَدَيَّ﴾؟","answer":"ذكر اليدين وتثنيتهما يبرز كمال العناية والتكريم واختصاص آدم بالتشريف، من غير واسطة أب ولا أم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص662، تحت عنوان «نكتة ذكر اليدين وتثنيتهما»","url":""}]},{"id":"s38-55","number":55,"surah":38,"verses":[76],"references":[{"surah":38,"verses":[76]}],"verseLabel":"ص: 76","question":"لماذا قدّم إبليس ذكر خلقه من النار على خلق آدم من الطين؟","answer":"اعتناءً بنفسه وزعمًا أنه أحق بالتقديم حالًا ومقالًا؛ فترتيبه يكشف أنانيته وتعاظمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص667، تحت عنوان «غرض تقديم خلق إبليس»","url":""}]},{"id":"s38-91","number":91,"surah":38,"verses":[76],"references":[{"surah":38,"verses":[76]}],"verseLabel":"ص: 76","question":"ماذا يفيد تنكير ﴿طِينٍ﴾ في احتجاج إبليس؟","answer":"يفيد التحقير في سياق استكباره، إذ صوّر أصل آدم مادة مجهولة حقيرة ليهوّن شأنه ويرفع نفسه عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص668، تحت عنوان «نكتة تنكير ﴿طين﴾»","url":""}]},{"id":"s38-56","number":56,"surah":38,"verses":[82],"references":[{"surah":38,"verses":[82]}],"verseLabel":"ص: 82","question":"لماذا أقسم إبليس بعزة الله في قوله: ﴿فَبِعِزَّتِكَ لَأُغْوِيَنَّهُمْ﴾؟","answer":"لأن العزة الكاملة لله هي التي لا يقع الإغواء إلا بما أذن به تقديرًا، فكأنه يقر بأنه لا يقدر على شيء خارج سلطان الله مع عزمه على الشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص690، تحت عنوان «سر القسم بصفة العزة دون غيرها»","url":""}]},{"id":"s38-92","number":92,"surah":38,"verses":[82],"references":[{"surah":38,"verses":[82]}],"verseLabel":"ص: 82","question":"ما دلالة توالي المؤكدات في قول إبليس: ﴿فَبِعِزَّتِكَ لَأُغْوِيَنَّهُمْ أَجْمَعِينَ﴾؟","answer":"يصور فرط ثقته وعزمه على إغواء بني آدم: جمع القسم ولام الجواب ونون التوكيد و﴿أجمعين﴾ ليؤكد شمول قصده وشدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص691، تحت عنوان «غرض توالي المؤكدات»","url":""}]},{"id":"s38-58","number":58,"surah":38,"verses":[86],"references":[{"surah":38,"verses":[86]}],"verseLabel":"ص: 86","question":"ما الذي ينفيه قول الرسول ﷺ: ﴿وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ﴾؟","answer":"ينفي أن يتصنع الوحي أو ينسب إلى الله ما لم يوح به، وأن يحمل الناس على كلام مختلق أو يتجاوز حدود البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص721، تحت عنوان «دلالة التعبير بالتكلف في ﴿المتكلفين﴾»","url":""}]},{"id":"s38-93","number":93,"surah":38,"verses":[86],"references":[{"surah":38,"verses":[86]}],"verseLabel":"ص: 86","question":"لماذا قال الرسول ﷺ: ﴿مِنَ الْمُتَكَلِّفِينَ﴾ بدل «ما أتكلف»؟","answer":"لأن نفي الانتساب إلى فئة المتكلفين أبلغ من نفي فعل عارض؛ فهو يبرئه من أن يكون التكلف طبعًا له أو شأنًا يُعرف به.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص722، تحت عنوان «نكتة إيثار التعبير بقوله: ﴿من المتكلفين﴾»","url":""}]},{"id":"s38-59","number":59,"surah":38,"verses":[87,88],"references":[{"surah":38,"verses":[87,88]}],"verseLabel":"ص: 87-88","question":"لماذا جاء الوعد: ﴿وَلَتَعْلَمُنَّ نَبَأَهُ﴾ مؤكدًا بالقسم؟","answer":"لتوكيد أنهم سيبلغون علمًا يقينيًا بصدق القرآن عند ظهور خبره، فيكون تهديدًا للمعرضين وبشارة للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص727، تحت عنوان «معنى (اللام) في قوله: ﴿ولتعلمن﴾»","url":""}]},{"id":"s38-94","number":94,"surah":38,"verses":[87,88],"references":[{"surah":38,"verses":[87,88]}],"verseLabel":"ص: 87-88","question":"كيف أحسن ختام سورة ص بقوله: ﴿وَلَتَعْلَمُنَّ نَبَأَهُ بَعْدَ حِينٍ﴾؟","answer":"ردّ آخر السورة إلى أولها الذي وصف القرآن بذي الذكر، وختم بوعد ووعيد مؤكدين؛ فظهر صدق الذكر واتصل ختام السورة بمطلعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص732، تحت عنوان «بلاغة حسن الختام في الآية»","url":""}]},{"id":"s38-95","number":95,"surah":38,"verses":[5],"references":[{"surah":38,"verses":[5]}],"verseLabel":"ص: 5","question":"ما دلالة وصف توحيد الآلهة بأنه ﴿لَشَيْءٌ عُجَابٌ﴾، مع توكيد الجملة باللام؟","answer":"تعددت عند المشركين دواعي العجب؛ عجبوا من مجيء منذر منهم، ثم اشتد عجبهم من دعوته إلى إله واحد وهم عريقون في الشرك. فناسب تراكم العجب توكيد الجملة باللام، واختيار «عُجاب» الدالة على المبالغة، لا مجرد «عجيب».","sources":[{"label":"فاضل السامرائي، «الفرق بين عُجاب وعَجَبًا»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-96","number":96,"surah":38,"verses":[9],"references":[{"surah":38,"verses":[9]}],"verseLabel":"ص: 9","question":"ما سر تقييد الخزائن بالرحمة في ﴿خَزَائِنُ رَحْمَةِ رَبِّكَ﴾، وإتباعها بالاسمين ﴿الْعَزِيزِ الْوَهَّابِ﴾؟","answer":"لما قُيّدت الخزائن بخزائن الرحمة ناسبها «الوهاب»؛ فالرحمة هبة، ولا يهب إلا من يملك. وناسبها «العزيز» لأن التصرف في تلك الخزائن لا يكون إلا لصاحب العزة والغلبة، فجاء الاسمان متممين لمعنى الرحمة والملك والهبة.","sources":[{"label":"فاضل السامرائي، «الفرق بين خزائن رحمة ربك وخزائن ربك»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-97","number":97,"surah":38,"verses":[17],"references":[{"surah":38,"verses":[17]}],"verseLabel":"ص: 17","question":"ما دلالة إضافة داود إلى ضمير العظمة في قوله: ﴿وَاذْكُرْ عَبْدَنَا دَاوُودَ﴾؟","answer":"وصف الإنسان نفسه بالعبودية تواضع، أما وصف الله له بأنه «عبدنا» فتكريم ووسام؛ لأنه إثبات للعبودية الاختيارية الكاملة، ثم إن إضافته إلى ضمير العظمة تزيد معنى التشريف والقرب والرعاية.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص163، مبحث «دلالة وصف النبي بالعبد وإضافته إلى ضمير العظمة».","url":""}]},{"id":"s38-98","number":98,"surah":38,"verses":[18],"references":[{"surah":38,"verses":[18]}],"verseLabel":"ص: 18","question":"ما دلالة تقديم ﴿الْجِبَالَ﴾ على الظرف في قوله: ﴿إِنَّا سَخَّرْنَا الْجِبَالَ مَعَهُ﴾؟","answer":"توسع سياق سورة ص في شأن الجبال والطير، فذكر تسبيح الجبال بالعشي والإشراق، ثم حشر الطير وأوبتها؛ لذلك قُدّمت الجبال لتكون موضع العناية. أما آية الأنبياء فأوجزت الخبر، فناسب كل ترتيب مقدار التفصيل في سياقه.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج4، ص180-181، مبحث «تسخير الجبال مع داود في الأنبياء وص».","url":""}]},{"id":"s38-99","number":99,"surah":38,"verses":[24],"references":[{"surah":38,"verses":[24]}],"verseLabel":"ص: 24","question":"ما سر التعبير بقوله: ﴿وَخَرَّ رَاكِعًا﴾ بدل «خر ساجدًا»؟","answer":"الركوع يأتي بمعنى الخضوع وتطأطؤ الرأس، و«الخرور» هو الهوي إلى الأمام؛ فالمعنى أنه خر من حال خضوعه حتى سجد. كما أن القرآن خص تعبير «خروا سجدًا» غالبًا بسماع آيات الله وتلاوتها، وهنا ذُكر خلاف الأولى في الحكم، فناسبه التعبير بالركوع.","sources":[{"label":"فاضل السامرائي، «الفرق بين الركوع والسجود في: وخر راكعًا»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-100","number":100,"surah":38,"verses":[30],"references":[{"surah":38,"verses":[30]}],"verseLabel":"ص: 30","question":"ما سر حذف المخصوص بالمدح في قوله: ﴿نِعْمَ الْعَبْدُ إِنَّهُ أَوَّابٌ﴾؟","answer":"يجوز حذف المخصوص بالمدح إذا كان معلومًا من السياق؛ فقد سبق ذكر سليمان، فلا يحتاج المقام إلى إعادة اسمه. والحذف هنا يشد الانتباه إلى صفة العبودية والأوبة نفسها، ويجعل المدح أسرع وأقوى اتصالًا بما قبله.","sources":[{"label":"فاضل السامرائي، «نعم العبد إنه أواب: من المخصوص بالمدح وما سبب حذفه؟»، منصة باحث.","url":""}]},{"id":"s38-101","number":101,"surah":38,"verses":[32],"references":[{"surah":38,"verses":[32]}],"verseLabel":"ص: 32","question":"ما جمال عودة الضمير في ﴿حَتَّى تَوَارَتْ بِالْحِجَابِ﴾ إلى الشمس مع أنها لم تُذكر؟","answer":"دل السياق على الشمس دلالة تغني عن التصريح بها؛ فالتواري بالحجاب عند العشي لا يلتبس بغير غروبها. والحذف يحقق الإيجاز، ويجعل المشهد حاضرًا في الذهن حتى كأن الشمس معلومة مشاهدة لا تحتاج إلى تسمية.","sources":[{"label":"فاضل السامرائي، «عودة الضمير على غير مذكور دل عليه السياق»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-102","number":102,"surah":38,"verses":[41],"references":[{"surah":38,"verses":[41]}],"verseLabel":"ص: 41","question":"ما الفرق البياني بين ﴿مَسَّنِيَ الشَّيْطَانُ بِنُصْبٍ وَعَذَابٍ﴾ هنا و﴿مَسَّنِيَ الضُّرُّ﴾ في سورة الأنبياء؟","answer":"يعبّر «مسني الشيطان» عن وسوسة الشيطان وما دخل النفس بسببها، أما «مسني الضر» فيعبّر عن المرض والشدة الواقعة في البدن والحال. فليستا عبارتين عن حالة واحدة من كل وجه، بل كل موضع أبرز جانبًا من ابتلاء أيوب يناسب سياقه.","sources":[{"label":"فاضل السامرائي، «ما معنى مسني الشيطان بنصب وعذاب؟»، منصة باحث.","url":""}]},{"id":"s38-103","number":103,"surah":38,"verses":[41],"references":[{"surah":38,"verses":[41]}],"verseLabel":"ص: 41","question":"ما دلالة التصريح بفعل الأمر ﴿وَاذْكُرْ عَبْدَنَا أَيُّوبَ﴾، بينما حُذف «اذكر» في قصص سورة الأنبياء؟","answer":"بنيت سورة ص على محور الذكر منذ مطلعها: ﴿وَالْقُرْآنِ ذِي الذِّكْرِ﴾؛ لذلك تكرر فيها الأمر ﴿واذكر﴾ مع قصص الأنبياء. أما سورة الأنبياء فتعطف أسماءهم على فعل مقدر، فجاء التصريح في ص متسقًا مع خيطها اللفظي والدلالي.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج4، ص191-195، مبحث «التناسب بين ذي الذكر وتكرار واذكر في سورة ص».","url":""}]},{"id":"s38-104","number":104,"surah":38,"verses":[43],"references":[{"surah":38,"verses":[43]}],"verseLabel":"ص: 43","question":"ما دلالة ﴿وَذِكْرَى لِأُولِي الْأَلْبَابِ﴾ هنا، مقابل ﴿وَذِكْرَى لِلْعَابِدِينَ﴾ في سورة الأنبياء؟","answer":"العابدون أولو ألباب وزيادة؛ فالعبادة تتضمن العقل الذي يصح به التكليف ثم العمل بمقتضاه. ولما كان سياق الأنبياء أوسع في مشاهد العبادة والاستجابة جاء بـ«العابدين»، أما سورة ص فغلب فيها خطاب التذكر والتدبر، فناسبها «أولو الألباب».","sources":[{"label":"فاضل السامرائي، «ذكرى للعابدين وذكرى لأولي الألباب»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-105","number":105,"surah":38,"verses":[43],"references":[{"surah":38,"verses":[43]}],"verseLabel":"ص: 43","question":"ما دلالة ﴿وَوَهَبْنَا لَهُ أَهْلَهُ﴾ هنا، مقابل ﴿وَآتَيْنَاهُ أَهْلَهُ﴾ في سورة الأنبياء؟","answer":"الإيتاء أعم من الهبة؛ فقد يكون هبة أو تمليكًا أو إعطاء حكم وعلم وكتاب، ولذلك يحمل معنى أوسع. وسياق الأنبياء أتم في إظهار الاستجابة وكشف الضر، فناسبه الأعم «آتيناه»، أما سورة ص فجرى فيها خيط الهبة والوهاب، فناسبها «وهبنا».","sources":[{"label":"فاضل السامرائي، «قصة أيوب بين آتيناه ووهبنا له»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-106","number":106,"surah":38,"verses":[44],"references":[{"surah":38,"verses":[44]}],"verseLabel":"ص: 44","question":"ما أثر حذف اسم أيوب من المدح في ﴿نِعْمَ الْعَبْدُ إِنَّهُ أَوَّابٌ﴾؟","answer":"سبق قوله ﴿إِنَّا وَجَدْنَاهُ صَابِرًا﴾ فعُلم أن الممدوح أيوب، فحُذف اسمه استغناء بالسياق. وبذلك اتصل الجزاء بالسبب مباشرة: صبرٌ أثبته الله، ثم مدحٌ بالعبودية والأوبة، من غير فاصل يبدد قوة الارتباط.","sources":[{"label":"فاضل السامرائي، «من المخصوص بالمدح وما سبب حذفه؟»، منصة باحث.","url":""}]},{"id":"s38-107","number":107,"surah":38,"verses":[45,48],"references":[{"surah":38,"verses":[45,48]}],"verseLabel":"ص: 45، 48","question":"ما سر وصف بعض الأنبياء بـ﴿عِبَادَنَا﴾، ثم حذف هذا الوصف عند إسماعيل واليسع وذي الكفل؟","answer":"مَن وصفهم بالعبودية فصّل أخبارهم وذكر ما تفضل به عليهم من النعم والاصطفاء، فناسب التفصيلُ ذكرَ صفة التكريم. أما إسماعيل واليسع وذو الكفل فذُكروا في آية موجزة بلا تفصيل لتلك المنح، فناسب الإيجازُ الإيجازَ وحُذفت الصفة.","sources":[{"label":"فاضل السامرائي، قبسات من البيان القرآني، ص289-291، مبحث «ذكر صفة العبد لأنبياء سورة ص وحذفها».","url":""}]},{"id":"s38-108","number":108,"surah":38,"verses":[51],"references":[{"surah":38,"verses":[51]}],"verseLabel":"ص: 51","question":"ما دلالة وصف أهل الجنة بأنهم ﴿مُتَّكِئِينَ فِيهَا﴾ قبل ذكر الفاكهة والشراب؟","answer":"الاتكاء غاية الراحة؛ فهو هيئة من لا ينتظر خطرًا ولا يستعد لعمل شاق. وجاء في القرآن غالبًا مع الطعام والشراب والمجالس الآمنة، فتصدره للمشهد يصور طمأنينة أهل الجنة قبل أن يعرض ما يدعونه من فاكهة كثيرة وشراب.","sources":[{"label":"فاضل السامرائي، «دلالة استعمال متكئين لأهل الجنة»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-109","number":109,"surah":38,"verses":[73],"references":[{"surah":38,"verses":[73]}],"verseLabel":"ص: 73","question":"ما سر تذكير الفعل في ﴿فَسَجَدَ الْمَلَائِكَةُ﴾ مع جواز تأنيثه؟","answer":"جمع التكسير يجوز معه التذكير والتأنيث نحويًا، لكن الاستعمال القرآني يختار التذكير للملائكة في أفعال العبادة والقوة والأوامر الصادرة إليهم. ولما كان السجود عبادة وامتثالًا جاء الفعل مذكرًا، موافقًا لهذا الخط التعبيري.","sources":[{"label":"فاضل السامرائي، «سر تذكير الفعل وتأنيثه مع الملائكة»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-110","number":110,"surah":38,"verses":[84,85],"references":[{"surah":38,"verses":[84,85]}],"verseLabel":"ص: 84، 85","question":"ما الدلالة الحاسمة في وصل ﴿فَالْحَقُّ وَالْحَقَّ أَقُولُ﴾ بقوله: ﴿لَأَمْلَأَنَّ جَهَنَّمَ﴾؟","answer":"هذا هو القول الحق الذي ثبت به الوعيد على إبليس وأتباعه؛ ولذلك ارتبطت عبارة «حق القول» في الاستعمال القرآني بثبوت العذاب ووجوبه. واجتماع الحق مع لام القسم ونون التوكيد في ﴿لأملأن﴾ يصور الحكم واقعًا لا مرد له.","sources":[{"label":"فاضل السامرائي، «ما معنى حق القول؟»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-111","number":111,"surah":38,"verses":[87,88],"references":[{"surah":38,"verses":[87,88]}],"verseLabel":"ص: 87، 88","question":"كيف أحكم ختام السورة ﴿إِنْ هُوَ إِلَّا ذِكْرٌ لِلْعَالَمِينَ﴾ صلته بمطلعها ﴿وَالْقُرْآنِ ذِي الذِّكْرِ﴾؟","answer":"افتتحت السورة بوصف القرآن بأنه ذو الذكر، ثم سرت مادة الذكر في أوامر ﴿واذكر﴾، وفي التذكر وذكرى الدار و﴿هذا ذكر﴾، وختمت بكونه ذكرًا للعالمين. فصار الذكر إطارًا يضم السورة كلها، ويجعل ﴿ولتعلمن نبأه بعد حين﴾ خاتمة إنذار لمن أعرض عن ذلك الذكر.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج4، ص191-195، مبحث «التناسب بين مطلع سورة ص وخاتمتها وتردد مادة الذكر».⋮ Top of Form Bottom of Form","url":""}]},{"id":"s38-112","number":112,"surah":38,"verses":[1],"references":[{"surah":38,"verses":[1]}],"verseLabel":"ص: 1","question":"ما سر حذف جواب القسم في قوله تعالى: ﴿ص وَالْقُرْآنِ ذِي الذِّكْرِ﴾؟","answer":"حُذف جواب القسم ليتسع المعنى، فلا ينحصر في جواب واحد، بل يحتمل كل ما يدل عليه سياق السورة من صدق القرآن والرسالة ووعيد المكذبين. فذكر جواب معين كان سيقيد الدلالة، أما حذفه ففتح الذهن على معانٍ متعددة كلها يقتضيها المقام.","sources":[{"label":"فاضل السامرائي، «أين جواب القسم في سورة ص؟»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-113","number":113,"surah":38,"verses":[9,10],"references":[{"surah":38,"verses":[9,10]}],"verseLabel":"ص: 9–10","question":"كيف قابل التعبير بين ﴿خَزَائِنُ رَحْمَةِ رَبِّكَ﴾ في سورة ص و﴿خَزَائِنُ رَبِّكَ أَمْ هُمُ الْمُصَيْطِرُونَ﴾ في سورة الطور؟","answer":"آية الطور أعم؛ فقد أطلقت الخزائن، فناسبها إطلاق السيطرة، لأن المسيطر عزيز وزيادة. أما سورة ص فخصت خزائن الرحمة، فناسب هذا التخصيص ذكر «العزيز الوهاب»، ثم جاء الارتقاء في الأسباب مقابل السُّلَّم في الطور، فوافق العمومُ العمومَ والتخصيصُ التخصيصَ.","sources":[{"label":"فاضل السامرائي، «خزائن ربك وخزائن رحمة ربك»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-114","number":114,"surah":38,"verses":[21,22],"references":[{"surah":38,"verses":[21,22]}],"verseLabel":"ص: 21–22","question":"كيف أفرد التعبير لفظ ﴿الْخَصْمِ﴾ ثم أعاد عليه ضمير الجمع في ﴿تَسَوَّرُوا﴾ و﴿مِنْهُمْ﴾؟","answer":"«الخصم» من الألفاظ التي تستعمل للواحد وللجماعة، كالبشر والضيف، فجيء به مفرد اللفظ للدلالة على الجنس، ثم روعي معناه الجمعي في الضمائر. وعندما قالوا ﴿خَصْمَانِ﴾ نظر إلى الفريقين المتقابلين، فجمع التعبير بين وحدة الوصف وتعدد أصحابه.","sources":[{"label":"فاضل السامرائي، «لماذا جاءت الخصم مفردة ثم ثُنّيت وجُمعت؟»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-115","number":115,"surah":38,"verses":[36],"references":[{"surah":38,"verses":[36]}],"verseLabel":"ص: 36","question":"ما سر وصف الريح هنا بأنها ﴿رُخَاءً﴾، ووصفها في سورة الأنبياء بأنها ﴿عَاصِفَةً﴾؟","answer":"الريح مسخرة لسليمان على الحال التي يريدها؛ تكون عاصفة حين يريد السرعة، ورخاء حين يريد اللين. وفي سورة ص سبق ذكر الجسد الملقى على كرسيه، والجسد ساكن لا يتحرك، فناسب هذا الجو وصف الريح بالرخاء، وهو تناسب لطيف بين اللفظة والسياق.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج4، ص184-188، مبحث «ريح سليمان بين عاصفة ورخاء».","url":""}]},{"id":"s38-116","number":116,"surah":38,"verses":[36,38],"references":[{"surah":38,"verses":[36,38]}],"verseLabel":"ص: 36، 38","question":"ما دلالة تفصيل سلطان سليمان في ﴿حَيْثُ أَصَابَ﴾ و﴿كُلَّ بَنَّاءٍ وَغَوَّاصٍ﴾ و﴿مُقَرَّنِينَ فِي الْأَصْفَادِ﴾؟","answer":"جمعت الآيات وجوه الانقياد الكامل: الريح تجري إلى الجهة التي يقصدها، والشياطين موزعون بين البناء والغوص، والمتمردون منهم مقيدون في الأصفاد. فالتفصيل يصور ملكًا نافذًا في الحركة والعمل والعقوبة، موافقًا لدعائه بملك لا ينبغي لأحد بعده.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج4، ص183-184، مبحث «قصة سليمان بين الأنبياء وسبأ وص».","url":""}]},{"id":"s38-117","number":117,"surah":38,"verses":[43],"references":[{"surah":38,"verses":[43]}],"verseLabel":"ص: 43","question":"ما سر قوله ﴿رَحْمَةً مِنَّا﴾ هنا، وقوله ﴿رَحْمَةً مِنْ عِنْدِنَا﴾ في سورة الأنبياء؟","answer":"«رحمة من عندنا» أخص، ولا تستعمل في القرآن إلا في مقام الخصوص بالمؤمنين، أما «رحمة منا» فأعم. وفي الأنبياء ذُكرت صفة ﴿أرحم الراحمين﴾، والاستجابة وكشف الضر تصريحًا، فجاءت الرحمة الخاصة؛ أما في ص فذُكر مس الشيطان وفُهم الكشف ضمنًا، فناسبها الأعم.","sources":[{"label":"فاضل السامرائي، «الفرق بين رحمة منا ورحمة من عندنا في قصة أيوب»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-118","number":118,"surah":38,"verses":[50],"references":[{"surah":38,"verses":[50]}],"verseLabel":"ص: 50","question":"ما الصورة التكريمية في قوله: ﴿جَنَّاتِ عَدْنٍ مُفَتَّحَةً لَهُمُ الْأَبْوَابُ﴾؟","answer":"يصور اسم المفعول أبواب الجنة مفتوحة مهيأة قبل وصول أهلها، لا أنهم يقفون حتى تُفتح لهم. وهذه حال إكرام واستقبال، بخلاف أبواب النار التي لا تفتح لأهلها إلا بعد مجيئهم، فيجتمع في اللفظ معنى الأمن والتبجيل وسرعة الدخول.","sources":[{"label":"فاضل السامرائي، «دلالة كون أبواب الجنة مفتحة»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-119","number":119,"surah":38,"verses":[75],"references":[{"surah":38,"verses":[75]}],"verseLabel":"ص: 75","question":"ما دلالة حذف «لا» في ﴿مَا مَنَعَكَ أَنْ تَسْجُدَ﴾، وإثباتها في ﴿مَا مَنَعَكَ أَلَّا تَسْجُدَ﴾ بالأعراف؟","answer":"«لا» في آية الأعراف صلة للتوكيد وليست نافية، وقد جيء بها لأن المعنى مأمون اللبس. وسياق الأعراف أشد توكيدًا وأطول في قصة إبليس، وتكررت فيه مشتقات السجود أكثر؛ فناسبه مزيد التوكيد، أما سياق ص فناسبه التعبير بلا «لا».","sources":[{"label":"فاضل السامرائي، «ما الفرق بين ما منعك أن تسجد وما منعك ألا تسجد؟»، منصة باحث.","url":""}]},{"id":"s39-1","number":1,"surah":39,"verses":[1],"references":[{"surah":39,"verses":[1]}],"verseLabel":"عنوان السورة","question":"ما مناسبة تسمية السورة بـ«الزمر»، وما صلة الاسم بمشهد سوق الفريقين في خاتمتها؟","answer":"ورد اسم الزمر في مشهدي سوق الكافرين والمتقين جماعات إلى مصيرهما. ويصل المبحث التسمية بمحور السورة في تحقيق الدين الخالص لله؛ إذ تتقابل فيها طوائف الناس ومواقفهم، ثم تظهر عواقبهم في مشهد الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص737–738، تحت عنوان «اسم السورة وسبب التسمية»","url":""}]},{"id":"s39-2","number":2,"surah":39,"verses":[1],"references":[{"surah":39,"verses":[1]}],"verseLabel":"الزمر: 1","question":"ما سر الجمع بين اسمي الله ﴿الْعَزِيزِ الْحَكِيمِ﴾ في مطلع السورة؟","answer":"ليدل على أن منزل القرآن غالب لا يعجزه شيء، وحكيم يضع تشريعه ووحيه في موضعهما؛ فاجتمعت قوة السلطان وكمال الحكمة ضمانًا لحق الكتاب وأحكامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص754–755، تحت عنوان «لطيفة الجمع بين ﴿العزيز﴾ و﴿الحكيم﴾»","url":""}]},{"id":"s39-3","number":3,"surah":39,"verses":[1],"references":[{"surah":39,"verses":[1]}],"verseLabel":"الزمر: 1","question":"ما مناسبة تقديم ﴿الْعَزِيزِ﴾ على ﴿الْحَكِيمِ﴾ في مصدر التنزيل؟","answer":"يذكر المبحث أن تقديم العزيز من تقديم السبب على المسبب؛ فالقدرة مقدمة على حسن التقدير، والعزة من صفات الذات والحكمة من صفات الأفعال. ويلائم الترتيب مقام بيان سلطان القرآن على معارضيه بالحجة وإحكام ما جاء به.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص755، تحت عنوان «نكتة تقديم ﴿العزيز﴾ على ﴿الحكيم﴾»","url":""}]},{"id":"s39-4","number":4,"surah":39,"verses":[2],"references":[{"surah":39,"verses":[2]}],"verseLabel":"الزمر: 2","question":"ماذا يفيد قوله: ﴿تَنْزِيلُ الْكِتَابِ مِنَ اللَّهِ﴾؟","answer":"تفيد ﴿مِنْ﴾ ابتداء صدور التنزيل من عند الله، فتقطع نسبته إلى غيره، وتزيد الكتاب تشريفًا لأن مصدره هو الله العزيز الحكيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص752، تحت عنوان «معنى ﴿من﴾ في قوله: ﴿من الله﴾»","url":""}]},{"id":"s39-116","number":116,"surah":39,"verses":[2],"references":[{"surah":39,"verses":[2]}],"verseLabel":"الزمر: 2","question":"لماذا انتقل التعبير من الغيبة في ﴿مِنَ اللَّهِ﴾ إلى التكلم في ﴿إِنَّا أَنْزَلْنَا إِلَيْكَ﴾؟","answer":"لينتقل السامع من الخبر عن منزل الكتاب إلى خطاب الرسول مباشرة، فيقوى معنى العناية به وبما أنزل إليه، ويجيء ضمير التعظيم ملائمًا لجلال القرآن وصدق إنزاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص757–758، تحت عنوان «نكتة العدول عن أسلوب الغيبة إلى التكلم»","url":""}]},{"id":"s39-5","number":5,"surah":39,"verses":[2,3],"references":[{"surah":39,"verses":[2,3]}],"verseLabel":"الزمر: 2–3","question":"ماذا يضيف قوله: ﴿مُخْلِصًا لَهُ الدِّينَ﴾ إلى الأمر بعبادة الله؟","answer":"يبين أن العبادة المطلوبة لا يكفي فيها ظاهر العمل، بل لا بد أن تُنقّى من كل شرك ورياء، فتكون الطاعة والقصد لله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص766، تحت عنوان «دلالة التعبير بالإخلاص في القيد ﴿مخلصًا﴾»","url":""}]},{"id":"s39-6","number":6,"surah":39,"verses":[3],"references":[{"surah":39,"verses":[3]}],"verseLabel":"الزمر: 3","question":"لماذا قال المشركون: ﴿لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى﴾ ولم يقولوا: ليكونوا واسطة؟","answer":"لأن ﴿زُلْفَى﴾ تصور غاية القرب وتمامه، فكشفت ضخامة وهمهم: ظنوا أن عبادة الأصنام تبلغ بهم أقصى القرب من الله، مع أن هذا الطريق نفسه يبعدهم عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص783، تحت عنوان «دلالة التعبير بـ﴿زلفى﴾ دون (واسطة)»","url":""}]},{"id":"s39-7","number":7,"surah":39,"verses":[3],"references":[{"surah":39,"verses":[3]}],"verseLabel":"الزمر: 3","question":"لماذا قُدّم وصف ﴿كَاذِبٌ﴾ على ﴿كَفَّارٌ﴾؟","answer":"لتفظيع كذبهم؛ لأن دعوى الولد والشفعاء كذب على الله، وهذا الكذب هو الذي ساقهم إلى شدة الكفر، فذُكر السبب قبل ما نشأ عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص793، تحت عنوان «نكتة تقديم ﴿كاذب﴾ على ﴿كفار﴾»","url":""}]},{"id":"s39-8","number":8,"surah":39,"verses":[4],"references":[{"surah":39,"verses":[4]}],"verseLabel":"الزمر: 4","question":"لماذا قال: ﴿لَاصْطَفَى مِمَّا يَخْلُقُ مَا يَشَاءُ﴾ ولم يقل: لاتخذ ولدًا؟","answer":"لأن الاصطفاء اختيار وتشريف لمخلوق، لا ولادة ولا مشاركة في الألوهية؛ فحوّل الفرض نفسه إلى ما يليق بالخالق، وأبطل تصور الولد من داخله.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص804–805، تحت عنوان «لطيفة العدول عن فعل الاتخاذ في الشرط»","url":""}]},{"id":"s39-9","number":9,"surah":39,"verses":[4],"references":[{"surah":39,"verses":[4]}],"verseLabel":"الزمر: 4","question":"ما مناسبة ختم نفي الولد بقوله: ﴿هُوَ اللَّهُ الْوَاحِدُ الْقَهَّارُ﴾؟","answer":"فـ﴿الواحد﴾ ينفي النظير والشريك والولد، و﴿القهار﴾ يقرر أن كل ما سواه مخلوق مقهور له؛ ومن كان واحدًا قاهرًا لا يحتاج إلى ولد يعينه أو يخلفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص809، تحت عنوان «وجه مناسبة صفتي ﴿الواحد القهار﴾»","url":""}]},{"id":"s39-10","number":10,"surah":39,"verses":[5],"references":[{"surah":39,"verses":[5]}],"verseLabel":"الزمر: 5","question":"ما الصورة التي يرسمها قوله: ﴿يُكَوِّرُ اللَّيْلَ عَلَى النَّهَارِ وَيُكَوِّرُ النَّهَارَ عَلَى اللَّيْلِ﴾؟","answer":"يشبه تعاقبهما بلف عمامة يلتف بعضها فوق بعض؛ فيغشى أحدهما الآخر شيئًا فشيئًا، ويصور امتدادهما المتداخل وتجدد دورانهما في نظام لا ينقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص17–18، تحت عنوان «بلاغة الاستعارة في الفعل ﴿يكور﴾»","url":""}]},{"id":"s39-11","number":11,"surah":39,"verses":[5],"references":[{"surah":39,"verses":[5]}],"verseLabel":"الزمر: 5","question":"لماذا قيل عن الشمس والقمر: ﴿كُلٌّ يَجْرِي لِأَجَلٍ مُسَمًّى﴾ ولم يقل: لوقت أو زمن؟","answer":"لأن ﴿الأجل﴾ زمن ينتهي عنده الشيء، فتومئ الكلمة إلى أن هذا الجريان المنظم ليس أبديًا، بل له حد مقدر تنتهي إليه مسيرته بأمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص27، تحت عنوان «دلالة التعبير بـ(أجل) دون (وقت) أو (زمن)»","url":""}]},{"id":"s39-12","number":12,"surah":39,"verses":[6],"references":[{"surah":39,"verses":[6]}],"verseLabel":"الزمر: 6","question":"لماذا قيل: ﴿وَأَنْزَلَ لَكُمْ مِنَ الْأَنْعَامِ﴾ باللام، لا: أنزل عليكم؟","answer":"لأن اللام تشعر بأن الأنعام مسخرة لمنفعة الناس ومهيأة لمصالحهم، أما ﴿على﴾ فتلائم مجرد وقوع الإنزال عليهم؛ فاختير ما يبرز نعمة الاختصاص والانتفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص45، تحت عنوان «نكتة تعدية فعل الإنزال باللام دون (على)»","url":""}]},{"id":"s39-13","number":13,"surah":39,"verses":[6],"references":[{"surah":39,"verses":[6]}],"verseLabel":"الزمر: 6","question":"لماذا أُخّر قوله: ﴿يَخْلُقُكُمْ فِي بُطُونِ أُمَّهَاتِكُمْ﴾ إلى ما بعد ذكر الأنعام؟","answer":"ليجيء خلق الإنسان الخفي بعد ذكر أصل البشر وخلق الأنعام شاهدًا أقرب إلى كل سامع؛ فانتقل السياق من النعم المحيطة به إلى أطوار وجوده نفسه، وهو أدعى للتأمل والتأثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص49، تحت عنوان «سر تأخير جملة: ﴿يخلقكم في بطون أمهاتكم﴾»","url":""}]},{"id":"s39-14","number":14,"surah":39,"verses":[6],"references":[{"surah":39,"verses":[6]}],"verseLabel":"الزمر: 6","question":"ماذا تضيف ﴿فِي﴾ في قوله: ﴿فِي ظُلُمَاتٍ ثَلَاثٍ﴾؟","answer":"تصور الجنين محاطًا بهذه الظلمات من كل جهة، مستقرًا داخل طبقات لا يصل إليها تدبير البشر؛ فيبرز حفظ الله له وقدرته على خلقه في ذلك الخفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص53، تحت عنوان «دلالة الظرفية في قوله: ﴿في ظلمات ثلاث﴾»","url":""}]},{"id":"s39-117","number":117,"surah":39,"verses":[6],"references":[{"surah":39,"verses":[6]}],"verseLabel":"الزمر: 6","question":"لماذا نُكّرت ﴿ظُلُمَاتٍ﴾ في قوله: ﴿فِي ظُلُمَاتٍ ثَلَاثٍ﴾؟","answer":"لتفخيم شدتها وإبهام حقيقتها على السامع، فهي ظلمات متراكبة عجيبة لا يدرك تفاصيلها، ومع ذلك ينفذ فيها خلق الله وتقديره.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص54، تحت عنوان «نكتة تنكير ﴿ظلمات﴾»","url":""}]},{"id":"s39-15","number":15,"surah":39,"verses":[6],"references":[{"surah":39,"verses":[6]}],"verseLabel":"الزمر: 6","question":"لماذا قُدّم ﴿لَهُ﴾ في قوله: ﴿لَهُ الْمُلْكُ﴾؟","answer":"لقصر الملك الحقيقي عليه وحده؛ فبعد إثبات الخلق والتدبير قرر أن السلطان كله له، ولا يملك من دونه استقلالًا شيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص57، تحت عنوان «غرض تقديم شبه الجملة الخبرية ﴿له﴾»","url":""}]},{"id":"s39-16","number":16,"surah":39,"verses":[7],"references":[{"surah":39,"verses":[7]}],"verseLabel":"الزمر: 7","question":"إذا كان الله غنيًا عن الناس، فلماذا قال: ﴿وَلَا يَرْضَى لِعِبَادِهِ الْكُفْرَ﴾؟","answer":"لئلا يُفهم من غناه أنه لا يبالي بأفعالهم؛ فهو لا ينتفع بإيمانهم ولا يتضرر بكفرهم، ومع ذلك يكره لهم الكفر رحمةً بهم لأنه سبب شقائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص73، تحت عنوان «بلاغة جملة الاعتراض في قوله: ﴿ولا يرضى لعباده الكفر﴾»","url":""}]},{"id":"s39-17","number":17,"surah":39,"verses":[7],"references":[{"surah":39,"verses":[7]}],"verseLabel":"الزمر: 7","question":"ما مناسبة قوله: ﴿وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى﴾ بعد ذكر الكفر والشكر؟","answer":"ليقرر أن نتيجة الاختيار عائدة إلى صاحبه وحده: فلا يضر كفر الكافر ربَّه ولا غيره، ولا ينفع شكر الشاكر إلا نفسه، وكل إنسان يحمل تبعة عمله عند الرجوع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص79، تحت عنوان «غرض الجملة الخبرية ﴿ولا تزر وازرة وزر أخرى﴾»","url":""}]},{"id":"s39-18","number":18,"surah":39,"verses":[8],"references":[{"surah":39,"verses":[8]}],"verseLabel":"الزمر: 8","question":"ماذا يصور وصف الإنسان بأنه يدعو ربه ﴿مُنِيبًا إِلَيْهِ﴾ عند الضر؟","answer":"يصور رجوعه السريع بكليته إلى الله، منقطعًا عمن سواه؛ فالشدّة تكشف في لحظتها ما تعرفه الفطرة من أن الملجأ الحقيقي هو الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص95، تحت عنوان «دلالة التعبير بلفظ الإنابة»","url":""}]},{"id":"s39-118","number":118,"surah":39,"verses":[8],"references":[{"surah":39,"verses":[8]}],"verseLabel":"الزمر: 8","question":"ماذا تكشف ﴿ثُمَّ﴾ في قوله: ﴿ثُمَّ إِذَا خَوَّلَهُ نِعْمَةً مِنْهُ نَسِيَ﴾؟","answer":"تكشف بُعد ما فعله عما يُنتظر منه؛ فبعد دعاء صادق ونعمة من الله كان المنتظر الشكر، لكنه انتقل انتقالًا مستبعدًا إلى النسيان والشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص97، تحت عنوان «دلالة حرف ﴿ثم﴾»","url":""}]},{"id":"s39-119","number":119,"surah":39,"verses":[8],"references":[{"surah":39,"verses":[8]}],"verseLabel":"الزمر: 8","question":"لماذا قيل: ﴿وَجَعَلَ لِلَّهِ أَنْدَادًا﴾ ولم يقل: واتخذ؟","answer":"لأن ﴿جعل﴾ تصور أنه اخترع لله أمثالًا من عند نفسه وأقامها في وهمه مقام الأنداد، مع أنها لا تملك في الحقيقة شيئًا من صفات الندية.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص103، تحت عنوان «نكتة التعبير بالجعل بدل الاتخاذ وغيره»","url":""}]},{"id":"s39-19","number":19,"surah":39,"verses":[8],"references":[{"surah":39,"verses":[8]}],"verseLabel":"الزمر: 8","question":"لماذا قيل: ﴿خَوَّلَهُ نِعْمَةً﴾ بدل: أعطاه نعمة؟","answer":"لأن التخويل عطاء واسع يجعله الله تحت تصرف الإنسان ويتمتع به مدة، فيذكّره اللفظ بأن النعمة منحة مفوضة إليه وليست ملكًا ذاتيًا مستقلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص98، تحت عنوان «دلالة التعبير بالتخويل في قوله: ﴿خوله﴾»","url":""}]},{"id":"s39-20","number":20,"surah":39,"verses":[9],"references":[{"surah":39,"verses":[9]}],"verseLabel":"الزمر: 9","question":"لماذا وُصف القانت بأنه يعبد الله ﴿آنَاءَ اللَّيْلِ﴾؟","answer":"للدلالة على أنه يوزع عبادته على ساعات الليل المختلفة ويكررها، لا أنها لحظة عابرة؛ وفي الليل مزيد إخلاص وهدوء وبعد عن أعين الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص120–121، تحت عنوان «فائدة ذكر الظرفية في ﴿آناء الليل﴾»","url":""}]},{"id":"s39-21","number":21,"surah":39,"verses":[9],"references":[{"surah":39,"verses":[9]}],"verseLabel":"الزمر: 9","question":"ما سر تقديم الحذر من الآخرة على رجاء رحمة الله؟","answer":"قدم الحذر لأنه يدفع ما تخشاه النفس، ودفع المضار مقدم على جلب المنافع. ثم جاء الرجاء ليكمل الباعث على العمل؛ فيجتمع اجتناب ما يوجب العقوبة وطلب ما يصلح العبد عند ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص127، تحت عنوان «نكتة تقديم الحذر على الرجاء»","url":""}]},{"id":"s39-22","number":22,"surah":39,"verses":[9],"references":[{"surah":39,"verses":[9]}],"verseLabel":"الزمر: 9","question":"لماذا قيل: ﴿الَّذِينَ يَعْلَمُونَ وَالَّذِينَ لَا يَعْلَمُونَ﴾ في سياق مقارنة القانت بغيره؟","answer":"لأن العلم هنا يظهر أثره في الإيمان والطاعة؛ فسمّى العامل بعلمه عالمًا، ونزّل من لا يعمل منزلة من لا يعلم، وفي التعبير تعريض بمن عرف الحق ثم لم يتبعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص132، تحت عنوان «بلاغة التعبير بقوله: ﴿الذين يعلمون والذين لا يعلمون﴾»","url":""}]},{"id":"s39-23","number":23,"surah":39,"verses":[10],"references":[{"surah":39,"verses":[10]}],"verseLabel":"الزمر: 10","question":"ماذا توحي عبارة ﴿وَأَرْضُ اللَّهِ وَاسِعَةٌ﴾ للمؤمن الذي لا يستطيع إقامة دينه؟","answer":"تكني عن فتح باب الهجرة وعدم الاستسلام لمكان يفتنه؛ فأرض الله ليست محصورة في موطن الأذى، وفي سعتها دعوة إلى طلب موضع يستطيع فيه طاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص151، تحت عنوان «بلاغة الكناية في قوله: ﴿وأرض الله واسعة﴾»","url":""}]},{"id":"s39-24","number":24,"surah":39,"verses":[11,12],"references":[{"surah":39,"verses":[11,12]}],"verseLabel":"الزمر: 11–12","question":"لماذا تكرر ﴿وَأُمِرْتُ﴾ في قوله: ﴿وَأُمِرْتُ لِأَنْ أَكُونَ أَوَّلَ الْمُسْلِمِينَ﴾؟","answer":"لإبراز أن المبادرة إلى الإسلام مأمور بها استقلالًا، وليست مجرد نتيجة تابعة للأمر بإخلاص العبادة؛ فتكرر الفعل ليمنح كل تكليف عنايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص161–162، تحت عنوان «دلالة تكرار الفعل في ﴿وأمرت﴾»","url":""}]},{"id":"s39-120","number":120,"surah":39,"verses":[11,12],"references":[{"surah":39,"verses":[11,12]}],"verseLabel":"الزمر: 11–12","question":"لماذا وصف الرسول ﷺ بأنه ﴿أَوَّلَ الْمُسْلِمِينَ﴾؟","answer":"ليعلن تمام مبادرته إلى الامتثال، فهو أول أمته انقيادًا لما يدعوهم إليه؛ وبذلك يطابق فعله قوله ولا يأمر الناس بما يتأخر عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص163، تحت عنوان «دلالة التعبير بالأولية والغرض من الإضافة»","url":""}]},{"id":"s39-26","number":26,"surah":39,"verses":[14],"references":[{"surah":39,"verses":[14]}],"verseLabel":"الزمر: 14","question":"ما دلالة تقديم اسم الجلالة في ﴿قُلِ اللَّهَ أَعْبُدُ مُخْلِصًا لَهُ دِينِي﴾؟","answer":"تقديم المفعول ﴿الله﴾ يقصر العبادة عليه، فيعلن الرسول ﷺ اختصاصه بها في مواجهة دعوة الشرك. ويؤكد التعبير بالاسم الجامع لصفات الكمال أنه وحده المستحق لهذه العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص172، تحت عنوان «الغرض من تقديم المفعول به ونكتة التعبير بالاسم الجليل»","url":""}]},{"id":"s39-27","number":27,"surah":39,"verses":[2,14],"references":[{"surah":39,"verses":[2,14]}],"verseLabel":"الزمر: 2، 14","question":"لماذا قال أولًا: ﴿مُخْلِصًا لَهُ الدِّينَ﴾ ثم قال: ﴿مُخْلِصًا لَهُ دِينِي﴾؟","answer":"الأولى تقرر وجوب إخلاص جنس الدين لله، أما إضافة ﴿ديني﴾ إلى ياء المتكلم فتنقل المعنى من الحكم العام إلى إعلان الرسول تطبيقه في عبادته هو.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص173–174، تحت عنوان «الغرض من الإضافة لياء المتكلم في ﴿ديني﴾»","url":""}]},{"id":"s39-28","number":28,"surah":39,"verses":[15],"references":[{"surah":39,"verses":[15]}],"verseLabel":"الزمر: 15","question":"لماذا قيل للمشركين: ﴿فَاعْبُدُوا مَا شِئْتُمْ مِنْ دُونِهِ﴾ مع أن عبادة غير الله محرمة؟","answer":"ليس إذنًا لهم، بل أمر تهديد وتخلية بعد إقامة الحجة؛ أي امضوا فيما اخترتم وستلقون عاقبته، ولذلك أعقبه فورًا بيان الخسران المبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص175، تحت عنوان «الغرض من فعل الأمر ﴿فاعبدوا﴾»","url":""}]},{"id":"s39-29","number":29,"surah":39,"verses":[15],"references":[{"surah":39,"verses":[15]}],"verseLabel":"الزمر: 15","question":"لماذا عرّف القرآن الخاسرين بأنهم الذين خسروا أنفسهم يوم القيامة؟","answer":"لقصر الخسران الحقيقي الكامل عليهم؛ فالخسارات الدنيوية يمكن تداركها، أما من أضاع نفسه في الآخرة فقد فقد رأس ماله الذي لا يعوض.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص177–178، تحت عنوان «معنى اللام ودلالتها، والغرض من تعريف المسند إليه والمسند»","url":""}]},{"id":"s39-121","number":121,"surah":39,"verses":[15],"references":[{"surah":39,"verses":[15]}],"verseLabel":"الزمر: 15","question":"لماذا أضاف إلى خسارة النفس قوله: ﴿وَأَهْلِيهِمْ﴾؟","answer":"ليصور أن الخسارة لا تقف عند مصير الفرد، بل تشمل فوات اجتماعه بأهله المؤمنين أو إهلاك من تبعه منهم؛ فتجتمع عليه وحشة النفس ووحشة الفراق.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص179، تحت عنوان «الغرض من الإضافة في ﴿وأهليهم﴾»","url":""}]},{"id":"s39-30","number":30,"surah":39,"verses":[16],"references":[{"surah":39,"verses":[16]}],"verseLabel":"الزمر: 16","question":"لماذا سُمّيت النار المحيطة بالكافرين ﴿ظُلَلًا﴾؟","answer":"جاء اللفظ على استعارة تهكمية؛ فالظلة يتوقع منها الوقاية والراحة، فإذا بها طبقات من النار تغشاهم، فينقلب الاسم المطمئن إلى صورة أشد رعبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص188، تحت عنوان «الغرض من التعبير بالاستعارة التهكمية في قوله: ﴿ظلل﴾»","url":""}]},{"id":"s39-122","number":122,"surah":39,"verses":[16],"references":[{"surah":39,"verses":[16]}],"verseLabel":"الزمر: 16","question":"لماذا أعيدت كلمة ﴿ظُلَلٌ﴾ في قوله: ﴿وَمِنْ تَحْتِهِمْ ظُلَلٌ﴾؟","answer":"لتأكيد أن ما تحتهم نار كثيفة طبقات كالنار التي فوقهم، لا مجرد لهب عابر؛ فالتكرار يجسم إحاطة العذاب بهم من الجهتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص189–190، تحت عنوان «بلاغة الإطناب في قوله: ﴿ومن تحتهم ظلل﴾»","url":""}]},{"id":"s39-31","number":31,"surah":39,"verses":[16],"references":[{"surah":39,"verses":[16]}],"verseLabel":"الزمر: 16","question":"لماذا قُدّم النداء ﴿يَا عِبَادِ﴾ على الأمر ﴿فَاتَّقُونِ﴾ بعد مشهد النار؟","answer":"ليسبق التحذيرَ تذكيرٌ برابطة العبودية المشرِّفة ورحمة المنادي؛ فيستجيب القلب للأمر اتقاءً لمن يخوف عباده رحمةً بهم لا رغبةً في عذابهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص194، تحت عنوان «سر تقديم النداء ﴿يا عباد﴾ على الأمر ﴿فاتقون﴾»","url":""}]},{"id":"s39-32","number":32,"surah":39,"verses":[17,18],"references":[{"surah":39,"verses":[17,18]}],"verseLabel":"الزمر: 17–18","question":"لماذا جُمع بين اجتناب الطاغوت والإنابة إلى الله؟","answer":"لأن ترك الباطل وحده لا يكمل الهداية حتى يصحبه إقبال على الحق؛ فجمع الوصف بين التخلي عن عبادة الطاغوت والتحلي بالرجوع إلى الله وطاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص202، تحت عنوان «دلالة العطف في قوله: ﴿وأنابوا إلى الله﴾»","url":""}]},{"id":"s39-33","number":33,"surah":39,"verses":[17,18],"references":[{"surah":39,"verses":[17,18]}],"verseLabel":"الزمر: 17–18","question":"ماذا تفيد الفاء في قوله: ﴿فَيَتَّبِعُونَ أَحْسَنَهُ﴾ بعد استماع القول؟","answer":"تفيد سرعة انتقالهم من حسن الاستماع والتمييز إلى العمل، فلا يقفون عند المعرفة ولا يؤخرون الاستجابة لما ظهر لهم أنه أحسن.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص209، تحت عنوان «معنى الفاء ودلالتها في ﴿فيتبعون﴾»","url":""}]},{"id":"s39-123","number":123,"surah":39,"verses":[17,18],"references":[{"surah":39,"verses":[17,18]}],"verseLabel":"الزمر: 17–18","question":"لماذا قيل: ﴿فَيَتَّبِعُونَ أَحْسَنَهُ﴾؟","answer":"ليدل على أنهم لا يكتفون بأي قول، بل يزنون ما يسمعون ثم يختارون أهداه وأصوبه؛ وفي إضافة الأحسن إلى القول إشارة إلى قدرتهم على التمييز وحسن الاتباع.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص210، تحت عنوان «دلالة التعبير بأفعل التفضيل ﴿أحسنه﴾، والغرض من الإضافة»","url":""}]},{"id":"s39-34","number":34,"surah":39,"verses":[18],"references":[{"surah":6,"verses":[90]},{"surah":39,"verses":[18]}],"verseLabel":"الزمر: 18؛ الأنعام: 90","question":"ماذا يفيد قوله: ﴿أُولَئِكَ الَّذِينَ هَدَاهُمُ اللَّهُ﴾ بعد وصف مستمعي القول؟","answer":"يقصر الهداية الكاملة على أصحاب هذا الوصف تنويهًا بهم: فهداية الله تظهر في عقل منصف يسمع ويميز ثم يتبع الأحسن، لا في مجرد سماع لا يثمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص211، تحت عنوان «بلاغة القصر في قوله: ﴿أولئك الذين﴾»","url":""}]},{"id":"s39-35","number":35,"surah":39,"verses":[19],"references":[{"surah":39,"verses":[19]}],"verseLabel":"الزمر: 19","question":"كيف يبني ترتيب قوله: ﴿أَفَمَنْ حَقَّ عَلَيْهِ كَلِمَةُ الْعَذَابِ أَفَأَنْتَ تُنْقِذُ مَنْ فِي النَّارِ﴾ معنى استحالة إنقاذه؟","answer":"يبدأ بثبوت كلمة العذاب عليه، ثم يواجه الرسول بسؤال إنكاري عن إنقاذه، ثم يصوره كأنه داخل النار؛ فتتدرج العبارة من الحكم المحتوم إلى نفي قدرة البشر على دفعه ثم إلى مشاهدة مآله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص224، تحت عنوان «بلاغة ترتيب الآية ونظمها»","url":""}]},{"id":"s39-36","number":36,"surah":39,"verses":[19],"references":[{"surah":39,"verses":[19]}],"verseLabel":"الزمر: 19","question":"ما غرض سؤال الرسول ﷺ: ﴿أَفَأَنْتَ تُنْقِذُ مَنْ فِي النَّارِ﴾؟","answer":"الاستفهام للإنكار والتسلية: من ثبتت عليه كلمة العذاب لا يملك الرسول إنقاذه قسرًا، وإنما عليه البلاغ؛ وفي توجيه السؤال إليه إبراز لعجز كل أحد عن تغيير حكم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص220–221، تحت عنوان «الغرض من الاستفهام في قوله: ﴿أفأنت﴾ وتكرره»","url":""}]},{"id":"s39-37","number":37,"surah":39,"verses":[20],"references":[{"surah":39,"verses":[20]}],"verseLabel":"الزمر: 20","question":"لماذا وُصفت غرف الجنة بأنها ﴿مَبْنِيَّةٌ﴾؟","answer":"لتأكيد رسوخها وإحكامها ودوامها؛ فكون الغرف فوق غرف قد يوهم بناءً معلقًا غير ثابت، فجاء الوصف ليزيل الوهم ويصور مساكن آمنة لا تزول.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص231–232، تحت عنوان «سر وصف الغرف بالوصف ﴿مبنية﴾ ومجيئه مفردًا»","url":""}]},{"id":"s39-38","number":38,"surah":39,"verses":[20],"references":[{"surah":39,"verses":[20]}],"verseLabel":"الزمر: 20","question":"ماذا يضيف قوله: ﴿وَعْدَ اللَّهِ﴾ بعد وصف غرف المتقين؟","answer":"جاء مصدرًا مؤكدًا لمضمون الوعد، ثم أضيف إلى الله ليبلغ اليقين غايته؛ فهذه الغرف ليست أمنية بل وعدًا صادرًا ممن لا يعجزه إنجازه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص234–235، تحت عنوان «سر التعبير بالمفعول المطلق ﴿وعد﴾»","url":""}]},{"id":"s39-124","number":124,"surah":39,"verses":[20],"references":[{"surah":39,"verses":[20]}],"verseLabel":"الزمر: 20","question":"لماذا قيل: ﴿لَا يُخْلِفُ اللَّهُ الْمِيعَادَ﴾ ولم يقل: لا يخلف الميعاد؟","answer":"لإعادة اسم الجلالة تصريحًا فتزداد الجملة استقلالًا وهيبةً وتوكيدًا؛ فالذي أسند إليه الوعد هو نفسه الكامل الذي يستحيل عليه إخلافه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص236، تحت عنوان «الغرض من التعبير عن الفاعل بالاسم الجليل ﴿الله﴾»","url":""}]},{"id":"s39-39","number":39,"surah":39,"verses":[21],"references":[{"surah":39,"verses":[21]}],"verseLabel":"الزمر: 21","question":"لماذا عرضت الآية دورة الماء والزرع حتى يصير حطامًا؟","answer":"لتضرب مشهدًا محسوسًا للحياة الدنيا: تبدأ بالنماء والبهجة ثم تذبل سريعًا وتنتهي فتاتًا، فيرى الإنسان في الزرع أمامه مصير الاغترار بالدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص240، تحت عنوان «دلالة الاستئناف وضرب المثل»","url":""}]},{"id":"s39-40","number":40,"surah":39,"verses":[21],"references":[{"surah":39,"verses":[21]}],"verseLabel":"الزمر: 21","question":"لماذا نُكرت ﴿يَنَابِيعَ﴾ في قوله: ﴿فَسَلَكَهُ يَنَابِيعَ فِي الْأَرْضِ﴾؟","answer":"للدلالة على كثرتها وتنوعها وخفاء مقاديرها؛ فالماء الواحد يسلكه الله عيونًا ومسالك لا يحصيها الناس في أنحاء الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص246، تحت عنوان «غرض تنكير ﴿ينابيع﴾»","url":""}]},{"id":"s39-41","number":41,"surah":39,"verses":[22],"references":[{"surah":39,"verses":[22]}],"verseLabel":"الزمر: 22","question":"ماذا يصور قوله عن المهتدي: ﴿فَهُوَ عَلَى نُورٍ مِنْ رَبِّهِ﴾؟","answer":"يصوّر الهداية نورًا يكشف له الحق ويبدد ظلمة الشك، وإضافة النور إلى ربه تبين أن مصدر بصيرته وهدايته هو الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص264، تحت عنوان «بلاغة الاستعارة التصريحية في مفردة النور»","url":""}]},{"id":"s39-42","number":42,"surah":39,"verses":[22],"references":[{"surah":39,"verses":[22]}],"verseLabel":"الزمر: 22","question":"لماذا قوبل شرح الصدر للإسلام بقسوة القلب؟","answer":"لأن انشراح الصدر يصور سعة النفس لقبول الحق، بينما القسوة تصور انغلاقها عن التأثر بالذكر؛ فجاء التقابل مختلف اللفظ متكامل الصورة ليكشف حال الهداية والضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص267، تحت عنوان «علة اختلاف التقابل في الآية»","url":""}]},{"id":"s39-43","number":43,"surah":39,"verses":[23],"references":[{"surah":39,"verses":[23]}],"verseLabel":"الزمر: 23","question":"لماذا وُصف القرآن بأنه ﴿أَحْسَنَ الْحَدِيثِ﴾؟","answer":"لأنه بلغ الغاية في صدق أخباره وحكمة أحكامه وحسن نظمه وتأثيره، فلا حديث يجمع جمال اللفظ وكمال المعنى والهداية كما يجمعها كلام الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص276، تحت عنوان «بلاغة التعبير باسم التفضيل»","url":""}]},{"id":"s39-125","number":125,"surah":39,"verses":[23],"references":[{"surah":39,"verses":[23]}],"verseLabel":"الزمر: 23","question":"ما دلالة وصف القرآن بأنه كتاب ﴿مُتَشَابِهًا﴾؟","answer":"أي يشبه بعضه بعضًا في الصدق والإحكام والجمال ويصدق بعضه بعضًا؛ فلا تناقض بين أجزائه ولا تفاوت يخرجه عن كماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص277، تحت عنوان «بلاغة وصف القرآن بالتشابه»","url":""}]},{"id":"s39-44","number":44,"surah":39,"verses":[23],"references":[{"surah":39,"verses":[23]}],"verseLabel":"الزمر: 23","question":"لماذا تقشعر جلود الذين يخشون ربهم عند سماع القرآن؟","answer":"لأن الوعيد والجلال يهزانهم حتى يظهر الخوف على ظاهر أجسادهم؛ فالاقشعرار صورة حسية لنفوذ كلام الله من السمع إلى أعماق النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص278، تحت عنوان «بلاغة التعبير بمفردة القشعريرة مادة وصيغة»","url":""}]},{"id":"s39-126","number":126,"surah":39,"verses":[23],"references":[{"surah":39,"verses":[23]}],"verseLabel":"الزمر: 23","question":"لماذا جمع بين الجلود والقلوب في قوله: ﴿ثُمَّ تَلِينُ جُلُودُهُمْ وَقُلُوبُهُمْ﴾؟","answer":"لأن أثر القرآن يشمل الظاهر والباطن: تسكن الجوارح بعد الوجل، وتطمئن القلوب بالرجاء والذكر؛ فجمعهما ليصور تحول الإنسان كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص281–282، تحت عنوان «فائدة عطف القلوب على الجلود»","url":""}]},{"id":"s39-45","number":45,"surah":39,"verses":[24],"references":[{"surah":39,"verses":[24]}],"verseLabel":"الزمر: 24","question":"ما الصورة التي يرسمها قوله ﴿أَفَمَنْ يَتَّقِي بِوَجْهِهِ سُوءَ الْعَذَابِ﴾؟","answer":"الوجه أشرف ما يصونه الإنسان، فإذا اتقى به العذاب دل ذلك على نهاية العجز عن دفعه. وتوجه الصورة إلى غل اليدين أو إلى الكناية عن استحالة الوقاية، فتقلب المألوف: ما كان يحمى صار وسيلة اتقاء لا تغني شيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص292، تحت عنوان «توجيه تخصيص الوجه بالذكر»","url":""}]},{"id":"s39-46","number":46,"surah":39,"verses":[24],"references":[{"surah":39,"verses":[24]}],"verseLabel":"الزمر: 24","question":"ما غرض الأمر ﴿ذُوقُوا﴾ في مواجهة أهل النار؟","answer":"ليس طلبًا حقيقيًا يملكون رده، بل أمر إهانة وتوبيخ يواجههم بأن العذاب صار واقعًا يباشرونه، وأن زمن الإنذار والاختيار قد انتهى.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص297، تحت عنوان «غرض الأمر ودلالته»","url":""}]},{"id":"s39-47","number":47,"surah":39,"verses":[25,26],"references":[{"surah":39,"verses":[25,26]}],"verseLabel":"الزمر: 25–26","question":"لماذا وُصف عذاب الآخرة بأنه ﴿أَكْبَرُ﴾؟","answer":"لأن عذاب الدنيا محدود زمنًا وقدرًا، أما عذاب الآخرة فأعظم شدة وأبقى أثرًا؛ فاسم التفضيل ينقل السامع من الخزي المشاهد إلى ما هو أهول منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص307، تحت عنوان «لطيفة اسم التفضيل»","url":""}]},{"id":"s39-48","number":48,"surah":39,"verses":[27,28],"references":[{"surah":39,"verses":[27,28]}],"verseLabel":"الزمر: 27–28","question":"ماذا تفيد خاتمة ﴿لَعَلَّهُمْ يَتَّقُونَ﴾ بعد ضرب الأمثال ونفي العوج؟","answer":"تبين أن جمال البيان واستقامته ليسا غاية فنية مجردة، بل طريق إلى يقظة القلب واتقاء الضلال والعذاب؛ ففي الرجاء حث للسامع على الانتفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص319، تحت عنوان «نكتة استعمال أداة الرجاء»","url":""}]},{"id":"s39-49","number":49,"surah":39,"verses":[28],"references":[{"surah":39,"verses":[28]}],"verseLabel":"الزمر: 28","question":"ما دلالة وصف القرآن بأنه ﴿غَيْرَ ذِي عِوَجٍ﴾ بعد وصفه بالعربية؟","answer":"ينفي عنه كل ميل أو تناقض أو اضطراب في ألفاظه ومعانيه؛ فجمع وضوح اللسان مع استقامة المضمون، فلا تبقى شبهة ناشئة من البيان أو المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص318، تحت عنوان «براعة نفي العوج بعد وصف القرآن بالعربي»","url":""}]},{"id":"s39-50","number":50,"surah":39,"verses":[29],"references":[{"surah":39,"verses":[29]}],"verseLabel":"الزمر: 29","question":"ماذا يصور وصف الشركاء بأنهم ﴿مُتَشَاكِسُونَ﴾؟","answer":"يصورهم شديدي التنازع وسوء الخلق، كل واحد يجذب عبده إلى جهة؛ فيعيش المشرك ممزق القلب لا يدري أي سيد يرضي.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص326، تحت عنوان «نكتة استعمال مفردة ﴿متشاكسون﴾ مادة وصيغة»","url":""}]},{"id":"s39-127","number":127,"surah":39,"verses":[29],"references":[{"surah":39,"verses":[29]}],"verseLabel":"الزمر: 29","question":"لماذا قوبل الرجل ذو الشركاء برجل ﴿سَلَمًا لِرَجُلٍ﴾؟","answer":"لأن ﴿سلمًا﴾ تصور عبدًا خالصًا لسيد واحد لا ينازعه فيه أحد؛ فاستقرت وجهته وأوامره، كما يستريح الموحد بإخلاص العبادة لله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص327، تحت عنوان «دلالة التعبير بـ﴿سلمًا﴾ مادة وصيغة»","url":""}]},{"id":"s39-51","number":51,"surah":39,"verses":[30,31],"references":[{"surah":39,"verses":[30,31]}],"verseLabel":"الزمر: 30–31","question":"ماذا تفيد ﴿ثُمَّ﴾ في الانتقال من موت الرسول ﷺ وموت قومه إلى اختصامهم عند الله؟","answer":"تطوي ما بين الموت والبعث ثم تنقل الجميع إلى موقف الحساب؛ فالموت لا ينهي النزاع بل يؤخر الفصل فيه حتى يقضي الله بينهم بالحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص335، تحت عنوان «نوع ﴿ثم﴾ ودلالتها»","url":""}]},{"id":"s39-128","number":128,"surah":39,"verses":[30,31],"references":[{"surah":39,"verses":[30,31]}],"verseLabel":"الزمر: 30–31","question":"لماذا قيل: ﴿عِنْدَ رَبِّكُمْ تَخْتَصِمُونَ﴾؟","answer":"اختيرت الربوبية لتذكيرهم بأن الذي رباهم ودبر أمرهم هو الحكم بينهم؛ فلا يضيع عنده حق ولا يخفى عليه ما وقع بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص337، تحت عنوان «سر اختيار لفظ الربوبية»","url":""}]},{"id":"s39-52","number":52,"surah":39,"verses":[32],"references":[{"surah":39,"verses":[32]}],"verseLabel":"الزمر: 32","question":"ماذا يكشف قوله: ﴿وَكَذَّبَ بِالصِّدْقِ إِذْ جَاءَهُ﴾؟","answer":"يكشف أنه بادر إلى تكذيب الحق ساعة وصوله من غير تدبر ولا انتظار؛ فظرف ﴿إذ﴾ يستحضر لحظة المواجهة ويزيد جريمته قبحًا لأن البيان جاءه واضحًا فرده فورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص352، تحت عنوان «دلالة التعبير بالظرف ﴿إذ﴾»","url":""}]},{"id":"s39-53","number":53,"surah":39,"verses":[32,33],"references":[{"surah":39,"verses":[32,33]}],"verseLabel":"الزمر: 32–33","question":"لماذا ختم وصف من جاء بالصدق وصدّق به بقوله: ﴿أُولَئِكَ هُمُ الْمُتَّقُونَ﴾؟","answer":"لأن التقوى تجمع الإتيان بالحق وقبوله والعمل بمقتضاه؛ فليس الفضل في حمل الصدق وحده ولا في تصديق بلا التزام، وإنما في موقف كامل يحجز صاحبه عن الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص366، تحت عنوان «سر التعبير بالتقوى دون غيرها في قوله: ﴿المتقون﴾»","url":""}]},{"id":"s39-54","number":54,"surah":39,"verses":[33],"references":[{"surah":39,"verses":[33]}],"verseLabel":"الزمر: 33","question":"لماذا قُدّم ﴿جَاءَ بِالصِّدْقِ﴾ على ﴿وَصَدَّقَ بِهِ﴾؟","answer":"لأن وصول الحق وبيانه سابق في الرتبة على الإيمان به؛ فبدأ بمن يحمله ويبلغه، ثم بمن يتلقاه بالتصديق، فجمع مصدر الهداية ومستجيبها بترتيب طبيعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص363، تحت عنوان «دلالة الترتيب في الآية»","url":""}]},{"id":"s39-55","number":55,"surah":39,"verses":[34,35],"references":[{"surah":39,"verses":[34,35]}],"verseLabel":"الزمر: 34–35","question":"لماذا ذُكر تكفير السيئات بعد قوله: ﴿ذَلِكَ جَزَاءُ الْمُحْسِنِينَ﴾؟","answer":"ليبين أن جزاء الإحسان يجمع دفع المكروه وجلب المحبوب: يمحو الله عنهم آثار السيئات ثم يمنحهم الثواب، فلا يقتصر إحسانه على أحد الجانبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص378، تحت عنوان «دلالة ذكر قوله: ﴿ليكفر الله عنهم﴾ بعد قوله: ﴿ذلك جزاء المحسنين﴾»","url":""}]},{"id":"s39-129","number":129,"surah":39,"verses":[34,35],"references":[{"surah":39,"verses":[34,35]}],"verseLabel":"الزمر: 34–35","question":"ما دلالة المقابلة بين ﴿أَسْوَأَ الَّذِي عَمِلُوا﴾ و﴿بِأَحْسَنِ الَّذِي كَانُوا يَعْمَلُونَ﴾؟","answer":"تظهر سعة الفضل: يمحو أسوأ الذنوب، ثم يجعل معيار الجزاء أحسن الأعمال؛ فلا يعاملهم بالموازنة المجردة بل بالمغفرة والكرم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص386، تحت عنوان «بلاغة الطباق بين ﴿أسوأ﴾ و(أحسن)»","url":""}]},{"id":"s39-56","number":56,"surah":39,"verses":[35],"references":[{"surah":39,"verses":[35]}],"verseLabel":"الزمر: 35","question":"لماذا عُبّر عن محو السيئات بقوله: ﴿لِيُكَفِّرَ اللَّهُ عَنْهُمْ﴾؟","answer":"التكفير أصله الستر، ثم استعمل في محو الذنب وإزالة أثره؛ فيصور السيئة وقد غطاها عفو الله فلم تعد تحيط بصاحبها أو تؤاخذه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص378–379، تحت عنوان «دلالة التعبير بالتكفير في قوله: ﴿ليكفر﴾»","url":""}]},{"id":"s39-57","number":57,"surah":39,"verses":[36,37],"references":[{"surah":39,"verses":[36,37]}],"verseLabel":"الزمر: 36–37","question":"لماذا قيل: ﴿أَلَيْسَ اللَّهُ بِكَافٍ عَبْدَهُ﴾؟","answer":"اختير وصف الكفاية ليشمل كل ما يحتاج العبد إلى دفعه أو جلبه؛ فمن كفاه الله لم تضره تخويفات المشركين ولا احتاج إلى حماية معبوداتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص393، تحت عنوان «سر التعبير بـ (كاف) دون غيره»","url":""}]},{"id":"s39-130","number":130,"surah":39,"verses":[36,37],"references":[{"surah":39,"verses":[36,37]}],"verseLabel":"الزمر: 36–37","question":"ما دلالة المقابلة بين ﴿فَمَا لَهُ مِنْ هَادٍ﴾ و﴿فَمَا لَهُ مِنْ مُضِلٍّ﴾؟","answer":"تقرر انفراد الله بالهداية والإضلال: من خذله فلا أحد يوصله إلى الحق، ومن هداه فلا أحد يقدر أن يصرفه عنه؛ فتسقط أوهام النفع والضر من غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص414، تحت عنوان «بلاغة الطباق ﴿يضلل﴾ و﴿يهد﴾، و﴿هاد﴾، و﴿مضل﴾»","url":""}]},{"id":"s39-58","number":58,"surah":39,"verses":[36,37,38],"references":[{"surah":39,"verses":[36,37,38]}],"verseLabel":"الزمر: 36–38","question":"ما سر التعبير عن الأصنام بضمير الإناث في ﴿هَلْ هُنَّ كَاشِفَاتُ ضُرِّهِ﴾؟","answer":"يرد التأنيث إلى أسمائهم للأصنام كاللات والعزى ومناة، أو إلى زعمهم أنها صور ملائكة إناث. ويعيدهم هذا التعبير إلى حقيقة ما سموه وعبدوه، في سياق ينكر قدرتها على كشف الضر أو إمساك الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص441، تحت عنوان «سر التعبير عن الأصنام بالتذكير ثم بالتأنيث»","url":""}]},{"id":"s39-59","number":59,"surah":39,"verses":[38],"references":[{"surah":39,"verses":[38]}],"verseLabel":"الزمر: 38","question":"لماذا قُدّم دفع الضر على إمساك الرحمة في سؤال المشركين عن معبوداتهم؟","answer":"لأن الخوف من الضر أشد استنفارًا للنفس وأسبق في مقام التحدي، ثم أتبعه بما يطمع فيه الإنسان من الرحمة؛ فاستوعب حالتي الخوف والرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص444–445، تحت عنوان «سر تقديم ما يتعلق بدفع الضر على ما يتعلق بإمساك الرحمة»","url":""}]},{"id":"s39-60","number":60,"surah":39,"verses":[38],"references":[{"surah":39,"verses":[38]}],"verseLabel":"الزمر: 38","question":"لماذا ذُيّل الاحتجاج بقوله: ﴿عَلَيْهِ يَتَوَكَّلُ الْمُتَوَكِّلُونَ﴾؟","answer":"ليحوّل نتيجة البرهان إلى قاعدة عامة: من عرف أن الله وحده يكشف الضر ويمسك الرحمة فحقه أن يعتمد عليه، وهذا شأن كل من صدق توكله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص450، تحت عنوان «بلاغة التذييل بجملة: ﴿عليه يتوكل المتوكلون﴾»","url":""}]},{"id":"s39-61","number":61,"surah":39,"verses":[39],"references":[{"surah":11,"verses":[93]},{"surah":39,"verses":[39]}],"verseLabel":"الزمر: 39؛ هود: 93","question":"ما دلالة الفاء في قوله بالزمر ﴿فسوف تعلمون﴾؟","answer":"الفاء تفرع العلم بالعاقبة على العمل السابق؛ فاستمرارهم على حالهم سيكشف لهم مآلها. ويجوز ربطها بالأمر بالعمل: اعملوا فسوف تعلمون، فيشتد الوعيد مع تأكيد الرسول ﷺ ثقته بما وعده الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص461، تحت عنوان «دلالة التعبير بالفاء في قوله: ﴿فسوف﴾»","url":""}]},{"id":"s39-62","number":62,"surah":39,"verses":[39,40],"references":[{"surah":39,"verses":[39,40]}],"verseLabel":"الزمر: 39–40","question":"ما الصورة في قوله: ﴿اعْمَلُوا عَلَى مَكَانَتِكُمْ﴾؟","answer":"تصور حالهم الراسخة منزلة يقفون عليها ويعملون منها؛ وفي ذلك تعريض بتمكنهم من العناد مع تحديهم أن يستفرغوا ما يستطيعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص458، تحت عنوان «بلاغة الاستعارة في قوله: ﴿مكانتكم﴾»","url":""}]},{"id":"s39-63","number":63,"surah":39,"verses":[41],"references":[{"surah":39,"verses":[41]}],"verseLabel":"الزمر: 41","question":"لماذا قيل في وصف القرآن: ﴿نَزَّلَ أَحْسَنَ الْحَدِيثِ﴾ دون: أنزل؟","answer":"صيغة ﴿نزّل﴾ تشعر بالتدرج والتكرار، فتوافق نزول القرآن مفرقًا بحسب الوقائع والحكمة، مع تجدد أثره في القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص275، تحت عنوان «دلالة التعبير بـ﴿نزل﴾ دون (أنزل)»","url":""}]},{"id":"s39-131","number":131,"surah":39,"verses":[41],"references":[{"surah":39,"verses":[41]}],"verseLabel":"الزمر: 41","question":"كيف سُمّي الوحي ﴿الْكِتَابَ﴾ في قوله: ﴿إِنَّا أَنْزَلْنَا عَلَيْكَ الْكِتَابَ﴾؟","answer":"أطلق اسم الكتاب الكامل على ما نزل منه باعتبار ما سيؤول إليه من تمام واجتماع، أو أريد به الجنس؛ فيؤكد أن كل ما يتنزل جزء من كتاب واحد محكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص474، تحت عنوان «بلاغة المجاز المرسل في إطلاق: ﴿الكتاب﴾»","url":""}]},{"id":"s39-64","number":64,"surah":39,"verses":[41],"references":[{"surah":39,"verses":[41]}],"verseLabel":"الزمر: 41","question":"لماذا قيل: ﴿فَمَنِ اهْتَدَى فَلِنَفْسِهِ﴾ بلا ﴿إنما﴾، ثم قيل: ﴿فَإِنَّمَا يَضِلُّ عَلَيْهَا﴾؟","answer":"حُذفت أداة القصر في جانب الهداية لأن اختصاص نفعها بصاحبها مفهوم من مقابلة الضلال، وأُبرز القصر في جانب الضلال لتبرئة الرسول من تبعته وقطع اعتذار من يلقي وزره على غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص481، تحت عنوان «بلاغة الحذف التقابلي في القصر»","url":""}]},{"id":"s39-65","number":65,"surah":39,"verses":[42],"references":[{"surah":39,"verses":[42]}],"verseLabel":"الزمر: 42","question":"لماذا عُبّر عن الموت والنوم معًا بتوفي الأنفس؟","answer":"لأن التوفي هو أخذ الشيء وافيًا؛ فالله يقبض النفس عند الموت قبضًا تامًا، ويقبضها في النوم قبضًا مؤقتًا، فيجمع اللفظ الحالتين ويكشف صلتهما مع اختلاف المآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص489–490، تحت عنوان «فائدة التعبير ﴿يتوفى﴾ مادة وصيغة»","url":""}]},{"id":"s39-66","number":66,"surah":39,"verses":[42],"references":[{"surah":39,"verses":[42]}],"verseLabel":"الزمر: 42","question":"ماذا تصور المقابلة بين ﴿فَيُمْسِكُ الَّتِي قَضَى عَلَيْهَا الْمَوْتَ﴾ و﴿وَيُرْسِلُ الْأُخْرَى﴾؟","answer":"تصور الأنفس كلها في قبضة الله عند النوم؛ فيحتفظ بما انتهى أجله فلا يعود إلى الجسد، ويطلق الأخرى لتستأنف حياتها، فيظهر سلطان واحد على الموت والبعث اليومي.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص497–498، تحت عنوان «بلاغة الطباق بين ﴿فيمسك﴾، و﴿ويرسل﴾»","url":""}]},{"id":"s39-67","number":67,"surah":39,"verses":[43,44],"references":[{"surah":39,"verses":[43,44]}],"verseLabel":"الزمر: 43–44","question":"لماذا قُدّم ﴿لِلَّهِ﴾ في قوله: ﴿قُلْ لِلَّهِ الشَّفَاعَةُ﴾؟","answer":"لقصر ملك الشفاعة وإذنها على الله وحده، فلا يملكها شفيع استقلالًا ولا تقع إلا لمن أذن له ورضي عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص520، تحت عنوان «دلالة تقديم شبه الجملة ﴿لله﴾»","url":""}]},{"id":"s39-132","number":132,"surah":39,"verses":[43,44],"references":[{"surah":39,"verses":[43,44]}],"verseLabel":"الزمر: 43–44","question":"ماذا يضيف قوله: ﴿الشَّفَاعَةُ جَمِيعًا﴾؟","answer":"يزيل كل احتمال لاستثناء نوع أو قدر منها؛ فكل شفاعة بلا استثناء داخلة في ملك الله وإذنه، لا بعض الشفاعة فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص521، تحت عنوان «موقع قوله: ﴿جميعًا﴾ وأثره في البيان»","url":""}]},{"id":"s39-68","number":68,"surah":39,"verses":[43],"references":[{"surah":39,"verses":[43]}],"verseLabel":"الزمر: 43","question":"لماذا احتج على بطلان شفاعة الأصنام بأنها لا تملك شيئًا ولا تعقل؟","answer":"لأن الشفيع لا بد أن يملك قدرة على النفع ووعيًا بمن يشفع له وما يطلبه؛ فإذا انتفى عن الأصنام الملك والعقل انتفى أصل صلاحيتها للشفاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص518، تحت عنوان «بلاغة الكناية في نفي الملك والعقل خاصة»","url":""}]},{"id":"s39-69","number":69,"surah":39,"verses":[45],"references":[{"surah":39,"verses":[45]}],"verseLabel":"الزمر: 45","question":"ماذا يصوّر اختيار ﴿اشْمَأَزَّتْ﴾ لنفور غير المؤمنين عند ذكر الله وحده؟","answer":"يصور نفورًا شديدًا يصحبه انقباض واضطراب، لا مجرد كراهية عابرة؛ فمادة الكلمة وصيغتها تستحضران حركة نفسية عنيفة تكشف شدة بغضهم للتوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص529–530، تحت عنوان «دلالة التعبير ﴿اشمأزت﴾ مادة وصيغة»","url":""}]},{"id":"s39-70","number":70,"surah":39,"verses":[45],"references":[{"surah":39,"verses":[45]}],"verseLabel":"الزمر: 45","question":"ما الذي تضيفه ﴿إِذَا﴾ في قوله: ﴿إِذَا هُمْ يَسْتَبْشِرُونَ﴾؟","answer":"تفيد المفاجأة وسرعة ظهور فرحهم بمجرد ذكر معبوداتهم؛ فكأن الانتقال من الذكر إلى الاستبشار يقع فورًا، مما يكشف شدة تعلقهم بها وغرابة انقلاب حالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص537، تحت عنوان «معنى (إذا)»","url":""}]},{"id":"s39-133","number":133,"surah":39,"verses":[45],"references":[{"surah":39,"verses":[45]}],"verseLabel":"الزمر: 45","question":"ماذا تكشف مقابلة ﴿اشْمَأَزَّتْ﴾ بـ﴿يَسْتَبْشِرُونَ﴾؟","answer":"تضع غاية النفور من ذكر الله وحده بإزاء غاية الفرح بذكر من دونه؛ فيبرز الطباق انقلاب فطرتهم وتمام التباعد بين الحالتين: انقباض القلب هناك وامتلاؤه سرورًا هنا.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص539، تحت عنوان «بلاغة الطباق بين الحالتين»","url":""}]},{"id":"s39-71","number":71,"surah":39,"verses":[46],"references":[{"surah":39,"verses":[46]}],"verseLabel":"الزمر: 46","question":"لماذا انتقل السياق من مجادلة المشركين إلى الدعاء: ﴿اللَّهُمَّ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"ليقطع الجدال العقيم بالتضرع إلى المرجع الأعلى الذي خلق الكون ويعلم السر والعلن ويحكم بين المختلفين؛ فالفصل ينقل المقام من الاحتجاج على عنادهم إلى تفويض الفصل لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص543، تحت عنوان «نكتة فصل الآية عن سابقتها»","url":""}]},{"id":"s39-134","number":134,"surah":39,"verses":[46],"references":[{"surah":39,"verses":[46]}],"verseLabel":"الزمر: 46","question":"لماذا جاء قوله: ﴿أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ﴾ بصيغة الخبر مع أنه في سياق الدعاء؟","answer":"لإظهار اليقين بأن حكم الله واقع لا محالة، حتى صيغ المطلوب في صورة حقيقة ثابتة؛ وفيه تفويض كامل واعتراف بأن الفصل بين المختلفين إليه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص549، تحت عنوان «نكتة مجيء: ﴿أنت تحكم﴾ بصيغة الخبر لا الإنشاء»","url":""}]},{"id":"s39-72","number":72,"surah":39,"verses":[46],"references":[{"surah":39,"verses":[46]}],"verseLabel":"الزمر: 46","question":"لماذا قُدّم وصف الله بـ﴿فَاطِرِ﴾ على وصفه بـ﴿عَالِمِ﴾؟","answer":"لأن آثار القدرة في الخلق أظهر للمخاطبين وأسبق إلى إدراكهم، ولأن مقام الفصل بين المختلفين يقتضي أولًا القدرة التامة على إنفاذ الحكم؛ ثم جاء العلم ليقرر إحاطته بما يحكم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص547–548، تحت عنوان «نكتة تقديم صفة ﴿فاطر﴾ على ﴿عالم﴾»","url":""}]},{"id":"s39-73","number":73,"surah":39,"verses":[47,48],"references":[{"surah":39,"verses":[47,48]}],"verseLabel":"الزمر: 47–48","question":"لماذا تكرر قوله: ﴿وَبَدَا لَهُمْ﴾ في مشهد الحساب؟","answer":"لأن الظهور الثاني ليس تكرارًا خاليًا من الزيادة؛ فالأول يكشف لهم من الله ما لم يحتسبوا، والثاني يصرح بظهور سيئات أعمالهم وآثارها، فيتجدد التهويل مع كل حقيقة تنكشف.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص570، تحت عنوان «سر تكرير فعل (بدا)»","url":""}]},{"id":"s39-74","number":74,"surah":39,"verses":[47],"references":[{"surah":39,"verses":[47]}],"verseLabel":"الزمر: 47","question":"لماذا قيل: ﴿مَا فِي الْأَرْضِ جَمِيعًا﴾ في فداء الظالمين؟","answer":"لتستغرق الصورة كل ما في الأرض بلا استثناء؛ فيتخيل السامع أن الظالم يملك ثرواتها كلها ثم يبذلها للنجاة، ومع ذلك لا تنفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص559، تحت عنوان «سر التوكيد بالحال ﴿جميعًا﴾»","url":""}]},{"id":"s39-135","number":135,"surah":39,"verses":[47],"references":[{"surah":39,"verses":[47]}],"verseLabel":"الزمر: 47","question":"لماذا زيد على ما في الأرض قوله: ﴿وَمِثْلَهُ مَعَهُ﴾؟","answer":"لمضاعفة الفداء المفروض إلى أبعد ما يتصوره الإنسان؛ فحتى لو اجتمع له كل ما في الأرض ومثله معه لبذله، ومع هذا يبقى عاجزًا عن دفع العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص559، تحت عنوان «نكتة التعبير بالمثلية: ﴿ومثله﴾»","url":""}]},{"id":"s39-136","number":136,"surah":39,"verses":[47],"references":[{"surah":39,"verses":[47]}],"verseLabel":"الزمر: 47","question":"ما الصورة التي يرسمها شرط افتداء الظالم بكل ما في الأرض؟","answer":"يمثل حالهم بحال أسير رأى الهلاك فقدم أعظم فدية ممكنة طلبًا للنجاة، ثم لم تقبل منه؛ فتجسد الشرطية شدة الفزع واليأس من كل وسيلة خلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص562، تحت عنوان «بلاغة الاستعارة التمثيلية في مضمون الشرطية»","url":""}]},{"id":"s39-75","number":75,"surah":39,"verses":[49,50,51],"references":[{"surah":39,"verses":[49,50,51]}],"verseLabel":"الزمر: 49–51","question":"لماذا قيل: ﴿مَسَّ الْإِنْسَانَ ضُرٌّ﴾؟","answer":"لأن المس يوحي بأدنى إصابة؛ فإذا كان مجرد مس الضر يدفع الإنسان إلى دعاء الله، كان نسيانه بعد كشفه أشد كشفًا لتقلبه وجحوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص580، تحت عنوان «بلاغة التعبير بالمس دون غيره»","url":""}]},{"id":"s39-137","number":137,"surah":39,"verses":[49,50,51],"references":[{"surah":39,"verses":[49,50,51]}],"verseLabel":"الزمر: 49–51","question":"لماذا قيل عن دعوى الإنسان: ﴿قَدْ قَالَهَا الَّذِينَ مِنْ قَبْلِهِمْ﴾؟","answer":"ليرد غروره إلى شبهة قديمة كررها الهالكون قبله؛ فليست مقالته دليل تفوق ولا اكتشافًا، وقد شهد مصير السابقين بأن ما كسبوه لم يغن عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص595، تحت عنوان «نكتة فصل ﴿قد قالها﴾»","url":""}]},{"id":"s39-76","number":76,"surah":39,"verses":[49],"references":[{"surah":39,"verses":[49]}],"verseLabel":"الزمر: 49","question":"ماذا يفيد وصف النعمة بأنها ﴿مِنَّا﴾؟","answer":"يصرح بأن مصدرها تفضل الله لا استحقاق الإنسان، فيمهد لكشف جحوده حين ينسبها بعد ذلك إلى علمه؛ فالكلمة ترد النعمة إلى واهبها الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص584، تحت عنوان «بلاغة الوصف بقوله ﴿منا﴾»","url":""}]},{"id":"s39-77","number":77,"surah":39,"verses":[51],"references":[{"surah":39,"verses":[51]}],"verseLabel":"الزمر: 51","question":"لماذا أشار إلى الظالمين المعاصرين بقوله: ﴿وَالَّذِينَ ظَلَمُوا مِنْ هَؤُلَاءِ﴾؟","answer":"لتعيين المخاطبين الحاضرين وتوجيه الوعيد إليهم مباشرة؛ فلا يظنوا أن قصة السابقين بعيدة عنهم، فهم يسلكون طريقهم ومهددون بمصيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص603، تحت عنوان «نكتة التعبير باسم الإشارة»","url":""}]},{"id":"s39-138","number":138,"surah":39,"verses":[51],"references":[{"surah":39,"verses":[51]}],"verseLabel":"الزمر: 51","question":"ماذا تفيد السين في قوله: ﴿سَيُصِيبُهُمْ سَيِّئَاتُ مَا كَسَبُوا﴾؟","answer":"تجعل جزاءهم الآتي قريب الوقوع محققًا، وتصل حاضرهم بمصير من قبلهم؛ فتأخر العقوبة لا يعني الإفلات منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص604، تحت عنوان «فائدة السين في ﴿سيصيبهم﴾»","url":""}]},{"id":"s39-78","number":78,"surah":39,"verses":[52],"references":[{"surah":39,"verses":[52]}],"verseLabel":"الزمر: 52","question":"ما سر ذكر الرزق مع البسط وحذفه مع التقدير في ﴿يَبْسُطُ الرِّزْقَ لِمَنْ يَشَاءُ وَيَقْدِرُ﴾؟","answer":"حذف متعلق ﴿ويقدر﴾ لدلالة ما قبله عليه؛ أي يقدر الرزق لمن يشاء. ففيه إيجاز يجمع البسط والتضييق في تدبير واحد، ويترك السياق يغني عن إعادة لفظ الرزق.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص613، تحت عنوان «بلاغة حذف متعلق ﴿ويقدر﴾»","url":""}]},{"id":"s39-79","number":79,"surah":39,"verses":[53],"references":[{"surah":39,"verses":[53]}],"verseLabel":"الزمر: 53","question":"لماذا قيل عن المسرفين: ﴿أَسْرَفُوا عَلَى أَنْفُسِهِمْ﴾؟","answer":"لأن وبال المعصية راجع إليهم لا إلى غيرهم؛ فالتعبير يوقظهم إلى أنهم تجاوزوا الحد بما يضر أنفسهم، وفي الوقت نفسه يدعوهم إلى إنقاذها بالتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص622–623، تحت عنوان «سر تخصيص ضرر الإسراف ﴿على أنفسهم﴾»","url":""}]},{"id":"s39-80","number":80,"surah":39,"verses":[53],"references":[{"surah":39,"verses":[53]}],"verseLabel":"الزمر: 53","question":"ماذا يصنع النهي ﴿لَا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ﴾ في نفس المذنب؟","answer":"يقطع طريق اليأس الذي يمنعه من التوبة، ويحوّل اعترافه بالإسراف إلى رجاء وعمل؛ فليس المقصود تهوين الذنب بل فتح باب العودة إلى رحمة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص623، تحت عنوان «دلالة النهي في ﴿لا تقنطوا﴾»","url":""}]},{"id":"s39-139","number":139,"surah":39,"verses":[53],"references":[{"surah":39,"verses":[53]}],"verseLabel":"الزمر: 53","question":"ماذا تضيف ﴿جَمِيعًا﴾ في قوله: ﴿إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا﴾؟","answer":"تؤكد استغراق المغفرة للذنوب عند تحقق التوبة، فلا يستعظم العائد ذنبًا على عفو الله؛ وبذلك تبلغ آية الرجاء غايتها من غير أن تكون ترخيصًا في الإصرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص626، تحت عنوان «بلاغة الحال بلفظ ﴿جميعًا﴾»","url":""}]},{"id":"s39-81","number":81,"surah":39,"verses":[53],"references":[{"surah":39,"verses":[53]}],"verseLabel":"الزمر: 53","question":"ما مناسبة تقديم ﴿الْغَفُورُ﴾ على ﴿الرَّحِيمُ﴾ في آية الرجاء؟","answer":"المغفرة تزيل موجب العقاب، والرحمة تحصل بها أسباب الثواب؛ فقدم ما يدفع الضرر على ما يجلب النفع. والمغفرة نفسها من آثار الرحمة، فجاء ترتيب الوصفين ملائمًا لمقام المذنب المدعو إلى الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص627، تحت عنوان «علة تقديم المغفرة على الرحمة»","url":""}]},{"id":"s39-82","number":82,"surah":39,"verses":[54,55],"references":[{"surah":39,"verses":[54,55]}],"verseLabel":"الزمر: 54–55","question":"لماذا جاء الأمر بالإسلام بعد الأمر بالإنابة؟","answer":"لأن الإنابة رجوع القلب عن المعصية، ثم يترجم الإسلام هذا الرجوع خضوعًا وإخلاصًا لله؛ فانتقل من توجه الباطن إلى استسلام العبد في اعتقاده وعمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص631، تحت عنوان «دلالة الأمر بالإسلام في السياق»","url":""}]},{"id":"s39-140","number":140,"surah":39,"verses":[54,55],"references":[{"surah":39,"verses":[54,55]}],"verseLabel":"الزمر: 54–55","question":"لماذا قيل بعد الإنابة والإسلام: ﴿وَاتَّبِعُوا أَحْسَنَ مَا أُنْزِلَ إِلَيْكُمْ﴾؟","answer":"لأن صدق الرجوع لا يقف عند الشعور والإقرار، بل يظهر في اتباع الوحي والعمل به؛ فعطف الاتباع يستكمل طريق التوبة بالطاعة العملية.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص636، تحت عنوان «بلاغة عطف جملة ﴿واتبعوا﴾»","url":""}]},{"id":"s39-83","number":83,"surah":39,"verses":[56],"references":[{"surah":39,"verses":[56]}],"verseLabel":"الزمر: 56","question":"ماذا يكشف قول النفس: ﴿فَرَّطْتُ﴾؟","answer":"يكشف أنها قصرت وضيعت ما كان في قدرتها فعله، لا أنها عجزت عنه؛ فلفظ التفريط يحمل اعترافًا بالمسؤولية عن الفرصة المهدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص647، تحت عنوان «دلالة التعبير بلفظ (التفريط) ﴿فرطت﴾»","url":""}]},{"id":"s39-84","number":84,"surah":39,"verses":[56],"references":[{"surah":39,"verses":[56]}],"verseLabel":"الزمر: 56","question":"لماذا عُبّر عن حق الله وطاعته بقوله: ﴿فِي جَنْبِ اللَّهِ﴾؟","answer":"لأن الجنب استُعمل كناية عن جهة الحق والطاعة والقرب؛ فتصور النفس نفسها وقد أهملت الجانب الذي كان ينبغي أن تلزمه، وإضافته إلى الله تعظم مقدار ما ضيعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص648، تحت عنوان «سر التعبير بلفظ (الجنب)»","url":""}]},{"id":"s39-85","number":85,"surah":39,"verses":[56,57,58],"references":[{"surah":39,"verses":[56,57,58]}],"verseLabel":"الزمر: 56–58","question":"ما دلالة ترتيب أعذار النفس من الحسرة على التفريط إلى تمني الهداية ثم تمني الرجعة؟","answer":"تبدأ النفس بالتحسر على تقصيرها، ثم تنتقل إلى التعلل بفقد الهداية، ثم تطلب الرجوع للعمل الصالح. ويربط هذا الترتيب أقوالها بما يتتابع عليها من انكشاف الحق ومشاهدة العذاب، فتتنقل بين الاعتراف والاعتذار والتمني حين لا ينفعها ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص657، تحت عنوان «نكتة التقديم بين الأقوال»","url":""}]},{"id":"s39-86","number":86,"surah":39,"verses":[58],"references":[{"surah":39,"verses":[58]}],"verseLabel":"الزمر: 58","question":"لماذا قُيّد تمني الرجعة وحده بقوله: ﴿حِينَ تَرَى الْعَذَابَ﴾ دون القولين السابقين؟","answer":"لأن الحسرة على التفريط والتعلل بفقد الهداية يبدآن قبل المعاينة، أما طلب الرجعة فلا ينفجر إلا حين ترى النفس العذاب وتدرك أن زمن العمل انتهى؛ فالقيد يوضح تدرج أقوالها بحسب انكشاف المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص659، تحت عنوان «سر الاختصاص بالقيد»","url":""}]},{"id":"s39-87","number":87,"surah":39,"verses":[59],"references":[{"surah":39,"verses":[59]}],"verseLabel":"الزمر: 59","question":"لماذا خُصّ قول النفس الثاني بالرد: ﴿بَلَى قَدْ جَاءَتْكَ آيَاتِي﴾؟","answer":"لأن قولها: لو أن الله هداني، يتضمن إلقاء تبعة الضلال على غيرها؛ فجاء الرد ليبطل هذه الدعوى ويثبت أن آيات الهداية بلغتها فكذبت واستكبرت.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص665–666، تحت عنوان «سر تخصيص القول الثاني للنفس بالرد»","url":""}]},{"id":"s39-141","number":141,"surah":39,"verses":[59],"references":[{"surah":39,"verses":[59]}],"verseLabel":"الزمر: 59","question":"لماذا قيل: ﴿وَكُنْتَ مِنَ الْكَافِرِينَ﴾ بدل: وكنت كافرًا؟","answer":"لإدخالها في جماعة رسخت فيهم صفة الكفر واتخذته طريقًا، لا وصف حال عابر؛ فينكشف أن مصيرها ثمرة اختيار متكرر وانتماء إلى أهل التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص674، تحت عنوان «سر العدول عن الإفراد إلى الجمع»","url":""}]},{"id":"s39-88","number":88,"surah":39,"verses":[60],"references":[{"surah":39,"verses":[60]}],"verseLabel":"الزمر: 60","question":"ماذا يصوّر اسوداد وجوه المكذبين يوم القيامة؟","answer":"يصور الذلة والكآبة والفضيحة التي تغشاهم، سواء حمل السواد على تغير حقيقي في اللون أو على الكناية عن شدة الخزي؛ وفي الحالين يتحول الباطن المظلم إلى أثر مشهود.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص682، تحت عنوان «اسوداد الوجوه بين الحقيقة والكناية»","url":""}]},{"id":"s39-89","number":89,"surah":39,"verses":[60],"references":[{"surah":39,"verses":[60]}],"verseLabel":"الزمر: 60","question":"لماذا عُيّن مأوى المتكبرين باسم ﴿جَهَنَّمَ﴾؟","answer":"لأن الاسم يستحضر النار المحيطة الشديدة، ويلائم جرمهم: قابلوا آيات الله بالكذب والتكبر، فقوبل استعلاؤهم بمأوى يحيط بهم ويذلهم؛ فالجزاء من جنس العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص683، تحت عنوان «علة التعبير بـ: ﴿جهنم﴾»","url":""}]},{"id":"s39-90","number":90,"surah":39,"verses":[61],"references":[{"surah":39,"verses":[61]}],"verseLabel":"الزمر: 61","question":"لماذا لم يذكر ما الذي يُنَجَّى منه المتقون في قوله: ﴿وَيُنَجِّي اللَّهُ الَّذِينَ اتَّقَوْا﴾؟","answer":"لأن جهنم حاضرة بقوة في الآية السابقة، ففهم منها المحذوف من غير تصريح؛ كما يوسع الحذف الوعد ليشمل إنجاءهم من جهنم ومن كل ما يقود إليها من الكذب والتكبر والشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص690، تحت عنوان «سر حذف معمولي التنجية والتقوى»","url":""}]},{"id":"s39-91","number":91,"surah":39,"verses":[61],"references":[{"surah":39,"verses":[61]}],"verseLabel":"الزمر: 61","question":"لماذا قُدّم ﴿لَا يَمَسُّهُمُ السُّوءُ﴾ على ﴿وَلَا هُمْ يَحْزَنُونَ﴾؟","answer":"لأن انتفاء السوء أصل في انتفاء الحزن الناشئ عنه، فقدم السبب ثم أتبعه بأثره النفسي؛ وبذلك جمع الوعد بين السلامة من المكروه في الخارج وطمأنينة القلب في الداخل.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص695–696، تحت عنوان «نكتة تقديم جملة: ﴿لا يمسهم السوء﴾»","url":""}]},{"id":"s39-92","number":92,"surah":39,"verses":[62,63],"references":[{"surah":39,"verses":[62,63]}],"verseLabel":"الزمر: 62–63","question":"لماذا قُدِّم قوله ﴿اللَّهُ خَالِقُ كُلِّ شَيْءٍ﴾ على ﴿وَهُوَ عَلَى كُلِّ شَيْءٍ وَكِيلٌ﴾؟","answer":"لأن الخلق أصل ما بعده؛ فالله أوجد الأشياء أولًا ثم تولى حفظها وتدبيرها. كما أن تقديم انفراده بالخلق أنسب بمقام الرد على المشركين وإقامة الحجة على إفراده بالعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص701–702، تحت عنوان «نكتة تقديم جملة: ﴿الله خالق كل شيء﴾»","url":""}]},{"id":"s39-93","number":93,"surah":39,"verses":[63],"references":[{"surah":39,"verses":[63]}],"verseLabel":"الزمر: 63","question":"ما الصورة التي يرسمها قوله ﴿لَهُ مَقَالِيدُ السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"يصور خزائن السماوات والأرض ومفاتيحها بيده وحده؛ فما فيها من أرزاق وتدبير وتصرف داخل في ملكه وقدرته، ولا يملك أحد سواه فتح شيء منها أو منعه استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص708–709، تحت عنوان «علة التعبير بـ: ﴿مقاليد﴾»","url":""}]},{"id":"s39-94","number":94,"surah":39,"verses":[64],"references":[{"surah":39,"verses":[64]}],"verseLabel":"الزمر: 64","question":"لماذا قال ﴿أَفَغَيْرَ اللَّهِ﴾ ولم يسمِّ معبودات المشركين؟","answer":"ليعم الإنكار كل ما سوى الله بلا استثناء؛ فبعد ثبوت انفراده بالخلق والتدبير تصبح عبادة أي موجود غيره باطلة، مهما اختلف اسمه أو صورته.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص720، تحت عنوان «سر العدول عن ذكر معبودات الكفار»","url":""}]},{"id":"s39-95","number":95,"surah":39,"verses":[64],"references":[{"surah":39,"verses":[64]}],"verseLabel":"الزمر: 64","question":"لماذا وُصف الداعون إلى عبادة غير الله بأنهم ﴿الْجَاهِلُونَ﴾؟","answer":"لأن دعوتهم تناقض أوضح دلائل التوحيد؛ فقد جهلوا عظمة الله واستحقاقه العبادة وحده، وجهلوا قبح ما يدعون إليه، فجاء الوصف توبيخًا لهم على هذا العمى بعد قيام الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص724–725، تحت عنوان «علة التعبير بالجهل»","url":""}]},{"id":"s39-96","number":96,"surah":39,"verses":[65],"references":[{"surah":39,"verses":[65]}],"verseLabel":"الزمر: 65","question":"كيف يُوجَّه التحذير من الشرك إلى النبي ﷺ وهو معصوم منه؟","answer":"الشرط يفرض الممتنع لبيان فداحة الشرك وأنه يحبط العمل مهما عظم صاحبه، لا ليدل على إمكان وقوعه من النبي ﷺ. وفي توجيه الخطاب إليه تغليظ للإنذار وتعريض بمن يشرك من أمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص733، تحت عنوان «بلاغة أسلوب الشرط»","url":""}]},{"id":"s39-97","number":97,"surah":39,"verses":[65],"references":[{"surah":39,"verses":[65]}],"verseLabel":"الزمر: 65","question":"ما الذي يصوره لفظ ﴿لَيَحْبَطَنَّ عَمَلُكَ﴾ عن أثر الشرك؟","answer":"يصور بطلان العمل وذهاب أثره وثوابه حتى يصير كأنه لم يكن؛ فالشرك لا ينقص قيمة العمل فحسب، بل يهدم أساس قبوله كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص735، تحت عنوان «علة التعبير بالحبط مادة وصيغة»","url":""}]},{"id":"s39-98","number":98,"surah":39,"verses":[66],"references":[{"surah":39,"verses":[66]}],"verseLabel":"الزمر: 66","question":"لماذا قُدِّم الأمر بعبادة الله على الأمر بشكره في ﴿بَلِ اللَّهَ فَاعْبُدْ وَكُنْ مِنَ الشَّاكِرِينَ﴾؟","answer":"لأن إفراد الله بالعبادة هو المقصود الأول في مقام إبطال الشرك، ثم يأتي الشكر ثمرةً لذلك واعترافًا بنعمة الهداية إلى التوحيد والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص744، تحت عنوان «نكتة تقديم الأمر بالعبادة على الأمر بالشكر»","url":""}]},{"id":"s39-99","number":99,"surah":39,"verses":[67],"references":[{"surah":39,"verses":[67]}],"verseLabel":"الزمر: 67","question":"لماذا جاء مشهد الأرض في قبضته والسماوات مطويات بيمينه عقب قوله ﴿وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ﴾؟","answer":"ليجعل عظمة قدرة الله مشهدًا كاشفًا لسوء تقديرهم؛ فمن كانت الأرض كلها في قبضته والسماوات مطويات بيمينه لا يليق أن يُجعل له شريك، فيتضاعف التوبيخ على شركهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص751–752، تحت عنوان «بلاغة جملة الحال»","url":""}]},{"id":"s39-100","number":100,"surah":39,"verses":[67],"references":[{"surah":39,"verses":[67]}],"verseLabel":"الزمر: 67","question":"لماذا قيل ﴿وَالْأَرْضُ جَمِيعًا قَبْضَتُهُ﴾ مع أن لفظ الأرض يشملها؟","answer":"لإزالة أي توهم بأن شيئًا من الأرض يخرج عن سلطان الله؛ فكل أجزائها وأقطارها مجتمعة في قبضته يوم القيامة، لا يستعصي منها شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص752، تحت عنوان «علة التعبير بـ: ﴿جميعًا﴾»","url":""}]},{"id":"s39-101","number":101,"surah":39,"verses":[68],"references":[{"surah":39,"verses":[68]}],"verseLabel":"الزمر: 68","question":"لماذا أُعيد فعل ﴿نُفِخَ﴾ عند النفخة الثانية؟","answer":"لتمييز النفختين وإبراز استقلال أثر كل واحدة: الأولى نفخة الصعق، والثانية نفخة البعث والقيام. فإعادة الفعل تمنع توهم أن المذكور أثر واحد لنفخة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص766، تحت عنوان «فائدة إعادة فعل ﴿نفخ﴾ مرة ثانية»","url":""}]}]);
